window.ExtraBibleBooks=window.ExtraBibleBooks||{};window.ExtraBibleBooks["AMO"]={"book":"AMO","editions":{"hbo-source":[[1,1,"דִּבְרֵ֣י עָמ֔וֹס אֲשֶׁר־הָיָ֥ה בַ⁠נֹּקְדִ֖ים מִ⁠תְּק֑וֹעַ אֲשֶׁר֩ חָזָ֨ה עַל־יִשְׂרָאֵ֜ל בִּ⁠ימֵ֣י ׀ עֻזִיָּ֣ה מֶֽלֶךְ־יְהוּדָ֗ה וּ⁠בִ⁠ימֵ֞י יָרָבְעָ֤ם בֶּן־יוֹאָשׁ֙ מֶ֣לֶךְ יִשְׂרָאֵ֔ל שְׁנָתַ֖יִם לִ⁠פְנֵ֥י הָ⁠רָֽעַשׁ׃","di̇bĕré֣y ʻám֔wòs ʼàşěr-háyá֥h ba⁠nò̇qĕdi֖ym mi⁠ţĕ̇q֑wòʻa ʼàşěr֩ ẖázá֨h ʻal-yişĕ̂ráʼé֜l bi̇⁠ymé֣y ׀ ʻuziyá֣̇h meֽlekĕ-yĕhẇdá֗h ẇ⁠bi⁠ymé֞y yárábĕʻá֤m bėn-ywòʼáş̌֙ me֣lekĕ yişĕ̂ráʼé֔l şĕ̌náţa֖yim li⁠pĕné֥y há⁠ráֽʻaş̌׃"],[1,2,"וַ⁠יֹּאמַ֓ר ׀ יְהוָה֙ מִ⁠צִיּ֣וֹן יִשְׁאָ֔ג וּ⁠מִ⁠ירוּשָׁלִַ֖ם יִתֵּ֣ן קוֹל֑⁠וֹ וְ⁠אָֽבְלוּ֙ נְא֣וֹת הָ⁠רֹעִ֔ים וְ⁠יָבֵ֖שׁ רֹ֥אשׁ הַ⁠כַּרְמֶֽל׃פ","wa⁠yò̇ʼma֓r ׀ yĕhwáh֙ mi⁠ẕiẏ֣wòn yişĕ̌ʼá֔g ẇ⁠mi⁠yrẇşá̌lia֖m yiţé֣̇n qwòl֑⁠wò wĕ⁠ʼáֽbĕlẇ֙ nĕʼ֣wòţ há⁠ròʻi֔ym wĕ⁠yábé֖ş̌ rò֥ʼş̌ ha⁠kȧrĕmeֽl׃p"],[1,3,"כֹּ֚ה אָמַ֣ר יְהוָ֔ה עַל־שְׁלֹשָׁה֙ פִּשְׁעֵ֣י דַמֶּ֔שֶׂק וְ⁠עַל־אַרְבָּעָ֖ה לֹ֣א אֲשִׁיבֶ֑⁠נּוּ עַל־דּוּשָׁ֛⁠ם בַּ⁠חֲרֻצ֥וֹת הַ⁠בַּרְזֶ֖ל אֶת־הַ⁠גִּלְעָֽד׃","kò֚̇h ʼáma֣r yĕhwá֔h ʻal-şĕ̌lòşá̌h֙ pi̇şĕ̌ʻé֣y damė֔şêq wĕ⁠ʻal-ʼarĕbá̇ʻá֖h lò֣ʼ ʼàşǐybe֑⁠ṅẇ ʻal-ḋẇşá֛̌⁠m bȧ⁠ẖàruẕ֥wòţ ha⁠bȧrĕze֖l ʼeţ-ha⁠gi̇lĕʻáֽd׃"],[1,4,"וְ⁠שִׁלַּ֥חְתִּי אֵ֖שׁ בְּ⁠בֵ֣ית חֲזָאֵ֑ל וְ⁠אָכְלָ֖ה אַרְמְנ֥וֹת בֶּן־הֲדָֽד׃","wĕ⁠şǐlȧ֥ẖĕţi̇y ʼé֖ş̌ bĕ̇⁠bé֣yţ ẖàzáʼé֑l wĕ⁠ʼákĕlá֖h ʼarĕmĕn֥wòţ bėn-hàdáֽd׃"],[1,5,"וְ⁠שָֽׁבַרְתִּי֙ בְּרִ֣יחַ דַּמֶּ֔שֶׂק וְ⁠הִכְרַתִּ֤י יוֹשֵׁב֙ מִ⁠בִּקְעַת־אָ֔וֶן וְ⁠תוֹמֵ֥ךְ שֵׁ֖בֶט מִ⁠בֵּ֣ית עֶ֑דֶן וְ⁠גָל֧וּ עַם־אֲרָ֛ם קִ֖ירָ⁠ה אָמַ֥ר יְהוָֽה׃פ","wĕ⁠şáֽ̌barĕţi̇y֙ bĕ̇ri֣yẖa dȧmė֔şêq wĕ⁠hikĕraţi֤̇y ywòşé̌b֙ mi⁠bi̇qĕʻaţ-ʼá֔wen wĕ⁠ţwòmé֥kĕ şé֖̌bet mi⁠bé֣̇yţ ʻe֑den wĕ⁠gál֧ẇ ʻam-ʼàrá֛m qi֖yrá⁠h ʼáma֥r yĕhwáֽh׃p"],[1,6,"כֹּ֚ה אָמַ֣ר יְהוָ֔ה עַל־שְׁלֹשָׁה֙ פִּשְׁעֵ֣י עַזָּ֔ה וְ⁠עַל־אַרְבָּעָ֖ה לֹ֣א אֲשִׁיבֶ֑⁠נּוּ עַל־הַגְלוֹתָ֛⁠ם גָּל֥וּת שְׁלֵמָ֖ה לְ⁠הַסְגִּ֥יר לֶ⁠אֱדֽוֹם׃","kò֚̇h ʼáma֣r yĕhwá֔h ʻal-şĕ̌lòşá̌h֙ pi̇şĕ̌ʻé֣y ʻazá̇֔h wĕ⁠ʻal-ʼarĕbá̇ʻá֖h lò֣ʼ ʼàşǐybe֑⁠ṅẇ ʻal-hagĕlwòţá֛⁠m gá̇l֥ẇţ şĕ̌lémá֖h lĕ⁠hasĕgi֥̇yr le⁠ʼèdֽwòm׃"],[1,7,"וְ⁠שִׁלַּ֥חְתִּי אֵ֖שׁ בְּ⁠חוֹמַ֣ת עַזָּ֑ה וְ⁠אָכְלָ֖ה אַרְמְנֹתֶֽי⁠הָ׃","wĕ⁠şǐlȧ֥ẖĕţi̇y ʼé֖ş̌ bĕ̇⁠ẖwòma֣ţ ʻazá֑̇h wĕ⁠ʼákĕlá֖h ʼarĕmĕnòţeֽy⁠há׃"],[1,8,"וְ⁠הִכְרַתִּ֤י יוֹשֵׁב֙ מֵֽ⁠אַשְׁדּ֔וֹד וְ⁠תוֹמֵ֥ךְ שֵׁ֖בֶט מֵֽ⁠אַשְׁקְל֑וֹן וַ⁠הֲשִׁיב֨וֹתִי יָדִ֜⁠י עַל־עֶקְר֗וֹן וְ⁠אָֽבְדוּ֙ שְׁאֵרִ֣ית פְּלִשְׁתִּ֔ים אָמַ֖ר אֲדֹנָ֥⁠י יְהוִֽה׃פ","wĕ⁠hikĕraţi֤̇y ywòşé̌b֙ méֽ⁠ʼaşĕ̌ḋ֔wòd wĕ⁠ţwòmé֥kĕ şé֖̌bet méֽ⁠ʼaşĕ̌qĕl֑wòn wa⁠hàşǐyb֨wòţiy yádi֜⁠y ʻal-ʻeqĕr֗wòn wĕ⁠ʼáֽbĕdẇ֙ şĕ̌ʼéri֣yţ pĕ̇lişĕ̌ţi̇֔ym ʼáma֖r ʼàdòná֥⁠y yĕhwiֽh׃p"],[1,9,"כֹּ֚ה אָמַ֣ר יְהוָ֔ה עַל־שְׁלֹשָׁה֙ פִּשְׁעֵי־צֹ֔ר וְ⁠עַל־אַרְבָּעָ֖ה לֹ֣א אֲשִׁיבֶ֑⁠נּוּ עַֽל־הַסְגִּירָ֞⁠ם גָּל֤וּת שְׁלֵמָה֙ לֶ⁠אֱד֔וֹם וְ⁠לֹ֥א זָכְר֖וּ בְּרִ֥ית אַחִֽים׃","kò֚̇h ʼáma֣r yĕhwá֔h ʻal-şĕ̌lòşá̌h֙ pi̇şĕ̌ʻéy-ẕò֔r wĕ⁠ʻal-ʼarĕbá̇ʻá֖h lò֣ʼ ʼàşǐybe֑⁠ṅẇ ʻaֽl-hasĕgi̇yrá֞⁠m gá̇l֤ẇţ şĕ̌lémáh֙ le⁠ʼèd֔wòm wĕ⁠lò֥ʼ zákĕr֖ẇ bĕ̇ri֥yţ ʼaẖiֽym׃"],[1,10,"וְ⁠שִׁלַּ֥חְתִּי אֵ֖שׁ בְּ⁠ח֣וֹמַת צֹ֑ר וְ⁠אָכְלָ֖ה אַרְמְנֹתֶֽי⁠הָ׃פ","wĕ⁠şǐlȧ֥ẖĕţi̇y ʼé֖ş̌ bĕ̇⁠ẖ֣wòmaţ ẕò֑r wĕ⁠ʼákĕlá֖h ʼarĕmĕnòţeֽy⁠há׃p"],[1,11,"כֹּ֚ה אָמַ֣ר יְהוָ֔ה עַל־שְׁלֹשָׁה֙ פִּשְׁעֵ֣י אֱד֔וֹם וְ⁠עַל־אַרְבָּעָ֖ה לֹ֣א אֲשִׁיבֶ֑⁠נּוּ עַל־רָדְפ֨⁠וֹ בַ⁠חֶ֤רֶב אָחִי⁠ו֙ וְ⁠שִׁחֵ֣ת רַחֲמָ֔י⁠ו וַ⁠יִּטְרֹ֤ף לָ⁠עַד֙ אַפּ֔⁠וֹ וְ⁠עֶבְרָת֖⁠וֹ שְׁמָ֥רָ⁠ה נֶֽצַח׃","kò֚̇h ʼáma֣r yĕhwá֔h ʻal-şĕ̌lòşá̌h֙ pi̇şĕ̌ʻé֣y ʼèd֔wòm wĕ⁠ʻal-ʼarĕbá̇ʻá֖h lò֣ʼ ʼàşǐybe֑⁠ṅẇ ʻal-rádĕp֨⁠wò ba⁠ẖe֤reb ʼáẖiy⁠w֙ wĕ⁠şǐẖé֣ţ raẖàmá֔y⁠w wa⁠yi̇tĕrò֤p lá⁠ʻad֙ ʼaṗ֔⁠wò wĕ⁠ʻebĕráţ֖⁠wò şĕ̌má֥rá⁠h neֽẕaẖ׃"],[1,12,"וְ⁠שִׁלַּ֥חְתִּי אֵ֖שׁ בְּ⁠תֵימָ֑ן וְ⁠אָכְלָ֖ה אַרְמְנ֥וֹת בָּצְרָֽה׃פ","wĕ⁠şǐlȧ֥ẖĕţi̇y ʼé֖ş̌ bĕ̇⁠ţéymá֑n wĕ⁠ʼákĕlá֖h ʼarĕmĕn֥wòţ bá̇ẕĕráֽh׃p"],[1,13,"כֹּ֚ה אָמַ֣ר יְהוָ֔ה עַל־שְׁלֹשָׁה֙ פִּשְׁעֵ֣י בְנֵֽי־עַמּ֔וֹן וְ⁠עַל־אַרְבָּעָ֖ה לֹ֣א אֲשִׁיבֶ֑⁠נּוּ עַל־בִּקְעָ⁠ם֙ הָר֣וֹת הַ⁠גִּלְעָ֔ד לְמַ֖עַן הַרְחִ֥יב אֶת־גְּבוּלָֽ⁠ם׃","kò֚̇h ʼáma֣r yĕhwá֔h ʻal-şĕ̌lòşá̌h֙ pi̇şĕ̌ʻé֣y bĕnéֽy-ʻaṁ֔wòn wĕ⁠ʻal-ʼarĕbá̇ʻá֖h lò֣ʼ ʼàşǐybe֑⁠ṅẇ ʻal-bi̇qĕʻá⁠m֙ hár֣wòţ ha⁠gi̇lĕʻá֔d lĕma֖ʻan harĕẖi֥yb ʼeţ-gĕ̇bẇláֽ⁠m׃"],[1,14,"וְ⁠הִצַּ֤תִּי אֵשׁ֙ בְּ⁠חוֹמַ֣ת רַבָּ֔ה וְ⁠אָכְלָ֖ה אַרְמְנוֹתֶ֑י⁠הָ בִּ⁠תְרוּעָה֙ בְּ⁠י֣וֹם מִלְחָמָ֔ה בְּ⁠סַ֖עַר בְּ⁠י֥וֹם סוּפָֽה","wĕ⁠hiẕȧ֤ţi̇y ʼéş̌֙ bĕ̇⁠ẖwòma֣ţ rabá̇֔h wĕ⁠ʼákĕlá֖h ʼarĕmĕnwòţe֑y⁠há bi̇⁠ţĕrẇʻáh֙ bĕ̇⁠y֣wòm milĕẖámá֔h bĕ̇⁠sa֖ʻar bĕ̇⁠y֥wòm sẇpáֽh"],[1,15,"וְ⁠הָלַ֥ךְ מַלְכָּ֖⁠ם בַּ⁠גּוֹלָ֑ה ה֧וּא וְ⁠שָׂרָ֛י⁠ו יַחְדָּ֖ו אָמַ֥ר יְהוָֽה׃פ","wĕ⁠hála֥kĕ malĕká֖̇⁠m bȧ⁠ġwòlá֑h h֧ẇʼ wĕ⁠şá̂rá֛y⁠w yaẖĕdá֖̇w ʼáma֥r yĕhwáֽh׃p"],[2,1,"כֹּ֚ה אָמַ֣ר יְהוָ֔ה עַל־שְׁלֹשָׁה֙ פִּשְׁעֵ֣י מוֹאָ֔ב וְ⁠עַל־אַרְבָּעָ֖ה לֹ֣א אֲשִׁיבֶ֑⁠נּוּ עַל־שָׂרְפ֛⁠וֹ עַצְמ֥וֹת מֶֽלֶךְ־אֱד֖וֹם לַ⁠שִּֽׂיד׃","kò֚̇h ʼáma֣r yĕhwá֔h ʻal-şĕ̌lòşá̌h֙ pi̇şĕ̌ʻé֣y mwòʼá֔b wĕ⁠ʻal-ʼarĕbá̇ʻá֖h lò֣ʼ ʼàşǐybe֑⁠ṅẇ ʻal-şá̂rĕp֛⁠wò ʻaẕĕm֥wòţ meֽlekĕ-ʼèd֖wòm la⁠şiֽ̇̂yd׃"],[2,2,"וְ⁠שִׁלַּחְתִּי־אֵ֣שׁ בְּ⁠מוֹאָ֔ב וְ⁠אָכְלָ֖ה אַרְמְנ֣וֹת הַ⁠קְּרִיּ֑וֹת וּ⁠מֵ֤ת בְּ⁠שָׁאוֹן֙ מוֹאָ֔ב בִּ⁠תְרוּעָ֖ה בְּ⁠ק֥וֹל שׁוֹפָֽר׃","wĕ⁠şǐlȧẖĕţi̇y-ʼé֣ş̌ bĕ̇⁠mwòʼá֔b wĕ⁠ʼákĕlá֖h ʼarĕmĕn֣wòţ ha⁠qĕ̇riẏ֑wòţ ẇ⁠mé֤ţ bĕ̇⁠şá̌ʼwòn֙ mwòʼá֔b bi̇⁠ţĕrẇʻá֖h bĕ̇⁠q֥wòl ş̌wòpáֽr׃"],[2,3,"וְ⁠הִכְרַתִּ֥י שׁוֹפֵ֖ט מִ⁠קִּרְבָּ֑⁠הּ וְ⁠כָל־שָׂרֶ֛י⁠הָ אֶהֱר֥וֹג עִמּ֖⁠וֹ אָמַ֥ר יְהוָֽה׃פ","wĕ⁠hikĕraţi֥̇y ş̌wòpé֖t mi⁠qi̇rĕbá֑̇⁠ḣ wĕ⁠kál-şá̂re֛y⁠há ʼehèr֥wòg ʻiṁ֖⁠wò ʼáma֥r yĕhwáֽh׃p"],[2,4,"כֹּ֚ה אָמַ֣ר יְהוָ֔ה עַל־שְׁלֹשָׁה֙ פִּשְׁעֵ֣י יְהוּדָ֔ה וְ⁠עַל־אַרְבָּעָ֖ה לֹ֣א אֲשִׁיבֶ֑⁠נּוּ עַֽל־מָאֳסָ֞⁠ם אֶת־תּוֹרַ֣ת יְהוָ֗ה וְ⁠חֻקָּי⁠ו֙ לֹ֣א שָׁמָ֔רוּ וַ⁠יַּתְעוּ⁠ם֙ כִּזְבֵי⁠הֶ֔ם אֲשֶׁר־הָלְכ֥וּ אֲבוֹתָ֖⁠ם אַחֲרֵי⁠הֶֽם׃","kò֚̇h ʼáma֣r yĕhwá֔h ʻal-şĕ̌lòşá̌h֙ pi̇şĕ̌ʻé֣y yĕhẇdá֔h wĕ⁠ʻal-ʼarĕbá̇ʻá֖h lò֣ʼ ʼàşǐybe֑⁠ṅẇ ʻaֽl-máʼosá֞⁠m ʼeţ-ţ̇wòra֣ţ yĕhwá֗h wĕ⁠ẖuqá̇y⁠w֙ lò֣ʼ şá̌má֔rẇ wa⁠yȧţĕʻẇ⁠m֙ ki̇zĕbéy⁠he֔m ʼàşěr-hálĕk֥ẇ ʼàbwòţá֖⁠m ʼaẖàréy⁠heֽm׃"],[2,5,"וְ⁠שִׁלַּ֥חְתִּי אֵ֖שׁ בִּֽ⁠יהוּדָ֑ה וְ⁠אָכְלָ֖ה אַרְמְנ֥וֹת יְרוּשָׁלִָֽם׃פ","wĕ⁠şǐlȧ֥ẖĕţi̇y ʼé֖ş̌ biֽ̇⁠yhẇdá֑h wĕ⁠ʼákĕlá֖h ʼarĕmĕn֥wòţ yĕrẇşá̌liáֽm׃p"],[2,6,"כֹּ֚ה אָמַ֣ר יְהוָ֔ה עַל־שְׁלֹשָׁה֙ פִּשְׁעֵ֣י יִשְׂרָאֵ֔ל וְ⁠עַל־אַרְבָּעָ֖ה לֹ֣א אֲשִׁיבֶ֑⁠נּוּ עַל־מִכְרָ֤⁠ם בַּ⁠כֶּ֨סֶף֙ צַדִּ֔יק וְ⁠אֶבְי֖וֹן בַּ⁠עֲב֥וּר נַעֲלָֽיִם׃","kò֚̇h ʼáma֣r yĕhwá֔h ʻal-şĕ̌lòşá̌h֙ pi̇şĕ̌ʻé֣y yişĕ̂ráʼé֔l wĕ⁠ʻal-ʼarĕbá̇ʻá֖h lò֣ʼ ʼàşǐybe֑⁠ṅẇ ʻal-mikĕrá֤⁠m bȧ⁠kė֨sep֙ ẕadi̇֔yq wĕ⁠ʼebĕy֖wòn bȧ⁠ʻàb֥ẇr naʻàláֽyim׃"],[2,7,"הַ⁠שֹּׁאֲפִ֤ים עַל־עֲפַר־אֶ֨רֶץ֙ בְּ⁠רֹ֣אשׁ דַּלִּ֔ים וְ⁠דֶ֥רֶךְ עֲנָוִ֖ים יַטּ֑וּ וְ⁠אִ֣ישׁ וְ⁠אָבִ֗י⁠ו יֵֽלְכוּ֙ אֶל־הַֽ⁠נַּעֲרָ֔ה לְמַ֥עַן חַלֵּ֖ל אֶת־שֵׁ֥ם קָדְשִֽׁ⁠י׃","ha⁠şò̇̌ʼàpi֤ym ʻal-ʻàpar-ʼe֨reẕ֙ bĕ̇⁠rò֣ʼş̌ dȧli̇֔ym wĕ⁠de֥rekĕ ʻànáwi֖ym yaṫ֑ẇ wĕ⁠ʼi֣yş̌ wĕ⁠ʼábi֗y⁠w yéֽlĕkẇ֙ ʼel-haֽ⁠nȧʻàrá֔h lĕma֥ʻan ẖalé֖̇l ʼeţ-şé֥̌m qádĕşǐֽ⁠y׃"],[2,8,"וְ⁠עַל־בְּגָדִ֤ים חֲבֻלִים֙ יַטּ֔וּ אֵ֖צֶל כָּל־מִזְבֵּ֑חַ וְ⁠יֵ֤ין עֲנוּשִׁים֙ יִשְׁתּ֔וּ בֵּ֖ית אֱלֹהֵי⁠הֶֽם׃","wĕ⁠ʻal-bĕ̇gádi֤ym ẖàbuliym֙ yaṫ֔ẇ ʼé֖ẕel ká̇l-mizĕbé֑̇ẖa wĕ⁠yé֤yn ʻànẇşǐym֙ yişĕ̌ţ̇֔ẇ bé֖̇yţ ʼèlòhéy⁠heֽm׃"],[2,9,"וְ⁠אָ֨נֹכִ֜י הִשְׁמַ֤דְתִּי אֶת־הָֽ⁠אֱמֹרִי֙ מִ⁠פְּנֵי⁠הֶ֔ם אֲשֶׁ֨ר כְּ⁠גֹ֤בַהּ אֲרָזִים֙ גָּבְה֔⁠וֹ וְ⁠חָסֹ֥ן ה֖וּא כָּֽ⁠אַלּוֹנִ֑ים וָ⁠אַשְׁמִ֤יד פִּרְי⁠וֹ֙ מִ⁠מַּ֔עַל וְ⁠שָׁרָשָׁ֖י⁠ו מִ⁠תָּֽחַת׃","wĕ⁠ʼá֨nòki֜y hişĕ̌ma֤dĕţi̇y ʼeţ-háֽ⁠ʼèmòriy֙ mi⁠pĕ̇néy⁠he֔m ʼàşě֨r kĕ̇⁠gò֤baḣ ʼàráziym֙ gá̇bĕh֔⁠wò wĕ⁠ẖásò֥n h֖ẇʼ káֽ̇⁠ʼal̇wòni֑ym wá⁠ʼaşĕ̌mi֤yd pi̇rĕy⁠wò֙ mi⁠mȧ֔ʻal wĕ⁠şá̌ráşá֖̌y⁠w mi⁠ţáֽ̇ẖaţ׃"],[2,10,"וְ⁠אָנֹכִ֛י הֶעֱלֵ֥יתִי אֶתְ⁠כֶ֖ם מֵ⁠אֶ֣רֶץ מִצְרָ֑יִם וָ⁠אוֹלֵ֨ךְ אֶתְ⁠כֶ֤ם בַּ⁠מִּדְבָּר֙ אַרְבָּעִ֣ים שָׁנָ֔ה לָ⁠רֶ֖שֶׁת אֶת־אֶ֥רֶץ הָ⁠אֱמֹרִֽי׃","wĕ⁠ʼánòki֛y heʻèlé֥yţiy ʼeţĕ⁠ke֖m mé⁠ʼe֣reẕ miẕĕrá֑yim wá⁠ʼwòlé֨kĕ ʼeţĕ⁠ke֤m bȧ⁠mi̇dĕbá̇r֙ ʼarĕbá̇ʻi֣ym şá̌ná֔h lá⁠re֖şěţ ʼeţ-ʼe֥reẕ há⁠ʼèmòriֽy׃"],[2,11,"וָ⁠אָקִ֤ים מִ⁠בְּנֵי⁠כֶם֙ לִ⁠נְבִיאִ֔ים וּ⁠מִ⁠בַּחוּרֵי⁠כֶ֖ם לִ⁠נְזִרִ֑ים הַ⁠אַ֥ף אֵֽין־זֹ֛את בְּנֵ֥י יִשְׂרָאֵ֖ל נְאֻם־יְהוָֽה׃","wá⁠ʼáqi֤ym mi⁠bĕ̇néy⁠kem֙ li⁠nĕbiyʼi֔ym ẇ⁠mi⁠bȧẖẇréy⁠ke֖m li⁠nĕziri֑ym ha⁠ʼa֥p ʼéֽyn-zò֛ʼţ bĕ̇né֥y yişĕ̂ráʼé֖l nĕʼum-yĕhwáֽh׃"],[2,12,"וַ⁠תַּשְׁק֥וּ אֶת־הַ⁠נְּזִרִ֖ים יָ֑יִן וְ⁠עַל־הַ⁠נְּבִיאִים֙ צִוִּיתֶ֣ם לֵ⁠אמֹ֔ר לֹ֖א תִּנָּבְאֽוּ׃","wa⁠ţȧşĕ̌q֥ẇ ʼeţ-ha⁠nĕ̇ziri֖ym yá֑yin wĕ⁠ʻal-ha⁠nĕ̇biyʼiym֙ ẕiwi̇yţe֣m lé⁠ʼmò֔r lò֖ʼ ţi̇ná̇bĕʼֽẇ׃"],[2,13,"הִנֵּ֛ה אָנֹכִ֥י מֵעִ֖יק תַּחְתֵּי⁠כֶ֑ם כַּ⁠אֲשֶׁ֤ר תָּעִיק֙ הָ⁠עֲגָלָ֔ה הַֽ⁠מְלֵאָ֥ה לָ֖⁠הּ עָמִֽיר׃","hiné֛̇h ʼánòki֥y méʻi֖yq ţȧẖĕţé̇y⁠ke֑m kȧ⁠ʼàşě֤r ţá̇ʻiyq֙ há⁠ʻàgálá֔h haֽ⁠mĕléʼá֥h lá֖⁠ḣ ʻámiֽyr׃"],[2,14,"וְ⁠אָבַ֤ד מָנוֹס֙ מִ⁠קָּ֔ל וְ⁠חָזָ֖ק לֹא־יְאַמֵּ֣ץ כֹּח֑⁠וֹ וְ⁠גִבּ֖וֹר לֹא־יְמַלֵּ֥ט נַפְשֽׁ⁠וֹ׃","wĕ⁠ʼába֤d mánwòs֙ mi⁠qá̇֔l wĕ⁠ẖázá֖q lòʼ-yĕʼamé֣̇ẕ kò̇ẖ֑⁠wò wĕ⁠giḃ֖wòr lòʼ-yĕmalé֥̇t napĕşֽ̌⁠wò׃"],[2,15,"וְ⁠תֹפֵ֤שׂ הַ⁠קֶּ֨שֶׁת֙ לֹ֣א יַעֲמֹ֔ד וְ⁠קַ֥ל בְּ⁠רַגְלָ֖י⁠ו לֹ֣א יְמַלֵּ֑ט וְ⁠רֹכֵ֣ב הַ⁠סּ֔וּס לֹ֥א יְמַלֵּ֖ט נַפְשֽׁ⁠וֹ׃","wĕ⁠ţòpé֤ş̂ ha⁠qė֨şěţ֙ lò֣ʼ yaʻàmò֔d wĕ⁠qa֥l bĕ̇⁠ragĕlá֖y⁠w lò֣ʼ yĕmalé֑̇t wĕ⁠ròké֣b ha⁠ṡ֔ẇs lò֥ʼ yĕmalé֖̇t napĕşֽ̌⁠wò׃"],[2,16,"וְ⁠אַמִּ֥יץ לִבּ֖⁠וֹ בַּ⁠גִּבּוֹרִ֑ים עָר֛וֹם יָנ֥וּס בַּ⁠יּוֹם־הַ⁠ה֖וּא נְאֻם־יְהוָֽה׃פ","wĕ⁠ʼami֥̇yẕ liḃ֖⁠wò bȧ⁠gi̇ḃwòri֑ym ʻár֛wòm yán֥ẇs bȧ⁠ẏwòm-ha⁠h֖ẇʼ nĕʼum-yĕhwáֽh׃p"],[3,1,"שִׁמְע֞וּ אֶת־הַ⁠דָּבָ֣ר הַ⁠זֶּ֗ה אֲשֶׁ֨ר דִּבֶּ֧ר יְהוָ֛ה עֲלֵי⁠כֶ֖ם בְּנֵ֣י יִשְׂרָאֵ֑ל עַ֚ל כָּל־הַ⁠מִּשְׁפָּחָ֔ה אֲשֶׁ֧ר הֶעֱלֵ֛יתִי מֵ⁠אֶ֥רֶץ מִצְרַ֖יִם לֵ⁠אמֹֽר׃","şǐmĕʻ֞ẇ ʼeţ-ha⁠dá̇bá֣r ha⁠zė֗h ʼàşě֨r di̇bė֧r yĕhwá֛h ʻàléy⁠ke֖m bĕ̇né֣y yişĕ̂ráʼé֑l ʻa֚l ká̇l-ha⁠mi̇şĕ̌pá̇ẖá֔h ʼàşě֧r heʻèlé֛yţiy mé⁠ʼe֥reẕ miẕĕra֖yim lé⁠ʼmòֽr׃"],[3,2,"רַ֚ק אֶתְ⁠כֶ֣ם יָדַ֔עְתִּי מִ⁠כֹּ֖ל מִשְׁפְּח֣וֹת הָ⁠אֲדָמָ֑ה עַל־כֵּן֙ אֶפְקֹ֣ד עֲלֵי⁠כֶ֔ם אֵ֖ת כָּל־עֲוֺנֹֽתֵי⁠כֶֽם׃","ra֚q ʼeţĕ⁠ke֣m yáda֔ʻĕţi̇y mi⁠kò֖̇l mişĕ̌pĕ̇ẖ֣wòţ há⁠ʼàdámá֑h ʻal-ké̇n֙ ʼepĕqò֣d ʻàléy⁠ke֔m ʼé֖ţ ká̇l-ʻàwֺnòֽţéy⁠keֽm׃"],[3,3,"הֲ⁠יֵלְכ֥וּ שְׁנַ֖יִם יַחְדָּ֑ו בִּלְתִּ֖י אִם־נוֹעָֽדוּ׃","hà⁠yélĕk֥ẇ şĕ̌na֖yim yaẖĕdá֑̇w bi̇lĕţi֖̇y ʼim-nwòʻáֽdẇ׃"],[3,4,"הֲ⁠יִשְׁאַ֤ג אַרְיֵה֙ בַּ⁠יַּ֔עַר וְ⁠טֶ֖רֶף אֵ֣ין ל֑⁠וֹ הֲ⁠יִתֵּ֨ן כְּפִ֤יר קוֹל⁠וֹ֙ מִ⁠מְּעֹ֣נָת֔⁠וֹ בִּלְתִּ֖י אִם־לָכָֽד׃","hà⁠yişĕ̌ʼa֤g ʼarĕyéh֙ bȧ⁠yȧ֔ʻar wĕ⁠te֖rep ʼé֣yn l֑⁠wò hà⁠yiţé̇֨n kĕ̇pi֤yr qwòl⁠wò֙ mi⁠mĕ̇ʻò֣náţ֔⁠wò bi̇lĕţi֖̇y ʼim-lákáֽd׃"],[3,5,"הֲ⁠תִפֹּ֤ל צִפּוֹר֙ עַל־פַּ֣ח הָ⁠אָ֔רֶץ וּ⁠מוֹקֵ֖שׁ אֵ֣ין לָ֑⁠הּ הֲ⁠יַֽעֲלֶה־פַּח֙ מִן־הָ֣⁠אֲדָמָ֔ה וְ⁠לָכ֖וֹד לֹ֥א יִלְכּֽוֹד׃","hà⁠ţipò֤̇l ẕiṗwòr֙ ʻal-pȧ֣ẖ há⁠ʼá֔reẕ ẇ⁠mwòqé֖ş̌ ʼé֣yn lá֑⁠ḣ hà⁠yaֽʻàleh-pȧẖ֙ min-há֣⁠ʼàdámá֔h wĕ⁠lák֖wòd lò֥ʼ yilĕkֽ̇wòd׃"],[3,6,"אִם־יִתָּקַ֤ע שׁוֹפָר֙ בְּ⁠עִ֔יר וְ⁠עָ֖ם לֹ֣א יֶחֱרָ֑דוּ אִם־תִּהְיֶ֤ה רָעָה֙ בְּ⁠עִ֔יר וַ⁠יהוָ֖ה לֹ֥א עָשָֽׂה׃","ʼim-yiţá̇qa֤ʻ ş̌wòpár֙ bĕ̇⁠ʻi֔yr wĕ⁠ʻá֖m lò֣ʼ yeẖèrá֑dẇ ʼim-ţi̇hĕye֤h ráʻáh֙ bĕ̇⁠ʻi֔yr wa⁠yhwá֖h lò֥ʼ ʻáşáֽ̂h׃"],[3,7,"כִּ֣י לֹ֧א יַעֲשֶׂ֛ה אֲדֹנָ֥⁠י יְהוִ֖ה דָּבָ֑ר כִּ֚י אִם־גָּלָ֣ה סוֹד֔⁠וֹ אֶל־עֲבָדָ֖י⁠ו הַ⁠נְּבִיאִֽים׃","ki֣̇y lò֧ʼ yaʻàşê֛h ʼàdòná֥⁠y yĕhwi֖h dá̇bá֑r ki֚̇y ʼim-gá̇lá֣h swòd֔⁠wò ʼel-ʻàbádá֖y⁠w ha⁠nĕ̇biyʼiֽym׃"],[3,8,"אַרְיֵ֥ה שָׁאָ֖ג מִ֣י לֹ֣א יִירָ֑א אֲדֹנָ֤⁠י יְהוִה֙ דִּבֶּ֔ר מִ֖י לֹ֥א יִנָּבֵֽא׃","ʼarĕyé֥h şá̌ʼá֖g mi֣y lò֣ʼ yiyrá֑ʼ ʼàdòná֤⁠y yĕhwih֙ di̇bė֔r mi֖y lò֥ʼ yiná̇béֽʼ׃"],[3,9,"הַשְׁמִ֨יעוּ֙ עַל־אַרְמְנ֣וֹת בְּ⁠אַשְׁדּ֔וֹד וְ⁠עַֽל־אַרְמְנ֖וֹת בְּ⁠אֶ֣רֶץ מִצְרָ֑יִם וְ⁠אִמְר֗וּ הֵאָֽסְפוּ֙ עַל־הָרֵ֣י שֹׁמְר֔וֹן וּ⁠רְא֞וּ מְהוּמֹ֤ת רַבּוֹת֙ בְּ⁠תוֹכָ֔⁠הּ וַ⁠עֲשׁוּקִ֖ים בְּ⁠קִרְבָּֽ⁠הּ׃","haşĕ̌mi֨yʻẇ֙ ʻal-ʼarĕmĕn֣wòţ bĕ̇⁠ʼaşĕ̌ḋ֔wòd wĕ⁠ʻaֽl-ʼarĕmĕn֖wòţ bĕ̇⁠ʼe֣reẕ miẕĕrá֑yim wĕ⁠ʼimĕr֗ẇ héʼáֽsĕpẇ֙ ʻal-háré֣y şò̌mĕr֔wòn ẇ⁠rĕʼ֞ẇ mĕhẇmò֤ţ raḃwòţ֙ bĕ̇⁠ţwòká֔⁠ḣ wa⁠ʻàş̌ẇqi֖ym bĕ̇⁠qirĕbáֽ̇⁠ḣ׃"],[3,10,"וְ⁠לֹֽא־יָדְע֥וּ עֲשׂוֹת־נְכֹחָ֖ה נְאֻם־יְהוָ֑ה הָ⁠אֽוֹצְרִ֛ים חָמָ֥ס וָ⁠שֹׁ֖ד בְּ⁠אַרְמְנֽוֹתֵי⁠הֶֽם׃פ","wĕ⁠lòֽʼ-yádĕʻ֥ẇ ʻàş̂wòţ-nĕkòẖá֖h nĕʼum-yĕhwá֑h há⁠ʼֽwòẕĕri֛ym ẖámá֥s wá⁠şò֖̌d bĕ̇⁠ʼarĕmĕnֽwòţéy⁠heֽm׃p"],[3,11,"לָ⁠כֵ֗ן כֹּ֤ה אָמַר֙ אֲדֹנָ֣⁠י יְהוִ֔ה צַ֖ר וּ⁠סְבִ֣יב הָ⁠אָ֑רֶץ וְ⁠הוֹרִ֤ד מִמֵּ⁠ךְ֙ עֻזֵּ֔⁠ךְ וְ⁠נָבֹ֖זּוּ אַרְמְנוֹתָֽיִ⁠ךְ׃","lá⁠ké֗n kò֤̇h ʼámar֙ ʼàdòná֣⁠y yĕhwi֔h ẕa֖r ẇ⁠sĕbi֣yb há⁠ʼá֑reẕ wĕ⁠hwòri֤d mimé̇⁠kĕ֙ ʻuzé̇֔⁠kĕ wĕ⁠nábò֖żẇ ʼarĕmĕnwòţáֽyi⁠kĕ׃"],[3,12,"כֹּה֮ אָמַ֣ר יְהוָה֒ כַּ⁠אֲשֶׁר֩ יַצִּ֨יל הָ⁠רֹעֶ֜ה מִ⁠פִּ֧י הָ⁠אֲרִ֛י שְׁתֵּ֥י כְרָעַ֖יִם א֣וֹ בְדַל־אֹ֑זֶן כֵּ֣ן יִנָּצְל֞וּ בְּנֵ֣י יִשְׂרָאֵ֗ל הַ⁠יֹּֽשְׁבִים֙ בְּ⁠שֹׁ֣מְר֔וֹן בִּ⁠פְאַ֥ת מִטָּ֖ה וּ⁠בִ⁠דְמֶ֥שֶׁק עָֽרֶשׂ׃","kò̇h֮ ʼáma֣r yĕhwáh֒ kȧ⁠ʼàşěr֩ yaẕi̇֨yl há⁠ròʻe֜h mi⁠pi֧̇y há⁠ʼàri֛y şĕ̌ţé֥̇y kĕráʻa֖yim ʼ֣wò bĕdal-ʼò֑zen ké֣̇n yiná̇ẕĕl֞ẇ bĕ̇né֣y yişĕ̂ráʼé֗l ha⁠yòֽ̇şĕ̌biym֙ bĕ̇⁠şò֣̌mĕr֔wòn bi̇⁠pĕʼa֥ţ mitá֖̇h ẇ⁠bi⁠dĕme֥şěq ʻáֽreş̂׃"],[3,13,"שִׁמְע֥וּ וְ⁠הָעִ֖ידוּ בְּ⁠בֵ֣ית יַֽעֲקֹ֑ב נְאֻם־אֲדֹנָ֥⁠י יְהוִ֖ה אֱלֹהֵ֥י הַ⁠צְּבָאֽוֹת׃","şǐmĕʻ֥ẇ wĕ⁠háʻi֖ydẇ bĕ̇⁠bé֣yţ yaֽʻàqò֑b nĕʼum-ʼàdòná֥⁠y yĕhwi֖h ʼèlòhé֥y ha⁠ẕĕ̇báʼֽwòţ׃"],[3,14,"כִּ֗י בְּ⁠י֛וֹם פָּקְדִ֥⁠י פִשְׁעֵֽי־יִשְׂרָאֵ֖ל עָלָ֑י⁠ו וּ⁠פָֽקַדְתִּי֙ עַל־מִזְבְּח֣וֹת בֵּֽית־אֵ֔ל וְ⁠נִגְדְּעוּ֙ קַרְנ֣וֹת הַ⁠מִּזְבֵּ֔חַ וְ⁠נָפְל֖וּ לָ⁠אָֽרֶץ׃","ki̇֗y bĕ̇⁠y֛wòm pá̇qĕdi֥⁠y pişĕ̌ʻéֽy-yişĕ̂ráʼé֖l ʻálá֑y⁠w ẇ⁠páֽqadĕţi̇y֙ ʻal-mizĕbĕ̇ẖ֣wòţ béֽ̇yţ-ʼé֔l wĕ⁠nigĕdĕ̇ʻẇ֙ qarĕn֣wòţ ha⁠mi̇zĕbé̇֔ẖa wĕ⁠nápĕl֖ẇ lá⁠ʼáֽreẕ׃"],[3,15,"וְ⁠הִכֵּיתִ֥י בֵית־הַ⁠חֹ֖רֶף עַל־בֵּ֣ית הַ⁠קָּ֑יִץ וְ⁠אָבְד֞וּ בָּתֵּ֣י הַ⁠שֵּׁ֗ן וְ⁠סָפ֛וּ בָּתִּ֥ים רַבִּ֖ים נְאֻם־יְהוָֽה׃ס","wĕ⁠hiké̇yţi֥y béyţ-ha⁠ẖò֖rep ʻal-bé֣̇yţ ha⁠qá֑̇yiẕ wĕ⁠ʼábĕd֞ẇ bá̇ţé֣̇y ha⁠şé̇̌֗n wĕ⁠sáp֛ẇ bá̇ţi֥̇ym rabi֖̇ym nĕʼum-yĕhwáֽh׃s"],[4,1,"שִׁמְע֞וּ הַ⁠דָּבָ֣ר הַ⁠זֶּ֗ה פָּר֤וֹת הַ⁠בָּשָׁן֙ אֲשֶׁר֙ בְּ⁠הַ֣ר שֹֽׁמְר֔וֹן הָ⁠עֹשְׁק֣וֹת דַּלִּ֔ים הָ⁠רֹצְצ֖וֹת אֶבְיוֹנִ֑ים הָ⁠אֹמְרֹ֥ת לַ⁠אֲדֹֽנֵי⁠הֶ֖ם הָבִ֥יאָ⁠ה וְ⁠נִשְׁתֶּֽה׃","şǐmĕʻ֞ẇ ha⁠dá̇bá֣r ha⁠zė֗h pá̇r֤wòţ ha⁠bá̇şá̌n֙ ʼàşěr֙ bĕ̇⁠ha֣r şòֽ̌mĕr֔wòn há⁠ʻòşĕ̌q֣wòţ dȧli̇֔ym há⁠ròẕĕẕ֖wòţ ʼebĕywòni֑ym há⁠ʼòmĕrò֥ţ la⁠ʼàdòֽnéy⁠he֖m hábi֥yʼá⁠h wĕ⁠nişĕ̌ţėֽh׃"],[4,2,"נִשְׁבַּ֨ע אֲדֹנָ֤⁠י יְהוִה֙ בְּ⁠קָדְשׁ֔⁠וֹ כִּ֛י הִנֵּ֥ה יָמִ֖ים בָּאִ֣ים עֲלֵי⁠כֶ֑ם וְ⁠נִשָּׂ֤א אֶתְ⁠כֶם֙ בְּ⁠צִנּ֔וֹת וְ⁠אַחֲרִיתְ⁠כֶ֖ן בְּ⁠סִיר֥וֹת דּוּגָֽה׃","nişĕ̌bȧ֨ʻ ʼàdòná֤⁠y yĕhwih֙ bĕ̇⁠qádĕş̌֔⁠wò ki֛̇y hiné֥̇h yámi֖ym bá̇ʼi֣ym ʻàléy⁠ke֑m wĕ⁠nişá֤̇̂ʼ ʼeţĕ⁠kem֙ bĕ̇⁠ẕiṅ֔wòţ wĕ⁠ʼaẖàriyţĕ⁠ke֖n bĕ̇⁠siyr֥wòţ ḋẇgáֽh׃"],[4,3,"וּ⁠פְרָצִ֥ים תֵּצֶ֖אנָה אִשָּׁ֣ה נֶגְדָּ֑⁠הּ וְ⁠הִשְׁלַכְתֶּ֥נָה הַ⁠הַרְמ֖וֹנָ⁠ה נְאֻם־יְהוָֽה׃","ẇ⁠pĕráẕi֥ym ţé̇ẕe֖ʼnáh ʼişá֣̇̌h negĕdá֑̇⁠ḣ wĕ⁠hişĕ̌lakĕţė֥náh ha⁠harĕm֖wòná⁠h nĕʼum-yĕhwáֽh׃"],[4,4,"בֹּ֤אוּ בֵֽית־אֵל֙ וּ⁠פִשְׁע֔וּ הַ⁠גִּלְגָּ֖ל הַרְבּ֣וּ לִ⁠פְשֹׁ֑עַ וְ⁠הָבִ֤יאוּ לַ⁠בֹּ֨קֶר֙ זִבְחֵי⁠כֶ֔ם לִ⁠שְׁלֹ֥שֶׁת יָמִ֖ים מַעְשְׂרֹֽתֵי⁠כֶֽם׃","bò֤̇ʼẇ béֽyţ-ʼél֙ ẇ⁠pişĕ̌ʻ֔ẇ ha⁠gi̇lĕgá֖̇l harĕḃ֣ẇ li⁠pĕşò֑̌ʻa wĕ⁠hábi֤yʼẇ la⁠bò̇֨qer֙ zibĕẖéy⁠ke֔m li⁠şĕ̌lò֥şěţ yámi֖ym maʻĕşĕ̂ròֽţéy⁠keֽm׃"],[4,5,"וְ⁠קַטֵּ֤ר מֵֽ⁠חָמֵץ֙ תּוֹדָ֔ה וְ⁠קִרְא֥וּ נְדָב֖וֹת הַשְׁמִ֑יעוּ כִּ֣י כֵ֤ן אֲהַבְתֶּם֙ בְּנֵ֣י יִשְׂרָאֵ֔ל נְאֻ֖ם אֲדֹנָ֥⁠י יְהוִֽה׃","wĕ⁠qaté֤̇r méֽ⁠ẖáméẕ֙ ţ̇wòdá֔h wĕ⁠qirĕʼ֥ẇ nĕdáb֖wòţ haşĕ̌mi֑yʻẇ ki֣̇y ké֤n ʼàhabĕţėm֙ bĕ̇né֣y yişĕ̂ráʼé֔l nĕʼu֖m ʼàdòná֥⁠y yĕhwiֽh׃"],[4,6,"וְ⁠גַם־אֲנִי֩ נָתַ֨תִּי לָ⁠כֶ֜ם נִקְי֤וֹן שִׁנַּ֨יִם֙ בְּ⁠כָל־עָ֣רֵי⁠כֶ֔ם וְ⁠חֹ֣סֶר לֶ֔חֶם בְּ⁠כֹ֖ל מְקוֹמֹֽתֵי⁠כֶ֑ם וְ⁠לֹֽא־שַׁבְתֶּ֥ם עָדַ֖⁠י נְאֻם־יְהוָֽה׃","wĕ⁠gam-ʼàniy֩ náţa֨ţi̇y lá⁠ke֜m niqĕy֤wòn şǐnȧ֨yim֙ bĕ̇⁠kál-ʻá֣réy⁠ke֔m wĕ⁠ẖò֣ser le֔ẖem bĕ̇⁠kò֖l mĕqwòmòֽţéy⁠ke֑m wĕ⁠lòֽʼ-şǎbĕţė֥m ʻáda֖⁠y nĕʼum-yĕhwáֽh׃"],[4,7,"וְ⁠גַ֣ם אָנֹכִי֩ מָנַ֨עְתִּי מִ⁠כֶּ֜ם אֶת־הַ⁠גֶּ֗שֶׁם בְּ⁠ע֨וֹד שְׁלֹשָׁ֤ה חֳדָשִׁים֙ לַ⁠קָּצִ֔יר וְ⁠הִמְטַרְתִּי֙ עַל־עִ֣יר אֶחָ֔ת וְ⁠עַל־עִ֥יר אַחַ֖ת לֹ֣א אַמְטִ֑יר חֶלְקָ֤ה אַחַת֙ תִּמָּטֵ֔ר וְ⁠חֶלְקָ֛ה אֲשֶֽׁר־לֹֽא־תַמְטִ֥יר עָלֶ֖י⁠הָ תִּיבָֽשׁ׃","wĕ⁠ga֣m ʼánòkiy֩ mána֨ʻĕţi̇y mi⁠kė֜m ʼeţ-ha⁠gė֗şěm bĕ̇⁠ʻ֨wòd şĕ̌lòşá֤̌h ẖodáşǐym֙ la⁠qá̇ẕi֔yr wĕ⁠himĕtarĕţi̇y֙ ʻal-ʻi֣yr ʼeẖá֔ţ wĕ⁠ʻal-ʻi֥yr ʼaẖa֖ţ lò֣ʼ ʼamĕti֑yr ẖelĕqá֤h ʼaẖaţ֙ ţi̇má̇té֔r wĕ⁠ẖelĕqá֛h ʼàşěֽr-lòֽʼ-ţamĕti֥yr ʻále֖y⁠há ţi̇ybáֽş̌׃"],[4,8,"וְ⁠נָע֡וּ שְׁתַּיִם֩ שָׁלֹ֨שׁ עָרִ֜ים אֶל־עִ֥יר אַחַ֛ת לִ⁠שְׁתּ֥וֹת מַ֖יִם וְ⁠לֹ֣א יִשְׂבָּ֑עוּ וְ⁠לֹֽא־שַׁבְתֶּ֥ם עָדַ֖⁠י נְאֻם־יְהוָֽה׃","wĕ⁠náʻ֡ẇ şĕ̌ţȧyim֩ şá̌lò֨ş̌ ʻári֜ym ʼel-ʻi֥yr ʼaẖa֛ţ li⁠şĕ̌ţ֥̇wòţ ma֖yim wĕ⁠lò֣ʼ yişĕ̂bá֑̇ʻẇ wĕ⁠lòֽʼ-şǎbĕţė֥m ʻáda֖⁠y nĕʼum-yĕhwáֽh׃"],[4,9,"הִכֵּ֣יתִי אֶתְ⁠כֶם֮ בַּ⁠שִּׁדָּפ֣וֹן וּ⁠בַ⁠יֵּרָקוֹן֒ הַרְבּ֨וֹת גַּנּוֹתֵי⁠כֶ֧ם וְ⁠כַרְמֵי⁠כֶ֛ם וּ⁠תְאֵנֵי⁠כֶ֥ם וְ⁠זֵיתֵי⁠כֶ֖ם יֹאכַ֣ל הַ⁠גָּזָ֑ם וְ⁠לֹֽא־שַׁבְתֶּ֥ם עָדַ֖⁠י נְאֻם־יְהוָֽה׃ס","hiké֣̇yţiy ʼeţĕ⁠kem֮ bȧ⁠şi̇̌dá̇p֣wòn ẇ⁠ba⁠yé̇ráqwòn֒ harĕḃ֨wòţ gȧṅwòţéy⁠ke֧m wĕ⁠karĕméy⁠ke֛m ẇ⁠ţĕʼénéy⁠ke֥m wĕ⁠zéyţéy⁠ke֖m yòʼka֣l ha⁠gá̇zá֑m wĕ⁠lòֽʼ-şǎbĕţė֥m ʻáda֖⁠y nĕʼum-yĕhwáֽh׃s"],[4,10,"שִׁלַּ֨חְתִּי בָ⁠כֶ֥ם דֶּ֨בֶר֙ בְּ⁠דֶ֣רֶךְ מִצְרַ֔יִם הָרַ֤גְתִּי בַ⁠חֶ֨רֶב֙ בַּח֣וּרֵי⁠כֶ֔ם עִ֖ם שְׁבִ֣י סֽוּסֵי⁠כֶ֑ם וָ⁠אַעֲלֶ֞ה בְּאֹ֤שׁ מַחֲנֵי⁠כֶם֙ וּֽ⁠בְ⁠אַפְּ⁠כֶ֔ם וְ⁠לֹֽא־שַׁבְתֶּ֥ם עָדַ֖⁠י נְאֻם־יְהוָֽה׃","şǐlȧ֨ẖĕţi̇y bá⁠ke֥m dė֨ber֙ bĕ̇⁠de֣rekĕ miẕĕra֔yim hára֤gĕţi̇y ba⁠ẖe֨reb֙ bȧẖ֣ẇréy⁠ke֔m ʻi֖m şĕ̌bi֣y sֽẇséy⁠ke֑m wá⁠ʼaʻàle֞h bĕ̇ʼò֤ş̌ maẖànéy⁠kem֙ ẇֽ⁠bĕ⁠ʼapĕ̇⁠ke֔m wĕ⁠lòֽʼ-şǎbĕţė֥m ʻáda֖⁠y nĕʼum-yĕhwáֽh׃"],[4,11,"הָפַ֣כְתִּי בָ⁠כֶ֗ם כְּ⁠מַהְפֵּכַ֤ת אֱלֹהִים֙ אֶת־סְדֹ֣ם וְ⁠אֶת־עֲמֹרָ֔ה וַ⁠תִּהְי֕וּ כְּ⁠א֖וּד מֻצָּ֣ל מִ⁠שְׂרֵפָ֑ה וְ⁠לֹֽא־שַׁבְתֶּ֥ם עָדַ֖⁠י נְאֻם־יְהוָֽה׃ס","hápa֣kĕţi̇y bá⁠ke֗m kĕ̇⁠mahĕpé̇ka֤ţ ʼèlòhiym֙ ʼeţ-sĕdò֣m wĕ⁠ʼeţ-ʻàmòrá֔h wa⁠ţi̇hĕy֕ẇ kĕ̇⁠ʼ֖ẇd muẕá֣̇l mi⁠şĕ̂répá֑h wĕ⁠lòֽʼ-şǎbĕţė֥m ʻáda֖⁠y nĕʼum-yĕhwáֽh׃s"],[4,12,"לָ⁠כֵ֕ן כֹּ֥ה אֶעֱשֶׂה־לְּ⁠ךָ֖ יִשְׂרָאֵ֑ל עֵ֚קֶב כִּֽי־זֹ֣את אֶֽעֱשֶׂה־לָּ֔⁠ךְ הִכּ֥וֹן לִ⁠קְרַאת־אֱלֹהֶ֖י⁠ךָ יִשְׂרָאֵֽל׃","lá⁠ké֕n kò֥̇h ʼeʻèşêh-lĕ̇⁠ká֖ yişĕ̂ráʼé֑l ʻé֚qeb kiֽ̇y-zò֣ʼţ ʼeֽʻèşêh-lá̇֔⁠kĕ hik֥̇wòn li⁠qĕraʼţ-ʼèlòhe֖y⁠ká yişĕ̂ráʼéֽl׃"],[4,13,"כִּ֡י הִנֵּה֩ יוֹצֵ֨ר הָרִ֜ים וּ⁠בֹרֵ֣א ר֗וּחַ וּ⁠מַגִּ֤יד לְ⁠אָדָם֙ מַה־שֵּׂח֔⁠וֹ עֹשֵׂ֥ה שַׁ֨חַר֙ עֵיפָ֔ה וְ⁠דֹרֵ֖ךְ עַל־בָּ֣מֳתֵי אָ֑רֶץ יְהוָ֥ה אֱלֹהֵֽי־צְבָא֖וֹת שְׁמֽ⁠וֹ׃ס","ki̇֡y hiné̇h֩ ywòẕé֨r hári֜ym ẇ⁠bòré֣ʼ r֗ẇẖa ẇ⁠magi֤̇yd lĕ⁠ʼádám֙ mah-şé̇̂ẖ֔⁠wò ʻòşé֥̂h şǎ֨ẖar֙ ʻéypá֔h wĕ⁠dòré֖kĕ ʻal-bá֣̇moţéy ʼá֑reẕ yĕhwá֥h ʼèlòhéֽy-ẕĕbáʼ֖wòţ şĕ̌mֽ⁠wò׃s"],[5,1,"שִׁמְע֞וּ אֶת־הַ⁠דָּבָ֣ר הַ⁠זֶּ֗ה אֲשֶׁ֨ר אָנֹכִ֜י נֹשֵׂ֧א עֲלֵי⁠כֶ֛ם קִינָ֖ה בֵּ֥ית יִשְׂרָאֵֽל׃","şǐmĕʻ֞ẇ ʼeţ-ha⁠dá̇bá֣r ha⁠zė֗h ʼàşě֨r ʼánòki֜y nòşé֧̂ʼ ʻàléy⁠ke֛m qiyná֖h bé֥̇yţ yişĕ̂ráʼéֽl׃"],[5,2,"נָֽפְלָה֙ לֹֽא־תוֹסִ֣יף ק֔וּם בְּתוּלַ֖ת יִשְׂרָאֵ֑ל נִטְּשָׁ֥ה עַל־אַדְמָתָ֖⁠הּ אֵ֥ין מְקִימָֽ⁠הּ׃","náֽpĕláh֙ lòֽʼ-ţwòsi֣yp q֔ẇm bĕ̇ţẇla֖ţ yişĕ̂ráʼé֑l nitĕ̇şá֥̌h ʻal-ʼadĕmáţá֖⁠ḣ ʼé֥yn mĕqiymáֽ⁠ḣ׃"],[5,3,"כִּ֣י כֹ֤ה אָמַר֙ אֲדֹנָ֣⁠י יְהוִ֔ה הָ⁠עִ֛יר הַ⁠יֹּצֵ֥את אֶ֖לֶף תַּשְׁאִ֣יר מֵאָ֑ה וְ⁠הַ⁠יּוֹצֵ֥את מֵאָ֛ה תַּשְׁאִ֥יר עֲשָׂרָ֖ה לְ⁠בֵ֥ית יִשְׂרָאֵֽל׃ס","ki֣̇y kò֤h ʼámar֙ ʼàdòná֣⁠y yĕhwi֔h há⁠ʻi֛yr ha⁠yò̇ẕé֥ʼţ ʼe֖lep ţȧşĕ̌ʼi֣yr méʼá֑h wĕ⁠ha⁠ẏwòẕé֥ʼţ méʼá֛h ţȧşĕ̌ʼi֥yr ʻàşá̂rá֖h lĕ⁠bé֥yţ yişĕ̂ráʼéֽl׃s"],[5,4,"כִּ֣י כֹ֥ה אָמַ֛ר יְהוָ֖ה לְ⁠בֵ֣ית יִשְׂרָאֵ֑ל דִּרְשׁ֖וּ⁠נִי וִֽ⁠חְיֽוּ׃","ki֣̇y kò֥h ʼáma֛r yĕhwá֖h lĕ⁠bé֣yţ yişĕ̂ráʼé֑l di̇rĕş֖̌ẇ⁠niy wiֽ⁠ẖĕyֽẇ׃"],[5,5,"וְ⁠אַֽל־תִּדְרְשׁוּ֙ בֵּֽית־אֵ֔ל וְ⁠הַ⁠גִּלְגָּל֙ לֹ֣א תָבֹ֔אוּ וּ⁠בְאֵ֥ר שֶׁ֖בַע לֹ֣א תַעֲבֹ֑רוּ כִּ֤י הַ⁠גִּלְגָּל֙ גָּלֹ֣ה יִגְלֶ֔ה וּ⁠בֵֽית־אֵ֖ל יִהְיֶ֥ה לְ⁠אָֽוֶן׃","wĕ⁠ʼaֽl-ţi̇dĕrĕş̌ẇ֙ béֽ̇yţ-ʼé֔l wĕ⁠ha⁠gi̇lĕgá̇l֙ lò֣ʼ ţábò֔ʼẇ ẇ⁠bĕʼé֥r şě֖baʻ lò֣ʼ ţaʻàbò֑rẇ ki֤̇y ha⁠gi̇lĕgá̇l֙ gá̇lò֣h yigĕle֔h ẇ⁠béֽyţ-ʼé֖l yihĕye֥h lĕ⁠ʼáֽwen׃"],[5,6,"דִּרְשׁ֥וּ אֶת־יְהוָ֖ה וִֽ⁠חְי֑וּ פֶּן־יִצְלַ֤ח כָּ⁠אֵשׁ֙ בֵּ֣ית יוֹסֵ֔ף וְ⁠אָכְלָ֥ה וְ⁠אֵין־מְכַבֶּ֖ה לְ⁠בֵֽית־אֵֽל׃","di̇rĕş֥̌ẇ ʼeţ-yĕhwá֖h wiֽ⁠ẖĕy֑ẇ pėn-yiẕĕla֤ẖ ká̇⁠ʼéş̌֙ bé֣̇yţ ywòsé֔p wĕ⁠ʼákĕlá֥h wĕ⁠ʼéyn-mĕkabė֖h lĕ⁠béֽyţ-ʼéֽl׃"],[5,7,"הַ⁠הֹפְכִ֥ים לְ⁠לַעֲנָ֖ה מִשְׁפָּ֑ט וּ⁠צְדָקָ֖ה לָ⁠אָ֥רֶץ הִנִּֽיחוּ׃","ha⁠hòpĕki֥ym lĕ⁠laʻàná֖h mişĕ̌pá֑̇t ẇ⁠ẕĕdáqá֖h lá⁠ʼá֥reẕ hiniֽ̇yẖẇ׃"],[5,8,"עֹשֵׂ֨ה כִימָ֜ה וּ⁠כְסִ֗יל וְ⁠הֹפֵ֤ךְ לַ⁠בֹּ֨קֶר֙ צַלְמָ֔וֶת וְ⁠י֖וֹם לַ֣יְלָה הֶחְשִׁ֑יךְ הַ⁠קּוֹרֵ֣א לְ⁠מֵֽי־הַ⁠יָּ֗ם וַֽ⁠יִּשְׁפְּכֵ֛⁠ם עַל־פְּנֵ֥י הָ⁠אָ֖רֶץ יְהוָ֥ה שְׁמֽ⁠וֹ׃ס","ʻòşé̂֨h kiymá֜h ẇ⁠kĕsi֗yl wĕ⁠hòpé֤kĕ la⁠bò̇֨qer֙ ẕalĕmá֔weţ wĕ⁠y֖wòm la֣yĕláh heẖĕşǐ֑ykĕ ha⁠q̇wòré֣ʼ lĕ⁠méֽy-ha⁠yá̇֗m waֽ⁠yi̇şĕ̌pĕ̇ké֛⁠m ʻal-pĕ̇né֥y há⁠ʼá֖reẕ yĕhwá֥h şĕ̌mֽ⁠wò׃s"],[5,9,"הַ⁠מַּבְלִ֥יג שֹׁ֖ד עַל־עָ֑ז וְ⁠שֹׁ֖ד עַל־מִבְצָ֥ר יָבֽוֹא׃","ha⁠mȧbĕli֥yg şò֖̌d ʻal-ʻá֑z wĕ⁠şò֖̌d ʻal-mibĕẕá֥r yábֽwòʼ׃"],[5,10,"שָׂנְא֥וּ בַ⁠שַּׁ֖עַר מוֹכִ֑יחַ וְ⁠דֹבֵ֥ר תָּמִ֖ים יְתָעֵֽבוּ׃","şá̂nĕʼ֥ẇ ba⁠şȧ֖̌ʻar mwòki֑yẖa wĕ⁠dòbé֥r ţá̇mi֖ym yĕţáʻéֽbẇ׃"],[5,11,"לָ֠⁠כֵן יַ֣עַן בּוֹשַׁסְ⁠כֶ֞ם עַל־דָּ֗ל וּ⁠מַשְׂאַת־בַּר֙ תִּקְח֣וּ מִמֶּ֔⁠נּוּ בָּתֵּ֥י גָזִ֛ית בְּנִיתֶ֖ם וְ⁠לֹא־תֵ֣שְׁבוּ בָ֑⁠ם כַּרְמֵי־חֶ֣מֶד נְטַעְתֶּ֔ם וְ⁠לֹ֥א תִשְׁתּ֖וּ אֶת־יֵינָֽ⁠ם׃","lá֠⁠kén ya֣ʻan ḃwòşǎsĕ⁠ke֞m ʻal-dá̇֗l ẇ⁠maşĕ̂ʼaţ-bȧr֙ ţi̇qĕẖ֣ẇ mimė֔⁠ṅẇ bá̇ţé֥̇y gázi֛yţ bĕ̇niyţe֖m wĕ⁠lòʼ-ţé֣şĕ̌bẇ bá֑⁠m kȧrĕméy-ẖe֣med nĕtaʻĕţė֔m wĕ⁠lò֥ʼ ţişĕ̌ţ֖̇ẇ ʼeţ-yéynáֽ⁠m׃"],[5,12,"כִּ֤י יָדַ֨עְתִּי֙ רַבִּ֣ים פִּשְׁעֵי⁠כֶ֔ם וַ⁠עֲצֻמִ֖ים חַטֹּֽאתֵי⁠כֶ֑ם צֹרְרֵ֤י צַדִּיק֙ לֹ֣קְחֵי כֹ֔פֶר וְ⁠אֶבְיוֹנִ֖ים בַּ⁠שַּׁ֥עַר הִטּֽוּ׃","ki֤̇y yáda֨ʻĕţi̇y֙ rabi֣̇ym pi̇şĕ̌ʻéy⁠ke֔m wa⁠ʻàẕumi֖ym ẖatòֽ̇ʼţéy⁠ke֑m ẕòrĕré֤y ẕadi̇yq֙ lò֣qĕẖéy kò֔per wĕ⁠ʼebĕywòni֖ym bȧ⁠şȧ֥̌ʻar hiṫֽẇ׃"],[5,13,"לָ⁠כֵ֗ן הַ⁠מַּשְׂכִּ֛יל בָּ⁠עֵ֥ת הַ⁠הִ֖יא יִדֹּ֑ם כִּ֛י עֵ֥ת רָעָ֖ה הִֽיא׃","lá⁠ké֗n ha⁠mȧşĕ̂ki֛̇yl bá̇⁠ʻé֥ţ ha⁠hi֖yʼ yidò֑̇m ki֛̇y ʻé֥ţ ráʻá֖h hiֽyʼ׃"],[5,14,"דִּרְשׁוּ־ט֥וֹב וְ⁠אַל־רָ֖ע לְמַ֣עַן תִּֽחְי֑וּ וִ⁠יהִי־כֵ֞ן יְהוָ֧ה אֱלֹהֵֽי־צְבָא֛וֹת אִתְּ⁠כֶ֖ם כַּ⁠אֲשֶׁ֥ר אֲמַרְתֶּֽם׃","di̇rĕş̌ẇ-t֥wòb wĕ⁠ʼal-rá֖ʻ lĕma֣ʻan ţiֽ̇ẖĕy֑ẇ wi⁠yhiy-ké֞n yĕhwá֧h ʼèlòhéֽy-ẕĕbáʼ֛wòţ ʼiţĕ̇⁠ke֖m kȧ⁠ʼàşě֥r ʼàmarĕţėֽm׃"],[5,15,"שִׂנְאוּ־רָע֙ וְ⁠אֶ֣הֱבוּ ט֔וֹב וְ⁠הַצִּ֥יגוּ בַ⁠שַּׁ֖עַר מִשְׁפָּ֑ט אוּלַ֗י יֶֽחֱנַ֛ן יְהוָ֥ה אֱלֹהֵֽי־צְבָא֖וֹת שְׁאֵרִ֥ית יוֹסֵֽף׃ס","şînĕʼẇ-ráʻ֙ wĕ⁠ʼe֣hèbẇ t֔wòb wĕ⁠haẕi֥̇ygẇ ba⁠şȧ֖̌ʻar mişĕ̌pá֑̇t ʼẇla֗y yֽeẖèna֛n yĕhwá֥h ʼèlòhéֽy-ẕĕbáʼ֖wòţ şĕ̌ʼéri֥yţ ywòséֽp׃s"],[5,16,"לָ֠⁠כֵן כֹּֽה־אָמַ֨ר יְהוָ֜ה אֱלֹהֵ֤י צְבָאוֹת֙ אֲדֹנָ֔⁠י בְּ⁠כָל־רְחֹב֣וֹת מִסְפֵּ֔ד וּ⁠בְ⁠כָל־חוּצ֖וֹת יֹאמְר֣וּ הוֹ־ה֑וֹ וְ⁠קָרְא֤וּ אִכָּר֙ אֶל־אֵ֔בֶל וּ⁠מִסְפֵּ֖ד אֶל־י֥וֹדְעֵי נֶֽהִי׃","lá֠⁠kén kòֽ̇h-ʼáma֨r yĕhwá֜h ʼèlòhé֤y ẕĕbáʼwòţ֙ ʼàdòná֔⁠y bĕ̇⁠kál-rĕẖòb֣wòţ misĕpé̇֔d ẇ⁠bĕ⁠kál-ẖẇẕ֖wòţ yòʼmĕr֣ẇ hwò-h֑wò wĕ⁠qárĕʼ֤ẇ ʼiká̇r֙ ʼel-ʼé֔bel ẇ⁠misĕpé֖̇d ʼel-y֥wòdĕʻéy neֽhiy׃"],[5,17,"וּ⁠בְ⁠כָל־כְּרָמִ֖ים מִסְפֵּ֑ד כִּֽי־אֶעֱבֹ֥ר בְּ⁠קִרְבְּ⁠ךָ֖ אָמַ֥ר יְהוָֽה׃ס","ẇ⁠bĕ⁠kál-kĕ̇rámi֖ym misĕpé֑̇d kiֽ̇y-ʼeʻèbò֥r bĕ̇⁠qirĕbĕ̇⁠ká֖ ʼáma֥r yĕhwáֽh׃s"],[5,18,"ה֥וֹי הַ⁠מִּתְאַוִּ֖ים אֶת־י֣וֹם יְהוָ֑ה לָ⁠מָּה־זֶּ֥ה לָ⁠כֶ֛ם י֥וֹם יְהוָ֖ה הוּא־חֹ֥שֶׁךְ וְ⁠לֹא־אֽוֹר׃","h֥wòy ha⁠mi̇ţĕʼawi֖̇ym ʼeţ-y֣wòm yĕhwá֑h lá⁠má̇h-zė֥h lá⁠ke֛m y֥wòm yĕhwá֖h hẇʼ-ẖò֥şěkĕ wĕ⁠lòʼ-ʼֽwòr׃"],[5,19,"כַּ⁠אֲשֶׁ֨ר יָנ֥וּס אִישׁ֙ מִ⁠פְּנֵ֣י הָ⁠אֲרִ֔י וּ⁠פְגָע֖⁠וֹ הַ⁠דֹּ֑ב וּ⁠בָ֣א הַ⁠בַּ֔יִת וְ⁠סָמַ֤ךְ יָד⁠וֹ֙ עַל־הַ⁠קִּ֔יר וּ⁠נְשָׁכ֖⁠וֹ הַ⁠נָּחָֽשׁ׃","kȧ⁠ʼàşě֨r yán֥ẇs ʼiyş̌֙ mi⁠pĕ̇né֣y há⁠ʼàri֔y ẇ⁠pĕgáʻ֖⁠wò ha⁠dò֑̇b ẇ⁠bá֣ʼ ha⁠bȧ֔yiţ wĕ⁠sáma֤kĕ yád⁠wò֙ ʻal-ha⁠qi̇֔yr ẇ⁠nĕşá̌k֖⁠wò ha⁠ná̇ẖáֽş̌׃"],[5,20,"הֲ⁠לֹא־חֹ֛שֶׁךְ י֥וֹם יְהוָ֖ה וְ⁠לֹא־א֑וֹר וְ⁠אָפֵ֖ל וְ⁠לֹא־נֹ֥גַֽהּ לֽ⁠וֹ׃","hà⁠lòʼ-ẖò֛şěkĕ y֥wòm yĕhwá֖h wĕ⁠lòʼ-ʼ֑wòr wĕ⁠ʼápé֖l wĕ⁠lòʼ-nò֥gaֽḣ lֽ⁠wò׃"],[5,21,"שָׂנֵ֥אתִי מָאַ֖סְתִּי חַגֵּי⁠כֶ֑ם וְ⁠לֹ֥א אָרִ֖יחַ בְּ⁠עַצְּרֹֽתֵי⁠כֶֽם׃","şá̂né֥ʼţiy máʼa֖sĕţi̇y ẖagé̇y⁠ke֑m wĕ⁠lò֥ʼ ʼári֖yẖa bĕ̇⁠ʻaẕĕ̇ròֽţéy⁠keֽm׃"],[5,22,"כִּ֣י אִם־תַּעֲלוּ־לִ֥⁠י עֹל֛וֹת וּ⁠מִנְחֹתֵי⁠כֶ֖ם לֹ֣א אֶרְצֶ֑ה וְ⁠שֶׁ֥לֶם מְרִיאֵי⁠כֶ֖ם לֹ֥א אַבִּֽיט׃","ki֣̇y ʼim-ţȧʻàlẇ-li֥⁠y ʻòl֛wòţ ẇ⁠minĕẖòţéy⁠ke֖m lò֣ʼ ʼerĕẕe֑h wĕ⁠şě֥lem mĕriyʼéy⁠ke֖m lò֥ʼ ʼabiֽ̇yt׃"],[5,23,"הָסֵ֥ר מֵ⁠עָלַ֖⁠י הֲמ֣וֹן שִׁרֶ֑י⁠ךָ וְ⁠זִמְרַ֥ת נְבָלֶ֖י⁠ךָ לֹ֥א אֶשְׁמָֽע׃","hásé֥r mé⁠ʻála֖⁠y hàm֣wòn şǐre֑y⁠ká wĕ⁠zimĕra֥ţ nĕbále֖y⁠ká lò֥ʼ ʼeşĕ̌máֽʻ׃"],[5,24,"וְ⁠יִגַּ֥ל כַּ⁠מַּ֖יִם מִשְׁפָּ֑ט וּ⁠צְדָקָ֖ה כְּ⁠נַ֥חַל אֵיתָֽן׃","wĕ⁠yigȧ֥l kȧ⁠mȧ֖yim mişĕ̌pá֑̇t ẇ⁠ẕĕdáqá֖h kĕ̇⁠na֥ẖal ʼéyţáֽn׃"],[5,25,"הַ⁠זְּבָחִ֨ים וּ⁠מִנְחָ֜ה הִֽגַּשְׁתֶּם־לִ֧⁠י בַ⁠מִּדְבָּ֛ר אַרְבָּעִ֥ים שָׁנָ֖ה בֵּ֥ית יִשְׂרָאֵֽל׃","ha⁠zĕ̇báẖi֨ym ẇ⁠minĕẖá֜h hiֽgȧşĕ̌ţėm-li֧⁠y ba⁠mi̇dĕbá֛̇r ʼarĕbá̇ʻi֥ym şá̌ná֖h bé֥̇yţ yişĕ̂ráʼéֽl׃"],[5,26,"וּ⁠נְשָׂאתֶ֗ם אֵ֚ת סִכּ֣וּת מַלְכְּ⁠כֶ֔ם וְ⁠אֵ֖ת כִּיּ֣וּן צַלְמֵי⁠כֶ֑ם כּוֹכַב֙ אֱלֹ֣הֵי⁠כֶ֔ם אֲשֶׁ֥ר עֲשִׂיתֶ֖ם לָ⁠כֶֽם׃","ẇ⁠nĕşá̂ʼţe֗m ʼé֚ţ sik֣̇ẇţ malĕkĕ̇⁠ke֔m wĕ⁠ʼé֖ţ ki̇ẏ֣ẇn ẕalĕméy⁠ke֑m k̇wòkab֙ ʼèlò֣héy⁠ke֔m ʼàşě֥r ʻàşîyţe֖m lá⁠keֽm׃"],[5,27,"וְ⁠הִגְלֵיתִ֥י אֶתְ⁠כֶ֖ם מֵ⁠הָ֣לְאָה לְ⁠דַמָּ֑שֶׂק אָמַ֛ר יְהוָ֥ה אֱלֹהֵֽי־צְבָא֖וֹת שְׁמֽ⁠וֹ׃פ","wĕ⁠higĕléyţi֥y ʼeţĕ⁠ke֖m mé⁠há֣lĕʼáh lĕ⁠damá֑̇şêq ʼáma֛r yĕhwá֥h ʼèlòhéֽy-ẕĕbáʼ֖wòţ şĕ̌mֽ⁠wò׃p"],[6,1,"ה֚וֹי הַ⁠שַּׁאֲנַנִּ֣ים בְּ⁠צִיּ֔וֹן וְ⁠הַ⁠בֹּטְחִ֖ים בְּ⁠הַ֣ר שֹׁמְר֑וֹן נְקֻבֵי֙ רֵאשִׁ֣ית הַ⁠גּוֹיִ֔ם וּ⁠בָ֥אוּ לָ⁠הֶ֖ם בֵּ֥ית יִשְׂרָאֵֽל׃","h֚wòy ha⁠şȧ̌ʼànani֣̇ym bĕ̇⁠ẕiẏ֔wòn wĕ⁠ha⁠bò̇tĕẖi֖ym bĕ̇⁠ha֣r şò̌mĕr֑wòn nĕqubéy֙ réʼşǐ֣yţ ha⁠ġwòyi֔m ẇ⁠bá֥ʼẇ lá⁠he֖m bé֥̇yţ yişĕ̂ráʼéֽl׃"],[6,2,"עִבְר֤וּ כַֽלְנֵה֙ וּ⁠רְא֔וּ וּ⁠לְכ֥וּ מִ⁠שָּׁ֖ם חֲמַ֣ת רַבָּ֑ה וּ⁠רְד֣וּ גַת־פְּלִשְׁתּ֗ים הֲ⁠טוֹבִים֙ מִן־הַ⁠מַּמְלָכ֣וֹת הָ⁠אֵ֔לֶּה אִם־רַ֥ב גְּבוּלָ֖⁠ם מִ⁠גְּבֻלְ⁠כֶֽם׃","ʻibĕr֤ẇ kaֽlĕnéh֙ ẇ⁠rĕʼ֔ẇ ẇ⁠lĕk֥ẇ mi⁠şá֖̇̌m ẖàma֣ţ rabá֑̇h ẇ⁠rĕd֣ẇ gaţ-pĕ̇lişĕ̌ţ̇֗ym hà⁠twòbiym֙ min-ha⁠mȧmĕlák֣wòţ há⁠ʼé֔lėh ʼim-ra֥b gĕ̇bẇlá֖⁠m mi⁠gĕ̇bulĕ⁠keֽm׃"],[6,3,"הַֽ⁠מְנַדִּ֖ים לְ⁠י֣וֹם רָ֑ע וַ⁠תַּגִּישׁ֖וּ⁠ן שֶׁ֥בֶת חָמָֽס׃","haֽ⁠mĕnadi֖̇ym lĕ⁠y֣wòm rá֑ʻ wa⁠ţȧgi̇yş֖̌ẇ⁠n şě֥beţ ẖámáֽs׃"],[6,4,"הַ⁠שֹּֽׁכְבִים֙ עַל־מִטּ֣וֹת שֵׁ֔ן וּ⁠סְרֻחִ֖ים עַל־עַרְשׂוֹתָ֑⁠ם וְ⁠אֹכְלִ֤ים כָּרִים֙ מִ⁠צֹּ֔אן וַ⁠עֲגָלִ֖ים מִ⁠תּ֥וֹךְ מַרְבֵּֽק׃","ha⁠şòֽ̇̌kĕbiym֙ ʻal-miṫ֣wòţ şé̌֔n ẇ⁠sĕruẖi֖ym ʻal-ʻarĕş̂wòţá֑⁠m wĕ⁠ʼòkĕli֤ym ká̇riym֙ mi⁠ẕò̇֔ʼn wa⁠ʻàgáli֖ym mi⁠ţ֥̇wòkĕ marĕbéֽ̇q׃"],[6,5,"הַ⁠פֹּרְטִ֖ים עַל־פִּ֣י הַ⁠נָּ֑בֶל כְּ⁠דָוִ֕יד חָשְׁב֥וּ לָ⁠הֶ֖ם כְּלֵי־שִֽׁיר׃","ha⁠pò̇rĕti֖ym ʻal-pi֣̇y ha⁠ná֑̇bel kĕ̇⁠dáwi֕yd ẖáşĕ̌b֥ẇ lá⁠he֖m kĕ̇léy-şǐֽyr׃"],[6,6,"הַ⁠שֹּׁתִ֤ים בְּ⁠מִזְרְקֵי֙ יַ֔יִן וְ⁠רֵאשִׁ֥ית שְׁמָנִ֖ים יִמְשָׁ֑חוּ וְ⁠לֹ֥א נֶחְל֖וּ עַל־שֵׁ֥בֶר יוֹסֵֽף","ha⁠şò̇̌ţi֤ym bĕ̇⁠mizĕrĕqéy֙ ya֔yin wĕ⁠réʼşǐ֥yţ şĕ̌máni֖ym yimĕşá֑̌ẖẇ wĕ⁠lò֥ʼ neẖĕl֖ẇ ʻal-şé֥̌ber ywòséֽp"],[6,7,"לָ⁠כֵ֛ן עַתָּ֥ה יִגְל֖וּ בְּ⁠רֹ֣אשׁ גֹּלִ֑ים וְ⁠סָ֖ר מִרְזַ֥ח סְרוּחִֽים׃פ","lá⁠ké֛n ʻaţá֥̇h yigĕl֖ẇ bĕ̇⁠rò֣ʼş̌ gò̇li֑ym wĕ⁠sá֖r mirĕza֥ẖ sĕrẇẖiֽym׃p"],[6,8,"נִשְׁבַּע֩ אֲדֹנָ֨⁠י יְהוִ֜ה בְּ⁠נַפְשׁ֗⁠וֹ נְאֻם־יְהוָה֙ אֱלֹהֵ֣י צְבָא֔וֹת מְתָאֵ֤ב אָֽנֹכִי֙ אֶת־גְּא֣וֹן יַֽעֲקֹ֔ב וְ⁠אַרְמְנֹתָ֖י⁠ו שָׂנֵ֑אתִי וְ⁠הִסְגַּרְתִּ֖י עִ֥יר וּ⁠מְלֹאָֽ⁠הּ׃","nişĕ̌bȧʻ֩ ʼàdòná֨⁠y yĕhwi֜h bĕ̇⁠napĕş̌֗⁠wò nĕʼum-yĕhwáh֙ ʼèlòhé֣y ẕĕbáʼ֔wòţ mĕţáʼé֤b ʼáֽnòkiy֙ ʼeţ-gĕ̇ʼ֣wòn yaֽʻàqò֔b wĕ⁠ʼarĕmĕnòţá֖y⁠w şá̂né֑ʼţiy wĕ⁠hisĕgȧrĕţi֖̇y ʻi֥yr ẇ⁠mĕlòʼáֽ⁠ḣ׃"],[6,9,"וְ⁠הָיָ֗ה אִם־יִוָּ֨תְר֜וּ עֲשָׂרָ֧ה אֲנָשִׁ֛ים בְּ⁠בַ֥יִת אֶחָ֖ד וָ⁠מֵֽתוּ׃","wĕ⁠háyá֗h ʼim-yiwá̇֨ţĕr֜ẇ ʻàşá̂rá֧h ʼànáşǐ֛ym bĕ̇⁠ba֥yiţ ʼeẖá֖d wá⁠méֽţẇ׃"],[6,10,"וּ⁠נְשָׂא֞⁠וֹ דּוֹד֣⁠וֹ וּ⁠מְסָרְפ֗⁠וֹ לְ⁠הוֹצִ֣יא עֲצָמִים֮ מִן־הַ⁠בַּיִת֒ וְ⁠אָמַ֞ר לַ⁠אֲשֶׁ֨ר בְּ⁠יַרְכְּתֵ֥י הַ⁠בַּ֛יִת הַ⁠ע֥וֹד עִמָּ֖⁠ךְ וְ⁠אָמַ֣ר אָ֑פֶס וְ⁠אָמַ֣ר הָ֔ס כִּ֛י לֹ֥א לְ⁠הַזְכִּ֖יר בְּ⁠שֵׁ֥ם יְהוָֽה׃","ẇ⁠nĕşá̂ʼ֞⁠wò ḋwòd֣⁠wò ẇ⁠mĕsárĕp֗⁠wò lĕ⁠hwòẕi֣yʼ ʻàẕámiym֮ min-ha⁠bȧyiţ֒ wĕ⁠ʼáma֞r la⁠ʼàşě֨r bĕ̇⁠yarĕkĕ̇ţé֥y ha⁠bȧ֛yiţ ha⁠ʻ֥wòd ʻimá֖̇⁠kĕ wĕ⁠ʼáma֣r ʼá֑pes wĕ⁠ʼáma֣r há֔s ki֛̇y lò֥ʼ lĕ⁠hazĕki֖̇yr bĕ̇⁠şé֥̌m yĕhwáֽh׃"],[6,11,"כִּֽי־הִנֵּ֤ה יְהוָה֙ מְצַוֶּ֔ה וְ⁠הִכָּ֛ה הַ⁠בַּ֥יִת הַ⁠גָּד֖וֹל רְסִיסִ֑ים וְ⁠הַ⁠בַּ֥יִת הַ⁠קָּטֹ֖ן בְּקִעִֽים׃","kiֽ̇y-hiné֤̇h yĕhwáh֙ mĕẕawė֔h wĕ⁠hiká֛̇h ha⁠bȧ֥yiţ ha⁠gá̇d֖wòl rĕsiysi֑ym wĕ⁠ha⁠bȧ֥yiţ ha⁠qá̇tò֖n bĕ̇qiʻiֽym׃"],[6,12,"הַ⁠יְרֻצ֤וּ⁠ן בַּ⁠סֶּ֨לַע֙ סוּסִ֔ים אִֽם־יַחֲר֖וֹשׁ בַּ⁠בְּקָרִ֑ים כִּֽי־הֲפַכְתֶּ֤ם לְ⁠רֹאשׁ֙ מִשְׁפָּ֔ט וּ⁠פְרִ֥י צְדָקָ֖ה לְ⁠לַעֲנָֽה׃","ha⁠yĕruẕ֤ẇ⁠n bȧ⁠sė֨laʻ֙ sẇsi֔ym ʼiֽm-yaẖàr֖wòş̌ bȧ⁠bĕ̇qári֑ym kiֽ̇y-hàpakĕţė֤m lĕ⁠ròʼş̌֙ mişĕ̌pá̇֔t ẇ⁠pĕri֥y ẕĕdáqá֖h lĕ⁠laʻànáֽh׃"],[6,13,"הַ⁠שְּׂמֵחִ֖ים לְ⁠לֹ֣א דָבָ֑ר הָ⁠אֹ֣מְרִ֔ים הֲ⁠ל֣וֹא בְ⁠חָזְקֵ֔⁠נוּ לָקַ֥חְנוּ לָ֖⁠נוּ קַרְנָֽיִם׃","ha⁠şĕ̇̂méẖi֖ym lĕ⁠lò֣ʼ dábá֑r há⁠ʼò֣mĕri֔ym hà⁠l֣wòʼ bĕ⁠ẖázĕqé֔⁠nẇ láqa֥ẖĕnẇ lá֖⁠nẇ qarĕnáֽyim׃"],[6,14,"כִּ֡י הִנְ⁠נִי֩ מֵקִ֨ים עֲלֵי⁠כֶ֜ם בֵּ֣ית יִשְׂרָאֵ֗ל נְאֻם־יְהוָ֛ה אֱלֹהֵ֥י הַ⁠צְּבָא֖וֹת גּ֑וֹי וְ⁠לָחֲצ֥וּ אֶתְ⁠כֶ֛ם מִ⁠לְּב֥וֹא חֲמָ֖ת עַד־נַ֥חַל הָ⁠עֲרָבָֽה׃ס","ki̇֡y hinĕ⁠niy֩ méqi֨ym ʻàléy⁠ke֜m bé֣̇yţ yişĕ̂ráʼé֗l nĕʼum-yĕhwá֛h ʼèlòhé֥y ha⁠ẕĕ̇báʼ֖wòţ ġ֑wòy wĕ⁠láẖàẕ֥ẇ ʼeţĕ⁠ke֛m mi⁠lĕ̇b֥wòʼ ẖàmá֖ţ ʻad-na֥ẖal há⁠ʻàrábáֽh׃s"],[7,1,"כֹּ֤ה הִרְאַ֨⁠נִי֙ אֲדֹנָ֣⁠י יְהוִ֔ה וְ⁠הִנֵּה֙ יוֹצֵ֣ר גֹּבַ֔י בִּ⁠תְחִלַּ֖ת עֲל֣וֹת הַ⁠לָּ֑קֶשׁ וְ⁠הִ֨נֵּה־לֶ֔קֶשׁ אַחַ֖ר גִּזֵּ֥י הַ⁠מֶּֽלֶךְ׃","kò֤̇h hirĕʼa֨⁠niy֙ ʼàdòná֣⁠y yĕhwi֔h wĕ⁠hiné̇h֙ ywòẕé֣r gò̇ba֔y bi̇⁠ţĕẖilȧ֖ţ ʻàl֣wòţ ha⁠lá֑̇qeş̌ wĕ⁠hi֨né̇h-le֔qeş̌ ʼaẖa֖r gi̇zé֥̇y ha⁠mėֽlekĕ׃"],[7,2,"וְ⁠הָיָ֗ה אִם־כִּלָּה֙ לֶֽ⁠אֱכוֹל֙ אֶת־עֵ֣שֶׂב הָ⁠אָ֔רֶץ וָ⁠אֹמַ֗ר אֲדֹנָ֤⁠י יְהוִה֙ סְֽלַֽח־נָ֔א מִ֥י יָק֖וּם יַֽעֲקֹ֑ב כִּ֥י קָטֹ֖ן הֽוּא׃","wĕ⁠háyá֗h ʼim-ki̇lá̇h֙ leֽ⁠ʼèkwòl֙ ʼeţ-ʻé֣şêb há⁠ʼá֔reẕ wá⁠ʼòma֗r ʼàdòná֤⁠y yĕhwih֙ sĕֽlaֽẖ-ná֔ʼ mi֥y yáq֖ẇm yaֽʻàqò֑b ki֥̇y qátò֖n hֽẇʼ׃"],[7,3,"נִחַ֥ם יְהוָ֖ה עַל־זֹ֑את לֹ֥א תִהְיֶ֖ה אָמַ֥ר יְהוָֽה׃","niẖa֥m yĕhwá֖h ʻal-zò֑ʼţ lò֥ʼ ţihĕye֖h ʼáma֥r yĕhwáֽh׃"],[7,4,"כֹּ֤ה הִרְאַ֨⁠נִי֙ אֲדֹנָ֣⁠י יְהוִ֔ה וְ⁠הִנֵּ֥ה קֹרֵ֛א לָ⁠רִ֥ב בָּ⁠אֵ֖שׁ אֲדֹנָ֣⁠י יְהוִ֑ה וַ⁠תֹּ֨אכַל֙ אֶת־תְּה֣וֹם רַבָּ֔ה וְ⁠אָכְלָ֖ה אֶת־הַ⁠חֵֽלֶק׃","kò֤̇h hirĕʼa֨⁠niy֙ ʼàdòná֣⁠y yĕhwi֔h wĕ⁠hiné֥̇h qòré֛ʼ lá⁠ri֥b bá̇⁠ʼé֖ş̌ ʼàdòná֣⁠y yĕhwi֑h wa⁠ţò̇֨ʼkal֙ ʼeţ-ţĕ̇h֣wòm rabá̇֔h wĕ⁠ʼákĕlá֖h ʼeţ-ha⁠ẖéֽleq׃"],[7,5,"וָ⁠אֹמַ֗ר אֲדֹנָ֤⁠י יְהוִה֙ חֲדַל־נָ֔א מִ֥י יָק֖וּם יַעֲקֹ֑ב כִּ֥י קָטֹ֖ן הֽוּא׃","wá⁠ʼòma֗r ʼàdòná֤⁠y yĕhwih֙ ẖàdal-ná֔ʼ mi֥y yáq֖ẇm yaʻàqò֑b ki֥̇y qátò֖n hֽẇʼ׃"],[7,6,"נִחַ֥ם יְהוָ֖ה עַל־זֹ֑את גַּם־הִיא֙ לֹ֣א תִֽהְיֶ֔ה אָמַ֖ר אֲדֹנָ֥⁠י יְהוִֽה׃ס","niẖa֥m yĕhwá֖h ʻal-zò֑ʼţ gȧm-hiyʼ֙ lò֣ʼ ţiֽhĕye֔h ʼáma֖r ʼàdòná֥⁠y yĕhwiֽh׃s"],[7,7,"כֹּ֣ה הִרְאַ֔⁠נִי וְ⁠הִנֵּ֧ה אֲדֹנָ֛⁠י נִצָּ֖ב עַל־חוֹמַ֣ת אֲנָ֑ךְ וּ⁠בְ⁠יָד֖⁠וֹ אֲנָֽךְ׃","kò֣̇h hirĕʼa֔⁠niy wĕ⁠hiné֧̇h ʼàdòná֛⁠y niẕá֖̇b ʻal-ẖwòma֣ţ ʼàná֑kĕ ẇ⁠bĕ⁠yád֖⁠wò ʼànáֽkĕ׃"],[7,8,"וַ⁠יֹּ֨אמֶר יְהוָ֜ה אֵלַ֗⁠י מָֽה־אַתָּ֤ה רֹאֶה֙ עָמ֔וֹס וָ⁠אֹמַ֖ר אֲנָ֑ךְ וַ⁠יֹּ֣אמֶר אֲדֹנָ֗⁠י הִנְ⁠נִ֨י שָׂ֤ם אֲנָךְ֙ בְּ⁠קֶ֨רֶב֙ עַמִּ֣⁠י יִשְׂרָאֵ֔ל לֹֽא־אוֹסִ֥יף ע֖וֹד עֲב֥וֹר לֽ⁠וֹ׃","wa⁠yò̇֨ʼmer yĕhwá֜h ʼéla֗⁠y máֽh-ʼaţá֤̇h ròʼeh֙ ʻám֔wòs wá⁠ʼòma֖r ʼàná֑kĕ wa⁠yò֣̇ʼmer ʼàdòná֗⁠y hinĕ⁠ni֨y şá֤̂m ʼànákĕ֙ bĕ̇⁠qe֨reb֙ ʻami֣̇⁠y yişĕ̂ráʼé֔l lòֽʼ-ʼwòsi֥yp ʻ֖wòd ʻàb֥wòr lֽ⁠wò׃"],[7,9,"וְ⁠נָשַׁ֨מּוּ֙ בָּמ֣וֹת יִשְׂחָ֔ק וּ⁠מִקְדְּשֵׁ֥י יִשְׂרָאֵ֖ל יֶחֱרָ֑בוּ וְ⁠קַמְתִּ֛י עַל־בֵּ֥ית יָרָבְעָ֖ם בֶּ⁠חָֽרֶב׃פ","wĕ⁠náşǎ֨ṁẇ֙ bá̇m֣wòţ yişĕ̂ẖá֔q ẇ⁠miqĕdĕ̇şé֥̌y yişĕ̂ráʼé֖l yeẖèrá֑bẇ wĕ⁠qamĕţi֛̇y ʻal-bé֥̇yţ yárábĕʻá֖m bė⁠ẖáֽreb׃p"],[7,10,"וַ⁠יִּשְׁלַ֗ח אֲמַצְיָה֙ כֹּהֵ֣ן בֵּֽית־אֵ֔ל אֶל־יָרָבְעָ֥ם מֶֽלֶךְ־יִשְׂרָאֵ֖ל לֵ⁠אמֹ֑ר קָשַׁ֨ר עָלֶ֜י⁠ךָ עָמ֗וֹס בְּ⁠קֶ֨רֶב֙ בֵּ֣ית יִשְׂרָאֵ֔ל לֹא־תוּכַ֣ל הָ⁠אָ֔רֶץ לְ⁠הָכִ֖יל אֶת־כָּל־דְּבָרָֽי⁠ו׃","wa⁠yi̇şĕ̌la֗ẖ ʼàmaẕĕyáh֙ kò̇hé֣n béֽ̇yţ-ʼé֔l ʼel-yárábĕʻá֥m meֽlekĕ-yişĕ̂ráʼé֖l lé⁠ʼmò֑r qáşǎ֨r ʻále֜y⁠ká ʻám֗wòs bĕ̇⁠qe֨reb֙ bé֣̇yţ yişĕ̂ráʼé֔l lòʼ-ţẇka֣l há⁠ʼá֔reẕ lĕ⁠háki֖yl ʼeţ-ká̇l-dĕ̇báráֽy⁠w׃"],[7,11,"כִּי־כֹה֙ אָמַ֣ר עָמ֔וֹס בַּ⁠חֶ֖רֶב יָמ֣וּת יָרָבְעָ֑ם וְ⁠יִ֨שְׂרָאֵ֔ל גָּלֹ֥ה יִגְלֶ֖ה מֵ⁠עַ֥ל אַדְמָתֽ⁠וֹ׃ס","ki̇y-kòh֙ ʼáma֣r ʻám֔wòs bȧ⁠ẖe֖reb yám֣ẇţ yárábĕʻá֑m wĕ⁠yi֨şĕ̂ráʼé֔l gá̇lò֥h yigĕle֖h mé⁠ʻa֥l ʼadĕmáţֽ⁠wò׃s"],[7,12,"וַ⁠יֹּ֤אמֶר אֲמַצְיָה֙ אֶל־עָמ֔וֹס חֹזֶ֕ה לֵ֥ךְ בְּרַח־לְ⁠ךָ֖ אֶל־אֶ֣רֶץ יְהוּדָ֑ה וֶ⁠אֱכָל־שָׁ֣ם לֶ֔חֶם וְ⁠שָׁ֖ם תִּנָּבֵֽא׃","wa⁠yò֤̇ʼmer ʼàmaẕĕyáh֙ ʼel-ʻám֔wòs ẖòze֕h lé֥kĕ bĕ̇raẖ-lĕ⁠ká֖ ʼel-ʼe֣reẕ yĕhẇdá֑h we⁠ʼèkál-şá֣̌m le֔ẖem wĕ⁠şá֖̌m ţi̇ná̇béֽʼ׃"],[7,13,"וּ⁠בֵֽית־אֵ֔ל לֹֽא־תוֹסִ֥יף ע֖וֹד לְ⁠הִנָּבֵ֑א כִּ֤י מִקְדַּשׁ־מֶ֨לֶךְ֙ ה֔וּא וּ⁠בֵ֥ית מַמְלָכָ֖ה הֽוּא׃ס","ẇ⁠béֽyţ-ʼé֔l lòֽʼ-ţwòsi֥yp ʻ֖wòd lĕ⁠hiná̇bé֑ʼ ki֤̇y miqĕdȧş̌-me֨lekĕ֙ h֔ẇʼ ẇ⁠bé֥yţ mamĕláká֖h hֽẇʼ׃s"],[7,14,"וַ⁠יַּ֤עַן עָמוֹס֙ וַ⁠יֹּ֣אמֶר אֶל־אֲמַצְיָ֔ה לֹא־נָבִ֣יא אָנֹ֔כִי וְ⁠לֹ֥א בֶן־נָבִ֖יא אָנֹ֑כִי כִּֽי־בוֹקֵ֥ר אָנֹ֖כִי וּ⁠בוֹלֵ֥ס שִׁקְמִֽים׃","wa⁠yȧ֤ʻan ʻámwòs֙ wa⁠yò֣̇ʼmer ʼel-ʼàmaẕĕyá֔h lòʼ-nábi֣yʼ ʼánò֔kiy wĕ⁠lò֥ʼ ben-nábi֖yʼ ʼánò֑kiy kiֽ̇y-bwòqé֥r ʼánò֖kiy ẇ⁠bwòlé֥s şǐqĕmiֽym׃"],[7,15,"וַ⁠יִּקָּחֵ֣⁠נִי יְהוָ֔ה מֵ⁠אַחֲרֵ֖י הַ⁠צֹּ֑אן וַ⁠יֹּ֤אמֶר אֵלַ⁠י֙ יְהוָ֔ה לֵ֥ךְ הִנָּבֵ֖א אֶל־עַמִּ֥⁠י יִשְׂרָאֵֽל׃","wa⁠yi̇qá̇ẖé֣⁠niy yĕhwá֔h mé⁠ʼaẖàré֖y ha⁠ẕò֑̇ʼn wa⁠yò֤̇ʼmer ʼéla⁠y֙ yĕhwá֔h lé֥kĕ hiná̇bé֖ʼ ʼel-ʻami֥̇⁠y yişĕ̂ráʼéֽl׃"],[7,16,"וְ⁠עַתָּ֖ה שְׁמַ֣ע דְּבַר־יְהוָ֑ה אַתָּ֣ה אֹמֵ֗ר לֹ֤א תִנָּבֵא֙ עַל־יִשְׂרָאֵ֔ל וְ⁠לֹ֥א תַטִּ֖יף עַל־בֵּ֥ית יִשְׂחָֽק׃","wĕ⁠ʻaţá֖̇h şĕ̌ma֣ʻ dĕ̇bar-yĕhwá֑h ʼaţá֣̇h ʼòmé֗r lò֤ʼ ţiná̇béʼ֙ ʻal-yişĕ̂ráʼé֔l wĕ⁠lò֥ʼ ţati֖̇yp ʻal-bé֥̇yţ yişĕ̂ẖáֽq׃"],[7,17,"לָ⁠כֵ֞ן כֹּה־אָמַ֣ר יְהוָ֗ה אִשְׁתְּ⁠ךָ֞ בָּ⁠עִ֤יר תִּזְנֶה֙ וּ⁠בָנֶ֤י⁠ךָ וּ⁠בְנֹתֶ֨י⁠ךָ֙ בַּ⁠חֶ֣רֶב יִפֹּ֔לוּ וְ⁠אַדְמָתְ⁠ךָ֖ בַּ⁠חֶ֣בֶל תְּחֻלָּ֑ק וְ⁠אַתָּ֗ה עַל־אֲדָמָ֤ה טְמֵאָה֙ תָּמ֔וּת וְ⁠יִ֨שְׂרָאֵ֔ל גָּלֹ֥ה יִגְלֶ֖ה מֵ⁠עַ֥ל אַדְמָתֽ⁠וֹ׃ס","lá⁠ké֞n kò̇h-ʼáma֣r yĕhwá֗h ʼişĕ̌ţĕ̇⁠ká֞ bá̇⁠ʻi֤yr ţi̇zĕneh֙ ẇ⁠báne֤y⁠ká ẇ⁠bĕnòţe֨y⁠ká֙ bȧ⁠ẖe֣reb yipò̇֔lẇ wĕ⁠ʼadĕmáţĕ⁠ká֖ bȧ⁠ẖe֣bel ţĕ̇ẖulá֑̇q wĕ⁠ʼaţá̇֗h ʻal-ʼàdámá֤h tĕméʼáh֙ ţá̇m֔ẇţ wĕ⁠yi֨şĕ̂ráʼé֔l gá̇lò֥h yigĕle֖h mé⁠ʻa֥l ʼadĕmáţֽ⁠wò׃s"],[8,1,"כֹּ֥ה הִרְאַ֖⁠נִי אֲדֹנָ֣⁠י יְהוִ֑ה וְ⁠הִנֵּ֖ה כְּל֥וּב קָֽיִץ׃","kò֥̇h hirĕʼa֖⁠niy ʼàdòná֣⁠y yĕhwi֑h wĕ⁠hiné֖̇h kĕ̇l֥ẇb qáֽyiẕ׃"],[8,2,"וַ⁠יֹּ֗אמֶר מָֽה־אַתָּ֤ה רֹאֶה֙ עָמ֔וֹס וָ⁠אֹמַ֖ר כְּל֣וּב קָ֑יִץ וַ⁠יֹּ֨אמֶר יְהוָ֜ה אֵלַ֗⁠י בָּ֤א הַ⁠קֵּץ֙ אֶל־עַמִּ֣⁠י יִשְׂרָאֵ֔ל לֹא־אוֹסִ֥יף ע֖וֹד עֲב֥וֹר לֽ⁠וֹ׃","wa⁠yò̇֗ʼmer máֽh-ʼaţá֤̇h ròʼeh֙ ʻám֔wòs wá⁠ʼòma֖r kĕ̇l֣ẇb qá֑yiẕ wa⁠yò̇֨ʼmer yĕhwá֜h ʼéla֗⁠y bá֤̇ʼ ha⁠qé̇ẕ֙ ʼel-ʻami֣̇⁠y yişĕ̂ráʼé֔l lòʼ-ʼwòsi֥yp ʻ֖wòd ʻàb֥wòr lֽ⁠wò׃"],[8,3,"וְ⁠הֵילִ֜ילוּ שִׁיר֤וֹת הֵיכָל֙ בַּ⁠יּ֣וֹם הַ⁠ה֔וּא נְאֻ֖ם אֲדֹנָ֣⁠י יְהוִ֑ה רַ֣ב הַ⁠פֶּ֔גֶר בְּ⁠כָל־מָק֖וֹם הִשְׁלִ֥יךְ הָֽס׃פ","wĕ⁠héyli֜ylẇ şǐyr֤wòţ héykál֙ bȧ⁠ẏ֣wòm ha⁠h֔ẇʼ nĕʼu֖m ʼàdòná֣⁠y yĕhwi֑h ra֣b ha⁠pė֔ger bĕ̇⁠kál-máq֖wòm hişĕ̌li֥ykĕ háֽs׃p"],[8,4,"שִׁמְעוּ־זֹ֕את הַ⁠שֹּׁאֲפִ֖ים אֶבְי֑וֹן וְ⁠לַ⁠שְׁבִּ֖ית ענוי־אָֽרֶץ׃","şǐmĕʻẇ-zò֕ʼţ ha⁠şò̇̌ʼàpi֖ym ʼebĕy֑wòn wĕ⁠la⁠şĕ̌bi֖̇yţ ʻnwy-ʼáֽreẕ׃"],[8,5,"לֵ⁠אמֹ֗ר מָתַ֞י יַעֲבֹ֤ר הַ⁠חֹ֨דֶשׁ֙ וְ⁠נַשְׁבִּ֣ירָה שֶּׁ֔בֶר וְ⁠הַ⁠שַּׁבָּ֖ת וְ⁠נִפְתְּחָה־בָּ֑ר לְ⁠הַקְטִ֤ין אֵיפָה֙ וּ⁠לְ⁠הַגְדִּ֣יל שֶׁ֔קֶל וּ⁠לְ⁠עַוֵּ֖ת מֹאזְנֵ֥י מִרְמָֽה׃","lé⁠ʼmò֗r máţa֞y yaʻàbò֤r ha⁠ẖò֨deş̌֙ wĕ⁠naşĕ̌bi֣̇yráh şė̌֔ber wĕ⁠ha⁠şȧ̌bá֖̇ţ wĕ⁠nipĕţĕ̇ẖáh-bá֑̇r lĕ⁠haqĕti֤yn ʼéypáh֙ ẇ⁠lĕ⁠hagĕdi֣̇yl şě֔qel ẇ⁠lĕ⁠ʻawé֖̇ţ mòʼzĕné֥y mirĕmáֽh׃"],[8,6,"לִ⁠קְנ֤וֹת בַּ⁠כֶּ֨סֶף֙ דַּלִּ֔ים וְ⁠אֶבְי֖וֹן בַּ⁠עֲב֣וּר נַעֲלָ֑יִם וּ⁠מַפַּ֥ל בַּ֖ר נַשְׁבִּֽיר׃","li⁠qĕn֤wòţ bȧ⁠kė֨sep֙ dȧli̇֔ym wĕ⁠ʼebĕy֖wòn bȧ⁠ʻàb֣ẇr naʻàlá֑yim ẇ⁠mapȧ֥l bȧ֖r naşĕ̌biֽ̇yr׃"],[8,7,"נִשְׁבַּ֥ע יְהוָ֖ה בִּ⁠גְא֣וֹן יַעֲקֹ֑ב אִם־אֶשְׁכַּ֥ח לָ⁠נֶ֖צַח כָּל־מַעֲשֵׂי⁠הֶֽם׃","nişĕ̌bȧ֥ʻ yĕhwá֖h bi̇⁠gĕʼ֣wòn yaʻàqò֑b ʼim-ʼeşĕ̌kȧ֥ẖ lá⁠ne֖ẕaẖ ká̇l-maʻàşé̂y⁠heֽm׃"],[8,8,"הַ֤⁠עַל זֹאת֙ לֹֽא־תִרְגַּ֣ז הָ⁠אָ֔רֶץ וְ⁠אָבַ֖ל כָּל־יוֹשֵׁ֣ב בָּ֑⁠הּ וְ⁠עָלְתָ֤ה כָ⁠אֹר֙ כֻּלָּ֔⁠הּ וְ⁠נִגְרְשָׁ֥ה ו⁠נשקה כִּ⁠יא֥וֹר מִצְרָֽיִם׃ס","ha֤⁠ʻal zòʼţ֙ lòֽʼ-ţirĕgȧ֣z há⁠ʼá֔reẕ wĕ⁠ʼába֖l ká̇l-ywòşé֣̌b bá֑̇⁠ḣ wĕ⁠ʻálĕţá֤h ká⁠ʼòr֙ ku̇lá̇֔⁠ḣ wĕ⁠nigĕrĕşá֥̌h w⁠nşqh ki̇⁠yʼ֥wòr miẕĕráֽyim׃s"],[8,9,"וְ⁠הָיָ֣ה ׀ בַּ⁠יּ֣וֹם הַ⁠ה֗וּא נְאֻם֙ אֲדֹנָ֣⁠י יְהוִ֔ה וְ⁠הֵבֵאתִ֥י הַ⁠שֶּׁ֖מֶשׁ בַּֽ⁠צָּהֳרָ֑יִם וְ⁠הַחֲשַׁכְתִּ֥י לָ⁠אָ֖רֶץ בְּ⁠י֥וֹם אֽוֹר׃","wĕ⁠háyá֣h ׀ bȧ⁠ẏ֣wòm ha⁠h֗ẇʼ nĕʼum֙ ʼàdòná֣⁠y yĕhwi֔h wĕ⁠hébéʼţi֥y ha⁠şė֖̌meş̌ bȧֽ⁠ẕá̇horá֑yim wĕ⁠haẖàşǎkĕţi֥̇y lá⁠ʼá֖reẕ bĕ̇⁠y֥wòm ʼֽwòr׃"],[8,10,"וְ⁠הָפַכְתִּ֨י חַגֵּי⁠כֶ֜ם לְ⁠אֵ֗בֶל וְ⁠כָל־שִֽׁירֵי⁠כֶם֙ לְ⁠קִינָ֔ה וְ⁠הַעֲלֵיתִ֤י עַל־כָּל־מָתְנַ֨יִם֙ שָׂ֔ק וְ⁠עַל־כָּל־רֹ֖אשׁ קָרְחָ֑ה וְ⁠שַׂמְתִּ֨י⁠הָ֙ כְּ⁠אֵ֣בֶל יָחִ֔יד וְ⁠אַחֲרִיתָ֖⁠הּ כְּ⁠י֥וֹם מָֽר׃","wĕ⁠hápakĕţi̇֨y ẖagé̇y⁠ke֜m lĕ⁠ʼé֗bel wĕ⁠kál-şǐֽyréy⁠kem֙ lĕ⁠qiyná֔h wĕ⁠haʻàléyţi֤y ʻal-ká̇l-máţĕna֨yim֙ şá̂֔q wĕ⁠ʻal-ká̇l-rò֖ʼş̌ qárĕẖá֑h wĕ⁠şâmĕţi̇֨y⁠há֙ kĕ̇⁠ʼé֣bel yáẖi֔yd wĕ⁠ʼaẖàriyţá֖⁠ḣ kĕ̇⁠y֥wòm máֽr׃"],[8,11,"הִנֵּ֣ה ׀ יָמִ֣ים בָּאִ֗ים נְאֻם֙ אֲדֹנָ֣⁠י יְהוִ֔ה וְ⁠הִשְׁלַחְתִּ֥י רָעָ֖ב בָּ⁠אָ֑רֶץ לֹֽא־רָעָ֤ב לַ⁠לֶּ֨חֶם֙ וְ⁠לֹֽא־צָמָ֣א לַ⁠מַּ֔יִם כִּ֣י אִם־לִ⁠שְׁמֹ֔עַ אֵ֖ת דִּבְרֵ֥י יְהוָֽה׃","hiné֣̇h ׀ yámi֣ym bá̇ʼi֗ym nĕʼum֙ ʼàdòná֣⁠y yĕhwi֔h wĕ⁠hişĕ̌laẖĕţi֥̇y ráʻá֖b bá̇⁠ʼá֑reẕ lòֽʼ-ráʻá֤b la⁠lė֨ẖem֙ wĕ⁠lòֽʼ-ẕámá֣ʼ la⁠mȧ֔yim ki֣̇y ʼim-li⁠şĕ̌mò֔ʻa ʼé֖ţ di̇bĕré֥y yĕhwáֽh׃"],[8,12,"וְ⁠נָעוּ֙ מִ⁠יָּ֣ם עַד־יָ֔ם וּ⁠מִ⁠צָּפ֖וֹן וְ⁠עַד־מִזְרָ֑ח יְשֽׁוֹטְט֛וּ לְ⁠בַקֵּ֥שׁ אֶת־דְּבַר־יְהוָ֖ה וְ⁠לֹ֥א יִמְצָֽאוּ׃","wĕ⁠náʻẇ֙ mi⁠yá֣̇m ʻad-yá֔m ẇ⁠mi⁠ẕá̇p֖wòn wĕ⁠ʻad-mizĕrá֑ẖ yĕşֽ̌wòtĕt֛ẇ lĕ⁠baqé֥̇ş̌ ʼeţ-dĕ̇bar-yĕhwá֖h wĕ⁠lò֥ʼ yimĕẕáֽʼẇ׃"],[8,13,"בַּ⁠יּ֨וֹם הַ⁠ה֜וּא תִּ֠תְעַלַּפְנָה הַ⁠בְּתוּלֹ֧ת הַ⁠יָּפ֛וֹת וְ⁠הַ⁠בַּחוּרִ֖ים בַּ⁠צָּמָֽא׃","bȧ⁠ẏ֨wòm ha⁠h֜ẇʼ ţi̇֠ţĕʻalȧpĕnáh ha⁠bĕ̇ţẇlò֧ţ ha⁠yá̇p֛wòţ wĕ⁠ha⁠bȧẖẇri֖ym bȧ⁠ẕá̇máֽʼ׃"],[8,14,"הַ⁠נִּשְׁבָּעִים֙ בְּ⁠אַשְׁמַ֣ת שֹֽׁמְר֔וֹן וְ⁠אָמְר֗וּ חֵ֤י אֱלֹהֶ֨י⁠ךָ֙ דָּ֔ן וְ⁠חֵ֖י דֶּ֣רֶךְ בְּאֵֽר־שָׁ֑בַע וְ⁠נָפְל֖וּ וְ⁠לֹא־יָק֥וּמוּ עֽוֹד׃ס","ha⁠ni̇şĕ̌bá̇ʻiym֙ bĕ̇⁠ʼaşĕ̌ma֣ţ şòֽ̌mĕr֔wòn wĕ⁠ʼámĕr֗ẇ ẖé֤y ʼèlòhe֨y⁠ká֙ dá̇֔n wĕ⁠ẖé֖y dė֣rekĕ bĕ̇ʼéֽr-şá֑̌baʻ wĕ⁠nápĕl֖ẇ wĕ⁠lòʼ-yáq֥ẇmẇ ʻֽwòd׃s"],[9,1,"רָאִ֨יתִי אֶת־אֲדֹנָ֜⁠י נִצָּ֣ב עַֽל־הַ⁠מִּזְבֵּ֗חַ וַ⁠יֹּאמֶר֩ הַ֨ךְ הַ⁠כַּפְתּ֜וֹר וְ⁠יִרְעֲשׁ֣וּ הַ⁠סִּפִּ֗ים וּ⁠בְצַ֨עַ⁠ם֙ בְּ⁠רֹ֣אשׁ כֻּלָּ֔⁠ם וְ⁠אַחֲרִיתָ֖⁠ם בַּ⁠חֶ֣רֶב אֶהֱרֹ֑ג לֹֽא־יָנ֤וּס לָ⁠הֶם֙ נָ֔ס וְ⁠לֹֽא־יִמָּלֵ֥ט לָ⁠הֶ֖ם פָּלִֽיט׃","ráʼi֨yţiy ʼeţ-ʼàdòná֜⁠y niẕá֣̇b ʻaֽl-ha⁠mi̇zĕbé̇֗ẖa wa⁠yò̇ʼmer֩ ha֨kĕ ha⁠kȧpĕţ̇֜wòr wĕ⁠yirĕʻàş֣̌ẇ ha⁠si̇pi̇֗ym ẇ⁠bĕẕa֨ʻa⁠m֙ bĕ̇⁠rò֣ʼş̌ ku̇lá̇֔⁠m wĕ⁠ʼaẖàriyţá֖⁠m bȧ⁠ẖe֣reb ʼehèrò֑g lòֽʼ-yán֤ẇs lá⁠hem֙ ná֔s wĕ⁠lòֽʼ-yimá̇lé֥t lá⁠he֖m pá̇liֽyt׃"],[9,2,"אִם־יַחְתְּר֣וּ בִ⁠שְׁא֔וֹל מִ⁠שָּׁ֖ם יָדִ֣⁠י תִקָּחֵ֑⁠ם וְ⁠אִֽם־יַעֲלוּ֙ הַ⁠שָּׁמַ֔יִם מִ⁠שָּׁ֖ם אוֹרִידֵֽ⁠ם׃","ʼim-yaẖĕţĕ̇r֣ẇ bi⁠şĕ̌ʼ֔wòl mi⁠şá֖̇̌m yádi֣⁠y ţiqá̇ẖé֑⁠m wĕ⁠ʼiֽm-yaʻàlẇ֙ ha⁠şá̇̌ma֔yim mi⁠şá֖̇̌m ʼwòriydéֽ⁠m׃"],[9,3,"וְ⁠אִם־יֵחָֽבְאוּ֙ בְּ⁠רֹ֣אשׁ הַ⁠כַּרְמֶ֔ל מִ⁠שָּׁ֥ם אֲחַפֵּ֖שׂ וּ⁠לְקַחְתִּ֑י⁠ם וְ⁠אִם־יִסָּ֨תְר֜וּ מִ⁠נֶּ֤גֶד עֵינַ⁠י֙ בְּ⁠קַרְקַ֣ע הַ⁠יָּ֔ם מִ⁠שָּׁ֛ם אֲצַוֶּ֥ה אֶת־הַ⁠נָּחָ֖שׁ וּ⁠נְשָׁכָֽ⁠ם׃","wĕ⁠ʼim-yéẖáֽbĕʼẇ֙ bĕ̇⁠rò֣ʼş̌ ha⁠kȧrĕme֔l mi⁠şá֥̇̌m ʼàẖapé֖̇ş̂ ẇ⁠lĕqaẖĕţi֑̇y⁠m wĕ⁠ʼim-yisá̇֨ţĕr֜ẇ mi⁠nė֤ged ʻéyna⁠y֙ bĕ̇⁠qarĕqa֣ʻ ha⁠yá̇֔m mi⁠şá֛̇̌m ʼàẕawė֥h ʼeţ-ha⁠ná̇ẖá֖ş̌ ẇ⁠nĕşá̌káֽ⁠m׃"],[9,4,"וְ⁠אִם־יֵלְכ֤וּ בַ⁠שְּׁבִי֙ לִ⁠פְנֵ֣י אֹֽיבֵי⁠הֶ֔ם מִ⁠שָּׁ֛ם אֲצַוֶּ֥ה אֶת־הַ⁠חֶ֖רֶב וַ⁠הֲרָגָ֑תַ⁠ם וְ⁠שַׂמְתִּ֨י עֵינִ֧⁠י עֲלֵי⁠הֶ֛ם לְ⁠רָעָ֖ה וְ⁠לֹ֥א לְ⁠טוֹבָֽה׃","wĕ⁠ʼim-yélĕk֤ẇ ba⁠şĕ̇̌biy֙ li⁠pĕné֣y ʼòֽybéy⁠he֔m mi⁠şá֛̇̌m ʼàẕawė֥h ʼeţ-ha⁠ẖe֖reb wa⁠hàrágá֑ţa⁠m wĕ⁠şâmĕţi̇֨y ʻéyni֧⁠y ʻàléy⁠he֛m lĕ⁠ráʻá֖h wĕ⁠lò֥ʼ lĕ⁠twòbáֽh׃"],[9,5,"וַ⁠אדֹנָ֨⁠י יְהוִ֜ה הַ⁠צְּבָא֗וֹת הַ⁠נּוֹגֵ֤עַ בָּ⁠אָ֨רֶץ֙ וַ⁠תָּמ֔וֹג וְ⁠אָבְל֖וּ כָּל־י֣וֹשְׁבֵי בָ֑⁠הּ וְ⁠עָלְתָ֤ה כַ⁠יְאֹר֙ כֻּלָּ֔⁠הּ וְ⁠שָׁקְעָ֖ה כִּ⁠יאֹ֥ר מִצְרָֽיִם","wa⁠ʼdòná֨⁠y yĕhwi֜h ha⁠ẕĕ̇báʼ֗wòţ ha⁠ṅwògé֤ʻa bá̇⁠ʼá֨reẕ֙ wa⁠ţá̇m֔wòg wĕ⁠ʼábĕl֖ẇ ká̇l-y֣wòşĕ̌béy bá֑⁠ḣ wĕ⁠ʻálĕţá֤h ka⁠yĕʼòr֙ ku̇lá̇֔⁠ḣ wĕ⁠şá̌qĕʻá֖h ki̇⁠yʼò֥r miẕĕráֽyim"],[9,6,"הַ⁠בּוֹנֶ֤ה בַ⁠שָּׁמַ֨יִם֙ מעלות⁠ו וַ⁠אֲגֻדָּת֖⁠וֹ עַל־אֶ֣רֶץ יְסָדָ֑⁠הּ הַ⁠קֹּרֵ֣א לְ⁠מֵֽי־הַ⁠יָּ֗ם וַֽ⁠יִּשְׁפְּכֵ֛⁠ם עַל־פְּנֵ֥י הָ⁠אָ֖רֶץ יְהוָ֥ה שְׁמֽ⁠וֹ׃","ha⁠ḃwòne֤h ba⁠şá̇̌ma֨yim֙ mʻlwţ⁠w wa⁠ʼàgudá̇ţ֖⁠wò ʻal-ʼe֣reẕ yĕsádá֑⁠ḣ ha⁠qò̇ré֣ʼ lĕ⁠méֽy-ha⁠yá̇֗m waֽ⁠yi̇şĕ̌pĕ̇ké֛⁠m ʻal-pĕ̇né֥y há⁠ʼá֖reẕ yĕhwá֥h şĕ̌mֽ⁠wò׃"],[9,7,"הֲ⁠ל֣וֹא כִ⁠בְנֵי֩ כֻשִׁיִּ֨ים אַתֶּ֥ם לִ֛⁠י בְּנֵ֥י יִשְׂרָאֵ֖ל נְאֻם־יְהוָ֑ה הֲ⁠ל֣וֹא אֶת־יִשְׂרָאֵ֗ל הֶעֱלֵ֨יתִי֙ מֵ⁠אֶ֣רֶץ מִצְרַ֔יִם וּ⁠פְלִשְׁתִּיִּ֥ים מִ⁠כַּפְתּ֖וֹר וַ⁠אֲרָ֥ם מִ⁠קִּֽיר׃","hà⁠l֣wòʼ ki⁠bĕnéy֩ kuşǐyi̇֨ym ʼaţė֥m li֛⁠y bĕ̇né֥y yişĕ̂ráʼé֖l nĕʼum-yĕhwá֑h hà⁠l֣wòʼ ʼeţ-yişĕ̂ráʼé֗l heʻèlé֨yţiy֙ mé⁠ʼe֣reẕ miẕĕra֔yim ẇ⁠pĕlişĕ̌ţi̇yi֥̇ym mi⁠kȧpĕţ֖̇wòr wa⁠ʼàrá֥m mi⁠qiֽ̇yr׃"],[9,8,"הִנֵּ֞ה עֵינֵ֣י ׀ אֲדֹנָ֣⁠י יְהוִ֗ה בַּ⁠מַּמְלָכָה֙ הַֽ⁠חַטָּאָ֔ה וְ⁠הִשְׁמַדְתִּ֣י אֹתָ֔⁠הּ מֵ⁠עַ֖ל פְּנֵ֣י הָ⁠אֲדָמָ֑ה אֶ֗פֶס כִּ֠י לֹ֣א הַשְׁמֵ֥יד אַשְׁמִ֛יד אֶת־בֵּ֥ית יַעֲקֹ֖ב נְאֻם־יְהוָֽה׃","hiné̇֞h ʻéyné֣y ׀ ʼàdòná֣⁠y yĕhwi֗h bȧ⁠mȧmĕlákáh֙ haֽ⁠ẖatá̇ʼá֔h wĕ⁠hişĕ̌madĕţi֣̇y ʼòţá֔⁠ḣ mé⁠ʻa֖l pĕ̇né֣y há⁠ʼàdámá֑h ʼe֗pes ki̇֠y lò֣ʼ haşĕ̌mé֥yd ʼaşĕ̌mi֛yd ʼeţ-bé֥̇yţ yaʻàqò֖b nĕʼum-yĕhwáֽh׃"],[9,9,"כִּֽי־הִנֵּ֤ה אָֽנֹכִי֙ מְצַוֶּ֔ה וַ⁠הֲנִע֥וֹתִי בְ⁠כָֽל־הַ⁠גּוֹיִ֖ם אֶת־בֵּ֣ית יִשְׂרָאֵ֑ל כַּ⁠אֲשֶׁ֤ר יִנּ֨וֹעַ֙ בַּ⁠כְּבָרָ֔ה וְ⁠לֹֽא־יִפּ֥וֹל צְר֖וֹר אָֽרֶץ׃","kiֽ̇y-hiné֤̇h ʼáֽnòkiy֙ mĕẕawė֔h wa⁠hàniʻ֥wòţiy bĕ⁠káֽl-ha⁠ġwòyi֖m ʼeţ-bé֣̇yţ yişĕ̂ráʼé֑l kȧ⁠ʼàşě֤r yiṅ֨wòʻa֙ bȧ⁠kĕ̇bárá֔h wĕ⁠lòֽʼ-yiṗ֥wòl ẕĕr֖wòr ʼáֽreẕ׃"],[9,10,"בַּ⁠חֶ֣רֶב יָמ֔וּתוּ כֹּ֖ל חַטָּאֵ֣י עַמִּ֑⁠י הָ⁠אֹמְרִ֗ים לֹֽא־תַגִּ֧ישׁ וְ⁠תַקְדִּ֛ים בַּעֲדֵ֖י⁠נוּ הָ⁠רָעָֽה׃","bȧ⁠ẖe֣reb yám֔ẇţẇ kò֖̇l ẖatá̇ʼé֣y ʻami֑̇⁠y há⁠ʼòmĕri֗ym lòֽʼ-ţagi֧̇yş̌ wĕ⁠ţaqĕdi֛̇ym bȧʻàdé֖y⁠nẇ há⁠ráʻáֽh׃"],[9,11,"בַּ⁠יּ֣וֹם הַ⁠ה֔וּא אָקִ֛ים אֶת־סֻכַּ֥ת דָּוִ֖יד הַ⁠נֹּפֶ֑לֶת וְ⁠גָדַרְתִּ֣י אֶת־פִּרְצֵי⁠הֶ֗ן וַ⁠הֲרִֽסֹתָי⁠ו֙ אָקִ֔ים וּ⁠בְנִיתִ֖י⁠הָ כִּ⁠ימֵ֥י עוֹלָֽם׃","bȧ⁠ẏ֣wòm ha⁠h֔ẇʼ ʼáqi֛ym ʼeţ-sukȧ֥ţ dá̇wi֖yd ha⁠nò̇pe֑leţ wĕ⁠gádarĕţi֣̇y ʼeţ-pi̇rĕẕéy⁠he֗n wa⁠hàriֽsòţáy⁠w֙ ʼáqi֔ym ẇ⁠bĕniyţi֖y⁠há ki̇⁠ymé֥y ʻwòláֽm׃"],[9,12,"לְמַ֨עַן יִֽירְשׁ֜וּ אֶת־שְׁאֵרִ֤ית אֱדוֹם֙ וְ⁠כָל־הַ⁠גּוֹיִ֔ם אֲשֶׁר־נִקְרָ֥א שְׁמִ֖⁠י עֲלֵי⁠הֶ֑ם נְאֻם־יְהוָ֖ה עֹ֥שֶׂה זֹּֽאת׃פ","lĕma֨ʻan yiֽyrĕş̌֜ẇ ʼeţ-şĕ̌ʼéri֤yţ ʼèdwòm֙ wĕ⁠kál-ha⁠ġwòyi֔m ʼàşěr-niqĕrá֥ʼ şĕ̌mi֖⁠y ʻàléy⁠he֑m nĕʼum-yĕhwá֖h ʻò֥şêh zòֽ̇ʼţ׃p"],[9,13,"הִנֵּ֨ה יָמִ֤ים בָּאִים֙ נְאֻם־יְהוָ֔ה וְ⁠נִגַּ֤שׁ חוֹרֵשׁ֙ בַּ⁠קֹּצֵ֔ר וְ⁠דֹרֵ֥ךְ עֲנָבִ֖ים בְּ⁠מֹשֵׁ֣ךְ הַ⁠זָּ֑רַע וְ⁠הִטִּ֤יפוּ הֶֽ⁠הָרִים֙ עָסִ֔יס וְ⁠כָל־הַ⁠גְּבָע֖וֹת תִּתְמוֹגַֽגְנָה׃","hiné̇֨h yámi֤ym bá̇ʼiym֙ nĕʼum-yĕhwá֔h wĕ⁠nigȧ֤ş̌ ẖwòréş̌֙ bȧ⁠qò̇ẕé֔r wĕ⁠dòré֥kĕ ʻànábi֖ym bĕ̇⁠mòşé֣̌kĕ ha⁠zá֑̇raʻ wĕ⁠hiti֤̇ypẇ heֽ⁠háriym֙ ʻási֔ys wĕ⁠kál-ha⁠gĕ̇báʻ֖wòţ ţi̇ţĕmwògaֽgĕnáh׃"],[9,14,"וְ⁠שַׁבְתִּי֮ אֶת־שְׁב֣וּת עַמִּ֣⁠י יִשְׂרָאֵל֒ וּ⁠בָנ֞וּ עָרִ֤ים נְשַׁמּוֹת֙ וְ⁠יָשָׁ֔בוּ וְ⁠נָטְע֣וּ כְרָמִ֔ים וְ⁠שָׁת֖וּ אֶת־יֵינָ֑⁠ם וְ⁠עָשׂ֣וּ גַנּ֔וֹת וְ⁠אָכְל֖וּ אֶת־פְּרִי⁠הֶֽם׃","wĕ⁠şǎbĕţi̇y֮ ʼeţ-şĕ̌b֣ẇţ ʻami֣̇⁠y yişĕ̂ráʼél֒ ẇ⁠bán֞ẇ ʻári֤ym nĕşǎṁwòţ֙ wĕ⁠yáşá̌֔bẇ wĕ⁠nátĕʻ֣ẇ kĕrámi֔ym wĕ⁠şá̌ţ֖ẇ ʼeţ-yéyná֑⁠m wĕ⁠ʻáş֣̂ẇ gaṅ֔wòţ wĕ⁠ʼákĕl֖ẇ ʼeţ-pĕ̇riy⁠heֽm׃"],[9,15,"וּ⁠נְטַעְתִּ֖י⁠ם עַל־אַדְמָתָ֑⁠ם וְ⁠לֹ֨א יִנָּתְשׁ֜וּ ע֗וֹד מֵ⁠עַ֤ל אַדְמָתָ⁠ם֙ אֲשֶׁ֣ר נָתַ֣תִּי לָ⁠הֶ֔ם אָמַ֖ר יְהוָ֥ה אֱלֹהֶֽי⁠ךָ׃","ẇ⁠nĕtaʻĕţi֖̇y⁠m ʻal-ʼadĕmáţá֑⁠m wĕ⁠lò֨ʼ yiná̇ţĕş̌֜ẇ ʻ֗wòd mé⁠ʻa֤l ʼadĕmáţá⁠m֙ ʼàşě֣r náţa֣ţi̇y lá⁠he֔m ʼáma֖r yĕhwá֥h ʼèlòheֽy⁠ká׃"]],"fra-lsg1910":[[1,1,"Paroles d'Amos, l'un des bergers de Tekoa, visions qu'il eut sur Israël, au temps d'Ozias, roi de Juda, et au temps de Jéroboam, fils de Joas, roi d'Israël, deux ans avant le tremblement de terre.","Paroles d'Amos, l'un des bergers de Tekoa, visions qu'il eut sur Israël, au temps d'Ozias, roi de Juda, et au temps de Jéroboam, fils de Joas, roi d'Israël, deux ans avant le tremblement de terre."],[1,2,"Il dit: De Sion l'Éternel rugit, De Jérusalem il fait entendre sa voix. Les pâturages des bergers sont dans le deuil, Et le sommet du Carmel est desséché.","Il dit: De Sion l'Éternel rugit, De Jérusalem il fait entendre sa voix. Les pâturages des bergers sont dans le deuil, Et le sommet du Carmel est desséché."],[1,3,"Ainsi parle l'Éternel: À cause de trois crimes de Damas, Même de quatre, je ne révoque pas mon arrêt, Parce qu'ils ont foulé Galaad sous des traîneaux de fer.","Ainsi parle l'Éternel: À cause de trois crimes de Damas, Même de quatre, je ne révoque pas mon arrêt, Parce qu'ils ont foulé Galaad sous des traîneaux de fer."],[1,4,"J'enverrai le feu dans la maison de Hazaël, Et il dévorera les palais de Ben-Hadad.","J'enverrai le feu dans la maison de Hazaël, Et il dévorera les palais de Ben-Hadad."],[1,5,"Je briserai les verrous de Damas, J'exterminerai de Bikath-Aven les habitants, Et de Beth-Éden celui qui tient le sceptre; Et le peuple de Syrie sera mené captif à Kir, dit l'Éternel.","Je briserai les verrous de Damas, J'exterminerai de Bikath-Aven les habitants, Et de Beth-Éden celui qui tient le sceptre; Et le peuple de Syrie sera mené captif à Kir, dit l'Éternel."],[1,6,"Ainsi parle l'Éternel: À cause de trois crimes de Gaza, Même de quatre, je ne révoque pas mon arrêt, Parce qu'ils ont fait une foule de captifs pour les livrer à Édom.","Ainsi parle l'Éternel: À cause de trois crimes de Gaza, Même de quatre, je ne révoque pas mon arrêt, Parce qu'ils ont fait une foule de captifs pour les livrer à Édom."],[1,7,"J'enverrai le feu dans les murs de Gaza, Et il en dévorera les palais.","J'enverrai le feu dans les murs de Gaza, Et il en dévorera les palais."],[1,8,"J'exterminerai d'Asdod les habitants, Et d'Askalon celui qui tient le sceptre; Je tournerai ma main contre Ékron, Et le reste des Philistins périra, dit le Seigneur, l'Éternel.","J'exterminerai d'Asdod les habitants, Et d'Askalon celui qui tient le sceptre; Je tournerai ma main contre Ékron, Et le reste des Philistins périra, dit le Seigneur, l'Éternel."],[1,9,"Ainsi parle l'Éternel: À cause de trois crimes de Tyr, Même de quatre, je ne révoque pas mon arrêt, Parce qu'ils ont livré à Édom une foule de captifs, Sans se souvenir de l'alliance fraternelle.","Ainsi parle l'Éternel: À cause de trois crimes de Tyr, Même de quatre, je ne révoque pas mon arrêt, Parce qu'ils ont livré à Édom une foule de captifs, Sans se souvenir de l'alliance fraternelle."],[1,10,"J'enverrai le feu dans les murs de Tyr, Et il en dévorera les palais.","J'enverrai le feu dans les murs de Tyr, Et il en dévorera les palais."],[1,11,"Ainsi parle l'Éternel: À cause de trois crimes d'Édom, Même de quatre, je ne révoque pas mon arrêt, Parce qu'il a poursuivi ses frères avec l'épée, En étouffant sa compassion, Parce que sa colère déchire toujours, Et qu'il garde éternellement sa fureur.","Ainsi parle l'Éternel: À cause de trois crimes d'Édom, Même de quatre, je ne révoque pas mon arrêt, Parce qu'il a poursuivi ses frères avec l'épée, En étouffant sa compassion, Parce que sa colère déchire toujours, Et qu'il garde éternellement sa fureur."],[1,12,"J'enverrai le feu dans Théman, Et il dévorera les palais de Botsra.","J'enverrai le feu dans Théman, Et il dévorera les palais de Botsra."],[1,13,"Ainsi parle l'Éternel: À cause de trois crimes des enfants d'Ammon, Même de quatre, je ne révoque pas mon arrêt, Parce qu'ils ont fendu le ventre des femmes enceintes de Galaad, Afin d'agrandir leur territoire.","Ainsi parle l'Éternel: À cause de trois crimes des enfants d'Ammon, Même de quatre, je ne révoque pas mon arrêt, Parce qu'ils ont fendu le ventre des femmes enceintes de Galaad, Afin d'agrandir leur territoire."],[1,14,"J'allumerai le feu dans les murs de Rabba, Et il en dévorera les palais, Au milieu des cris de guerre au jour du combat, Au milieu de l'ouragan au jour de la tempête;","J'allumerai le feu dans les murs de Rabba, Et il en dévorera les palais, Au milieu des cris de guerre au jour du combat, Au milieu de l'ouragan au jour de la tempête;"],[1,15,"Et leur roi s'en ira en captivité, Lui, et ses chefs avec lui, dit l'Éternel.","Et leur roi s'en ira en captivité, Lui, et ses chefs avec lui, dit l'Éternel."],[2,1,"Ainsi parle l'Éternel: À cause de trois crimes de Moab, Même de quatre, je ne révoque pas mon arrêt, Parce qu'il a brûlé, calciné les os du roi d'Édom.","Ainsi parle l'Éternel: À cause de trois crimes de Moab, Même de quatre, je ne révoque pas mon arrêt, Parce qu'il a brûlé, calciné les os du roi d'Édom."],[2,2,"J'enverrai le feu dans Moab, Et il dévorera les palais de Kerijoth; Et Moab périra au milieu du tumulte, Au milieu des cris de guerre et du bruit de la trompette.","J'enverrai le feu dans Moab, Et il dévorera les palais de Kerijoth; Et Moab périra au milieu du tumulte, Au milieu des cris de guerre et du bruit de la trompette."],[2,3,"J'exterminerai de son sein le juge, Et je tuerai tous ses chefs avec lui, dit l'Éternel.","J'exterminerai de son sein le juge, Et je tuerai tous ses chefs avec lui, dit l'Éternel."],[2,4,"Ainsi parle l'Éternel: À cause de trois crimes de Juda, Même de quatre, je ne révoque pas mon arrêt, Parce qu'ils ont méprisé la loi de l'Éternel Et qu'ils n'ont pas gardé ses ordonnances, Parce qu'ils ont été égarés par les idoles mensongères Après lesquelles leurs pères ont marché.","Ainsi parle l'Éternel: À cause de trois crimes de Juda, Même de quatre, je ne révoque pas mon arrêt, Parce qu'ils ont méprisé la loi de l'Éternel Et qu'ils n'ont pas gardé ses ordonnances, Parce qu'ils ont été égarés par les idoles mensongères Après lesquelles leurs pères ont marché."],[2,5,"J'enverrai le feu dans Juda, Et il dévorera les palais de Jérusalem.","J'enverrai le feu dans Juda, Et il dévorera les palais de Jérusalem."],[2,6,"Ainsi parle l'Éternel: À cause de trois crimes d'Israël, Même de quatre, je ne révoque pas mon arrêt, Parce qu'ils ont vendu le juste pour de l'argent, Et le pauvre pour une paire de souliers.","Ainsi parle l'Éternel: À cause de trois crimes d'Israël, Même de quatre, je ne révoque pas mon arrêt, Parce qu'ils ont vendu le juste pour de l'argent, Et le pauvre pour une paire de souliers."],[2,7,"Ils aspirent à voir la poussière de la terre sur la tête des misérables, Et ils violent le droit des malheureux. Le fils et le père vont vers la même fille, Afin de profaner mon saint nom.","Ils aspirent à voir la poussière de la terre sur la tête des misérables, Et ils violent le droit des malheureux. Le fils et le père vont vers la même fille, Afin de profaner mon saint nom."],[2,8,"Ils s'étendent près de chaque autel sur des vêtements pris en gage, Et ils boivent dans la maison de leurs dieux le vin de ceux qu'ils condamnent.","Ils s'étendent près de chaque autel sur des vêtements pris en gage, Et ils boivent dans la maison de leurs dieux le vin de ceux qu'ils condamnent."],[2,9,"Et pourtant j'ai détruit devant eux les Amoréens, Dont la hauteur égalait celle des cèdres, Et la force celle des chênes; J'ai détruit leurs fruits en haut, Et leurs racines en bas.","Et pourtant j'ai détruit devant eux les Amoréens, Dont la hauteur égalait celle des cèdres, Et la force celle des chênes; J'ai détruit leurs fruits en haut, Et leurs racines en bas."],[2,10,"Et pourtant je vous ai fait monter du pays d'Égypte, Et je vous ai conduits quarante ans dans le désert, Pour vous mettre en possession du pays des Amoréens.","Et pourtant je vous ai fait monter du pays d'Égypte, Et je vous ai conduits quarante ans dans le désert, Pour vous mettre en possession du pays des Amoréens."],[2,11,"J'ai suscité parmi vos fils des prophètes, Et parmi vos jeunes hommes des nazaréens. N'en est-il pas ainsi, enfants d'Israël? dit l'Éternel...","J'ai suscité parmi vos fils des prophètes, Et parmi vos jeunes hommes des nazaréens. N'en est-il pas ainsi, enfants d'Israël? dit l'Éternel..."],[2,12,"Et vous avez fait boire du vin aux nazaréens! Et aux prophètes vous avez donné cet ordre: Ne prophétisez pas!","Et vous avez fait boire du vin aux nazaréens! Et aux prophètes vous avez donné cet ordre: Ne prophétisez pas!"],[2,13,"Voici, je vous écraserai, Comme foule la terre un chariot chargé de gerbes.","Voici, je vous écraserai, Comme foule la terre un chariot chargé de gerbes."],[2,14,"Celui qui est agile ne pourra fuir, Celui qui a de la force ne pourra s'en servir, Et l'homme vaillant ne sauvera pas sa vie;","Celui qui est agile ne pourra fuir, Celui qui a de la force ne pourra s'en servir, Et l'homme vaillant ne sauvera pas sa vie;"],[2,15,"Celui qui manie l'arc ne résistera pas, Celui qui a les pieds légers n'échappera pas, Et le cavalier ne sauvera pas sa vie;","Celui qui manie l'arc ne résistera pas, Celui qui a les pieds légers n'échappera pas, Et le cavalier ne sauvera pas sa vie;"],[2,16,"Le plus courageux des guerriers S'enfuira nu dans ce jour-là, dit l'Éternel.","Le plus courageux des guerriers S'enfuira nu dans ce jour-là, dit l'Éternel."],[3,1,"Écoutez cette parole que l'Éternel prononce contre vous, enfants d'Israël, Contre toute la famille que j'ai fait monter du pays d'Égypte!","Écoutez cette parole que l'Éternel prononce contre vous, enfants d'Israël, Contre toute la famille que j'ai fait monter du pays d'Égypte!"],[3,2,"Je vous ai choisis, vous seuls parmi toutes les familles de la terre; C'est pourquoi je vous châtierai pour toutes vos iniquités.","Je vous ai choisis, vous seuls parmi toutes les familles de la terre; C'est pourquoi je vous châtierai pour toutes vos iniquités."],[3,3,"Deux hommes marchent-ils ensemble, Sans en être convenus?","Deux hommes marchent-ils ensemble, Sans en être convenus?"],[3,4,"Le lion rugit-il dans la forêt, Sans avoir une proie? Le lionceau pousse-t-il des cris du fond de sa tanière, Sans avoir fait une capture?","Le lion rugit-il dans la forêt, Sans avoir une proie? Le lionceau pousse-t-il des cris du fond de sa tanière, Sans avoir fait une capture?"],[3,5,"L'oiseau tombe-t-il dans le filet qui est à terre, Sans qu'il y ait un piège? Le filet s'élève-t-il de terre, Sans qu'il y ait rien de pris?","L'oiseau tombe-t-il dans le filet qui est à terre, Sans qu'il y ait un piège? Le filet s'élève-t-il de terre, Sans qu'il y ait rien de pris?"],[3,6,"Sonne-t-on de la trompette dans une ville, Sans que le peuple soit dans l'épouvante? Arrive-t-il un malheur dans une ville, Sans que l'Éternel en soit l'auteur?","Sonne-t-on de la trompette dans une ville, Sans que le peuple soit dans l'épouvante? Arrive-t-il un malheur dans une ville, Sans que l'Éternel en soit l'auteur?"],[3,7,"Car le Seigneur, l'Éternel, ne fait rien Sans avoir révélé son secret à ses serviteurs les prophètes.","Car le Seigneur, l'Éternel, ne fait rien Sans avoir révélé son secret à ses serviteurs les prophètes."],[3,8,"Le lion rugit: qui ne serait effrayé? Le Seigneur, l'Éternel, parle: qui ne prophétiserait?","Le lion rugit: qui ne serait effrayé? Le Seigneur, l'Éternel, parle: qui ne prophétiserait?"],[3,9,"Faites retentir votre voix dans les palais d'Asdod Et dans les palais du pays d'Égypte, Et dites: Rassemblez-vous sur les montagnes de Samarie, Et voyez quelle immense confusion au milieu d'elle, Quelles violences dans son sein!","Faites retentir votre voix dans les palais d'Asdod Et dans les palais du pays d'Égypte, Et dites: Rassemblez-vous sur les montagnes de Samarie, Et voyez quelle immense confusion au milieu d'elle, Quelles violences dans son sein!"],[3,10,"Ils ne savent pas agir avec droiture, dit l'Éternel, Ils entassent dans leurs palais les produits de la violence et de la rapine.","Ils ne savent pas agir avec droiture, dit l'Éternel, Ils entassent dans leurs palais les produits de la violence et de la rapine."],[3,11,"C'est pourquoi ainsi parle le Seigneur, l'Éternel: L'ennemi investira le pays, Il détruira ta force, Et tes palais seront pillés.","C'est pourquoi ainsi parle le Seigneur, l'Éternel: L'ennemi investira le pays, Il détruira ta force, Et tes palais seront pillés."],[3,12,"Ainsi parle l'Éternel: Comme le berger arrache de la gueule du lion Deux jambes ou un bout d'oreille, Ainsi se sauveront les enfants d'Israël qui sont assis dans Samarie À l'angle d'un lit et sur des tapis de damas.","Ainsi parle l'Éternel: Comme le berger arrache de la gueule du lion Deux jambes ou un bout d'oreille, Ainsi se sauveront les enfants d'Israël qui sont assis dans Samarie À l'angle d'un lit et sur des tapis de damas."],[3,13,"Écoutez, et déclarez ceci à la maison de Jacob! Dit le Seigneur, l'Éternel, le Dieu des armées.","Écoutez, et déclarez ceci à la maison de Jacob! Dit le Seigneur, l'Éternel, le Dieu des armées."],[3,14,"Le jour où je punirai Israël pour ses transgressions, Je frapperai sur les autels de Béthel; Les cornes de l'autel seront brisées, Et tomberont à terre.","Le jour où je punirai Israël pour ses transgressions, Je frapperai sur les autels de Béthel; Les cornes de l'autel seront brisées, Et tomberont à terre."],[3,15,"Je renverserai les maisons d'hiver et les maisons d'été; Les palais d'ivoire périront, Les maisons des grands disparaîtront, dit l'Éternel.","Je renverserai les maisons d'hiver et les maisons d'été; Les palais d'ivoire périront, Les maisons des grands disparaîtront, dit l'Éternel."],[4,1,"Écoutez cette parole, génisses de Basan qui êtes sur la montagne de Samarie, Vous qui opprimez les misérables, qui écrasez les indigents, Et qui dites à vos maris: Apportez, et buvons!","Écoutez cette parole, génisses de Basan qui êtes sur la montagne de Samarie, Vous qui opprimez les misérables, qui écrasez les indigents, Et qui dites à vos maris: Apportez, et buvons!"],[4,2,"Le Seigneur, l'Éternel, l'a juré par sa sainteté: Voici, les jours viendront pour vous Où l'on vous enlèvera avec des crochets, Et votre postérité avec des hameçons;","Le Seigneur, l'Éternel, l'a juré par sa sainteté: Voici, les jours viendront pour vous Où l'on vous enlèvera avec des crochets, Et votre postérité avec des hameçons;"],[4,3,"Vous sortirez par les brèches, chacune devant soi, Et vous serez jetées dans la forteresse, dit l'Éternel.","Vous sortirez par les brèches, chacune devant soi, Et vous serez jetées dans la forteresse, dit l'Éternel."],[4,4,"Allez à Béthel, et péchez! Allez à Guilgal, et péchez davantage! Offrez vos sacrifices chaque matin, Et vos dîmes tous les trois jours!","Allez à Béthel, et péchez! Allez à Guilgal, et péchez davantage! Offrez vos sacrifices chaque matin, Et vos dîmes tous les trois jours!"],[4,5,"Faites vos sacrifices d'actions de grâces avec du levain! Proclamez, publiez vos offrandes volontaires! Car c'est là ce que vous aimez, enfants d'Israël, Dit le Seigneur, l'Éternel.","Faites vos sacrifices d'actions de grâces avec du levain! Proclamez, publiez vos offrandes volontaires! Car c'est là ce que vous aimez, enfants d'Israël, Dit le Seigneur, l'Éternel."],[4,6,"Et moi, je vous ai envoyé la famine dans toutes vos villes, Le manque de pain dans toutes vos demeures. Malgré cela, vous n'êtes pas revenus à moi, dit l'Éternel.","Et moi, je vous ai envoyé la famine dans toutes vos villes, Le manque de pain dans toutes vos demeures. Malgré cela, vous n'êtes pas revenus à moi, dit l'Éternel."],[4,7,"Et moi, je vous ai refusé la pluie, Lorsqu'il y avait encore trois mois jusqu'à la moisson; J'ai fait pleuvoir sur une ville, Et je n'ai pas fait pleuvoir sur une autre ville; Un champ a reçu la pluie, Et un autre qui ne l'a pas reçue s'est desséché.","Et moi, je vous ai refusé la pluie, Lorsqu'il y avait encore trois mois jusqu'à la moisson; J'ai fait pleuvoir sur une ville, Et je n'ai pas fait pleuvoir sur une autre ville; Un champ a reçu la pluie, Et un autre qui ne l'a pas reçue s'est desséché."],[4,8,"Deux, trois villes sont allées vers une autre pour boire de l'eau, Et elles n'ont point apaisé leur soif. Malgré cela, vous n'êtes pas revenus à moi, dit l'Éternel.","Deux, trois villes sont allées vers une autre pour boire de l'eau, Et elles n'ont point apaisé leur soif. Malgré cela, vous n'êtes pas revenus à moi, dit l'Éternel."],[4,9,"Je vous ai frappés par la rouille et par la nielle; Vos nombreux jardins, vos vignes, vos figuiers et vos oliviers Ont été dévorés par les sauterelles. Malgré cela, vous n'êtes pas revenus à moi, dit l'Éternel.","Je vous ai frappés par la rouille et par la nielle; Vos nombreux jardins, vos vignes, vos figuiers et vos oliviers Ont été dévorés par les sauterelles. Malgré cela, vous n'êtes pas revenus à moi, dit l'Éternel."],[4,10,"J'ai envoyé parmi vous la peste, comme en Égypte; J'ai tué vos jeunes gens par l'épée, Et laissé prendre vos chevaux; J'ai fait monter à vos narines l'infection de votre camp. Malgré cela, vous n'êtes pas revenus à moi, dit l'Éternel.","J'ai envoyé parmi vous la peste, comme en Égypte; J'ai tué vos jeunes gens par l'épée, Et laissé prendre vos chevaux; J'ai fait monter à vos narines l'infection de votre camp. Malgré cela, vous n'êtes pas revenus à moi, dit l'Éternel."],[4,11,"Je vous ai bouleversés, Comme Sodome et Gomorrhe, que Dieu détruisit; Et vous avez été comme un tison arraché de l'incendie. Malgré cela, vous n'êtes pas revenus à moi, dit l'Éternel...","Je vous ai bouleversés, Comme Sodome et Gomorrhe, que Dieu détruisit; Et vous avez été comme un tison arraché de l'incendie. Malgré cela, vous n'êtes pas revenus à moi, dit l'Éternel..."],[4,12,"C'est pourquoi je te traiterai de la même manière, Israël; Et puisque je te traiterai de la même manière, Prépare-toi à la rencontre de ton Dieu, O Israël!","C'est pourquoi je te traiterai de la même manière, Israël; Et puisque je te traiterai de la même manière, Prépare-toi à la rencontre de ton Dieu, O Israël!"],[4,13,"Car voici celui qui a formé les montagnes et créé le vent, Et qui fait connaître à l'homme ses pensées, Celui qui change l'aurore en ténèbres, Et qui marche sur les hauteurs de la terre: Son nom est l'Éternel, le Dieu des armées.","Car voici celui qui a formé les montagnes et créé le vent, Et qui fait connaître à l'homme ses pensées, Celui qui change l'aurore en ténèbres, Et qui marche sur les hauteurs de la terre: Son nom est l'Éternel, le Dieu des armées."],[5,1,"Écoutez cette parole, Cette complainte que je prononce sur vous, Maison d'Israël!","Écoutez cette parole, Cette complainte que je prononce sur vous, Maison d'Israël!"],[5,2,"Elle est tombée, elle ne se relèvera plus, La vierge d'Israël; Elle est couchée par terre, Nul ne la relève.","Elle est tombée, elle ne se relèvera plus, La vierge d'Israël; Elle est couchée par terre, Nul ne la relève."],[5,3,"Car ainsi parle le Seigneur, l'Éternel: La ville qui mettait en campagne mille hommes N'en conservera que cent, Et celle qui mettait en campagne cent hommes N'en conservera que dix, pour la maison d'Israël.","Car ainsi parle le Seigneur, l'Éternel: La ville qui mettait en campagne mille hommes N'en conservera que cent, Et celle qui mettait en campagne cent hommes N'en conservera que dix, pour la maison d'Israël."],[5,4,"Car ainsi parle l'Éternel à la maison d'Israël: Cherchez-moi, et vous vivrez!","Car ainsi parle l'Éternel à la maison d'Israël: Cherchez-moi, et vous vivrez!"],[5,5,"Ne cherchez pas Béthel, N'allez pas à Guilgal, Ne passez pas à Beer-Schéba. Car Guilgal sera captif, Et Béthel anéanti.","Ne cherchez pas Béthel, N'allez pas à Guilgal, Ne passez pas à Beer-Schéba. Car Guilgal sera captif, Et Béthel anéanti."],[5,6,"Cherchez l'Éternel, et vous vivrez! Craignez qu'il ne saisisse comme un feu la maison de Joseph, Et que ce feu ne la dévore, sans personne à Béthel pour l'éteindre,","Cherchez l'Éternel, et vous vivrez! Craignez qu'il ne saisisse comme un feu la maison de Joseph, Et que ce feu ne la dévore, sans personne à Béthel pour l'éteindre,"],[5,7,"O vous qui changez le droit en absinthe, Et qui foulez à terre la justice!","O vous qui changez le droit en absinthe, Et qui foulez à terre la justice!"],[5,8,"Il a créé les Pléiades et l'Orion, Il change les ténèbres en aurore, Il obscurcit le jour pour en faire la nuit, Il appelle les eaux de la mer, Et les répand à la surface de la terre: L'Éternel est son nom.","Il a créé les Pléiades et l'Orion, Il change les ténèbres en aurore, Il obscurcit le jour pour en faire la nuit, Il appelle les eaux de la mer, Et les répand à la surface de la terre: L'Éternel est son nom."],[5,9,"Il fait lever la ruine sur les puissants, Et la ruine vient sur les forteresses.","Il fait lever la ruine sur les puissants, Et la ruine vient sur les forteresses."],[5,10,"Ils haïssent celui qui les reprend à la porte, Et ils ont en horreur celui qui parle sincèrement.","Ils haïssent celui qui les reprend à la porte, Et ils ont en horreur celui qui parle sincèrement."],[5,11,"Aussi, parce que vous avez foulé le misérable, Et que vous avez pris de lui du blé en présent, Vous avez bâti des maisons en pierres de taille, Mais vous ne les habiterez pas; Vous avez planté d'excellentes vignes, Mais vous n'en boirez pas le vin.","Aussi, parce que vous avez foulé le misérable, Et que vous avez pris de lui du blé en présent, Vous avez bâti des maisons en pierres de taille, Mais vous ne les habiterez pas; Vous avez planté d'excellentes vignes, Mais vous n'en boirez pas le vin."],[5,12,"Car, je le sais, vos crimes sont nombreux, Vos péchés se sont multipliés; Vous opprimez le juste, vous recevez des présents, Et vous violez à la porte le droit des pauvres.","Car, je le sais, vos crimes sont nombreux, Vos péchés se sont multipliés; Vous opprimez le juste, vous recevez des présents, Et vous violez à la porte le droit des pauvres."],[5,13,"Voilà pourquoi, en des temps comme ceux-ci, le sage se tait; Car ces temps sont mauvais.","Voilà pourquoi, en des temps comme ceux-ci, le sage se tait; Car ces temps sont mauvais."],[5,14,"Recherchez le bien et non le mal, afin que vous viviez, Et qu'ainsi l'Éternel, le Dieu des armées, soit avec vous, Comme vous le dites.","Recherchez le bien et non le mal, afin que vous viviez, Et qu'ainsi l'Éternel, le Dieu des armées, soit avec vous, Comme vous le dites."],[5,15,"Haïssez le mal et aimez le bien, Faites régner à la porte la justice; Et peut-être l'Éternel, le Dieu des armées, aura pitié Des restes de Joseph.","Haïssez le mal et aimez le bien, Faites régner à la porte la justice; Et peut-être l'Éternel, le Dieu des armées, aura pitié Des restes de Joseph."],[5,16,"C'est pourquoi ainsi parle l'Éternel, le Dieu des armées, le Seigneur; Dans toutes les places on se lamentera, Dans toutes les rues on dira: Hélas! hélas! On appellera le laboureur au deuil, Et aux lamentations ceux qui disent des complaintes.","C'est pourquoi ainsi parle l'Éternel, le Dieu des armées, le Seigneur; Dans toutes les places on se lamentera, Dans toutes les rues on dira: Hélas! hélas! On appellera le laboureur au deuil, Et aux lamentations ceux qui disent des complaintes."],[5,17,"Dans toutes les vignes on se lamentera, Lorsque je passerai au milieu de toi, dit l'Éternel.","Dans toutes les vignes on se lamentera, Lorsque je passerai au milieu de toi, dit l'Éternel."],[5,18,"Malheur à ceux qui désirent le jour de l'Éternel! Qu'attendez-vous du jour de l'Éternel? Il sera ténèbres et non lumière.","Malheur à ceux qui désirent le jour de l'Éternel! Qu'attendez-vous du jour de l'Éternel? Il sera ténèbres et non lumière."],[5,19,"Vous serez comme un homme qui fuit devant un lion Et que rencontre un ours, Qui gagne sa demeure, appuie sa main sur la muraille, Et que mord un serpent.","Vous serez comme un homme qui fuit devant un lion Et que rencontre un ours, Qui gagne sa demeure, appuie sa main sur la muraille, Et que mord un serpent."],[5,20,"Le jour de l'Éternel n'est-il pas ténèbres et non lumière? N'est-il pas obscur et sans éclat?","Le jour de l'Éternel n'est-il pas ténèbres et non lumière? N'est-il pas obscur et sans éclat?"],[5,21,"Je hais, je méprise vos fêtes, Je ne puis sentir vos assemblées.","Je hais, je méprise vos fêtes, Je ne puis sentir vos assemblées."],[5,22,"Quand vous me présentez des holocaustes et des offrandes, Je n'y prends aucun plaisir; Et les veaux engraissés que vous sacrifiez en actions de grâces, Je ne les regarde pas.","Quand vous me présentez des holocaustes et des offrandes, Je n'y prends aucun plaisir; Et les veaux engraissés que vous sacrifiez en actions de grâces, Je ne les regarde pas."],[5,23,"Éloigne de moi le bruit de tes cantiques; Je n'écoute pas le son de tes luths.","Éloigne de moi le bruit de tes cantiques; Je n'écoute pas le son de tes luths."],[5,24,"Mais que la droiture soit comme un courant d'eau, Et la justice comme un torrent qui jamais ne tarit.","Mais que la droiture soit comme un courant d'eau, Et la justice comme un torrent qui jamais ne tarit."],[5,25,"M'avez-vous fait des sacrifices et des offrandes Pendant les quarante années du désert, maison d'Israël?...","M'avez-vous fait des sacrifices et des offrandes Pendant les quarante années du désert, maison d'Israël?..."],[5,26,"Emportez donc la tente de votre roi, Le piédestal de vos idoles, L'étoile de votre Dieu Que vous vous êtes fabriqué!","Emportez donc la tente de votre roi, Le piédestal de vos idoles, L'étoile de votre Dieu Que vous vous êtes fabriqué!"],[5,27,"Et je vous emmènerai captifs au delà de Damas, Dit l'Éternel, dont le nom est le Dieu des armées.","Et je vous emmènerai captifs au delà de Damas, Dit l'Éternel, dont le nom est le Dieu des armées."],[6,1,"Malheur à ceux qui vivent tranquilles dans Sion, Et en sécurité sur la montagne de Samarie, À ces grands de la première des nations, Auprès desquels va la maison d'Israël!...","Malheur à ceux qui vivent tranquilles dans Sion, Et en sécurité sur la montagne de Samarie, À ces grands de la première des nations, Auprès desquels va la maison d'Israël!..."],[6,2,"Passez à Calné et voyez, Allez de là jusqu'à Hamath la grande, Et descendez à Gath chez les Philistins: Ces villes sont-elles plus prospères que vos deux royaumes, Et leur territoire est-il plus étendu que le vôtre?...","Passez à Calné et voyez, Allez de là jusqu'à Hamath la grande, Et descendez à Gath chez les Philistins: Ces villes sont-elles plus prospères que vos deux royaumes, Et leur territoire est-il plus étendu que le vôtre?..."],[6,3,"Vous croyez éloigné le jour du malheur, Et vous faites approcher le règne de la violence.","Vous croyez éloigné le jour du malheur, Et vous faites approcher le règne de la violence."],[6,4,"Ils reposent sur des lits d'ivoire, Ils sont mollement étendus sur leurs couches; Ils mangent les agneaux du troupeau, Les veaux mis à l'engrais.","Ils reposent sur des lits d'ivoire, Ils sont mollement étendus sur leurs couches; Ils mangent les agneaux du troupeau, Les veaux mis à l'engrais."],[6,5,"Ils extravaguent au son du luth, Ils se croient habiles comme David sur les instruments de musique.","Ils extravaguent au son du luth, Ils se croient habiles comme David sur les instruments de musique."],[6,6,"Ils boivent le vin dans de larges coupes, Ils s'oignent avec la meilleure huile, Et ils ne s'attristent pas sur la ruine de Joseph!","Ils boivent le vin dans de larges coupes, Ils s'oignent avec la meilleure huile, Et ils ne s'attristent pas sur la ruine de Joseph!"],[6,7,"C'est pourquoi ils seront emmenés à la tête des captifs; Et les cris de joie de ces voluptueux cesseront.","C'est pourquoi ils seront emmenés à la tête des captifs; Et les cris de joie de ces voluptueux cesseront."],[6,8,"Le Seigneur, l'Éternel, l'a juré par lui-même; L'Éternel, le Dieu des armées, a dit: J'ai en horreur l'orgueil de Jacob, Et je hais ses palais; Je livrerai la ville et tout ce qu'elle renferme.","Le Seigneur, l'Éternel, l'a juré par lui-même; L'Éternel, le Dieu des armées, a dit: J'ai en horreur l'orgueil de Jacob, Et je hais ses palais; Je livrerai la ville et tout ce qu'elle renferme."],[6,9,"Et s'il reste dix hommes dans une maison, ils mourront.","Et s'il reste dix hommes dans une maison, ils mourront."],[6,10,"Lorsqu'un parent prendra un mort pour le brûler Et qu'il enlèvera de la maison les ossements, Il dira à celui qui est au fond de la maison: Y a-t-il encore quelqu'un avec toi? Et cet homme répondra: Personne... Et l'autre dira: Silence! Ce n'est pas le moment de prononcer le nom de l'Éternel.","Lorsqu'un parent prendra un mort pour le brûler Et qu'il enlèvera de la maison les ossements, Il dira à celui qui est au fond de la maison: Y a-t-il encore quelqu'un avec toi? Et cet homme répondra: Personne... Et l'autre dira: Silence! Ce n'est pas le moment de prononcer le nom de l'Éternel."],[6,11,"Car voici, l'Éternel ordonne: Il fera tomber en ruines la grande maison, Et en débris la petite maison.","Car voici, l'Éternel ordonne: Il fera tomber en ruines la grande maison, Et en débris la petite maison."],[6,12,"Est-ce que les chevaux courent sur un rocher, Est-ce qu'on y laboure avec des boeufs, Pour que vous ayez changé la droiture en poison, Et le fruit de la justice en absinthe?","Est-ce que les chevaux courent sur un rocher, Est-ce qu'on y laboure avec des boeufs, Pour que vous ayez changé la droiture en poison, Et le fruit de la justice en absinthe?"],[6,13,"Vous vous réjouissez de ce qui n'est que néant, Vous dites: N'est-ce pas par notre force Que nous avons acquis de la puissance?","Vous vous réjouissez de ce qui n'est que néant, Vous dites: N'est-ce pas par notre force Que nous avons acquis de la puissance?"],[6,14,"C'est pourquoi voici, je ferai lever contre vous, maison d'Israël, Dit l'Éternel, le Dieu des armées, une nation Qui vous opprimera depuis l'entrée de Hamath Jusqu'au torrent du désert.","C'est pourquoi voici, je ferai lever contre vous, maison d'Israël, Dit l'Éternel, le Dieu des armées, une nation Qui vous opprimera depuis l'entrée de Hamath Jusqu'au torrent du désert."],[7,1,"Le Seigneur, l'Éternel, m'envoya cette vision. Voici, il formait des sauterelles, Au moment où le regain commençait à croître; C'était le regain après la coupe du roi.","Le Seigneur, l'Éternel, m'envoya cette vision. Voici, il formait des sauterelles, Au moment où le regain commençait à croître; C'était le regain après la coupe du roi."],[7,2,"Et comme elles dévoraient entièrement l'herbe de la terre, Je dis: Seigneur Éternel, pardonne donc! Comment Jacob subsistera-t-il? Car il est si faible!","Et comme elles dévoraient entièrement l'herbe de la terre, Je dis: Seigneur Éternel, pardonne donc! Comment Jacob subsistera-t-il? Car il est si faible!"],[7,3,"L'Éternel se repentit de cela. Cela n'arrivera pas, dit l'Éternel.","L'Éternel se repentit de cela. Cela n'arrivera pas, dit l'Éternel."],[7,4,"Le Seigneur, l'Éternel, m'envoya cette vision. Voici, le Seigneur, l'Éternel, proclamait le châtiment par le feu; Et le feu dévorait le grand abîme Et dévorait le champ.","Le Seigneur, l'Éternel, m'envoya cette vision. Voici, le Seigneur, l'Éternel, proclamait le châtiment par le feu; Et le feu dévorait le grand abîme Et dévorait le champ."],[7,5,"Je dis: Seigneur Éternel, arrête donc! Comment Jacob subsistera-t-il? Car il est si faible!","Je dis: Seigneur Éternel, arrête donc! Comment Jacob subsistera-t-il? Car il est si faible!"],[7,6,"L'Éternel se repentit de cela. Cela non plus n'arrivera pas, dit le Seigneur, l'Éternel.","L'Éternel se repentit de cela. Cela non plus n'arrivera pas, dit le Seigneur, l'Éternel."],[7,7,"Il m'envoya cette vision. Voici, le Seigneur se tenait sur un mur tiré au cordeau, Et il avait un niveau dans la main.","Il m'envoya cette vision. Voici, le Seigneur se tenait sur un mur tiré au cordeau, Et il avait un niveau dans la main."],[7,8,"L'Éternel me dit: Que vois-tu, Amos? Je répondis: Un niveau. Et le Seigneur dit: Je mettrai le niveau au milieu de mon peuple d'Israël, Je ne lui pardonnerai plus;","L'Éternel me dit: Que vois-tu, Amos? Je répondis: Un niveau. Et le Seigneur dit: Je mettrai le niveau au milieu de mon peuple d'Israël, Je ne lui pardonnerai plus;"],[7,9,"Les hauts lieux d'Isaac seront ravagés; Les sanctuaires d'Israël seront détruits, Et je me lèverai contre la maison de Jéroboam avec l'épée.","Les hauts lieux d'Isaac seront ravagés; Les sanctuaires d'Israël seront détruits, Et je me lèverai contre la maison de Jéroboam avec l'épée."],[7,10,"Alors Amatsia, prêtre de Béthel, fit dire à Jéroboam, roi d'Israël: Amos conspire contre toi au milieu de la maison d'Israël; le pays ne peut supporter toutes ses paroles.","Alors Amatsia, prêtre de Béthel, fit dire à Jéroboam, roi d'Israël: Amos conspire contre toi au milieu de la maison d'Israël; le pays ne peut supporter toutes ses paroles."],[7,11,"Car voici ce que dit Amos: Jéroboam mourra par l'épée, et Israël sera emmené captif loin de son pays.","Car voici ce que dit Amos: Jéroboam mourra par l'épée, et Israël sera emmené captif loin de son pays."],[7,12,"Et Amatsia dit à Amos: Homme à visions, va-t-en, fuis dans le pays de Juda; manges-y ton pain, et là tu prophétiseras.","Et Amatsia dit à Amos: Homme à visions, va-t-en, fuis dans le pays de Juda; manges-y ton pain, et là tu prophétiseras."],[7,13,"Mais ne continue pas à prophétiser à Béthel, car c'est un sanctuaire du roi, et c'est une maison royale.","Mais ne continue pas à prophétiser à Béthel, car c'est un sanctuaire du roi, et c'est une maison royale."],[7,14,"Amos répondit à Amatsia: Je ne suis ni prophète, ni fils de prophète; mais je suis berger, et je cultive des sycomores.","Amos répondit à Amatsia: Je ne suis ni prophète, ni fils de prophète; mais je suis berger, et je cultive des sycomores."],[7,15,"L'Éternel m'a pris derrière le troupeau, et l'Éternel m'a dit: Va, prophétise à mon peuple d'Israël.","L'Éternel m'a pris derrière le troupeau, et l'Éternel m'a dit: Va, prophétise à mon peuple d'Israël."],[7,16,"Écoute maintenant la parole de l'Éternel, toi qui dis: Ne prophétise pas contre Israël, et ne parle pas contre la maison d'Isaac.","Écoute maintenant la parole de l'Éternel, toi qui dis: Ne prophétise pas contre Israël, et ne parle pas contre la maison d'Isaac."],[7,17,"À cause de cela, voici ce que dit l'Éternel: Ta femme se prostituera dans la ville, tes fils et tes filles tomberont par l'épée, ton champ sera partagé au cordeau; et toi, tu mourras sur une terre impure, et Israël sera emmené captif loin de son pays.","À cause de cela, voici ce que dit l'Éternel: Ta femme se prostituera dans la ville, tes fils et tes filles tomberont par l'épée, ton champ sera partagé au cordeau; et toi, tu mourras sur une terre impure, et Israël sera emmené captif loin de son pays."],[8,1,"Le Seigneur, l'Éternel, m'envoya cette vision. Voici, c'était une corbeille de fruits.","Le Seigneur, l'Éternel, m'envoya cette vision. Voici, c'était une corbeille de fruits."],[8,2,"Il dit: Que vois-tu, Amos? Je répondis: Une corbeille de fruits. Et l'Éternel me dit: La fin est venue pour mon peuple d'Israël; Je ne lui pardonnerai plus.","Il dit: Que vois-tu, Amos? Je répondis: Une corbeille de fruits. Et l'Éternel me dit: La fin est venue pour mon peuple d'Israël; Je ne lui pardonnerai plus."],[8,3,"En ce jour-là, les chants du palais seront des gémissements, Dit le Seigneur, l'Éternel; On jettera partout en silence une multitude de cadavres.","En ce jour-là, les chants du palais seront des gémissements, Dit le Seigneur, l'Éternel; On jettera partout en silence une multitude de cadavres."],[8,4,"Écoutez ceci, vous qui dévorez l'indigent, Et qui ruinez les malheureux du pays!","Écoutez ceci, vous qui dévorez l'indigent, Et qui ruinez les malheureux du pays!"],[8,5,"Vous dites: Quand la nouvelle lune sera-t-elle passée, Afin que nous vendions du blé? Quand finira le sabbat, afin que nous ouvrions les greniers? Nous diminuerons l'épha, nous augmenterons le prix, Nous falsifierons les balances pour tromper;","Vous dites: Quand la nouvelle lune sera-t-elle passée, Afin que nous vendions du blé? Quand finira le sabbat, afin que nous ouvrions les greniers? Nous diminuerons l'épha, nous augmenterons le prix, Nous falsifierons les balances pour tromper;"],[8,6,"Puis nous achèterons les misérables pour de l'argent, Et le pauvre pour une paire de souliers, Et nous vendrons la criblure du froment.","Puis nous achèterons les misérables pour de l'argent, Et le pauvre pour une paire de souliers, Et nous vendrons la criblure du froment."],[8,7,"L'Éternel l'a juré par la gloire de Jacob: Je n'oublierai jamais aucune de leurs oeuvres.","L'Éternel l'a juré par la gloire de Jacob: Je n'oublierai jamais aucune de leurs oeuvres."],[8,8,"Le pays, à cause d'elles, ne sera-t-il pas ébranlé, Et tous ses habitants ne seront-ils pas dans le deuil? Le pays montera tout entier comme le fleuve, Il se soulèvera et s'affaissera comme le fleuve d'Égypte.","Le pays, à cause d'elles, ne sera-t-il pas ébranlé, Et tous ses habitants ne seront-ils pas dans le deuil? Le pays montera tout entier comme le fleuve, Il se soulèvera et s'affaissera comme le fleuve d'Égypte."],[8,9,"En ce jour-là, dit le Seigneur, l'Éternel, Je ferai coucher le soleil à midi, Et j'obscurcirai la terre en plein jour;","En ce jour-là, dit le Seigneur, l'Éternel, Je ferai coucher le soleil à midi, Et j'obscurcirai la terre en plein jour;"],[8,10,"Je changerai vos fêtes en deuil, Et tous vos chants en lamentations, Je couvrirai de sacs tous les reins, Et je rendrai chauves toutes les têtes; Je mettrai le pays dans le deuil comme pour un fils unique, Et sa fin sera comme un jour d'amertume.","Je changerai vos fêtes en deuil, Et tous vos chants en lamentations, Je couvrirai de sacs tous les reins, Et je rendrai chauves toutes les têtes; Je mettrai le pays dans le deuil comme pour un fils unique, Et sa fin sera comme un jour d'amertume."],[8,11,"Voici, les jours viennent, dit le Seigneur, l'Éternel, Où j'enverrai la famine dans le pays, Non pas la disette du pain et la soif de l'eau, Mais la faim et la soif d'entendre les paroles de l'Éternel.","Voici, les jours viennent, dit le Seigneur, l'Éternel, Où j'enverrai la famine dans le pays, Non pas la disette du pain et la soif de l'eau, Mais la faim et la soif d'entendre les paroles de l'Éternel."],[8,12,"Ils seront alors errants d'une mer à l'autre, Du septentrion à l'orient, Ils iront çà et là pour chercher la parole de l'Éternel, Et ils ne la trouveront pas.","Ils seront alors errants d'une mer à l'autre, Du septentrion à l'orient, Ils iront çà et là pour chercher la parole de l'Éternel, Et ils ne la trouveront pas."],[8,13,"En ce jour, les belles jeunes filles et les jeunes hommes mourront de soif.","En ce jour, les belles jeunes filles et les jeunes hommes mourront de soif."],[8,14,"Ils jurent par le péché de Samarie, Et ils disent: Vive ton Dieu, Dan! Vive la voie de Beer-Schéba! Mais ils tomberont, et ne se relèveront plus.","Ils jurent par le péché de Samarie, Et ils disent: Vive ton Dieu, Dan! Vive la voie de Beer-Schéba! Mais ils tomberont, et ne se relèveront plus."],[9,1,"Je vis le Seigneur qui se tenait sur l'autel. Et il dit: Frappe les chapiteaux et que les seuils s'ébranlent, Et brise-les sur leurs têtes à tous! Je ferai périr le reste par l'épée. Aucun d'eux ne pourra se sauver en fuyant, Aucun d'eux n'échappera.","Je vis le Seigneur qui se tenait sur l'autel. Et il dit: Frappe les chapiteaux et que les seuils s'ébranlent, Et brise-les sur leurs têtes à tous! Je ferai périr le reste par l'épée. Aucun d'eux ne pourra se sauver en fuyant, Aucun d'eux n'échappera."],[9,2,"S'ils pénètrent dans le séjour des morts, Ma main les en arrachera; S'ils montent aux cieux, Je les en ferai descendre.","S'ils pénètrent dans le séjour des morts, Ma main les en arrachera; S'ils montent aux cieux, Je les en ferai descendre."],[9,3,"S'ils se cachent au sommet du Carmel, Je les y chercherai et je les saisirai; S'ils se dérobent à mes regards dans le fond de la mer, Là j'ordonnerai au serpent de les mordre.","S'ils se cachent au sommet du Carmel, Je les y chercherai et je les saisirai; S'ils se dérobent à mes regards dans le fond de la mer, Là j'ordonnerai au serpent de les mordre."],[9,4,"S'ils vont en captivité devant leurs ennemis, Là j'ordonnerai à l'épée de les faire périr; Je dirigerai contre eux mes regards Pour faire du mal et non du bien.","S'ils vont en captivité devant leurs ennemis, Là j'ordonnerai à l'épée de les faire périr; Je dirigerai contre eux mes regards Pour faire du mal et non du bien."],[9,5,"Le Seigneur, l'Éternel des armées, touche la terre, et elle tremble, Et tous ses habitants sont dans le deuil; Elle monte tout entière comme le fleuve, Et elle s'affaisse comme le fleuve d'Égypte.","Le Seigneur, l'Éternel des armées, touche la terre, et elle tremble, Et tous ses habitants sont dans le deuil; Elle monte tout entière comme le fleuve, Et elle s'affaisse comme le fleuve d'Égypte."],[9,6,"Il a bâti sa demeure dans les cieux, Et fondé sa voûte sur la terre; Il appelle les eaux de la mer, Et les répand à la surface de la terre: L'Éternel est son nom.","Il a bâti sa demeure dans les cieux, Et fondé sa voûte sur la terre; Il appelle les eaux de la mer, Et les répand à la surface de la terre: L'Éternel est son nom."],[9,7,"N'êtes-vous pas pour moi comme les enfants des Éthiopiens, Enfants d'Israël? dit l'Éternel. N'ai-je pas fait sortir Israël du pays d'Égypte, Comme les Philistins de Caphtor et les Syriens de Kir?","N'êtes-vous pas pour moi comme les enfants des Éthiopiens, Enfants d'Israël? dit l'Éternel. N'ai-je pas fait sortir Israël du pays d'Égypte, Comme les Philistins de Caphtor et les Syriens de Kir?"],[9,8,"Voici, le Seigneur, l'Éternel, a les yeux sur le royaume coupable. Je le détruirai de dessus la face de la terre; Toutefois je ne détruirai pas entièrement la maison de Jacob, Dit l'Éternel.","Voici, le Seigneur, l'Éternel, a les yeux sur le royaume coupable. Je le détruirai de dessus la face de la terre; Toutefois je ne détruirai pas entièrement la maison de Jacob, Dit l'Éternel."],[9,9,"Car voici, je donnerai mes ordres, Et je secouerai la maison d'Israël parmi toutes les nations, Comme on secoue avec le crible, Sans qu'il tombe à terre un seul grain.","Car voici, je donnerai mes ordres, Et je secouerai la maison d'Israël parmi toutes les nations, Comme on secoue avec le crible, Sans qu'il tombe à terre un seul grain."],[9,10,"Tous les pécheurs de mon peuple mourront par l'épée, Ceux qui disent: Le malheur n'approchera pas, ne nous atteindra pas.","Tous les pécheurs de mon peuple mourront par l'épée, Ceux qui disent: Le malheur n'approchera pas, ne nous atteindra pas."],[9,11,"En ce temps-là, je relèverai de sa chute la maison de David, J'en réparerai les brèches, j'en redresserai les ruines, Et je la rebâtirai comme elle était autrefois,","En ce temps-là, je relèverai de sa chute la maison de David, J'en réparerai les brèches, j'en redresserai les ruines, Et je la rebâtirai comme elle était autrefois,"],[9,12,"Afin qu'ils possèdent le reste d'Édom et toutes les nations Sur lesquelles mon nom a été invoqué, Dit l'Éternel, qui accomplira ces choses.","Afin qu'ils possèdent le reste d'Édom et toutes les nations Sur lesquelles mon nom a été invoqué, Dit l'Éternel, qui accomplira ces choses."],[9,13,"Voici, les jours viennent, dit l'Éternel, Où le laboureur suivra de près le moissonneur, Et celui qui foule le raisin celui qui répand la semence, Où le moût ruissellera des montagnes Et coulera de toutes les collines.","Voici, les jours viennent, dit l'Éternel, Où le laboureur suivra de près le moissonneur, Et celui qui foule le raisin celui qui répand la semence, Où le moût ruissellera des montagnes Et coulera de toutes les collines."],[9,14,"Je ramènerai les captifs de mon peuple d'Israël; Ils rebâtiront les villes dévastées et les habiteront, Ils planteront des vignes et en boiront le vin, Ils établiront des jardins et en mangeront les fruits.","Je ramènerai les captifs de mon peuple d'Israël; Ils rebâtiront les villes dévastées et les habiteront, Ils planteront des vignes et en boiront le vin, Ils établiront des jardins et en mangeront les fruits."],[9,15,"Je les planterai dans leur pays, Et ils ne seront plus arrachés du pays que je leur ai donné, Dit L'Éternel, ton Dieu.","Je les planterai dans leur pays, Et ils ne seront plus arrachés du pays que je leur ai donné, Dit L'Éternel, ton Dieu."]],"spa-rv1909":[[1,1,"LAS palabrasde Amós, quefuéentre los pastoresde Tecoa, las cuales vióacercade Israelen díasde Uzzíareyde Judá, y en díasde Jeroboamhijode Joasreyde Israel, dosañosantesdel terremoto.","LAS palabrasde Amós, quefuéentre los pastoresde Tecoa, las cuales vióacercade Israelen díasde Uzzíareyde Judá, y en díasde Jeroboamhijode Joasreyde Israel, dosañosantesdel terremoto."],[1,2,"Y dijo: Jehovábramará desde Sión, y darásu vozdesde Jerusalem; y las estanciasde los pastoresse enlutarán, y secarásela cumbredel Carmelo.","Y dijo: Jehovábramará desde Sión, y darásu vozdesde Jerusalem; y las estanciasde los pastoresse enlutarán, y secarásela cumbredel Carmelo."],[1,3,"Asíha dichoJehová: Portrespecadosde Damasco, y porel cuarto, nodesviarésu castigo; porquetrillaron á Galaadcon trillosde hierro.","Asíha dichoJehová: Portrespecadosde Damasco, y porel cuarto, nodesviarésu castigo; porquetrillaron á Galaadcon trillosde hierro."],[1,4,"Y meteréfuegoen la casade Hazael, y consumirálos palaciosde Benhadad.","Y meteréfuegoen la casade Hazael, y consumirálos palaciosde Benhadad."],[1,5,"Y quebraréla barra de Damasco, y talarélos moradoresde Bicath-aven, y los gobernadoresde Beth-eden: y el pueblode Aramserá trasportadoá Chîr, diceJehová.","Y quebraréla barra de Damasco, y talarélos moradoresde Bicath-aven, y los gobernadoresde Beth-eden: y el pueblode Aramserá trasportadoá Chîr, diceJehová."],[1,6,"Asíha dichoJehová: Portrespecadosde Gaza, y porel cuarto, nodesviarésu castigo; porquellevó cautivatoda la cautividad, para entregarlosá Edom.","Asíha dichoJehová: Portrespecadosde Gaza, y porel cuarto, nodesviarésu castigo; porquellevó cautivatoda la cautividad, para entregarlosá Edom."],[1,7,"Y meteréfuegoen el murode Gaza, y quemarásus palacios.","Y meteréfuegoen el murode Gaza, y quemarásus palacios."],[1,8,"Y talarélos moradoresde Azoto, y los gobernadoresde Ascalón: y tornarémi manosobre Ecrón, y las reliquias de los Palestinosperecerán, ha dichoel SeñorJehová.","Y talarélos moradoresde Azoto, y los gobernadoresde Ascalón: y tornarémi manosobre Ecrón, y las reliquias de los Palestinosperecerán, ha dichoel SeñorJehová."],[1,9,"Asíha dichoJehová: Portrespecadosde Tiro, y porel cuarto, nodesviarésu castigo; porqueentregaronla cautividad entera á Edom, y nose acordarondel conciertode hermanos.","Asíha dichoJehová: Portrespecadosde Tiro, y porel cuarto, nodesviarésu castigo; porqueentregaronla cautividad entera á Edom, y nose acordarondel conciertode hermanos."],[1,10,"Y meteréfuegoen el murode Tiro, y consumirásus palacios.","Y meteréfuegoen el murode Tiro, y consumirásus palacios."],[1,11,"Asíha dichoJehová: Portrespecadosde Edom, y porel cuarto, nodesviarésu castigo; porquepersiguióá cuchilloá su hermano, y rompiósus conmiseraciones; y con su furorle ha robadosiempre, y ha perpetuamenteguardadoel enojo.","Asíha dichoJehová: Portrespecadosde Edom, y porel cuarto, nodesviarésu castigo; porquepersiguióá cuchilloá su hermano, y rompiósus conmiseraciones; y con su furorle ha robadosiempre, y ha perpetuamenteguardadoel enojo."],[1,12,"Y meteréfuegoen Temán, y consumirálos palaciosde Bosra.","Y meteréfuegoen Temán, y consumirálos palaciosde Bosra."],[1,13,"Asíha dichoJehová: Portrespecadosde los hijosde Ammón, y porel cuarto, nodesviarésu castigo; porqueabrieronlas preñadasde Galaad, para ensancharsu término.","Asíha dichoJehová: Portrespecadosde los hijosde Ammón, y porel cuarto, nodesviarésu castigo; porqueabrieronlas preñadasde Galaad, para ensancharsu término."],[1,14,"Y encenderéfuegoen el murode Rabba, y consumirásus palacioscon estruendoen díade batalla, con tempestaden díatempestuoso:","Y encenderéfuegoen el murode Rabba, y consumirásus palacioscon estruendoen díade batalla, con tempestaden díatempestuoso:"],[1,15,"Y su reyiráen cautiverio, ély suspríncipestodos, diceJehová.","Y su reyiráen cautiverio, ély suspríncipestodos, diceJehová."],[2,1,"ASÍha dichoJehová: Portrespecadosde Moab, y porel cuarto, nodesviarésu castigo; porquequemólos huesosdel reyde Idumeahasta tornarlosen cal.","ASÍha dichoJehová: Portrespecadosde Moab, y porel cuarto, nodesviarésu castigo; porquequemólos huesosdel reyde Idumeahasta tornarlosen cal."],[2,2,"Y meteré fuegoen Moab, y consumirálos palaciosde Chêrioth: y moriráMoaben alboroto, en estrépitoy sonidode trompeta.","Y meteré fuegoen Moab, y consumirálos palaciosde Chêrioth: y moriráMoaben alboroto, en estrépitoy sonidode trompeta."],[2,3,"Y quitaréel juezde en mediode él, y mataréconél á todossus príncipes, diceJehová.","Y quitaréel juezde en mediode él, y mataréconél á todossus príncipes, diceJehová."],[2,4,"Asíha dichoJehová: Portrespecadosde Judá, y porel cuarto, nodesviarésu castigo; porquemenospreciaronla leyde Jehová, y noguardaronsus ordenanzas; é hiciéronlos errarsus mentiras, en posde las cuales anduvieronsus padres.","Asíha dichoJehová: Portrespecadosde Judá, y porel cuarto, nodesviarésu castigo; porquemenospreciaronla leyde Jehová, y noguardaronsus ordenanzas; é hiciéronlos errarsus mentiras, en posde las cuales anduvieronsus padres."],[2,5,"Meterépor tanto fuegoen Judá, el cual consumirálos palaciosde Jerusalem.","Meterépor tanto fuegoen Judá, el cual consumirálos palaciosde Jerusalem."],[2,6,"Asíha dichoJehová: Portrespecadosde Israel, y porel cuarto, nodesviarésu castigo; porquevendieronpordineroal justo, y al pobreporun par de zapatos:","Asíha dichoJehová: Portrespecadosde Israel, y porel cuarto, nodesviarésu castigo; porquevendieronpordineroal justo, y al pobreporun par de zapatos:"],[2,7,"Que anhelanporque haya polvode tierrasobre la cabezade los pobres, y tuercenel caminode los humildes: y el hombre y su padreentraronála mismamoza, profanandomi santonombre.","Que anhelanporque haya polvode tierrasobre la cabezade los pobres, y tuercenel caminode los humildes: y el hombre y su padreentraronála mismamoza, profanandomi santonombre."],[2,8,"Y sobrelas ropasempeñadasse acuestanjuntoá cualquieraltar; y el vinode los penadosbebenen la casade sus dioses.","Y sobrelas ropasempeñadasse acuestanjuntoá cualquieraltar; y el vinode los penadosbebenen la casade sus dioses."],[2,9,"Y yodestruídelantede ellos al Amorrheo, cuyaalturaera como la alturade los cedros, y fuertecomo un alcornoque; y destruísufrutoarriba, susraícesabajo.","Y yodestruídelantede ellos al Amorrheo, cuyaalturaera como la alturade los cedros, y fuertecomo un alcornoque; y destruísufrutoarriba, susraícesabajo."],[2,10,"Y yo os hice á vosotros subirde la tierrade Egipto, y os traje por el desiertocuarentaaños, para que poseyeseis la tierradel Amorrheo.","Y yo os hice á vosotros subirde la tierrade Egipto, y os traje por el desiertocuarentaaños, para que poseyeseis la tierradel Amorrheo."],[2,11,"Y levantéde vuestros hijospara profetas, y de vuestros mancebospara que fuesen Nazareos. ¿No es estoasí, diceJehová, hijosde Israel?","Y levantéde vuestros hijospara profetas, y de vuestros mancebospara que fuesen Nazareos. ¿No es estoasí, diceJehová, hijosde Israel?"],[2,12,"Mas vosotros disteis de bebervinoá los Nazareos; y álos profetasmandasteis, diciendo: Noprofeticéis.","Mas vosotros disteis de bebervinoá los Nazareos; y álos profetasmandasteis, diciendo: Noprofeticéis."],[2,13,"Pues he aquí, yoosapretaréen vuestro lugar, como se aprietael carrollenode haces;","Pues he aquí, yoosapretaréen vuestro lugar, como se aprietael carrollenode haces;"],[2,14,"Y la huídaperecerádel ligero, y el fuertenoesforzarásu fuerza, ni el valientelibrarásu vida;","Y la huídaperecerádel ligero, y el fuertenoesforzarásu fuerza, ni el valientelibrarásu vida;"],[2,15,"Y el que toma el arconoresistirá, niescaparáel ligerode pies, niel que cabalgaen caballosalvarásu vida.","Y el que toma el arconoresistirá, niescaparáel ligerode pies, niel que cabalgaen caballosalvarásu vida."],[2,16,"El esforzadoentre esforzados huirá desnudoaqueldía, diceJehová.","El esforzadoentre esforzados huirá desnudoaqueldía, diceJehová."],[3,1,"OIDesta palabraqueha habladoJehovácontravosotros, hijosde Israel, contratodala familiaquehice subirde la tierrade Egipto. Diceasí:","OIDesta palabraqueha habladoJehovácontravosotros, hijosde Israel, contratodala familiaquehice subirde la tierrade Egipto. Diceasí:"],[3,2,"A vosotros solamentehe conocidode todaslas familiasde la tierra; portantovisitarécontra vosotros todasvuestras maldades.","A vosotros solamentehe conocidode todaslas familiasde la tierra; portantovisitarécontra vosotros todasvuestras maldades."],[3,3,"¿Andarándosjuntos, sinoestuvieren de concierto?","¿Andarándosjuntos, sinoestuvieren de concierto?"],[3,4,"¿Bramaráel leónen el montesinhacer presa? ¿daráel leoncillosu bramidodesde su morada, sinoprendiere?","¿Bramaráel leónen el montesinhacer presa? ¿daráel leoncillosu bramidodesde su morada, sinoprendiere?"],[3,5,"¿Caeráel aveenel lazoenla tierra, sinhaber armador? ¿alzaráseel lazodela tierra, si nose ha prendidoalgo?","¿Caeráel aveenel lazoenla tierra, sinhaber armador? ¿alzaráseel lazodela tierra, si nose ha prendidoalgo?"],[3,6,"¿Tocarásela trompetaen la ciudad, y nose alborotaráel pueblo? ¿habráalgún malen la ciudad, el cual Jehovánohaya hecho?","¿Tocarásela trompetaen la ciudad, y nose alborotaráel pueblo? ¿habráalgún malen la ciudad, el cual Jehovánohaya hecho?"],[3,7,"Porquenoharánadael SeñorJehová, sin que revelesu secretoásus siervoslos profetas.","Porquenoharánadael SeñorJehová, sin que revelesu secretoásus siervoslos profetas."],[3,8,"Bramandoel león, ¿quiénnotemerá? hablandoel SeñorJehová, ¿quiénnoprofetizará?","Bramandoel león, ¿quiénnotemerá? hablandoel SeñorJehová, ¿quiénnoprofetizará?"],[3,9,"Haced pregonarsobrelos palaciosde Azoto, y sobrelos palaciosde tierrade Egipto, y decid: Reuníossobrelos montesde Samaria, y vedmuchasopresionesen mediode ella, y violenciasen mediode ella.","Haced pregonarsobrelos palaciosde Azoto, y sobrelos palaciosde tierrade Egipto, y decid: Reuníossobrelos montesde Samaria, y vedmuchasopresionesen mediode ella, y violenciasen mediode ella."],[3,10,"Y nosabenhacerlo recto, diceJehová, atesorandorapiñasy despojosen sus palacios.","Y nosabenhacerlo recto, diceJehová, atesorandorapiñasy despojosen sus palacios."],[3,11,"Por tanto, el SeñorJehováha dichoasí: Un enemigohabráaún por todoslados de la tierra, y derribaráde ti tu fortaleza, y tus palaciosserán saqueados.","Por tanto, el SeñorJehováha dichoasí: Un enemigohabráaún por todoslados de la tierra, y derribaráde ti tu fortaleza, y tus palaciosserán saqueados."],[3,12,"Asíha dichoJehová: De la manera que el pastorlibrade la bocadel leóndospiernas, óla puntade una oreja, asíescaparánlos hijosde Israelque moranen Samariaen el rincónde la cama, y al canto del lecho.","Asíha dichoJehová: De la manera que el pastorlibrade la bocadel leóndospiernas, óla puntade una oreja, asíescaparánlos hijosde Israelque moranen Samariaen el rincónde la cama, y al canto del lecho."],[3,13,"Oidy protestad en la casade Jacob, ha dichoJehováDiosde los ejércitos:","Oidy protestad en la casade Jacob, ha dichoJehováDiosde los ejércitos:"],[3,14,"Queel díaquevisitarélas rebelionesde Israelsobre él, visitarétambién sobre los altaresde Beth-el; y serán cortadoslos cuernosdel altar, y caeráná tierra.","Queel díaquevisitarélas rebelionesde Israelsobre él, visitarétambién sobre los altaresde Beth-el; y serán cortadoslos cuernosdel altar, y caeráná tierra."],[3,15,"Y heriréla casadel inviernoconla casadel verano, y las casasde marfilperecerán; y muchascasasserán arruinadas, diceJehová.","Y heriréla casadel inviernoconla casadel verano, y las casasde marfilperecerán; y muchascasasserán arruinadas, diceJehová."],[4,1,"OIDesta palabra, vacasde Basán, queestáis en el montede Samaria, que oprimíslos pobres, que quebrantáislos menesterosos, que decísá sus señores: Traed, y beberemos.","OIDesta palabra, vacasde Basán, queestáis en el montede Samaria, que oprimíslos pobres, que quebrantáislos menesterosos, que decísá sus señores: Traed, y beberemos."],[4,2,"El SeñorJehovájurópor su santidad: He aquí, vienendíassobrevosotros en que os llevará en anzuelos, y á vuestros descendientesen barquillosde pescador.","El SeñorJehovájurópor su santidad: He aquí, vienendíassobrevosotros en que os llevará en anzuelos, y á vuestros descendientesen barquillosde pescador."],[4,3,"Y saldránpor los portillosla una en pos de la otra, y seréis echadasdel palacio, diceJehová.","Y saldránpor los portillosla una en pos de la otra, y seréis echadasdel palacio, diceJehová."],[4,4,"Idá Beth-el, y prevaricad; en Gilgalaumentadla rebelión, y traedde mañanavuestros sacrificios, y vuestros diezmoscada tresaños;","Idá Beth-el, y prevaricad; en Gilgalaumentadla rebelión, y traedde mañanavuestros sacrificios, y vuestros diezmoscada tresaños;"],[4,5,"Y ofrecedsacrificio de alabanzacon leudo, y pregonad, publicadvoluntariasofrendas; puesque asílo queréis, hijosde Israel, diceel SeñorJehová.","Y ofrecedsacrificio de alabanzacon leudo, y pregonad, publicadvoluntariasofrendas; puesque asílo queréis, hijosde Israel, diceel SeñorJehová."],[4,6,"Yo también os dí limpieza de dientes en todasvuestras ciudades, y faltade panen todosvuestros pueblos: mas noos tornasteisámí, diceJehová.","Yo también os dí limpieza de dientes en todasvuestras ciudades, y faltade panen todosvuestros pueblos: mas noos tornasteisámí, diceJehová."],[4,7,"Y tambiényo osdetuvela lluviatresmesesantes de la siega: é hice lloversobreunaciudad, y sobreotraciudadnohice llover: sobreunapartellovió; la partesobrela cualnollovió, secóse.","Y tambiényo osdetuvela lluviatresmesesantes de la siega: é hice lloversobreunaciudad, y sobreotraciudadnohice llover: sobreunapartellovió; la partesobrela cualnollovió, secóse."],[4,8,"Y veníandosó tresciudadesá unaciudadpara beberagua, y nose hartaban: con todo noos tornasteisámí, diceJehová.","Y veníandosó tresciudadesá unaciudadpara beberagua, y nose hartaban: con todo noos tornasteisámí, diceJehová."],[4,9,"Os herícon viento solanoy oruga; vuestros muchoshuertosy vuestras viñas, y vuestros higueralesy vuestros olivarescomióla langosta: pero nuncaos tornasteisámí, diceJehová.","Os herícon viento solanoy oruga; vuestros muchoshuertosy vuestras viñas, y vuestros higueralesy vuestros olivarescomióla langosta: pero nuncaos tornasteisámí, diceJehová."],[4,10,"Enviéentre vosotros mortandadal modo que en Egipto: matéá cuchillovuestros mancebos, concautiveriode vuestros caballos; é hice subirel hedorde vuestros realeshasta vuestras narices: empero noos tornasteisámí, diceJehová.","Enviéentre vosotros mortandadal modo que en Egipto: matéá cuchillovuestros mancebos, concautiveriode vuestros caballos; é hice subirel hedorde vuestros realeshasta vuestras narices: empero noos tornasteisámí, diceJehová."],[4,11,"Trastornéos, como cuando Diostrastornóá Sodomay á Gomorra, y fuisteiscomo tizónescapadodel fuego: mas noos tornasteisámí, diceJehová.","Trastornéos, como cuando Diostrastornóá Sodomay á Gomorra, y fuisteiscomo tizónescapadodel fuego: mas noos tornasteisámí, diceJehová."],[4,12,"Por tanto, de esta maneraharéá ti, oh Israel: y porquete he de haceresto, aparéjate para venir al encuentroá tu Dios, oh Israel.","Por tanto, de esta maneraharéá ti, oh Israel: y porquete he de haceresto, aparéjate para venir al encuentroá tu Dios, oh Israel."],[4,13,"Porquehe aquí, el que formalos montes, y cría el viento, y denuncia al hombresu pensamiento; el que haceá las tinieblasmañana, y pasasobrelas alturasde la tierra; Jehová, Diosde los ejércitos, es su nombre.","Porquehe aquí, el que formalos montes, y cría el viento, y denuncia al hombresu pensamiento; el que haceá las tinieblasmañana, y pasasobrelas alturasde la tierra; Jehová, Diosde los ejércitos, es su nombre."],[5,1,"OIDesta palabra, porque yolevantoendecha sobrevosotros, casade Israel.","OIDesta palabra, porque yolevantoendecha sobrevosotros, casade Israel."],[5,2,"Cayóla virgende Israel, nomáspodrá levantarse; dejadafué sobresu tierra, nohay quien la levante.","Cayóla virgende Israel, nomáspodrá levantarse; dejadafué sobresu tierra, nohay quien la levante."],[5,3,"Porqueasíha dichoel SeñorJehová: La ciudadque sacaba mil, quedará con ciento; y la que sacabaciento, quedarácon diez, en la casade Israel.","Porqueasíha dichoel SeñorJehová: La ciudadque sacaba mil, quedará con ciento; y la que sacabaciento, quedarácon diez, en la casade Israel."],[5,4,"EmperoasídiceJehováá la casade Israel: Buscadme, y viviréis;","EmperoasídiceJehováá la casade Israel: Buscadme, y viviréis;"],[5,5,"Y nobusquéisá Beth-elnientréisen Gilgal, nipaséisá Beer-seba: porqueGilgalserá llevadaen cautiverio, y Beth-elserá deshecha.","Y nobusquéisá Beth-elnientréisen Gilgal, nipaséisá Beer-seba: porqueGilgalserá llevadaen cautiverio, y Beth-elserá deshecha."],[5,6,"Buscadá Jehová, y vivid; nosea que hienda, como fuego, á la casade José, y la consuma, sinhaber en Beth-elquien lo apague.","Buscadá Jehová, y vivid; nosea que hienda, como fuego, á la casade José, y la consuma, sinhaber en Beth-elquien lo apague."],[5,7,"Los que convierten en ajenjoel juicio, y dejan en tierrala justicia,","Los que convierten en ajenjoel juicio, y dejan en tierrala justicia,"],[5,8,"Mirenal que haceel Arcturoy el Orión, y las tinieblasvuelveen mañana, y haceoscurecerel díaen noche; el que llamaá las aguasde la mar, y las derramasobrela hazde la tierra: Jehováes su nombre:","Mirenal que haceel Arcturoy el Orión, y las tinieblasvuelveen mañana, y haceoscurecerel díaen noche; el que llamaá las aguasde la mar, y las derramasobrela hazde la tierra: Jehováes su nombre:"],[5,9,"Que da esfuerzoal despojadorsobreel fuerte, y que el despojadorvengacontra la fortaleza.","Que da esfuerzoal despojadorsobreel fuerte, y que el despojadorvengacontra la fortaleza."],[5,10,"Ellos aborrecieronen la puertaal reprensor, y al que hablabalo rectoabominaron.","Ellos aborrecieronen la puertaal reprensor, y al que hablabalo rectoabominaron."],[5,11,"Por tanto, pues que vejáisalpobrey recibísdeél cargadetrigo; edificasteiscasasde sillares, mas nolas habitaréis; plantasteishermosasviñas, mas nobeberéisel vinodeellas.","Por tanto, pues que vejáisalpobrey recibísdeél cargadetrigo; edificasteiscasasde sillares, mas nolas habitaréis; plantasteishermosasviñas, mas nobeberéisel vinodeellas."],[5,12,"Porquesabido he vuestras muchasrebeliones, y vuestros grandespecados: que afligen al justo, y reciben cohecho, y á los pobresen la puertahacen perdersu causa.","Porquesabido he vuestras muchasrebeliones, y vuestros grandespecados: que afligen al justo, y reciben cohecho, y á los pobresen la puertahacen perdersu causa."],[5,13,"Por tanto, el prudenteen tal tiempo calla, porqueel tiempoes malo.","Por tanto, el prudenteen tal tiempo calla, porqueel tiempoes malo."],[5,14,"Buscadlo bueno, y nolo malo, para que viváis; porque asíJehováDiosde los ejércitosserá convosotros, como decís.","Buscadlo bueno, y nolo malo, para que viváis; porque asíJehováDiosde los ejércitosserá convosotros, como decís."],[5,15,"Aborrecedel mal, y amadel bien, y poned juicioen la puerta: quizáJehová, Diosde los ejércitos, tendrá piedaddel remanentede José.","Aborrecedel mal, y amadel bien, y poned juicioen la puerta: quizáJehová, Diosde los ejércitos, tendrá piedaddel remanentede José."],[5,16,"Por tanto, asíha dichoJehováDiosde los ejércitos, el Señor: En todaslas plazashabrá llanto, y en todaslas callesdirán, ¡Ay! ¡ay! y al labradorllamaráná lloro, y á endechaálos que endecharsupieren.","Por tanto, asíha dichoJehováDiosde los ejércitos, el Señor: En todaslas plazashabrá llanto, y en todaslas callesdirán, ¡Ay! ¡ay! y al labradorllamaráná lloro, y á endechaálos que endecharsupieren."],[5,17,"Y en todaslas viñashabrá llanto; porquepasarépor mediode ti, diceJehová.","Y en todaslas viñashabrá llanto; porquepasarépor mediode ti, diceJehová."],[5,18,"¡Ayde los que deseanel díade Jehová! ¿para quéqueréis estedíade Jehová? Será detinieblas, y noluz:","¡Ayde los que deseanel díade Jehová! ¿para quéqueréis estedíade Jehová? Será detinieblas, y noluz:"],[5,19,"Comoelque huyede delantedel león, y se topa con eloso; ó si entrareen casay arrimare su manoá la pared, y le muerda la culebra.","Comoelque huyede delantedel león, y se topa con eloso; ó si entrareen casay arrimare su manoá la pared, y le muerda la culebra."],[5,20,"¿Noserá el díade Jehovátinieblas, y noluz; oscuridad, que notiene resplandor?","¿Noserá el díade Jehovátinieblas, y noluz; oscuridad, que notiene resplandor?"],[5,21,"Aborrecí, abominévuestras solemnidades, y nome darán buen olor vuestras asambleas.","Aborrecí, abominévuestras solemnidades, y nome darán buen olor vuestras asambleas."],[5,22,"Ysime ofreciereisholocaustosyvuestros presentes, nolos recibiré; nimiraréá los pacíficosde vuestros engordados.","Ysime ofreciereisholocaustosyvuestros presentes, nolos recibiré; nimiraréá los pacíficosde vuestros engordados."],[5,23,"Quitade mí la multitudde tus cantares, que noescucharélas salmodiasde tus instrumentos.","Quitade mí la multitudde tus cantares, que noescucharélas salmodiasde tus instrumentos."],[5,24,"Antes corrael juiciocomo las aguas, y la justiciacomo impetuosoarroyo.","Antes corrael juiciocomo las aguas, y la justiciacomo impetuosoarroyo."],[5,25,"¿Habéisme ofrecido sacrificiosy presentesen el desiertoen cuarentaaños, casade Israel?","¿Habéisme ofrecido sacrificiosy presentesen el desiertoen cuarentaaños, casade Israel?"],[5,26,"Mas llevabaisel tabernáculode vuestro Molochy Chiún, ídolosvuestros, la estrellade vuestros diosesqueos hicisteis.","Mas llevabaisel tabernáculode vuestro Molochy Chiún, ídolosvuestros, la estrellade vuestros diosesqueos hicisteis."],[5,27,"Hareos pues trasportar más alláde Damasco, ha dichoJehová, cuyo nombrees Diosde los ejércitos.","Hareos pues trasportar más alláde Damasco, ha dichoJehová, cuyo nombrees Diosde los ejércitos."],[6,1,"¡AYde los reposadosen Sión, y de los confiadosen el montede Samaria, nombradosprincipalesentre las mismas naciones, las cualesvendrán sobre ellos, oh casade Israel!","¡AYde los reposadosen Sión, y de los confiadosen el montede Samaria, nombradosprincipalesentre las mismas naciones, las cualesvendrán sobre ellos, oh casade Israel!"],[6,2,"Pasadá Calne, y mirad; y deallíidá la granHamath; descendedluego á Gathdelos Palestinos: vedsi sonaquellos reinos mejoresque estos reinos, sisu término esmayorque vuestro término.","Pasadá Calne, y mirad; y deallíidá la granHamath; descendedluego á Gathdelos Palestinos: vedsi sonaquellos reinos mejoresque estos reinos, sisu término esmayorque vuestro término."],[6,3,"Vosotros que dilatáisel díamalo, y acercáisla sillade iniquidad;","Vosotros que dilatáisel díamalo, y acercáisla sillade iniquidad;"],[6,4,"Duermenencamasde marfil, y se extienden sobresus lechos; y comenlos corderosdel rebaño, y los becerros de enmediodel engordadero;","Duermenencamasde marfil, y se extienden sobresus lechos; y comenlos corderosdel rebaño, y los becerros de enmediodel engordadero;"],[6,5,"Gorjeanalsonde la flauta, é inventaninstrumentosmúsicos, como David;","Gorjeanalsonde la flauta, é inventaninstrumentosmúsicos, como David;"],[6,6,"Bebenvinoen tazones, y se ungencon los ungüentosmás preciosos; y nose afligenporel quebrantamientode José.","Bebenvinoen tazones, y se ungencon los ungüentosmás preciosos; y nose afligenporel quebrantamientode José."],[6,7,"Por tanto, ahorapasaránen el principiode los que á cautividadpasaren, y se acercaráel clamor de los extendidos.","Por tanto, ahorapasaránen el principiode los que á cautividadpasaren, y se acercaráel clamor de los extendidos."],[6,8,"El SeñorJehovájurópor su alma, JehováDiosde los ejércitosha dicho: Tengo en abominación la grandezade Jacob, y aborrezcosus palacios: y la ciudady su plenitud entregaréal enemigo.","El SeñorJehovájurópor su alma, JehováDiosde los ejércitosha dicho: Tengo en abominación la grandezade Jacob, y aborrezcosus palacios: y la ciudady su plenitud entregaréal enemigo."],[6,9,"Y aconteceráque sidiezhombresquedarenen unacasa, morirán.","Y aconteceráque sidiezhombresquedarenen unacasa, morirán."],[6,10,"Y su tío tomaráá cada uno, y quemarále para sacarlos huesosde casa; y diráal queestará en los rinconesde la casa: ¿Hay aúnalguno contigo? Y dirá: No. Y diráaquél: Calla, quenopodemoshacer mención del nombrede Jehová.","Y su tío tomaráá cada uno, y quemarále para sacarlos huesosde casa; y diráal queestará en los rinconesde la casa: ¿Hay aúnalguno contigo? Y dirá: No. Y diráaquél: Calla, quenopodemoshacer mención del nombrede Jehová."],[6,11,"Porquehe aquí, Jehovámandará, y herirácon hendidurasla casamayor, y la casamenorcon aberturas.","Porquehe aquí, Jehovámandará, y herirácon hendidurasla casamayor, y la casamenorcon aberturas."],[6,12,"¿Correránlos caballospor las peñas? ¿araránen ellascon vacas? ¿porqué habéis vosotros tornadoel juicioen veneno, y el frutode justiciaen ajenjo?","¿Correránlos caballospor las peñas? ¿araránen ellascon vacas? ¿porqué habéis vosotros tornadoel juicioen veneno, y el frutode justiciaen ajenjo?"],[6,13,"Vosotros que os alegráisen nada, que decís: ¿Nonos hemos adquiridopotenciacon nuestrafortaleza?","Vosotros que os alegráisen nada, que decís: ¿Nonos hemos adquiridopotenciacon nuestrafortaleza?"],[6,14,"Pueshe aquí, levantaréyo sobrevosotros, oh casade Israel, diceJehováDiosde los ejércitos, genteque os oprimirádesde la entradade Hamathhastael arroyodel desierto.","Pueshe aquí, levantaréyo sobrevosotros, oh casade Israel, diceJehováDiosde los ejércitos, genteque os oprimirádesde la entradade Hamathhastael arroyodel desierto."],[7,1,"ASÍme ha mostradoel SeñorJehová: y he aquí, él criabalangostasal principio que comenzabaá crecerel henotardío; y he aquí, era el henotardío despuésde las siegasdel rey.","ASÍme ha mostradoel SeñorJehová: y he aquí, él criabalangostasal principio que comenzabaá crecerel henotardío; y he aquí, era el henotardío despuésde las siegasdel rey."],[7,2,"Y acaecióque como acabóde comerla hierbade la tierra, yo dije: SeñorJehová, perdonaahora; ¿quiénlevantaráá Jacob? porquees pequeño.","Y acaecióque como acabóde comerla hierbade la tierra, yo dije: SeñorJehová, perdonaahora; ¿quiénlevantaráá Jacob? porquees pequeño."],[7,3,"ArrepintióseJehovádeesto: Noserá, dijoJehová.","ArrepintióseJehovádeesto: Noserá, dijoJehová."],[7,4,"El SeñorJehováme mostróasí: y he aquí, llamabapara juzgarpor fuegoel SeñorJehová; y consumióun granabismo, y consumióuna partede la tierra.","El SeñorJehováme mostróasí: y he aquí, llamabapara juzgarpor fuegoel SeñorJehová; y consumióun granabismo, y consumióuna partede la tierra."],[7,5,"Y dije: SeñorJehová, cesaahora; ¿quiénlevantaráá Jacob? porquees pequeño.","Y dije: SeñorJehová, cesaahora; ¿quiénlevantaráá Jacob? porquees pequeño."],[7,6,"ArrepintióseJehovádeesto: Noseráestotampoco, dijoel SeñorJehová.","ArrepintióseJehovádeesto: Noseráestotampoco, dijoel SeñorJehová."],[7,7,"Enseñómeasí: he aquí, el Señorestabasobreun murohecho á plomo, y en su manouna plomadade albañil.","Enseñómeasí: he aquí, el Señorestabasobreun murohecho á plomo, y en su manouna plomadade albañil."],[7,8,"Jehováentonces medijo: ¿Quéves, Amós? Y dije: Una plomadade albañil. Y el Señordijo: He aquí, yo pongoplomadade albañil en mediode mi puebloIsrael: nole pasarémás:","Jehováentonces medijo: ¿Quéves, Amós? Y dije: Una plomadade albañil. Y el Señordijo: He aquí, yo pongoplomadade albañil en mediode mi puebloIsrael: nole pasarémás:"],[7,9,"Y los altaresde Isaacserán destruídos, y los santuariosde Israelserán asolados; y levantarémecon espadasobrela casade Jeroboam.","Y los altaresde Isaacserán destruídos, y los santuariosde Israelserán asolados; y levantarémecon espadasobrela casade Jeroboam."],[7,10,"Entonces Amasíassacerdotede Beth-elenvióá deciráJeroboam, reyde Israel: Amósse ha conjurado contrati en mediode la casade Israel: la tierranopuedesufrirtodassus palabras.","Entonces Amasíassacerdotede Beth-elenvióá deciráJeroboam, reyde Israel: Amósse ha conjurado contrati en mediode la casade Israel: la tierranopuedesufrirtodassus palabras."],[7,11,"Porqueasíha dichoAmós: Jeroboammoriráá cuchillo, é Israelpasaráde su tierraen cautiverio.","Porqueasíha dichoAmós: Jeroboammoriráá cuchillo, é Israelpasaráde su tierraen cautiverio."],[7,12,"Y Amasíasdijoá Amós: Vidente, vete, y huyeátierrade Judá, y comeallátu pan, y profetizaallí:","Y Amasíasdijoá Amós: Vidente, vete, y huyeátierrade Judá, y comeallátu pan, y profetizaallí:"],[7,13,"Y noprofeticesmásen Beth-el, porquees santuariodel rey, y cabecera del reino.","Y noprofeticesmásen Beth-el, porquees santuariodel rey, y cabecera del reino."],[7,14,"Entonces respondióAmós, y dijoáAmasías: Nosoy profeta, nisoy hijode profeta, sinoque soy boyero, y cogedor de cabrahigos:","Entonces respondióAmós, y dijoáAmasías: Nosoy profeta, nisoy hijode profeta, sinoque soy boyero, y cogedor de cabrahigos:"],[7,15,"Y Jehováme tomóde trasel ganado, y díjomeJehová: Ve, y profetizaámi puebloIsrael.","Y Jehováme tomóde trasel ganado, y díjomeJehová: Ve, y profetizaámi puebloIsrael."],[7,16,"Ahorapues, oyepalabrade Jehová. Túdices: NoprofeticescontraIsrael, nihablescontrala casade Isaac:","Ahorapues, oyepalabrade Jehová. Túdices: NoprofeticescontraIsrael, nihablescontrala casade Isaac:"],[7,17,"Por tanto, asíha dichoJehová: Tumujerfornicaráen la ciudad, y tushijosy tushijascaeráná cuchillo, y tutierraserá partida por suertes; y túmorirásentierrainmunda, é Israelserá traspasadode su tierra.","Por tanto, asíha dichoJehová: Tumujerfornicaráen la ciudad, y tushijosy tushijascaeráná cuchillo, y tutierraserá partida por suertes; y túmorirásentierrainmunda, é Israelserá traspasadode su tierra."],[8,1,"ASÍme ha mostradoJehová: y he aquíun canastillode fruta de verano.","ASÍme ha mostradoJehová: y he aquíun canastillode fruta de verano."],[8,2,"Y dijo: ¿Quéves, Amós? Y dije: Un canastillode fruta de verano. Y díjomeJehová: Venidoha el finsobremi puebloIsrael; no lepasarémás.","Y dijo: ¿Quéves, Amós? Y dije: Un canastillode fruta de verano. Y díjomeJehová: Venidoha el finsobremi puebloIsrael; no lepasarémás."],[8,3,"Y los cantoresdel temploaullaránen aquel día, diceel SeñorJehová; muchosserán los cuerposmuertos; en todolugarechadosserán en silencio.","Y los cantoresdel temploaullaránen aquel día, diceel SeñorJehová; muchosserán los cuerposmuertos; en todolugarechadosserán en silencio."],[8,4,"Oidesto, los que tragáis á los menesterosos, y arruináislos pobresde la tierra,","Oidesto, los que tragáis á los menesterosos, y arruináislos pobresde la tierra,"],[8,5,"Diciendo: ¿Cuándopasaráel mes, y venderemosel trigo; y la semana, y abriremoslos alfolíesdel pan, y achicaremosla medida, y engrandeceremosel precio, y falsearemosel pesoengañoso;","Diciendo: ¿Cuándopasaráel mes, y venderemosel trigo; y la semana, y abriremoslos alfolíesdel pan, y achicaremosla medida, y engrandeceremosel precio, y falsearemosel pesoengañoso;"],[8,6,"Para comprarlos pobrespor dinero, y los necesitadospor un par de zapatos, y venderemoslas aechaduras del trigo?","Para comprarlos pobrespor dinero, y los necesitadospor un par de zapatos, y venderemoslas aechaduras del trigo?"],[8,7,"Jehovájurópor la gloriade Jacob: Nome olvidarépara siempre de todassus obras.","Jehovájurópor la gloriade Jacob: Nome olvidarépara siempre de todassus obras."],[8,8,"¿Nose ha de estremecerla tierrasobreesto? ¿y todohabitadorde ella nollorará? y subirátodacomo un río, y será arrojada, y hundiráse como el ríode Egipto.","¿Nose ha de estremecerla tierrasobreesto? ¿y todohabitadorde ella nollorará? y subirátodacomo un río, y será arrojada, y hundiráse como el ríode Egipto."],[8,9,"Y acaeceráen aquel día, diceel SeñorJehová, que haré se pongael solal mediodía, y la tierracubriré de tinieblasen el díaclaro.","Y acaeceráen aquel día, diceel SeñorJehová, que haré se pongael solal mediodía, y la tierracubriré de tinieblasen el díaclaro."],[8,10,"Y tornaré vuestras fiestasen lloro, y todosvuestros cantaresen endechas; y haré ponersacosobretodoslomos, y peladura sobretodacabeza; y tornarélacomo en llantode unigénito, y su postrimeríacomo díaamargo.","Y tornaré vuestras fiestasen lloro, y todosvuestros cantaresen endechas; y haré ponersacosobretodoslomos, y peladura sobretodacabeza; y tornarélacomo en llantode unigénito, y su postrimeríacomo díaamargo."],[8,11,"He aquívienendías, diceel SeñorJehová, en los cuales enviaréhambreá la tierra, nohambrede pan, nisedde agua, sino de oirpalabrade Jehová.","He aquívienendías, diceel SeñorJehová, en los cuales enviaréhambreá la tierra, nohambrede pan, nisedde agua, sino de oirpalabrade Jehová."],[8,12,"E irán errantesde marámar: desde el nortehastael orientediscurrirán buscandopalabrade Jehová, y nola hallarán.","E irán errantesde marámar: desde el nortehastael orientediscurrirán buscandopalabrade Jehová, y nola hallarán."],[8,13,"En aquel tiempolas doncellashermosasy los mancebosdesmayaránde sed.","En aquel tiempolas doncellashermosasy los mancebosdesmayaránde sed."],[8,14,"Los que juranpor el pecadode Samaria, y dicen, Vive tu Diosde Dan: y, Vive el caminode Beer-seba: caerán, y nuncamásse levantarán.","Los que juranpor el pecadode Samaria, y dicen, Vive tu Diosde Dan: y, Vive el caminode Beer-seba: caerán, y nuncamásse levantarán."],[9,1,"VIal Señorque estabasobreel altar, y dijo: Hiere el umbral, y estremézcanselas puertas: y córtales en piezas la cabezade todos; y el postrerode ellos mataréá cuchillo: nohabrá de ellos quien se fugue, niquien escape.","VIal Señorque estabasobreel altar, y dijo: Hiere el umbral, y estremézcanselas puertas: y córtales en piezas la cabezade todos; y el postrerode ellos mataréá cuchillo: nohabrá de ellos quien se fugue, niquien escape."],[9,2,"Aunquecavasenhasta el infierno, de allálos tomarámi mano; y si subierenhasta el cielo, de allálos haré descender.","Aunquecavasenhasta el infierno, de allálos tomarámi mano; y si subierenhasta el cielo, de allálos haré descender."],[9,3,"Y sise escondierenen la cumbredel Carmelo, allílos buscaréy los tomaré; y aunquese escondierende delantede mis ojosen el profundode la mar, allímandaréá la culebra, y morderálos.","Y sise escondierenen la cumbredel Carmelo, allílos buscaréy los tomaré; y aunquese escondierende delantede mis ojosen el profundode la mar, allímandaréá la culebra, y morderálos."],[9,4,"Y sifuerenen cautiverio, delantede sus enemigos, allímandaréal cuchillo, y los matará; y pondrésobreellos mis ojospara mal, y nopara bien.","Y sifuerenen cautiverio, delantede sus enemigos, allímandaréal cuchillo, y los matará; y pondrésobreellos mis ojospara mal, y nopara bien."],[9,5,"El SeñorJehováde los ejércitosesel que tocala tierra, y se derretirá, y llorarántodoslos que en ella moran: y subirá todacomo un río, y hundiráseluego como el ríode Egipto.","El SeñorJehováde los ejércitosesel que tocala tierra, y se derretirá, y llorarántodoslos que en ella moran: y subirá todacomo un río, y hundiráseluego como el ríode Egipto."],[9,6,"El edificóen el cielosus gradas, y ha establecidosu expansiónsobrela tierra: él llamalas aguasde la mar, y sobrela hazde la tierralas derrama: Jehováes su nombre.","El edificóen el cielosus gradas, y ha establecidosu expansiónsobrela tierra: él llamalas aguasde la mar, y sobrela hazde la tierralas derrama: Jehováes su nombre."],[9,7,"Hijosde Israel, ¿nome sois vosotros, diceJehová, como hijosde Etiopes? ¿nohice yo subirá Israelde la tierrade Egipto, y á los Palestinosde Caphtor, y de Chîrá los Arameos?","Hijosde Israel, ¿nome sois vosotros, diceJehová, como hijosde Etiopes? ¿nohice yo subirá Israelde la tierrade Egipto, y á los Palestinosde Caphtor, y de Chîrá los Arameos?"],[9,8,"He aquílos ojosdel SeñorJehováestán contra el reinopecador, y yo lo asolaréde la hazde la tierra: masnodestruirédel todola casade Jacob, diceJehová.","He aquílos ojosdel SeñorJehováestán contra el reinopecador, y yo lo asolaréde la hazde la tierra: masnodestruirédel todola casade Jacob, diceJehová."],[9,9,"Porquehe aquíyomandaré, y haré que la casade Israelsea zarandeadaentre todaslas gentes, como se zarandeael granoen un harnero, y nocaeun granitoen la tierra.","Porquehe aquíyomandaré, y haré que la casade Israelsea zarandeadaentre todaslas gentes, como se zarandeael granoen un harnero, y nocaeun granitoen la tierra."],[9,10,"A cuchillomorirántodoslos pecadoresde mi pueblo, que dicen: Nose acercará, ni nosalcanzaráel mal.","A cuchillomorirántodoslos pecadoresde mi pueblo, que dicen: Nose acercará, ni nosalcanzaráel mal."],[9,11,"En aquel díayo levantaréel tabernáculode David, caído, y cerrarésus portillos, y levantarésusruinas, y edificarélocomo en el tiempopasado;","En aquel díayo levantaréel tabernáculode David, caído, y cerrarésus portillos, y levantarésusruinas, y edificarélocomo en el tiempopasado;"],[9,12,"Paraque aquellos sobrelos cualeses llamado mi nombre, poseanel restode Idumea, y á todaslas naciones, diceJehováque haceesto.","Paraque aquellos sobrelos cualeses llamado mi nombre, poseanel restode Idumea, y á todaslas naciones, diceJehováque haceesto."],[9,13,"He aquívienendías, diceJehová, en que el que araalcanzaráal segador, y el pisadorde las uvasal que lleva la simiente; y los montesdestilaránmosto, y todoslos colladosse derretirán.","He aquívienendías, diceJehová, en que el que araalcanzaráal segador, y el pisadorde las uvasal que lleva la simiente; y los montesdestilaránmosto, y todoslos colladosse derretirán."],[9,14,"Y tornaréel cautiveriode mi puebloIsrael, y edificaránellos las ciudadesasoladas, y las habitarán; y plantaránviñas, y beberánel vinode ellas; y haránhuertos, y comeránel frutode ellos.","Y tornaréel cautiveriode mi puebloIsrael, y edificaránellos las ciudadesasoladas, y las habitarán; y plantaránviñas, y beberánel vinode ellas; y haránhuertos, y comeránel frutode ellos."],[9,15,"Pues losplantarésobresutierra, y nuncamásserán arrancadosde sutierraqueyo les dí, ha dichoJehováDiostuyo.","Pues losplantarésobresutierra, y nuncamásserán arrancadosde sutierraqueyo les dí, ha dichoJehováDiostuyo."]],"rus-synodal":[[1,1,"Слова Амоса, одного из пастухов Фекойских, которые он слышал в видении об Израиле во дни Озии, царя Иудейского, и во дни Иеровоама, сына Иоасова, царя Израильского, за два года перед землетрясением.","Slova Amosa, odnogo iz pastuhov Fekojskih, kotorye on slyšal v videnii ob Izraile vo dni Ozii, carâ Iudejskogo, i vo dni Ierovoama, syna Ioasova, carâ Izrailʹskogo, za dva goda pered zemletrâseniem."],[1,2,"И сказал он: Господь возгремит с Сиона и даст глас Свой из Иерусалима, и восплачут хижины пастухов, и иссохнет вершина Кармила.","I skazal on: Gospodʹ vozgremit s Siona i dast glas Svoj iz Ierusalima, i vosplačut hižiny pastuhov, i issohnet veršina Karmila."],[1,3,"Так говорит Господь: за три преступления Дамаска и за четыре не пощажу его, потому что они молотили Галаад железными молотилами.","Tak govorit Gospodʹ: za tri prestupleniâ Damaska i za četyre ne poŝažu ego, potomu čto oni molotili Galaad železnymi molotilami."],[1,4,"И пошлю огонь на дом Азаила, и пожрет он чертоги Венадада.","I pošlû ogonʹ na dom Azaila, i požret on čertogi Venadada."],[1,5,"И сокрушу затворы Дамаска, и истреблю жителей долины Авен и держащего скипетр – из дома Еденова, и пойдет народ Арамейский в плен в Кир, говорит Господь.","I sokrušu zatvory Damaska, i istreblû žitelej doliny Aven i deržaŝego skipetr – iz doma Edenova, i pojdet narod Aramejskij v plen v Kir, govorit Gospodʹ."],[1,6,"Так говорит Господь: за три преступления Газы и за четыре не пощажу ее, потому что они вывели всех в плен, чтобы предать их Едому.","Tak govorit Gospodʹ: za tri prestupleniâ Gazy i za četyre ne poŝažu ee, potomu čto oni vyveli vseh v plen, čtoby predatʹ ih Edomu."],[1,7,"И пошлю огонь в стены Газы, и пожрет чертоги ее.","I pošlû ogonʹ v steny Gazy, i požret čertogi ee."],[1,8,"И истреблю жителей Азота и держащего скипетр в Аскалоне, и обращу руку Мою на Екрон, и погибнет остаток Филистимлян, говорит Господь Бог.","I istreblû žitelej Azota i deržaŝego skipetr v Askalone, i obraŝu ruku Moû na Ekron, i pogibnet ostatok Filistimlân, govorit Gospodʹ Bog."],[1,9,"Так говорит Господь: за три преступления Тира и за четыре не пощажу его, потому что они передали всех пленных Едому и не вспомнили братского союза.","Tak govorit Gospodʹ: za tri prestupleniâ Tira i za četyre ne poŝažu ego, potomu čto oni peredali vseh plennyh Edomu i ne vspomnili bratskogo soûza."],[1,10,"Пошлю огонь в стены Тира, и пожрет чертоги его.","Pošlû ogonʹ v steny Tira, i požret čertogi ego."],[1,11,"Так говорит Господь: за три преступления Едома и за четыре не пощажу его, потому что он преследовал брата своего мечом, подавил чувства родства, свирепствовал постоянно во гневе своем и всегда сохранял ярость свою.","Tak govorit Gospodʹ: za tri prestupleniâ Edoma i za četyre ne poŝažu ego, potomu čto on presledoval brata svoego mečom, podavil čuvstva rodstva, svirepstvoval postoânno vo gneve svoem i vsegda sohranâl ârostʹ svoû."],[1,12,"И пошлю огонь на Феман, и пожрет чертоги Восора.","I pošlû ogonʹ na Feman, i požret čertogi Vosora."],[1,13,"Так говорит Господь: за три преступления сынов Аммоновых и за четыре не пощажу их, потому что они рассекали беременных в Галааде, чтобы расширить пределы свои.","Tak govorit Gospodʹ: za tri prestupleniâ synov Ammonovyh i za četyre ne poŝažu ih, potomu čto oni rassekali beremennyh v Galaade, čtoby rasširitʹ predely svoi."],[1,14,"И запалю огонь в стенах Раввы, и пожрет чертоги ее, среди крика в день брани, с вихрем в день бури.","I zapalû ogonʹ v stenah Ravvy, i požret čertogi ee, sredi krika v denʹ brani, s vihrem v denʹ buri."],[1,15,"И пойдет царь их в плен, он и князья его вместе с ним, говорит Господь.","I pojdet carʹ ih v plen, on i knâzʹâ ego vmeste s nim, govorit Gospodʹ."],[2,1,"Так говорит Господь: за три преступления Моава и за четыре не пощажу его, потому что он пережег кости царя Едомского в известь.","Tak govorit Gospodʹ: za tri prestupleniâ Moava i za četyre ne poŝažu ego, potomu čto on perežeg kosti carâ Edomskogo v izvestʹ."],[2,2,"И пошлю огонь на Моава, и пожрет чертоги Кериофа, и погибнет Моав среди разгрома с шумом, при звуке трубы.","I pošlû ogonʹ na Moava, i požret čertogi Keriofa, i pogibnet Moav sredi razgroma s šumom, pri zvuke truby."],[2,3,"Истреблю судью из среды его и умерщвлю всех князей его вместе с ним, говорит Господь.","Istreblû sudʹû iz sredy ego i umerŝvlû vseh knâzej ego vmeste s nim, govorit Gospodʹ."],[2,4,"Так говорит Господь: за три преступления Иуды и за четыре не пощажу его, потому что отвергли закон Господень и постановлений Его не сохранили, и идолы их, вслед которых ходили отцы их, совратили их с пути.","Tak govorit Gospodʹ: za tri prestupleniâ Iudy i za četyre ne poŝažu ego, potomu čto otvergli zakon Gospodenʹ i postanovlenij Ego ne sohranili, i idoly ih, vsled kotoryh hodili otcy ih, sovratili ih s puti."],[2,5,"И пошлю огонь на Иуду, и пожрет чертоги Иерусалима.","I pošlû ogonʹ na Iudu, i požret čertogi Ierusalima."],[2,6,"Так говорит Господь: за три преступления Израиля и за четыре не пощажу его, потому что продают правого за серебро и бедного – за пару сандалий.","Tak govorit Gospodʹ: za tri prestupleniâ Izrailâ i za četyre ne poŝažu ego, potomu čto prodaût pravogo za serebro i bednogo – za paru sandalij."],[2,7,"Жаждут, чтобы прах земной был на голове бедных, и путь кротких извращают; даже отец и сын ходят к одной женщине, чтобы бесславить святое имя Мое.","Žaždut, čtoby prah zemnoj byl na golove bednyh, i putʹ krotkih izvraŝaût; daže otec i syn hodât k odnoj ženŝine, čtoby besslavitʹ svâtoe imâ Moe."],[2,8,"На одеждах, взятых в залог, возлежат при всяком жертвеннике, и вино, взыскиваемое с обвиненных, пьют в доме богов своих.","Na odeždah, vzâtyh v zalog, vozležat pri vsâkom žertvennike, i vino, vzyskivaemoe s obvinennyh, pʹût v dome bogov svoih."],[2,9,"А Я истребил перед лицом их Аморрея, которого высота была как высота кедра и который был крепок как дуб; Я истребил плод его вверху и корни его внизу.","A Â istrebil pered licom ih Amorreâ, kotorogo vysota byla kak vysota kedra i kotoryj byl krepok kak dub; Â istrebil plod ego vverhu i korni ego vnizu."],[2,10,"Вас же Я вывел из земли Египетской и водил вас в пустыне сорок лет, чтобы вам наследовать землю Аморрейскую.","Vas že Â vyvel iz zemli Egipetskoj i vodil vas v pustyne sorok let, čtoby vam nasledovatʹ zemlû Amorrejskuû."],[2,11,"Из сыновей ваших Я избирал в пророки и из юношей ваших – в назореи; не так ли это, сыны Израиля? говорит Господь.","Iz synovej vaših Â izbiral v proroki i iz ûnošej vaših – v nazorei; ne tak li éto, syny Izrailâ? govorit Gospodʹ."],[2,12,"А вы назореев поили вином и пророкам приказывали, говоря: «не пророчествуйте».","A vy nazoreev poili vinom i prorokam prikazyvali, govorâ: «ne proročestvujte»."],[2,13,"Вот, Я придавлю вас, как давит колесница, нагруженная снопами, –","Vot, Â pridavlû vas, kak davit kolesnica, nagružennaâ snopami, –"],[2,14,"и у проворного не станет силы бежать, и крепкий не удержит крепости своей, и храбрый не спасет своей жизни,","i u provornogo ne stanet sily bežatʹ, i krepkij ne uderžit kreposti svoej, i hrabryj ne spaset svoej žizni,"],[2,15,"ни стреляющий из лука не устоит, ни скороход не убежит, ни сидящий на коне не спасет своей жизни.","ni strelâûŝij iz luka ne ustoit, ni skorohod ne ubežit, ni sidâŝij na kone ne spaset svoej žizni."],[2,16,"И самый отважный из храбрых убежит нагой в тот день, говорит Господь.","I samyj otvažnyj iz hrabryh ubežit nagoj v tot denʹ, govorit Gospodʹ."],[3,1,"Слушайте слово сие, которое Господь изрек на вас, сыны Израилевы, на все племя, которое вывел Я из земли Египетской, говоря:","Slušajte slovo sie, kotoroe Gospodʹ izrek na vas, syny Izrailevy, na vse plemâ, kotoroe vyvel Â iz zemli Egipetskoj, govorâ:"],[3,2,"только вас признал Я из всех племен земли, потому и взыщу с вас за все беззакония ваши.","tolʹko vas priznal Â iz vseh plemen zemli, potomu i vzyŝu s vas za vse bezzakoniâ vaši."],[3,3,"Пойдут ли двое вместе, не сговорившись между собою?","Pojdut li dvoe vmeste, ne sgovorivšisʹ meždu soboû?"],[3,4,"Ревет ли лев в лесу, когда нет перед ним добычи? подает ли свой голос львенок из логовища своего, когда он ничего не поймал?","Revet li lev v lesu, kogda net pered nim dobyči? podaet li svoj golos lʹvenok iz logoviŝa svoego, kogda on ničego ne pojmal?"],[3,5,"Попадет ли птица в петлю на земле, когда силка нет для нее? Поднимется ли с земли петля, когда ничего не попало в нее?","Popadet li ptica v petlû na zemle, kogda silka net dlâ nee? Podnimetsâ li s zemli petlâ, kogda ničego ne popalo v nee?"],[3,6,"Трубит ли в городе труба, – и народ не испугался бы? Бывает ли в городе бедствие, которое не Господь попустил бы?","Trubit li v gorode truba, – i narod ne ispugalsâ by? Byvaet li v gorode bedstvie, kotoroe ne Gospodʹ popustil by?"],[3,7,"Ибо Господь Бог ничего не делает, не открыв Своей тайны рабам Своим, пророкам.","Ibo Gospodʹ Bog ničego ne delaet, ne otkryv Svoej tajny rabam Svoim, prorokam."],[3,8,"Лев начал рыкать – кто не содрогнется? Господь Бог сказал – кто не будет пророчествовать?","Lev načal rykatʹ – kto ne sodrognetsâ? Gospodʹ Bog skazal – kto ne budet proročestvovatʹ?"],[3,9,"Провозгласите на кровлях в Азоте и на кровлях в земле Египетской и скажите: соберитесь на горы Самарии и посмотрите на великое бесчинство в ней и на притеснения среди нее.","Provozglasite na krovlâh v Azote i na krovlâh v zemle Egipetskoj i skažite: soberitesʹ na gory Samarii i posmotrite na velikoe besčinstvo v nej i na pritesneniâ sredi nee."],[3,10,"Они не умеют поступать справедливо, говорит Господь: насилием и грабежом собирают сокровища в чертоги свои.","Oni ne umeût postupatʹ spravedlivo, govorit Gospodʹ: nasiliem i grabežom sobiraût sokroviŝa v čertogi svoi."],[3,11,"Посему так говорит Господь Бог: вот неприятель, и притом вокруг всей земли! он низложит могущество твое, и ограблены будут чертоги твои.","Posemu tak govorit Gospodʹ Bog: vot nepriâtelʹ, i pritom vokrug vsej zemli! on nizložit moguŝestvo tvoe, i ogrableny budut čertogi tvoi."],[3,12,"Так говорит Господь: как иногда пастух исторгает из пасти львиной две голени или часть уха, так спасены будут сыны Израилевы, сидящие в Самарии в углу постели и в Дамаске на ложе.","Tak govorit Gospodʹ: kak inogda pastuh istorgaet iz pasti lʹvinoj dve goleni ili častʹ uha, tak spaseny budut syny Izrailevy, sidâŝie v Samarii v uglu posteli i v Damaske na lože."],[3,13,"Слушайте и засвидетельствуйте дому Иакова, говорит Господь Бог, Бог Саваоф.","Slušajte i zasvidetelʹstvujte domu Iakova, govorit Gospodʹ Bog, Bog Savaof."],[3,14,"Ибо в тот день, когда Я взыщу с Израиля за преступления его, взыщу и за жертвенники в Вефиле, и отсечены будут роги алтаря, и падут на землю.","Ibo v tot denʹ, kogda Â vzyŝu s Izrailâ za prestupleniâ ego, vzyŝu i za žertvenniki v Vefile, i otsečeny budut rogi altarâ, i padut na zemlû."],[3,15,"И поражу дом зимний вместе с домом летним, и исчезнут дома с украшениями из слоновой кости, и не станет многих домов, говорит Господь.","I poražu dom zimnij vmeste s domom letnim, i isčeznut doma s ukrašeniâmi iz slonovoj kosti, i ne stanet mnogih domov, govorit Gospodʹ."],[4,1,"Слушайте слово сие, телицы Васанские, которые на горе Самарийской, вы, притесняющие бедных, угнетающие нищих, говорящие господам своим: «подавай, и мы будем пить!»","Slušajte slovo sie, telicy Vasanskie, kotorye na gore Samarijskoj, vy, pritesnâûŝie bednyh, ugnetaûŝie niŝih, govorâŝie gospodam svoim: «podavaj, i my budem pitʹ!»"],[4,2,"Клялся Господь Бог святостью Своею, что вот, придут на вас дни, когда повлекут вас крюками и остальных ваших удами.","Klâlsâ Gospodʹ Bog svâtostʹû Svoeû, čto vot, pridut na vas dni, kogda povlekut vas krûkami i ostalʹnyh vaših udami."],[4,3,"И сквозь проломы стен выйдете, каждая, как случится, и бросите все убранство чертогов, говорит Господь.","I skvozʹ prolomy sten vyjdete, každaâ, kak slučitsâ, i brosite vse ubranstvo čertogov, govorit Gospodʹ."],[4,4,"Идите в Вефиль – и грешите, в Галгал – и умножайте преступления; приносите жертвы ваши каждое утро, десятины ваши хотя через каждые три дня.","Idite v Vefilʹ – i grešite, v Galgal – i umnožajte prestupleniâ; prinosite žertvy vaši každoe utro, desâtiny vaši hotâ čerez každye tri dnâ."],[4,5,"Приносите в жертву благодарения квасное, провозглашайте о добровольных приношениях ваших и разглашайте о них, ибо это вы любите, сыны Израилевы, говорит Господь Бог.","Prinosite v žertvu blagodareniâ kvasnoe, provozglašajte o dobrovolʹnyh prinošeniâh vaših i razglašajte o nih, ibo éto vy lûbite, syny Izrailevy, govorit Gospodʹ Bog."],[4,6,"За то и дал Я вам голые зубы во всех городах ваших и недостаток хлеба во всех селениях ваших; но вы не обратились ко Мне, говорит Господь.","Za to i dal Â vam golye zuby vo vseh gorodah vaših i nedostatok hleba vo vseh seleniâh vaših; no vy ne obratilisʹ ko Mne, govorit Gospodʹ."],[4,7,"И удерживал от вас дождь за три месяца до жатвы; проливал дождь на один город, а на другой город не проливал дождя; один участок напояем был дождем, а другой, не окропленный дождем, засыхал.","I uderžival ot vas doždʹ za tri mesâca do žatvy; prolival doždʹ na odin gorod, a na drugoj gorod ne prolival doždâ; odin učastok napoâem byl doždem, a drugoj, ne okroplennyj doždem, zasyhal."],[4,8,"И сходились два-три города в один город, чтобы напиться воды, и не могли досыта напиться; но и тогда вы не обратились ко Мне, говорит Господь.","I shodilisʹ dva-tri goroda v odin gorod, čtoby napitʹsâ vody, i ne mogli dosyta napitʹsâ; no i togda vy ne obratilisʹ ko Mne, govorit Gospodʹ."],[4,9,"Я поражал вас ржою и блеклостью хлеба; множество садов ваших и виноградников ваших, и смоковниц ваших, и маслин ваших пожирала гусеница, – и при всем том вы не обратились ко Мне, говорит Господь.","Â poražal vas ržoû i bleklostʹû hleba; množestvo sadov vaših i vinogradnikov vaših, i smokovnic vaših, i maslin vaših požirala gusenica, – i pri vsem tom vy ne obratilisʹ ko Mne, govorit Gospodʹ."],[4,10,"Посылал Я на вас моровую язву, подобную Египетской, убивал мечом юношей ваших, отводя коней в плен, так что смрад от станов ваших поднимался в ноздри ваши, – и при всем том вы не обратились ко Мне, говорит Господь.","Posylal Â na vas morovuû âzvu, podobnuû Egipetskoj, ubival mečom ûnošej vaših, otvodâ konej v plen, tak čto smrad ot stanov vaših podnimalsâ v nozdri vaši, – i pri vsem tom vy ne obratilisʹ ko Mne, govorit Gospodʹ."],[4,11,"Производил Я среди вас разрушения, как разрушил Бог Содом и Гоморру, и вы были выхвачены, как головня из огня, – и при всем том вы не обратились ко Мне, говорит Господь.","Proizvodil Â sredi vas razrušeniâ, kak razrušil Bog Sodom i Gomorru, i vy byli vyhvačeny, kak golovnâ iz ognâ, – i pri vsem tom vy ne obratilisʹ ko Mne, govorit Gospodʹ."],[4,12,"Посему так поступлю Я с тобою, Израиль; и как Я так поступлю с тобою, то приготовься к сретению Бога твоего, Израиль.","Posemu tak postuplû Â s toboû, Izrailʹ; i kak Â tak postuplû s toboû, to prigotovʹsâ k sreteniû Boga tvoego, Izrailʹ."],[4,13,"Ибо вот Он, Который образует горы, и творит ветер, и объявляет человеку намерения его, утренний свет обращает в мрак, и шествует превыше земли; Господь Бог Саваоф – имя Ему.","Ibo vot On, Kotoryj obrazuet gory, i tvorit veter, i obʺâvlâet čeloveku namereniâ ego, utrennij svet obraŝaet v mrak, i šestvuet prevyše zemli; Gospodʹ Bog Savaof – imâ Emu."],[5,1,"Слушайте это слово, в котором я подниму плач о вас, дом Израилев.","Slušajte éto slovo, v kotorom â podnimu plač o vas, dom Izrailev."],[5,2,"Упала, не встает более дева Израилева! повержена на земле своей, и некому поднять ее.","Upala, ne vstaet bolee deva Izraileva! poveržena na zemle svoej, i nekomu podnâtʹ ee."],[5,3,"Ибо так говорит Господь Бог: город, выступавший тысячею, останется только с сотнею, и выступавший сотнею, останется с десятком у дома Израилева.","Ibo tak govorit Gospodʹ Bog: gorod, vystupavšij tysâčeû, ostanetsâ tolʹko s sotneû, i vystupavšij sotneû, ostanetsâ s desâtkom u doma Izraileva."],[5,4,"Ибо так говорит Господь дому Израилеву: взыщите Меня и будете живы.","Ibo tak govorit Gospodʹ domu Izrailevu: vzyŝite Menâ i budete živy."],[5,5,"Не ищите Вефиля и не ходите в Галгал, и в Вирсавию не странствуйте, ибо Галгал весь пойдет в плен и Вефиль обратится в ничто.","Ne iŝite Vefilâ i ne hodite v Galgal, i v Virsaviû ne stranstvujte, ibo Galgal vesʹ pojdet v plen i Vefilʹ obratitsâ v ničto."],[5,6,"Взыщите Господа – и будете живы, чтобы Он не устремился на дом Иосифов как огонь, который пожрет его, и некому будет погасить его в Вефиле.","Vzyŝite Gospoda – i budete živy, čtoby On ne ustremilsâ na dom Iosifov kak ogonʹ, kotoryj požret ego, i nekomu budet pogasitʹ ego v Vefile."],[5,7,"О, вы, которые суд превращаете в отраву и правду повергаете на землю!","O, vy, kotorye sud prevraŝaete v otravu i pravdu povergaete na zemlû!"],[5,8,"Кто сотворил семизвездие и Орион и претворяет смертную тень в ясное утро, а день делает темным как ночь, призывает воды морские и разливает их по лицу земли? – Господь имя Ему!","Kto sotvoril semizvezdie i Orion i pretvorâet smertnuû tenʹ v âsnoe utro, a denʹ delaet temnym kak nočʹ, prizyvaet vody morskie i razlivaet ih po licu zemli? – Gospodʹ imâ Emu!"],[5,9,"Он укрепляет опустошителя против сильного, и опустошитель входит в крепость.","On ukreplâet opustošitelâ protiv silʹnogo, i opustošitelʹ vhodit v krepostʹ."],[5,10,"А они ненавидят обличающего в воротах и гнушаются тем, кто говорит правду.","A oni nenavidât obličaûŝego v vorotah i gnušaûtsâ tem, kto govorit pravdu."],[5,11,"Итак за то, что вы попираете бедного и берете от него подарки хлебом, вы построите дома из тесаных камней, но жить не будете в них; разведете прекрасные виноградники, а вина из них не будете пить.","Itak za to, čto vy popiraete bednogo i berete ot nego podarki hlebom, vy postroite doma iz tesanyh kamnej, no žitʹ ne budete v nih; razvedete prekrasnye vinogradniki, a vina iz nih ne budete pitʹ."],[5,12,"Ибо Я знаю, как многочисленны преступления ваши и как тяжки грехи ваши: вы враги правого, берете взятки и извращаете в суде дела бедных.","Ibo Â znaû, kak mnogočislenny prestupleniâ vaši i kak tâžki grehi vaši: vy vragi pravogo, berete vzâtki i izvraŝaete v sude dela bednyh."],[5,13,"Поэтому разумный безмолвствует в это время, ибо злое это время.","Poétomu razumnyj bezmolvstvuet v éto vremâ, ibo zloe éto vremâ."],[5,14,"Ищите добра, а не зла, чтобы вам остаться в живых, – и тогда Господь Бог Саваоф будет с вами, как вы говорите.","Iŝite dobra, a ne zla, čtoby vam ostatʹsâ v živyh, – i togda Gospodʹ Bog Savaof budet s vami, kak vy govorite."],[5,15,"Возненавидьте зло и возлюбите добро, и восстановите у ворот правосудие; может быть, Господь Бог Саваоф помилует остаток Иосифов.","Voznenavidʹte zlo i vozlûbite dobro, i vosstanovite u vorot pravosudie; možet bytʹ, Gospodʹ Bog Savaof pomiluet ostatok Iosifov."],[5,16,"Посему так говорит Господь Бог Саваоф, Вседержитель: на всех улицах будет плач, и на всех дорогах будут восклицать: «увы, увы!», и призовут земледельца сетовать и искусных в плачевных песнях – плакать,","Posemu tak govorit Gospodʹ Bog Savaof, Vsederžitelʹ: na vseh ulicah budet plač, i na vseh dorogah budut vosklicatʹ: «uvy, uvy!», i prizovut zemledelʹca setovatʹ i iskusnyh v plačevnyh pesnâh – plakatʹ,"],[5,17,"и во всех виноградниках будет плач, ибо Я пройду среди тебя, говорит Господь.","i vo vseh vinogradnikah budet plač, ibo Â projdu sredi tebâ, govorit Gospodʹ."],[5,18,"Горе желающим дня Господня! для чего вам этот день Господень? он – тьма, а не свет,","Gore želaûŝim dnâ Gospodnâ! dlâ čego vam étot denʹ Gospodenʹ? on – tʹma, a ne svet,"],[5,19,"то же, как если бы кто убежал от льва, и попался бы ему навстречу медведь, или если бы пришел домой и оперся рукою о стену, и змея ужалила бы его.","to že, kak esli by kto ubežal ot lʹva, i popalsâ by emu navstreču medvedʹ, ili esli by prišel domoj i opersâ rukoû o stenu, i zmeâ užalila by ego."],[5,20,"Разве день Господень не мрак, а свет? он – тьма, и нет в нем сияния.","Razve denʹ Gospodenʹ ne mrak, a svet? on – tʹma, i net v nem siâniâ."],[5,21,"Ненавижу, отвергаю праздники ваши и не обоняю жертв во время торжественных собраний ваших.","Nenavižu, otvergaû prazdniki vaši i ne obonâû žertv vo vremâ toržestvennyh sobranij vaših."],[5,22,"Если вознесете Мне всесожжение и хлебное приношение, Я не приму их и не призрю на благодарственную жертву из тучных тельцов ваших.","Esli voznesete Mne vsesožženie i hlebnoe prinošenie, Â ne primu ih i ne prizrû na blagodarstvennuû žertvu iz tučnyh telʹcov vaših."],[5,23,"Удали от Меня шум песней твоих, ибо звуков гуслей твоих Я не буду слушать.","Udali ot Menâ šum pesnej tvoih, ibo zvukov guslej tvoih Â ne budu slušatʹ."],[5,24,"Пусть, как вода, течет суд, и правда – как сильный поток!","Pustʹ, kak voda, tečet sud, i pravda – kak silʹnyj potok!"],[5,25,"Приносили ли вы Мне жертвы и хлебные дары в пустыне в течение сорока лет, дом Израилев?","Prinosili li vy Mne žertvy i hlebnye dary v pustyne v tečenie soroka let, dom Izrailev?"],[5,26,"Вы носили скинию Молохову и звезду бога вашего Ремфана, изображения, которые вы сделали для себя.","Vy nosili skiniû Molohovu i zvezdu boga vašego Remfana, izobraženiâ, kotorye vy sdelali dlâ sebâ."],[5,27,"За то Я переселю вас за Дамаск, говорит Господь; Бог Саваоф – имя Ему!","Za to Â pereselû vas za Damask, govorit Gospodʹ; Bog Savaof – imâ Emu!"],[6,1,"Горе беспечным на Сионе и надеющимся на гору Самарийскую именитым первенствующего народа, к которым приходит дом Израиля!","Gore bespečnym na Sione i nadeûŝimsâ na goru Samarijskuû imenitym pervenstvuûŝego naroda, k kotorym prihodit dom Izrailâ!"],[6,2,"Пройдите в Калне и посмотрите, оттуда перейдите в Емаф великий и спуститесь в Геф Филистимский: не лучше ли они сих царств? не обширнее ли пределы их пределов ваших?","Projdite v Kalne i posmotrite, ottuda perejdite v Emaf velikij i spustitesʹ v Gef Filistimskij: ne lučše li oni sih carstv? ne obširnee li predely ih predelov vaših?"],[6,3,"Вы, которые день бедствия считаете далеким и приближаете торжество насилия, –","Vy, kotorye denʹ bedstviâ sčitaete dalekim i približaete toržestvo nasiliâ, –"],[6,4,"вы, которые лежите на ложах из слоновой кости и нежитесь на постелях ваших, едите лучших овнов из стада и тельцов с тучного пастбища,","vy, kotorye ležite na ložah iz slonovoj kosti i nežitesʹ na postelâh vaših, edite lučših ovnov iz stada i telʹcov s tučnogo pastbiŝa,"],[6,5,"поете под звуки гуслей, думая, что владеете музыкальным орудием, как Давид,","poete pod zvuki guslej, dumaâ, čto vladeete muzykalʹnym orudiem, kak David,"],[6,6,"пьете из чаш вино, мажетесь наилучшими мастями и не болезнуете о бедствии Иосифа!","pʹete iz čaš vino, mažetesʹ nailučšimi mastâmi i ne boleznuete o bedstvii Iosifa!"],[6,7,"За то ныне пойдут они в плен во главе пленных, и кончится ликование изнеженных.","Za to nyne pojdut oni v plen vo glave plennyh, i končitsâ likovanie iznežennyh."],[6,8,"Клянется Господь Бог Самим Собою, и так говорит Господь Бог Саваоф: гнушаюсь высокомерием Иакова и ненавижу чертоги его, и предам город и все, что наполняет его.","Klânetsâ Gospodʹ Bog Samim Soboû, i tak govorit Gospodʹ Bog Savaof: gnušaûsʹ vysokomeriem Iakova i nenavižu čertogi ego, i predam gorod i vse, čto napolnâet ego."],[6,9,"И будет: если в каком доме останется десять человек, то умрут и они,","I budet: esli v kakom dome ostanetsâ desâtʹ čelovek, to umrut i oni,"],[6,10,"и возьмет их родственник их или сожигатель, чтобы вынести кости их из дома, и скажет находящемуся при доме: есть ли еще у тебя кто? Тот ответит: нет никого. И скажет сей: молчи! ибо нельзя упоминать имени Господня.","i vozʹmet ih rodstvennik ih ili sožigatelʹ, čtoby vynesti kosti ih iz doma, i skažet nahodâŝemusâ pri dome: estʹ li eŝe u tebâ kto? Tot otvetit: net nikogo. I skažet sej: molči! ibo nelʹzâ upominatʹ imeni Gospodnâ."],[6,11,"Ибо вот, Господь даст повеление и поразит большие дома расселинами, а малые дома – трещинами.","Ibo vot, Gospodʹ dast povelenie i porazit bolʹšie doma rasselinami, a malye doma – treŝinami."],[6,12,"Бегают ли кони по скале? можно ли распахивать ее волами? Вы между тем суд превращаете в яд и плод правды в горечь;","Begaût li koni po skale? možno li raspahivatʹ ee volami? Vy meždu tem sud prevraŝaete v âd i plod pravdy v gorečʹ;"],[6,13,"вы, которые восхищаетесь ничтожными вещами и говорите: «не своею ли силою мы приобрели себе могущество?»","vy, kotorye voshiŝaetesʹ ničtožnymi veŝami i govorite: «ne svoeû li siloû my priobreli sebe moguŝestvo?»"],[6,14,"Вот Я, говорит Господь Бог Саваоф, воздвигну народ против вас, дом Израилев, и будут теснить вас от входа в Емаф до потока в пустыне.","Vot Â, govorit Gospodʹ Bog Savaof, vozdvignu narod protiv vas, dom Izrailev, i budut tesnitʹ vas ot vhoda v Emaf do potoka v pustyne."],[7,1,"Такое видение открыл мне Господь Бог: вот, Он создал саранчу в начале произрастания поздней травы, и это была трава после царского покоса.","Takoe videnie otkryl mne Gospodʹ Bog: vot, On sozdal saranču v načale proizrastaniâ pozdnej travy, i éto byla trava posle carskogo pokosa."],[7,2,"И было, когда она окончила есть траву на земле, я сказал: Господи Боже! пощади; как устоит Иаков? он очень мал.","I bylo, kogda ona okončila estʹ travu na zemle, â skazal: Gospodi Bože! poŝadi; kak ustoit Iakov? on očenʹ mal."],[7,3,"И пожалел Господь о том; «не будет сего», сказал Господь.","I požalel Gospodʹ o tom; «ne budet sego», skazal Gospodʹ."],[7,4,"Такое видение открыл мне Господь Бог: вот, Господь Бог произвел для суда огонь, – и он пожрал великую пучину, пожрал и часть земли.","Takoe videnie otkryl mne Gospodʹ Bog: vot, Gospodʹ Bog proizvel dlâ suda ogonʹ, – i on požral velikuû pučinu, požral i častʹ zemli."],[7,5,"И сказал я: Господи Боже! останови; как устоит Иаков? он очень мал.","I skazal â: Gospodi Bože! ostanovi; kak ustoit Iakov? on očenʹ mal."],[7,6,"И пожалел Господь о том; «и этого не будет», сказал Господь Бог.","I požalel Gospodʹ o tom; «i étogo ne budet», skazal Gospodʹ Bog."],[7,7,"Такое видение открыл Он мне: вот, Господь стоял на отвесной стене, и в руке у Него свинцовый отвес.","Takoe videnie otkryl On mne: vot, Gospodʹ stoâl na otvesnoj stene, i v ruke u Nego svincovyj otves."],[7,8,"И сказал мне Господь: что ты видишь, Амос? Я ответил: отвес. И Господь сказал: вот, положу отвес среди народа Моего, Израиля; не буду более прощать ему.","I skazal mne Gospodʹ: čto ty vidišʹ, Amos? Â otvetil: otves. I Gospodʹ skazal: vot, položu otves sredi naroda Moego, Izrailâ; ne budu bolee proŝatʹ emu."],[7,9,"И опустошены будут жертвенные высоты Исааковы, и разрушены будут святилища Израилевы, и восстану с мечом против дома Иеровоамова.","I opustošeny budut žertvennye vysoty Isaakovy, i razrušeny budut svâtiliŝa Izrailevy, i vosstanu s mečom protiv doma Ierovoamova."],[7,10,"И послал Амасия, священник Вефильский, к Иеровоаму, царю Израильскому, сказать: Амос производит возмущение против тебя среди дома Израилева; земля не может терпеть всех слов его.","I poslal Amasiâ, svâŝennik Vefilʹskij, k Ierovoamu, carû Izrailʹskomu, skazatʹ: Amos proizvodit vozmuŝenie protiv tebâ sredi doma Izraileva; zemlâ ne možet terpetʹ vseh slov ego."],[7,11,"Ибо так говорит Амос: «от меча умрет Иеровоам, а Израиль непременно отведен будет пленным из земли своей».","Ibo tak govorit Amos: «ot meča umret Ierovoam, a Izrailʹ nepremenno otveden budet plennym iz zemli svoej»."],[7,12,"И сказал Амасия Амосу: провидец! пойди и удались в землю Иудину; там ешь хлеб и там пророчествуй,","I skazal Amasiâ Amosu: providec! pojdi i udalisʹ v zemlû Iudinu; tam ešʹ hleb i tam proročestvuj,"],[7,13,"а в Вефиле больше не пророчествуй, ибо он святыня царя и дом царский.","a v Vefile bolʹše ne proročestvuj, ibo on svâtynâ carâ i dom carskij."],[7,14,"И отвечал Амос и сказал Амасии: я не пророк и не сын пророка; я был пастух и собирал сикоморы.","I otvečal Amos i skazal Amasii: â ne prorok i ne syn proroka; â byl pastuh i sobiral sikomory."],[7,15,"Но Господь взял меня от овец, и сказал мне Господь: «иди, пророчествуй к народу Моему, Израилю».","No Gospodʹ vzâl menâ ot ovec, i skazal mne Gospodʹ: «idi, proročestvuj k narodu Moemu, Izrailû»."],[7,16,"Теперь выслушай слово Господне. Ты говоришь: «не пророчествуй на Израиля и не произноси слов на дом Исааков».","Teperʹ vyslušaj slovo Gospodne. Ty govorišʹ: «ne proročestvuj na Izrailâ i ne proiznosi slov na dom Isaakov»."],[7,17,"За это вот что говорит Господь: жена твоя будет обесчещена в городе, сыновья и дочери твои падут от меча, земля твоя будет разделена межевою вервью, а ты умрешь в земле нечистой, и Израиль непременно выведен будет из земли своей.","Za éto vot čto govorit Gospodʹ: žena tvoâ budet obesčeŝena v gorode, synovʹâ i dočeri tvoi padut ot meča, zemlâ tvoâ budet razdelena meževoû vervʹû, a ty umrešʹ v zemle nečistoj, i Izrailʹ nepremenno vyveden budet iz zemli svoej."],[8,1,"Такое видение открыл мне Господь Бог: вот корзина со спелыми плодами.","Takoe videnie otkryl mne Gospodʹ Bog: vot korzina so spelymi plodami."],[8,2,"И сказал Он: что ты видишь, Амос? Я ответил: корзину со спелыми плодами. Тогда Господь сказал мне: приспел конец народу Моему, Израилю: не буду более прощать ему.","I skazal On: čto ty vidišʹ, Amos? Â otvetil: korzinu so spelymi plodami. Togda Gospodʹ skazal mne: prispel konec narodu Moemu, Izrailû: ne budu bolee proŝatʹ emu."],[8,3,"Песни чертога в тот день обратятся в рыдание, говорит Господь Бог; много будет трупов, на всяком месте будут бросать их молча.","Pesni čertoga v tot denʹ obratâtsâ v rydanie, govorit Gospodʹ Bog; mnogo budet trupov, na vsâkom meste budut brosatʹ ih molča."],[8,4,"Выслушайте это, алчущие поглотить бедных и погубить нищих, –","Vyslušajte éto, alčuŝie poglotitʹ bednyh i pogubitʹ niŝih, –"],[8,5,"вы, которые говорите: «когда-то пройдет новолуние, чтобы нам продавать хлеб, и суббота, чтобы открыть житницы, уменьшить меру, увеличить цену сикля и обманывать неверными весами,","vy, kotorye govorite: «kogda-to projdet novolunie, čtoby nam prodavatʹ hleb, i subbota, čtoby otkrytʹ žitnicy, umenʹšitʹ meru, uveličitʹ cenu siklâ i obmanyvatʹ nevernymi vesami,"],[8,6,"чтобы покупать неимущих за серебро и бедных за пару обуви, а высевки из хлеба продавать».","čtoby pokupatʹ neimuŝih za serebro i bednyh za paru obuvi, a vysevki iz hleba prodavatʹ»."],[8,7,"Клялся Господь славою Иакова: поистине вовеки не забуду ни одного из дел их!","Klâlsâ Gospodʹ slavoû Iakova: poistine voveki ne zabudu ni odnogo iz del ih!"],[8,8,"Не поколеблется ли от этого земля, и не восплачет ли каждый, живущий на ней? Взволнуется вся она, как река, и будет подниматься и опускаться, как река Египетская.","Ne pokolebletsâ li ot étogo zemlâ, i ne vosplačet li každyj, živuŝij na nej? Vzvolnuetsâ vsâ ona, kak reka, i budet podnimatʹsâ i opuskatʹsâ, kak reka Egipetskaâ."],[8,9,"И будет в тот день, говорит Господь Бог: произведу закат солнца в полдень и омрачу землю среди светлого дня.","I budet v tot denʹ, govorit Gospodʹ Bog: proizvedu zakat solnca v poldenʹ i omraču zemlû sredi svetlogo dnâ."],[8,10,"И обращу праздники ваши в сетование и все песни ваши в плач, и возложу на все чресла вретище и плешь на всякую голову; и произведу в стране плач, как о единственном сыне, и конец ее будет – как горький день.","I obraŝu prazdniki vaši v setovanie i vse pesni vaši v plač, i vozložu na vse čresla vretiŝe i plešʹ na vsâkuû golovu; i proizvedu v strane plač, kak o edinstvennom syne, i konec ee budet – kak gorʹkij denʹ."],[8,11,"Вот наступают дни, говорит Господь Бог, когда Я пошлю на землю голод, – не голод хлеба, не жажду воды, но жажду слышания слов Господних.","Vot nastupaût dni, govorit Gospodʹ Bog, kogda Â pošlû na zemlû golod, – ne golod hleba, ne žaždu vody, no žaždu slyšaniâ slov Gospodnih."],[8,12,"И будут ходить от моря до моря и скитаться от севера к востоку, ища слова Господня, и не найдут его.","I budut hoditʹ ot morâ do morâ i skitatʹsâ ot severa k vostoku, iŝa slova Gospodnâ, i ne najdut ego."],[8,13,"В тот день истаевать будут от жажды красивые девы и юноши,","V tot denʹ istaevatʹ budut ot žaždy krasivye devy i ûnoši,"],[8,14,"которые клянутся грехом Самарийским и говорят: «жив бог твой, Дан! и жив путь в Вирсавию!» – Они падут и уже не встанут.","kotorye klânutsâ grehom Samarijskim i govorât: «živ bog tvoj, Dan! i živ putʹ v Virsaviû!» – Oni padut i uže ne vstanut."],[9,1,"Видел я Господа стоящим над жертвенником, и Он сказал: ударь в притолоку над воротами, чтобы потряслись косяки, и обрушь их на головы всех их, остальных же из них Я поражу мечом: не убежит у них никто бегущий и не спасется из них никто, желающий спастись.","Videl â Gospoda stoâŝim nad žertvennikom, i On skazal: udarʹ v pritoloku nad vorotami, čtoby potrâslisʹ kosâki, i obrušʹ ih na golovy vseh ih, ostalʹnyh že iz nih Â poražu mečom: ne ubežit u nih nikto beguŝij i ne spasetsâ iz nih nikto, želaûŝij spastisʹ."],[9,2,"Хотя бы они зарылись в преисподнюю, и оттуда рука Моя возьмет их; хотя бы взошли на небо, и оттуда свергну их.","Hotâ by oni zarylisʹ v preispodnûû, i ottuda ruka Moâ vozʹmet ih; hotâ by vzošli na nebo, i ottuda svergnu ih."],[9,3,"И хотя бы они скрылись на вершине Кармила, и там отыщу и возьму их; хотя бы сокрылись от очей Моих на дне моря, и там повелю морскому змею уязвить их.","I hotâ by oni skrylisʹ na veršine Karmila, i tam otyŝu i vozʹmu ih; hotâ by sokrylisʹ ot očej Moih na dne morâ, i tam povelû morskomu zmeû uâzvitʹ ih."],[9,4,"И если пойдут в плен впереди врагов своих, то повелю мечу и там убить их. Обращу на них очи Мои на беду им, а не во благо.","I esli pojdut v plen vperedi vragov svoih, to povelû meču i tam ubitʹ ih. Obraŝu na nih oči Moi na bedu im, a ne vo blago."],[9,5,"Ибо Господь Бог Саваоф коснется земли, – и она растает, и восплачут все живущие на ней; и поднимется вся она, как река, и опустится, как река Египетская.","Ibo Gospodʹ Bog Savaof kosnetsâ zemli, – i ona rastaet, i vosplačut vse živuŝie na nej; i podnimetsâ vsâ ona, kak reka, i opustitsâ, kak reka Egipetskaâ."],[9,6,"Он устроил горние чертоги Свои на небесах и свод Свой утвердил на земле, призывает воды морские и изливает их по лицу земли; Господь – имя Ему.","On ustroil gornie čertogi Svoi na nebesah i svod Svoj utverdil na zemle, prizyvaet vody morskie i izlivaet ih po licu zemli; Gospodʹ – imâ Emu."],[9,7,"Не таковы ли, как сыны Ефиоплян, и вы для Меня, сыны Израилевы? говорит Господь. Не Я ли вывел Израиля из земли Египетской, и Филистимлян – из Кафтора, и Арамлян – из Кира?","Ne takovy li, kak syny Efioplân, i vy dlâ Menâ, syny Izrailevy? govorit Gospodʹ. Ne Â li vyvel Izrailâ iz zemli Egipetskoj, i Filistimlân – iz Kaftora, i Aramlân – iz Kira?"],[9,8,"Вот, очи Господа Бога – на грешное царство, и Я истреблю его с лица земли; но дом Иакова не совсем истреблю, говорит Господь.","Vot, oči Gospoda Boga – na grešnoe carstvo, i Â istreblû ego s lica zemli; no dom Iakova ne sovsem istreblû, govorit Gospodʹ."],[9,9,"Ибо вот, Я повелю и рассыплю дом Израилев по всем народам, как рассыпают зерна в решете, и ни одно не падает на землю.","Ibo vot, Â povelû i rassyplû dom Izrailev po vsem narodam, kak rassypaût zerna v rešete, i ni odno ne padaet na zemlû."],[9,10,"От меча умрут все грешники из народа Моего, которые говорят: «не постигнет нас и не придет к нам это бедствие!»","Ot meča umrut vse grešniki iz naroda Moego, kotorye govorât: «ne postignet nas i ne pridet k nam éto bedstvie!»"],[9,11,"В тот день Я восстановлю скинию Давидову падшую, заделаю трещины в ней и разрушенное восстановлю, и устрою ее, как в дни древние,","V tot denʹ Â vosstanovlû skiniû Davidovu padšuû, zadelaû treŝiny v nej i razrušennoe vosstanovlû, i ustroû ee, kak v dni drevnie,"],[9,12,"чтобы они овладели остатком Едома и всеми народами, между которыми возвестится имя Мое, говорит Господь, творящий все сие.","čtoby oni ovladeli ostatkom Edoma i vsemi narodami, meždu kotorymi vozvestitsâ imâ Moe, govorit Gospodʹ, tvorâŝij vse sie."],[9,13,"Вот, наступят дни, говорит Господь, когда пахарь застанет еще жнеца, а топчущий виноград – сеятеля; и горы источать будут виноградный сок, и все холмы потекут.","Vot, nastupât dni, govorit Gospodʹ, kogda paharʹ zastanet eŝe žneca, a topčuŝij vinograd – seâtelâ; i gory istočatʹ budut vinogradnyj sok, i vse holmy potekut."],[9,14,"И возвращу из плена народ Мой, Израиля, и застроят опустевшие города и поселятся в них, насадят виноградники и будут пить вино из них, разведут сады и станут есть плоды из них.","I vozvraŝu iz plena narod Moj, Izrailâ, i zastroât opustevšie goroda i poselâtsâ v nih, nasadât vinogradniki i budut pitʹ vino iz nih, razvedut sady i stanut estʹ plody iz nih."],[9,15,"И водворю их на земле их, и они не будут более исторгаемы из земли своей, которую Я дал им, говорит Господь Бог твой.","I vodvorû ih na zemle ih, i oni ne budut bolee istorgaemy iz zemli svoej, kotoruû Â dal im, govorit Gospodʹ Bog tvoj."]],"cmn-cuv-hant":[[1,1,"當 猶大王 烏西雅， 以色列王 約阿施的兒子 耶羅波安在位的時候，大地震前二年， 提哥亞牧人中的 阿摩司得默示論 以色列。","dāng yóu dà wáng wū xī yǎ， yǐ sè liè wáng yuē ā shī de ér zǐ yé luó bō ān zài wèi de shí hòu， dà de zhèn qián èr nián， tí gē yà mù rén zhōng de ā mó sī dé mò shì lùn yǐ sè liè."],[1,2,"他說：耶和華必從 錫安吼叫， 從 耶路撒冷發聲； 牧人的草場要悲哀； 迦密的山頂要枯乾。","tā shuō： yé hé huá bì cóng xī ān hǒu jiào， cóng yé lù sā lěng fā shēng； mù rén de cǎo chǎng yào bēi āi； jiā mì de shān dǐng yào kū qián."],[1,3,"耶和華如此說： 大馬士革三番四次地犯罪， 我必不免去她的刑罰； 因為她以打糧食的鐵器打過 基列。","yé hé huá rú cǐ shuō： dà mǎ shì gé sān fān sì cì de fàn zuì， wǒ bì bù miǎn qù tā de xíng fá； yīn wèi tā yǐ dǎ liáng shí de tiě qì dǎ guò jī liè."],[1,4,"我卻要降火在 哈薛的家中， 燒滅 便‧哈達的宮殿。","wǒ què yào jiàng huǒ zài hā xuē de jiā zhōng， shāo miè biàn‧hā dá de gōng diàn."],[1,5,"我必折斷 大馬士革的門閂， 剪除 亞文平原的居民和 伯‧伊甸掌權的。 亞蘭人必被擄到 吉珥。 這是耶和華說的。","wǒ bì zhé duàn dà mǎ shì gé de mén shuān， jiǎn chú yà wén píng yuán de jū mín hé bó‧yī diàn zhǎng quán de. yà lán rén bì bèi lǔ dào jí ěr. zhè shì yé hé huá shuō de."],[1,6,"耶和華如此說： 迦薩三番四次地犯罪， 我必不免去她的刑罰； 因為她擄掠眾民交給 以東。","yé hé huá rú cǐ shuō： jiā sà sān fān sì cì de fàn zuì， wǒ bì bù miǎn qù tā de xíng fá； yīn wèi tā lǔ lüè zhòng mín jiāo gěi yǐ dōng."],[1,7,"我卻要降火在 迦薩的城內， 燒滅其中的宮殿。","wǒ què yào jiàng huǒ zài jiā sà de chéng nèi， shāo miè qí zhōng de gōng diàn."],[1,8,"我必剪除 亞實突的居民和 亞實基倫掌權的， 也必反手攻擊 以革倫。 非利士人所餘剩的必都滅亡。 這是主耶和華說的。","wǒ bì jiǎn chú yà shí tū de jū mín hé yà shí jī lún zhǎng quán de， yě bì fǎn shǒu gōng jī yǐ gé lún. fēi lì shì rén suǒ yú shèng de bì dōu miè wáng. zhè shì zhǔ yé hé huá shuō de."],[1,9,"耶和華如此說： 泰爾三番四次地犯罪， 我必不免去她的刑罰； 因為她將眾民交給 以東， 並不記念弟兄的盟約。","yé hé huá rú cǐ shuō： tài ěr sān fān sì cì de fàn zuì， wǒ bì bù miǎn qù tā de xíng fá； yīn wèi tā jiāng zhòng mín jiāo gěi yǐ dōng， bìng bù jì niàn dì xiōng de méng yuē."],[1,10,"我卻要降火在 泰爾的城內， 燒滅其中的宮殿。","wǒ què yào jiàng huǒ zài tài ěr de chéng nèi， shāo miè qí zhōng de gōng diàn."],[1,11,"耶和華如此說： 以東三番四次地犯罪， 我必不免去她的刑罰； 因為她拿刀追趕兄弟，毫無憐憫， 發怒撕裂，永懷忿怒。","yé hé huá rú cǐ shuō： yǐ dōng sān fān sì cì de fàn zuì， wǒ bì bù miǎn qù tā de xíng fá； yīn wèi tā ná dāo zhuī gǎn xiōng dì， háo wú lián mǐn， fā nù sī liè， yǒng huái fèn nù."],[1,12,"我卻要降火在 提幔， 燒滅 波斯拉的宮殿。","wǒ què yào jiàng huǒ zài tí màn， shāo miè bō sī lā de gōng diàn."],[1,13,"耶和華如此說： 亞捫人三番四次地犯罪， 我必不免去他們的刑罰； 因為他們剖開 基列的孕婦， 擴張自己的境界。","yé hé huá rú cǐ shuō： yà mén rén sān fān sì cì de fàn zuì， wǒ bì bù miǎn qù tā men de xíng fá； yīn wèi tā men pōu kāi jī liè de yùn fù， kuò zhāng zì jǐ de jìng jiè."],[1,14,"我卻要在爭戰吶喊的日子， 旋風狂暴的時候， 點火在 拉巴的城內， 燒滅其中的宮殿。","wǒ què yào zài zhēng zhàn nà hǎn de rì zǐ， xuán fēng kuáng bào de shí hòu， diǎn huǒ zài lā bā de chéng nèi， shāo miè qí zhōng de gōng diàn."],[1,15,"他們的王和首領必一同被擄去。 這是耶和華說的。","tā men de wáng hé shǒu lǐng bì yī tóng bèi lǔ qù. zhè shì yé hé huá shuō de."],[2,1,"耶和華如此說： 摩押三番四次地犯罪， 我必不免去她的刑罰； 因為她將 以東王的骸骨焚燒成灰。","yé hé huá rú cǐ shuō： mó yā sān fān sì cì de fàn zuì， wǒ bì bù miǎn qù tā de xíng fá； yīn wèi tā jiāng yǐ dōng wáng de hái gǔ fén shāo chéng huī."],[2,2,"我卻要降火在 摩押， 燒滅 加略的宮殿。 摩押必在鬨嚷吶喊吹角之中死亡。","wǒ què yào jiàng huǒ zài mó yā， shāo miè jiā lüè de gōng diàn. mó yā bì zài hòng rǎng nà hǎn chuī jiǎo zhī zhōng sǐ wáng."],[2,3,"我必剪除 摩押中的審判者， 將其中的一切首領和他一同殺戮。 這是耶和華說的。","wǒ bì jiǎn chú mó yā zhōng de shěn pàn zhě， jiāng qí zhōng de yī qiè shǒu lǐng hé tā yī tóng shā lù. zhè shì yé hé huá shuō de."],[2,4,"耶和華如此說： 猶大人三番四次地犯罪， 我必不免去他們的刑罰； 因為他們厭棄耶和華的訓誨， 不遵守他的律例。 他們列祖所隨從虛假的 偶像使他們走迷了。","yé hé huá rú cǐ shuō： yóu dà rén sān fān sì cì de fàn zuì， wǒ bì bù miǎn qù tā men de xíng fá； yīn wèi tā men yàn qì yé hé huá de xùn huì， bù zūn shǒu tā de lǜ lì. tā men liè zǔ suǒ suí cóng xū jiǎ de ǒu xiàng shǐ tā men zǒu mí le."],[2,5,"我卻要降火在 猶大， 燒滅 耶路撒冷的宮殿。","wǒ què yào jiàng huǒ zài yóu dà， shāo miè yé lù sā lěng de gōng diàn."],[2,6,"耶和華如此說： 以色列人三番四次地犯罪， 我必不免去他們的刑罰； 因他們為銀子賣了義人， 為一雙鞋賣了窮人。","yé hé huá rú cǐ shuō： yǐ sè liè rén sān fān sì cì de fàn zuì， wǒ bì bù miǎn qù tā men de xíng fá； yīn tā men wèi yín zǐ mài le yì rén， wèi yī shuāng xié mài le qióng rén."],[2,7,"他們見窮人頭上所蒙的灰也都垂涎， 阻礙謙卑人的道路。 父子同一個女子行淫， 褻瀆我的聖名。","tā men jiàn qióng rén tóu shàng suǒ méng de huī yě dōu chuí xián， zǔ ài qiān bēi rén de dào lù. fù zǐ tóng yī gè nǚ zǐ xíng yín， xiè dú wǒ de shèng míng."],[2,8,"他們在各壇旁鋪人所當的衣服，臥在其上， 又在他們神的廟中喝受罰之人的酒。","tā men zài gè tán páng pù rén suǒ dāng de yī fú， wò zài qí shàng， yòu zài tā men shén de miào zhōng hē shòu fá zhī rén de jiǔ."],[2,9,"我從 以色列人面前除滅 亞摩利人。 他雖高大如香柏樹，堅固如橡樹， 我卻上滅他的果子，下絕他的根本。","wǒ cóng yǐ sè liè rén miàn qián chú miè yà mó lì rén. tā suī gāo dà rú xiāng bǎi shù， jiān gù rú xiàng shù， wǒ què shàng miè tā de guǒ zǐ， xià jué tā de gēn běn."],[2,10,"我也將你們從 埃及地領上來， 在曠野引導你們四十年， 使你們得 亞摩利人之地為業。","wǒ yě jiāng nǐ men cóng āi jí de lǐng shàng lái， zài kuàng yě yǐn dǎo nǐ men sì shí nián， shǐ nǐ men dé yà mó lì rén zhī de wèi yè."],[2,11,"我從你們子弟中興起先知， 又從你們少年人中興起拿細耳人。 以色列人哪，不是這樣嗎？ 這是耶和華說的。","wǒ cóng nǐ men zǐ dì zhōng xìng qǐ xiān zhī， yòu cóng nǐ men shǎo nián rén zhōng xìng qǐ ná xì ěr rén. yǐ sè liè rén nǎ， bù shì zhè yàng ma？ zhè shì yé hé huá shuō de."],[2,12,"你們卻給拿細耳人酒喝， 囑咐先知說：不要說預言。","nǐ men què gěi ná xì ěr rén jiǔ hē， zhǔ fù xiān zhī shuō： bù yào shuō yù yán."],[2,13,"看哪，在你們所住之地，我必壓 你們， 如同裝滿禾捆的車壓 物一樣。","kàn nǎ， zài nǐ men suǒ zhù zhī de， wǒ bì yā nǐ men， rú tóng zhuāng mǎn hé kǔn de chē yā wù yī yàng."],[2,14,"快跑的不能逃脫； 有力的不能用力； 剛勇的也不能自救。","kuài pǎo de bù néng táo tuō； yǒu lì de bù néng yòng lì； gāng yǒng de yě bù néng zì jiù."],[2,15,"拿弓的不能站立； 腿快的不能逃脫； 騎馬的也不能自救。","ná gōng de bù néng zhàn lì； tuǐ kuài de bù néng táo tuō； qí mǎ de yě bù néng zì jiù."],[2,16,"到那日，勇士中最有膽量的， 必赤身逃跑。 這是耶和華說的。","dào nà rì， yǒng shì zhōng zuì yǒu dǎn liàng de， bì chì shēn táo pǎo. zhè shì yé hé huá shuō de."],[3,1,"以色列人哪，你們全家是我從 埃及地領上來的，當聽耶和華攻擊你們的話：","yǐ sè liè rén nǎ， nǐ men quán jiā shì wǒ cóng āi jí de lǐng shàng lái de， dāng tīng yé hé huá gōng jī nǐ men de huà："],[3,2,"在地上萬族中，我只認識你們； 因此，我必追討你們的一切罪孽。","zài de shàng wàn zú zhōng， wǒ zhǐ rèn shí nǐ men； yīn cǐ， wǒ bì zhuī tǎo nǐ men de yī qiè zuì niè."],[3,3,"二人若不同心，豈能同行呢？","èr rén ruò bù tóng xīn， qǐ néng tóng xíng ne？"],[3,4,"獅子若非抓食，豈能在林中咆哮呢？ 少壯獅子若無所得，豈能從洞中發聲呢？","shī zǐ ruò fēi zhuā shí， qǐ néng zài lín zhōng páo xiào ne？ shǎo zhuàng shī zǐ ruò wú suǒ dé， qǐ néng cóng dòng zhōng fā shēng ne？"],[3,5,"若沒有機檻，雀鳥豈能陷在網羅裏呢？ 網羅若無所得，豈能從地上翻起呢？","ruò méi yǒu jī kǎn， què niǎo qǐ néng xiàn zài wǎng luó lǐ ne？ wǎng luó ruò wú suǒ dé， qǐ néng cóng de shàng fān qǐ ne？"],[3,6,"城中若吹角，百姓豈不驚恐呢？ 災禍若臨到一城，豈非耶和華所降的嗎？","chéng zhōng ruò chuī jiǎo， bǎi xìng qǐ bù jīng kǒng ne？ zāi huò ruò lín dào yī chéng， qǐ fēi yé hé huá suǒ jiàng de ma？"],[3,7,"主耶和華若不將奧祕指示他的僕人－眾先知， 就一無所行。","zhǔ yé hé huá ruò bù jiāng ào mì zhǐ shì tā de pú rén－zhòng xiān zhī， jiù yī wú suǒ xíng."],[3,8,"獅子吼叫，誰不懼怕呢？ 主耶和華發命，誰能不說預言呢？","shī zǐ hǒu jiào， shuí bù jù pà ne？ zhǔ yé hé huá fā mìng， shuí néng bù shuō yù yán ne？"],[3,9,"要在 亞實突的宮殿中 和 埃及地的宮殿裏傳揚說： 你們要聚集在 撒馬利亞的山上， 就看見城中有何等大的擾亂與欺壓的事。","yào zài yà shí tū de gōng diàn zhōng hé āi jí de de gōng diàn lǐ chuán yáng shuō： nǐ men yào jù jí zài sā mǎ lì yà de shān shàng， jiù kàn jiàn chéng zhōng yǒu hé děng dà de rǎo luàn yǔ qī yā de shì."],[3,10,"那些以強暴搶奪財物、 積蓄在自己家中的人 不知道行正直的事。 這是耶和華說的。","nà xiē yǐ qiáng bào qiǎng duó cái wù, jī xù zài zì jǐ jiā zhōng de rén bù zhī dào xíng zhèng zhí de shì. zhè shì yé hé huá shuō de."],[3,11,"所以主耶和華如此說： 敵人必來圍攻這地， 使你的勢力衰微， 搶掠你的家宅。","suǒ yǐ zhǔ yé hé huá rú cǐ shuō： dí rén bì lái wéi gōng zhè de， shǐ nǐ de shì lì shuāi wēi， qiǎng lüè nǐ de jiā zhái."],[3,12,"耶和華如此說：「牧人怎樣從獅子口中搶回兩條 羊腿或半個耳朵，住 撒馬利亞的 以色列人躺臥在床角上或鋪繡花毯的榻上，他們得救也不過如此。」","yé hé huá rú cǐ shuō：‘mù rén zěn yàng cóng shī zǐ kǒu zhōng qiǎng huí liǎng tiáo yáng tuǐ huò bàn gè ěr duǒ， zhù sā mǎ lì yà de yǐ sè liè rén tǎng wò zài chuáng jiǎo shàng huò pù xiù huā tǎn de tà shàng， tā men dé jiù yě bù guò rú cǐ.’"],[3,13,"主耶和華－萬軍之神說： 當聽這話，警戒 雅各家。","zhǔ yé hé huá－wàn jūn zhī shén shuō： dāng tīng zhè huà， jǐng jiè yǎ gè jiā."],[3,14,"我討 以色列罪的日子，也要討 伯特利祭壇的罪； 壇角必被砍下，墜落於地。","wǒ tǎo yǐ sè liè zuì de rì zǐ， yě yào tǎo bó tè lì jì tán de zuì； tán jiǎo bì bèi kǎn xià， zhuì luò yú de."],[3,15,"我要拆毀過冬和過夏的房屋。 象牙的房屋也必毀滅； 高大的房屋都歸無有。 這是耶和華說的。","wǒ yào chāi huǐ guò dōng hé guò xià de fáng wū. xiàng yá de fáng wū yě bì huǐ miè； gāo dà de fáng wū dōu guī wú yǒu. zhè shì yé hé huá shuō de."],[4,1,"你們住 撒馬利亞山如 巴珊母牛的啊， 當聽我的話－ 你們欺負貧寒的，壓碎窮乏的， 對家主說：拿 酒來，我們喝吧！","nǐ men zhù sā mǎ lì yà shān rú bā shān mǔ niú de a， dāng tīng wǒ de huà－ nǐ men qī fù pín hán de， yā suì qióng fá de， duì jiā zhǔ shuō： ná jiǔ lái， wǒ men hē ba！"],[4,2,"主耶和華指着自己的聖潔起誓說： 日子快到，人必用鉤子將你們鉤去， 用魚鉤將你們餘剩的鉤去。","zhǔ yé hé huá zhǐ zhe zì jǐ de shèng jié qǐ shì shuō： rì zǐ kuài dào， rén bì yòng gōu zǐ jiāng nǐ men gōu qù， yòng yú gōu jiāng nǐ men yú shèng de gōu qù."],[4,3,"你們各人必從破口直往前行， 投入 哈門。 這是耶和華說的。","nǐ men gè rén bì cóng pò kǒu zhí wǎng qián xíng， tóu rù hā mén. zhè shì yé hé huá shuō de."],[4,4,"以色列人哪，任你們往 伯特利去犯罪， 到 吉甲加增罪過； 每日早晨獻上你們的祭物， 每三日奉上你們的十分之一。","yǐ sè liè rén nǎ， rèn nǐ men wǎng bó tè lì qù fàn zuì， dào jí jiǎ jiā zēng zuì guò； měi rì zǎo chén xiàn shàng nǐ men de jì wù， měi sān rì fèng shàng nǐ men de shí fēn zhī yī."],[4,5,"任你們獻有酵的感謝祭， 把甘心祭宣傳報告給眾人， 因為是你們所喜愛的。 這是主耶和華說的。","rèn nǐ men xiàn yǒu jiào de gǎn xiè jì， bǎ gān xīn jì xuān chuán bào gào gěi zhòng rén， yīn wèi shì nǐ men suǒ xǐ ài de. zhè shì zhǔ yé hé huá shuō de."],[4,6,"我使你們在一切城中牙齒乾淨， 在你們各處糧食缺乏， 你們仍不歸向我。 這是耶和華說的。","wǒ shǐ nǐ men zài yī qiè chéng zhōng yá chǐ qián jìng， zài nǐ men gè chù liáng shí quē fá， nǐ men réng bù guī xiàng wǒ. zhè shì yé hé huá shuō de."],[4,7,"在收割的前三月，我使雨停止， 不降在你們那裏； 我降雨在這城， 不降雨在那城； 這塊地有雨， 那塊地無雨； 無雨的就枯乾了。","zài shōu gē de qián sān yuè， wǒ shǐ yǔ tíng zhǐ， bù jiàng zài nǐ men nà lǐ； wǒ jiàng yǔ zài zhè chéng， bù jiàng yǔ zài nà chéng； zhè kuài de yǒu yǔ， nà kuài de wú yǔ； wú yǔ de jiù kū qián le."],[4,8,"這樣，兩三城的人湊到一城去找水， 卻喝不足； 你們仍不歸向我。 這是耶和華說的。","zhè yàng， liǎng sān chéng de rén còu dào yī chéng qù zhǎo shuǐ， què hē bù zú； nǐ men réng bù guī xiàng wǒ. zhè shì yé hé huá shuō de."],[4,9,"我以旱 風、霉爛攻擊你們， 你們園中許多菜蔬、葡萄樹、 無花果樹、橄欖樹都被剪蟲所吃； 你們仍不歸向我。 這是耶和華說的。","wǒ yǐ hàn fēng, méi làn gōng jī nǐ men， nǐ men yuán zhōng xǔ duō cài shū, pú táo shù, wú huā guǒ shù, gǎn lǎn shù dōu bèi jiǎn chóng suǒ chī； nǐ men réng bù guī xiàng wǒ. zhè shì yé hé huá shuō de."],[4,10,"我降瘟疫在你們中間， 像在 埃及一樣； 用刀殺戮你們的少年人， 使你們的馬匹被擄掠， 營中 屍首的臭氣撲鼻； 你們仍不歸向我。 這是耶和華說的。","wǒ jiàng wēn yì zài nǐ men zhōng jiān， xiàng zài āi jí yī yàng； yòng dāo shā lù nǐ men de shǎo nián rén， shǐ nǐ men de mǎ pǐ bèi lǔ lüè， yíng zhōng shī shǒu de chòu qì pū bí； nǐ men réng bù guī xiàng wǒ. zhè shì yé hé huá shuō de."],[4,11,"我傾覆你們中間的 城邑， 如同我從前傾覆 所多瑪、 蛾摩拉一樣， 使你們好像從火中抽出來的一根柴； 你們仍不歸向我。 這是耶和華說的。","wǒ qīng fù nǐ men zhōng jiān de chéng yì， rú tóng wǒ cóng qián qīng fù suǒ duō mǎ, é mó lā yī yàng， shǐ nǐ men hǎo xiàng cóng huǒ zhōng chōu chū lái de yī gēn chái； nǐ men réng bù guī xiàng wǒ. zhè shì yé hé huá shuō de."],[4,12,"以色列啊，我必向你如此行； 以色列啊，我既這樣行， 你當預備迎見你的神。","yǐ sè liè a， wǒ bì xiàng nǐ rú cǐ xíng； yǐ sè liè a， wǒ jì zhè yàng xíng， nǐ dāng yù bèi yíng jiàn nǐ de shén."],[4,13,"那創山、造風、將心意指示人、 使晨光變為幽暗、腳踏在地之高處的， 他的名是耶和華－萬軍之神。","nà chuàng shān, zào fēng, jiāng xīn yì zhǐ shì rén, shǐ chén guāng biàn wèi yōu àn, jiǎo tà zài de zhī gāo chù de， tā de míng shì yé hé huá－wàn jūn zhī shén."],[5,1,"以色列家啊，要聽我為你們所作的哀歌：","yǐ sè liè jiā a， yào tīng wǒ wèi nǐ men suǒ zuò de āi gē："],[5,2,"以色列民跌倒，不得再起； 躺在地上，無人攙扶。","yǐ sè liè mín diē dào， bù dé zài qǐ； tǎng zài de shàng， wú rén chān fú."],[5,3,"主耶和華如此說： 以色列家的城發出一千 兵的，只剩一百； 發出一百的，只剩十個。","zhǔ yé hé huá rú cǐ shuō： yǐ sè liè jiā de chéng fā chū yī qiān bīng de， zhǐ shèng yī bǎi； fā chū yī bǎi de， zhǐ shèng shí gè."],[5,4,"耶和華向 以色列家如此說： 你們要尋求我，就必存活。","yé hé huá xiàng yǐ sè liè jiā rú cǐ shuō： nǐ men yào xún qiú wǒ， jiù bì cún huó."],[5,5,"不要往 伯特利尋求， 不要進入 吉甲， 不要過到 別是巴； 因為 吉甲必被擄掠， 伯特利也必歸於無有。","bù yào wǎng bó tè lì xún qiú， bù yào jìn rù jí jiǎ， bù yào guò dào bié shì bā； yīn wèi jí jiǎ bì bèi lǔ lüè， bó tè lì yě bì guī yú wú yǒu."],[5,6,"要尋求耶和華，就必存活， 免得他在 約瑟家像火發出， 在 伯特利焚燒，無人撲滅。","yào xún qiú yé hé huá， jiù bì cún huó， miǎn dé tā zài yuē sè jiā xiàng huǒ fā chū， zài bó tè lì fén shāo， wú rén pū miè."],[5,7,"你們這使公平變為茵蔯、 將公義丟棄於地的，","nǐ men zhè shǐ gōng píng biàn wèi yīn chén, jiāng gōng yì diū qì yú de de，"],[5,8,"要 尋求那造昴星和參星， 使死蔭變為晨光， 使白日變為黑夜， 命海水來澆在地上的－ 耶和華是他的名；","yào xún qiú nà zào mǎo xīng hé cān xīng， shǐ sǐ yīn biàn wèi chén guāng， shǐ bái rì biàn wèi hēi yè， mìng hǎi shuǐ lái jiāo zài de shàng de－ yé hé huá shì tā de míng；"],[5,9,"他使力強的忽遭滅亡， 以致保障遭遇毀壞。","tā shǐ lì qiáng de hū zāo miè wáng， yǐ zhì bǎo zhàng zāo yù huǐ huài."],[5,10,"你們怨恨那在城門口責備人的， 憎惡那說正直話的。","nǐ men yuàn hèn nà zài chéng mén kǒu zé bèi rén de， zēng è nà shuō zhèng zhí huà de."],[5,11,"你們踐踏貧民， 向他們勒索麥子； 你們用鑿過的石頭建造房屋， 卻不得住在其內； 栽種美好的葡萄園， 卻不得喝所出的酒。","nǐ men jiàn tà pín mín， xiàng tā men lēi suǒ mài zǐ； nǐ men yòng záo guò de shí tóu jiàn zào fáng wū， què bù dé zhù zài qí nèi； zāi zhǒng měi hǎo de pú táo yuán， què bù dé hē suǒ chū de jiǔ."],[5,12,"我知道你們的罪過何等多， 你們的罪惡何等大。 你們苦待義人，收受賄賂，在城門口屈枉窮乏人。","wǒ zhī dào nǐ men de zuì guò hé děng duō， nǐ men de zuì è hé děng dà. nǐ men kǔ dài yì rén， shōu shòu huì lù， zài chéng mén kǒu qū wǎng qióng fá rén."],[5,13,"所以通達人見這樣的時勢必靜默不言， 因為時勢真惡。","suǒ yǐ tōng dá rén jiàn zhè yàng de shí shì bì jìng mò bù yán， yīn wèi shí shì zhēn è."],[5,14,"你們要求善， 不要求惡，就必存活。 這樣，耶和華－萬軍之神 必照你們所說的與你們同在。","nǐ men yào qiú shàn， bù yào qiú è， jiù bì cún huó. zhè yàng， yé hé huá－wàn jūn zhī shén bì zhào nǐ men suǒ shuō de yǔ nǐ men tóng zài."],[5,15,"要惡惡好善， 在城門口秉公行義； 或者耶和華－萬軍之神向 約瑟的餘民施恩。","yào è è hǎo shàn， zài chéng mén kǒu bǐng gōng xíng yì； huò zhě yé hé huá－wàn jūn zhī shén xiàng yuē sè de yú mín shī ēn."],[5,16,"主耶和華－萬軍之神如此說： 在一切寬闊處必有哀號的聲音； 在各街市上必有人說： 哀哉！哀哉！ 又必叫農夫來哭號， 叫善唱哀歌的來舉哀。","zhǔ yé hé huá－wàn jūn zhī shén rú cǐ shuō： zài yī qiè kuān kuò chù bì yǒu āi hào de shēng yīn； zài gè jiē shì shàng bì yǒu rén shuō： āi zāi！ āi zāi！ yòu bì jiào nóng fū lái kū hào， jiào shàn chàng āi gē de lái jǔ āi."],[5,17,"在各葡萄園必有哀號的聲音， 因為我必從你中間經過。 這是耶和華說的。","zài gè pú táo yuán bì yǒu āi hào de shēng yīn， yīn wèi wǒ bì cóng nǐ zhōng jiān jīng guò. zhè shì yé hé huá shuō de."],[5,18,"想望耶和華日子來到的有禍了！ 你們為何想望耶和華的日子呢？ 那日黑暗沒有光明，","xiǎng wàng yé hé huá rì zǐ lái dào de yǒu huò le！ nǐ men wèi hé xiǎng wàng yé hé huá de rì zǐ ne？ nà rì hēi àn méi yǒu guāng míng，"],[5,19,"景況好像人躲避獅子又遇見熊， 或是進房屋以手靠牆，就被蛇咬。","jǐng kuàng hǎo xiàng rén duǒ bì shī zǐ yòu yù jiàn xióng， huò shì jìn fáng wū yǐ shǒu kào qiáng， jiù bèi shé yǎo."],[5,20,"耶和華的日子不是黑暗沒有光明嗎？ 不是幽暗毫無光輝嗎？","yé hé huá de rì zǐ bù shì hēi àn méi yǒu guāng míng ma？ bù shì yōu àn háo wú guāng huī ma？"],[5,21,"我厭惡你們的節期， 也不喜悅你們的嚴肅會。","wǒ yàn è nǐ men de jié qī， yě bù xǐ yuè nǐ men de yán sù huì."],[5,22,"你們雖然向我獻燔祭和素祭， 我卻不悅納， 也不顧你們用肥畜獻的平安祭；","nǐ men suī rán xiàng wǒ xiàn fán jì hé sù jì， wǒ què bù yuè nà， yě bù gù nǐ men yòng féi chù xiàn de píng ān jì；"],[5,23,"要使你們歌唱的聲音遠離我， 因為我不聽你們彈琴的響聲。","yào shǐ nǐ men gē chàng de shēng yīn yuǎn lí wǒ， yīn wèi wǒ bù tīng nǐ men dàn qín de xiǎng shēng."],[5,24,"惟願公平如大水滾滾， 使公義如江河滔滔。","wéi yuàn gōng píng rú dà shuǐ gǔn gǔn， shǐ gōng yì rú jiāng hé tāo tāo."],[5,25,"「 以色列家啊，你們在曠野四十年，豈是將祭物和供物獻給我呢？","‘ yǐ sè liè jiā a， nǐ men zài kuàng yě sì shí nián， qǐ shì jiāng jì wù hé gōng wù xiàn gěi wǒ ne？"],[5,26,"你們抬着為自己所造之 摩洛的帳幕和偶像的龕，並你們的神星。","nǐ men tái zhe wèi zì jǐ suǒ zào zhī mó luò de zhàng mù hé ǒu xiàng de kān， bìng nǐ men de shén xīng."],[5,27,"所以我要把你們擄到 大馬士革以外。」這是耶和華－名為萬軍之神說的。","suǒ yǐ wǒ yào bǎ nǐ men lǔ dào dà mǎ shì gé yǐ wài.’ zhè shì yé hé huá－míng wèi wàn jūn zhī shén shuō de."],[6,1,"國為列國之首，人最著名， 且為 以色列家所歸向， 在 錫安和 撒馬利亞山安逸無慮的，有禍了！","guó wèi liè guó zhī shǒu， rén zuì zhù míng， qiě wèi yǐ sè liè jiā suǒ guī xiàng， zài xī ān hé sā mǎ lì yà shān ān yì wú lǜ de， yǒu huò le！"],[6,2,"你們要過到 甲尼察看， 從那裏往大 城 哈馬去， 又下到 非利士人的 迦特， 看那些國比你們的國還強嗎？ 境界比你們的境界還寬嗎？","nǐ men yào guò dào jiǎ ní chá kàn， cóng nà lǐ wǎng dà chéng hā mǎ qù， yòu xià dào fēi lì shì rén de jiā tè， kàn nà xiē guó bǐ nǐ men de guó hái qiáng ma？ jìng jiè bǐ nǐ men de jìng jiè hái kuān ma？"],[6,3,"你們以為降禍的日子還遠， 坐在位上盡行強暴。","nǐ men yǐ wèi jiàng huò de rì zǐ hái yuǎn， zuò zài wèi shàng jǐn xíng qiáng bào."],[6,4,"你們躺臥在象牙床上，舒身在榻上， 吃群中的羊羔，棚裏的牛犢；","nǐ men tǎng wò zài xiàng yá chuáng shàng， shū shēn zài tà shàng， chī qún zhōng de yáng gāo， péng lǐ de niú dú；"],[6,5,"彈琴鼓瑟唱消閑的歌曲， 為自己製造樂器，如同 大衛 所造的；","dàn qín gǔ sè chàng xiāo xián de gē qū， wèi zì jǐ zhì zào lè qì， rú tóng dà wèi suǒ zào de；"],[6,6,"以大碗喝酒，用上等的油抹身， 卻不為 約瑟的苦難擔憂。","yǐ dà wǎn hē jiǔ， yòng shàng děng de yóu mǒ shēn， què bù wèi yuē sè de kǔ nán dān yōu."],[6,7,"所以這些人必在被擄的人中首先被擄； 舒身的人荒宴之樂必消滅了。","suǒ yǐ zhè xiē rén bì zài bèi lǔ de rén zhōng shǒu xiān bèi lǔ； shū shēn de rén huāng yàn zhī lè bì xiāo miè le."],[6,8,"主耶和華－萬軍之神指着自己起誓說： 我憎惡 雅各的榮華，厭棄他的宮殿； 因此，我必將城和其中所有的都交付 敵人。","zhǔ yé hé huá－wàn jūn zhī shén zhǐ zhe zì jǐ qǐ shì shuō： wǒ zēng è yǎ gè de róng huá， yàn qì tā de gōng diàn； yīn cǐ， wǒ bì jiāng chéng hé qí zhōng suǒ yǒu de dōu jiāo fù dí rén."],[6,9,"那時，若在一房之內剩下十個人，也都必死。","nà shí， ruò zài yī fáng zhī nèi shèng xià shí gè rén， yě dōu bì sǐ."],[6,10,"死人的伯叔，就是燒他屍首的，要將這屍首搬到房外，問房屋內間的人說：「你那裏還有人沒有？」他必說：「沒有」；又說：「不要作聲，因為我們不可提耶和華的名。」","sǐ rén de bó shū， jiù shì shāo tā shī shǒu de， yào jiāng zhè shī shǒu bān dào fáng wài， wèn fáng wū nèi jiān de rén shuō：‘nǐ nà lǐ hái yǒu rén méi yǒu？’ tā bì shuō：‘méi yǒu’； yòu shuō：‘bù yào zuò shēng， yīn wèi wǒ men bù kě tí yé hé huá de míng.’"],[6,11,"看哪，耶和華出令， 大房就被攻破， 小屋就被打裂。","kàn nǎ， yé hé huá chū lìng， dà fáng jiù bèi gōng pò， xiǎo wū jiù bèi dǎ liè."],[6,12,"馬豈能在崖石上奔跑？ 人豈能 在那裏用牛耕種呢？ 你們卻使公平變為苦膽， 使公義的果子變為茵蔯。","mǎ qǐ néng zài yá shí shàng bēn pǎo？ rén qǐ néng zài nà lǐ yòng niú gēng zhǒng ne？ nǐ men què shǐ gōng píng biàn wèi kǔ dǎn， shǐ gōng yì de guǒ zǐ biàn wèi yīn chén."],[6,13,"你們喜愛虛浮的事， 自誇說： 我們不是憑自己的力量取了角嗎？","nǐ men xǐ ài xū fú de shì， zì kuā shuō： wǒ men bù shì píng zì jǐ de lì liàng qǔ le jiǎo ma？"],[6,14,"耶和華、萬軍之神說： 以色列家啊，我必興起一國攻擊你們； 他們必欺壓你們， 從 哈馬口直到 亞拉巴的河。","yé hé huá, wàn jūn zhī shén shuō： yǐ sè liè jiā a， wǒ bì xìng qǐ yī guó gōng jī nǐ men； tā men bì qī yā nǐ men， cóng hā mǎ kǒu zhí dào yà lā bā de hé."],[7,1,"主耶和華指示我一件事：為王割菜之後，菜又發生；剛發生的時候，主造蝗蟲。","zhǔ yé hé huá zhǐ shì wǒ yī jiàn shì： wèi wáng gē cài zhī hòu， cài yòu fā shēng； gāng fā shēng de shí hòu， zhǔ zào huáng chóng."],[7,2,"蝗蟲吃盡那地的青物，我就說：「主耶和華啊，求你赦免；因為 雅各微弱，他怎能站立得住呢？」","huáng chóng chī jǐn nà de de qīng wù， wǒ jiù shuō：‘zhǔ yé hé huá a， qiú nǐ shè miǎn； yīn wèi yǎ gè wēi ruò， tā zěn néng zhàn lì dé zhù ne？’"],[7,3,"耶和華就後悔說：「這災可以免了。」","yé hé huá jiù hòu huǐ shuō：‘zhè zāi kě yǐ miǎn le.’"],[7,4,"主耶和華又指示我一件事：他命火來懲罰 以色列，火就吞滅深淵，險些將地燒滅。","zhǔ yé hé huá yòu zhǐ shì wǒ yī jiàn shì： tā mìng huǒ lái chéng fá yǐ sè liè， huǒ jiù tūn miè shēn yuān， xiǎn xiē jiāng de shāo miè."],[7,5,"我就說：「主耶和華啊，求你止息；因為 雅各微弱，他怎能站立得住呢？」","wǒ jiù shuō：‘zhǔ yé hé huá a， qiú nǐ zhǐ xī； yīn wèi yǎ gè wēi ruò， tā zěn néng zhàn lì dé zhù ne？’"],[7,6,"耶和華就後悔說：「這災也可免了。」","yé hé huá jiù hòu huǐ shuō：‘zhè zāi yě kě miǎn le.’"],[7,7,"他又指示我一件事：有一道牆是按準繩建築的，主手拿準繩站在其上。","tā yòu zhǐ shì wǒ yī jiàn shì： yǒu yī dào qiáng shì àn zhǔn shéng jiàn zhú de， zhǔ shǒu ná zhǔn shéng zhàn zài qí shàng."],[7,8,"耶和華對我說：「 阿摩司啊，你看見甚麼？」我說：「看見準繩。」主說：「我要吊起準繩在我民 以色列中，我必不再寬恕他們。","yé hé huá duì wǒ shuō：‘ ā mó sī a， nǐ kàn jiàn shèn me？’ wǒ shuō：‘kàn jiàn zhǔn shéng.’ zhǔ shuō：‘wǒ yào diào qǐ zhǔn shéng zài wǒ mín yǐ sè liè zhōng， wǒ bì bù zài kuān shù tā men."],[7,9,"以撒的邱壇必然淒涼； 以色列的聖所必然荒廢。我必興起，用刀攻擊 耶羅波安的家。」","yǐ sā de qiū tán bì rán qī liáng； yǐ sè liè de shèng suǒ bì rán huāng fèi. wǒ bì xìng qǐ， yòng dāo gōng jī yé luó bō ān de jiā.’"],[7,10,"伯特利的祭司 亞瑪謝打發人到 以色列王 耶羅波安那裏，說：「 阿摩司在 以色列家中圖謀背叛你；他所說的一切話，這國擔當不起；","bó tè lì de jì sī yà mǎ xiè dǎ fā rén dào yǐ sè liè wáng yé luó bō ān nà lǐ， shuō：‘ ā mó sī zài yǐ sè liè jiā zhōng tú móu bèi pàn nǐ； tā suǒ shuō de yī qiè huà， zhè guó dān dāng bù qǐ；"],[7,11,"因為 阿摩司如此說：『 耶羅波安必被刀殺； 以色列民定被擄去離開本地。』」","yīn wèi ā mó sī rú cǐ shuō：“ yé luó bō ān bì bèi dāo shā； yǐ sè liè mín dìng bèi lǔ qù lí kāi běn de.”’"],[7,12,"亞瑪謝又對 阿摩司說：「你這先見哪，要逃往 猶大地去，在那裏糊口，在那裏說預言，","yà mǎ xiè yòu duì ā mó sī shuō：‘nǐ zhè xiān jiàn nǎ， yào táo wǎng yóu dà de qù， zài nà lǐ hú kǒu， zài nà lǐ shuō yù yán，"],[7,13,"卻不要在 伯特利再說預言；因為這裏有王的聖所，有王的宮殿。」","què bù yào zài bó tè lì zài shuō yù yán； yīn wèi zhè lǐ yǒu wáng de shèng suǒ， yǒu wáng de gōng diàn.’"],[7,14,"阿摩司對 亞瑪謝說：「我原不是先知，也不是先知的門徒。我是牧人，又是修理桑樹的。","ā mó sī duì yà mǎ xiè shuō：‘wǒ yuán bù shì xiān zhī， yě bù shì xiān zhī de mén tú. wǒ shì mù rén， yòu shì xiū lǐ sāng shù de."],[7,15,"耶和華選召我，使我不跟從羊群，對我說：『你去向我民 以色列說預言。』","yé hé huá xuǎn zhào wǒ， shǐ wǒ bù gēn cóng yáng qún， duì wǒ shuō：“nǐ qù xiàng wǒ mín yǐ sè liè shuō yù yán.”"],[7,16,"亞瑪謝啊，現在你要聽耶和華的話。你說：『不要向 以色列說預言，也不要向 以撒家滴下 預言。』","yà mǎ xiè a， xiàn zài nǐ yào tīng yé hé huá de huà. nǐ shuō：“bù yào xiàng yǐ sè liè shuō yù yán， yě bù yào xiàng yǐ sā jiā dī xià yù yán.”"],[7,17,"所以耶和華如此說：『你的妻子必在城中作妓女；你的兒女必倒在刀下。你的地必有人用繩子量了分取；你自己必死在污穢之地。 以色列民定被擄去離開本地。』」","suǒ yǐ yé hé huá rú cǐ shuō：“nǐ de qī zǐ bì zài chéng zhōng zuò jì nǚ； nǐ de ér nǚ bì dào zài dāo xià. nǐ de de bì yǒu rén yòng shéng zǐ liàng le fēn qǔ； nǐ zì jǐ bì sǐ zài wū huì zhī de. yǐ sè liè mín dìng bèi lǔ qù lí kāi běn de.”’"],[8,1,"主耶和華又指示我一件事：我看見一筐夏天的果子。","zhǔ yé hé huá yòu zhǐ shì wǒ yī jiàn shì： wǒ kàn jiàn yī kuāng xià tiān de guǒ zǐ."],[8,2,"他說：「 阿摩司啊，你看見甚麼？」我說：「看見一筐夏天的果子。」耶和華說：「我民 以色列的結局到了，我必不再寬恕他們。」","tā shuō：‘ ā mó sī a， nǐ kàn jiàn shèn me？’ wǒ shuō：‘kàn jiàn yī kuāng xià tiān de guǒ zǐ.’ yé hé huá shuō：‘wǒ mín yǐ sè liè de jié jú dào le， wǒ bì bù zài kuān shù tā men.’"],[8,3,"主耶和華說：「那日，殿中的詩歌變為哀號；必有許多屍首在各處拋棄，無人作聲。」","zhǔ yé hé huá shuō：‘nà rì， diàn zhōng de shī gē biàn wèi āi hào； bì yǒu xǔ duō shī shǒu zài gè chù pāo qì， wú rén zuò shēng.’"],[8,4,"你們這些要吞吃窮乏人、 使困苦人衰敗的，當聽我的話！","nǐ men zhè xiē yào tūn chī qióng fá rén, shǐ kùn kǔ rén shuāi bài de， dāng tīng wǒ de huà！"],[8,5,"你們說：月朔幾時過去， 我們好賣糧； 安息日幾時過去， 我們好擺開麥子； 賣出用小升斗， 收銀用大戥子， 用詭詐的天平欺哄人，","nǐ men shuō： yuè shuò jǐ shí guò qù， wǒ men hǎo mài liáng； ān xī rì jǐ shí guò qù， wǒ men hǎo bǎi kāi mài zǐ； mài chū yòng xiǎo shēng dòu， shōu yín yòng dà děng zǐ， yòng guǐ zhà de tiān píng qī hōng rén，"],[8,6,"好用銀子買貧寒人， 用一雙鞋換窮乏人， 將壞了的麥子賣給人。","hǎo yòng yín zǐ mǎi pín hán rén， yòng yī shuāng xié huàn qióng fá rén， jiāng huài le de mài zǐ mài gěi rén."],[8,7,"耶和華指着 雅各的榮耀起誓說： 他們的一切行為，我必永遠不忘。","yé hé huá zhǐ zhe yǎ gè de róng yào qǐ shì shuō： tā men de yī qiè xíng wèi， wǒ bì yǒng yuǎn bù wàng."],[8,8,"地豈不因這事震動？ 其上的居民不也悲哀嗎？ 地必全然像 尼羅河漲起， 如同 埃及河湧上落下。","de qǐ bù yīn zhè shì zhèn dòng？ qí shàng de jū mín bù yě bēi āi ma？ de bì quán rán xiàng ní luó hé zhǎng qǐ， rú tóng āi jí hé yǒng shàng luò xià."],[8,9,"主耶和華說：到那日， 我必使日頭在午間落下， 使地在白晝黑暗。","zhǔ yé hé huá shuō： dào nà rì， wǒ bì shǐ rì tóu zài wǔ jiān luò xià， shǐ de zài bái zhòu hēi àn."],[8,10,"我必使你們的節期變為悲哀， 歌曲變為哀歌。 眾人腰束麻布，頭上光禿， 使這場悲哀如喪獨生子， 至終如痛苦的日子一樣。","wǒ bì shǐ nǐ men de jié qī biàn wèi bēi āi， gē qū biàn wèi āi gē. zhòng rén yāo shù má bù， tóu shàng guāng tū， shǐ zhè chǎng bēi āi rú sàng dú shēng zǐ， zhì zhōng rú tòng kǔ de rì zǐ yī yàng."],[8,11,"主耶和華說：日子將到， 我必命饑荒降在地上。 人飢餓非因無餅，乾渴非因無水， 乃因不聽耶和華的話。","zhǔ yé hé huá shuō： rì zǐ jiāng dào， wǒ bì mìng jī huāng jiàng zài de shàng. rén jī è fēi yīn wú bǐng， qián kě fēi yīn wú shuǐ， nǎi yīn bù tīng yé hé huá de huà."],[8,12,"他們必飄流，從這海到那海， 從北邊到東邊，往來奔跑， 尋求耶和華的話，卻尋不着。","tā men bì piāo liú， cóng zhè hǎi dào nà hǎi， cóng běi biān dào dōng biān， wǎng lái bēn pǎo， xún qiú yé hé huá de huà， què xún bù zhe."],[8,13,"當那日，美貌的處女 和少年的男子必因乾渴發昏。","dāng nà rì， měi mào de chù nǚ hé shǎo nián de nán zǐ bì yīn qián kě fā hūn."],[8,14,"那指着 撒馬利亞牛犢起誓的說： 但哪，我們指着你那裏的活神起誓； 又說：我們指着 別是巴的神道起誓。 這些人都必仆倒，永不再起來。","nà zhǐ zhe sā mǎ lì yà niú dú qǐ shì de shuō： dàn nǎ， wǒ men zhǐ zhe nǐ nà lǐ de huó shén qǐ shì； yòu shuō： wǒ men zhǐ zhe bié shì bā de shén dào qǐ shì. zhè xiē rén dōu bì pū dào， yǒng bù zài qǐ lái."],[9,1,"我看見主站在祭壇旁邊； 他說：你要擊打柱頂，使門檻震動， 打碎柱頂，落在眾人頭上； 所剩下的人，我必用刀殺戮， 無一人能逃避，無一人能逃脫。","wǒ kàn jiàn zhǔ zhàn zài jì tán páng biān； tā shuō： nǐ yào jī dǎ zhù dǐng， shǐ mén kǎn zhèn dòng， dǎ suì zhù dǐng， luò zài zhòng rén tóu shàng； suǒ shèng xià de rén， wǒ bì yòng dāo shā lù， wú yī rén néng táo bì， wú yī rén néng táo tuō."],[9,2,"他們雖然挖透陰間， 我的手必取出他們來； 雖然爬上天去， 我必拿下他們來；","tā men suī rán wā tòu yīn jiān， wǒ de shǒu bì qǔ chū tā men lái； suī rán pá shàng tiān qù， wǒ bì ná xià tā men lái；"],[9,3,"雖然藏在 迦密山頂， 我必搜尋，捉出他們來； 雖然從我眼前藏在海底， 我必命蛇咬他們；","suī rán cáng zài jiā mì shān dǐng， wǒ bì sōu xún， zhuō chū tā men lái； suī rán cóng wǒ yǎn qián cáng zài hǎi dǐ， wǒ bì mìng shé yǎo tā men；"],[9,4,"雖被仇敵擄去， 我必命刀劍殺戮他們； 我必向他們定住眼目， 降禍不降福。","suī bèi chóu dí lǔ qù， wǒ bì mìng dāo jiàn shā lù tā men； wǒ bì xiàng tā men dìng zhù yǎn mù， jiàng huò bù jiàng fú."],[9,5,"主－萬軍之耶和華摸地，地就消化， 凡住在地上的都必悲哀。 地必全然像 尼羅河漲起， 如同 埃及河落下。","zhǔ－wàn jūn zhī yé hé huá mō de， de jiù xiāo huà， fán zhù zài de shàng de dōu bì bēi āi. de bì quán rán xiàng ní luó hé zhǎng qǐ， rú tóng āi jí hé luò xià."],[9,6,"那在天上建造樓閣、 在地上安定穹蒼、 命海水澆在地上的－ 耶和華是他的名。","nà zài tiān shàng jiàn zào lóu gé, zài de shàng ān dìng qióng cāng, mìng hǎi shuǐ jiāo zài de shàng de－ yé hé huá shì tā de míng."],[9,7,"耶和華說： 以色列人哪， 我豈不看你們如 古實人嗎？ 我豈不是領 以色列人出 埃及地， 領 非利士人出 迦斐託， 領 亞蘭人出 吉珥嗎？","yé hé huá shuō： yǐ sè liè rén nǎ， wǒ qǐ bù kàn nǐ men rú gǔ shí rén ma？ wǒ qǐ bù shì lǐng yǐ sè liè rén chū āi jí de， lǐng fēi lì shì rén chū jiā fěi tuō， lǐng yà lán rén chū jí ěr ma？"],[9,8,"主耶和華的眼目察看這有罪的國， 必將這國從地上滅絕， 卻不將 雅各家滅絕淨盡。 這是耶和華說的。","zhǔ yé hé huá de yǎn mù chá kàn zhè yǒu zuì de guó， bì jiāng zhè guó cóng de shàng miè jué， què bù jiāng yǎ gè jiā miè jué jìng jǐn. zhè shì yé hé huá shuō de."],[9,9,"我必出令， 將 以色列家分散在列國中， 好像用篩子篩 穀， 連一粒也不落在地上。","wǒ bì chū lìng， jiāng yǐ sè liè jiā fēn sàn zài liè guó zhōng， hǎo xiàng yòng shāi zǐ shāi gǔ， lián yī lì yě bù luò zài de shàng."],[9,10,"我民中的一切罪人說： 災禍必追不上我們， 也迎不着我們。 他們必死在刀下。","wǒ mín zhōng de yī qiè zuì rén shuō： zāi huò bì zhuī bù shàng wǒ men， yě yíng bù zhe wǒ men. tā men bì sǐ zài dāo xià."],[9,11,"到那日，我必建立 大衛倒塌的帳幕， 堵住其中的破口， 把那破壞的建立起來， 重新修造，像古時一樣，","dào nà rì， wǒ bì jiàn lì dà wèi dào tā de zhàng mù， dǔ zhù qí zhōng de pò kǒu， bǎ nà pò huài de jiàn lì qǐ lái， zhòng xīn xiū zào， xiàng gǔ shí yī yàng，"],[9,12,"使 以色列人得 以東所餘剩的 和所有稱為我名下的國。 此乃行這事的耶和華說的。","shǐ yǐ sè liè rén dé yǐ dōng suǒ yú shèng de hé suǒ yǒu chēng wèi wǒ míng xià de guó. cǐ nǎi xíng zhè shì de yé hé huá shuō de."],[9,13,"耶和華說： 日子將到， 耕種的必接續收割的； 踹葡萄的必接續撒種的； 大山要滴下甜酒； 小山都必流奶。","yé hé huá shuō： rì zǐ jiāng dào， gēng zhǒng de bì jiē xù shōu gē de； chuài pú táo de bì jiē xù sā zhǒng de； dà shān yào dī xià tián jiǔ； xiǎo shān dōu bì liú nǎi."],[9,14,"我必使我民 以色列被擄的歸回； 他們必重修荒廢的城邑居住， 栽種葡萄園，喝其中所出的酒， 修造果木園，吃其中的果子。","wǒ bì shǐ wǒ mín yǐ sè liè bèi lǔ de guī huí； tā men bì zhòng xiū huāng fèi de chéng yì jū zhù， zāi zhǒng pú táo yuán， hē qí zhōng suǒ chū de jiǔ， xiū zào guǒ mù yuán， chī qí zhōng de guǒ zǐ."],[9,15,"我要將他們栽於本地， 他們不再從我所賜給他們的地上拔出來。 這是耶和華－你的神說的。","wǒ yào jiāng tā men zāi yú běn de， tā men bù zài cóng wǒ suǒ cì gěi tā men de de shàng bá chū lái. zhè shì yé hé huá－nǐ de shén shuō de."]],"arb-vandyck":[[1,1,"أَقْوَالُ عَامُوسَ ٱلَّذِي كَانَ بَيْنَ ٱلرُّعَاةِ مِنْ تَقُوعَ ٱلَّتِي رَآهَا عَنْ إِسْرَائِيلَ، فِي أَيَّامِ عُزِّيَّا مَلِكِ يَهُوذَا، وَفِي أَيَّامِ يَرُبْعَامَ بْنِ يُوآشَ مَلِكِ إِسْرَائِيلَ، قَبْلَ ٱلزَّلْزَلَةِ بِسَنَتَيْنِ.","ạảq̊wālu ʿāmūsa ٱlãdẖī kāna baẙna ٱlrũʿāẗi min̊ taqūʿa ٱlãtī rā̂hā ʿan̊ ại̹s̊rāyỉyla, fī ạảyãạmi ʿuzĩyãạ maliki yahūdẖā, wafī ạảyãạmi yarub̊ʿāma b̊ni yūậsẖa maliki ại̹s̊rāyỉyla, qab̊la ٱlzãl̊zalaẗi bisanataẙni."],[1,2,"فَقَالَ: «إِنَّ ٱلرَّبَّ يُزَمْجِرُ مِنْ صِهْيَوْنَ، وَيُعْطِي صَوْتَهُ مِنْ أُورُشَلِيمَ، فَتَنُوحُ مَرَاعِي ٱلرُّعَاةِ وَيَيْبَسُ رَأْسُ ٱلْكَرْمَلِ».","faqāla: «ại̹nã ٱlrãbã yuzam̊jiru min̊ ṣih̊yaẘna, wayuʿ̊ṭī ṣaẘtahu min̊ ạủwrusẖalīma, fatanūḥu marāʿī ٱlrũʿāẗi wayaẙbasu rā̊̉su ٱl̊kar̊mali»."],[1,3,"هَكَذَا قَالَ ٱلرَّبُّ: «مِنْ أَجْلِ ذُنُوبِ دِمَشْقَ ٱلثَّلَاثَةِ وَٱلْأَرْبَعَةِ لَا أَرْجِعُ عَنْهُ، لِأَنَّهُمْ دَاسُوا جِلْعَادَ بِنَوَارِجَ مِنْ حَدِيدٍ.","hakadẖā qāla ٱlrãbũ: «min̊ ạảj̊li dẖunūbi dimasẖ̊qa ٱltẖãlātẖaẗi waٱl̊ạảr̊baʿaẗi lā ạảr̊jiʿu ʿan̊hu, liạảnãhum̊ dāsūạ jil̊ʿāda binawārija min̊ ḥadīdiⁿ."],[1,4,"فَأُرْسِلُ نَارًا عَلَى بَيْتِ حَزَائِيلَ فَتَأْكُلُ قُصُورَ بَنْهَدَدَ.","fāủr̊silu nāraⁿạ ʿalay̱ baẙti ḥazāyỉyla fatā̊̉kulu quṣūra ban̊hadada."],[1,5,"وَأُكَسِّرُ مِغْلَاقَ دِمَشْقَ، وَأَقْطَعُ ٱلسَّاكِنَ مِنْ بُقْعَةِ آوَنَ، وَمَاسِكَ ٱلْقَضِيبِ مِنْ بَيْتِ عَدْنٍ، وَيُسْبَى شَعْبُ أَرَامَ إِلَى قِيرَ، قَالَ ٱلرَّبُّ».","wāủkasĩru migẖ̊lāqa dimasẖ̊qa, wāảq̊ṭaʿu ٱlsãạkina min̊ buq̊ʿaẗi ậwana, wamāsika ٱl̊qaḍībi min̊ baẙti ʿad̊niⁿ, wayus̊bay̱ sẖaʿ̊bu ạảrāma ại̹lay̱ qīra, qāla ٱlrãbũ»."],[1,6,"هَكَذَا قَالَ ٱلرَّبُّ: «مِنْ أَجْلِ ذُنُوبِ غَزَّةَ ٱلثَّلَاثَةِ وَٱلْأَرْبَعَةِ لَا أَرْجِعُ عَنْهُ، لِأَنَّهُمْ سَبَوْا سَبْيًا كَامِلًا لِكَىْ يُسَلِّمُوهُ إِلَى أَدُومَ.","hakadẖā qāla ٱlrãbũ: «min̊ ạảj̊li dẖunūbi gẖazãẗa ٱltẖãlātẖaẗi waٱl̊ạảr̊baʿaẗi lā ạảr̊jiʿu ʿan̊hu, liạảnãhum̊ sabaẘạ sab̊yaⁿạ kāmilaⁿạ likaẙ̱ yusalĩmūhu ại̹lay̱ ạảdūma."],[1,7,"فَأُرْسِلُ نَارًا عَلَى سُورِ غَزَّةَ فَتَأْكُلُ قُصُورَهَا.","fāủr̊silu nāraⁿạ ʿalay̱ sūri gẖazãẗa fatā̊̉kulu quṣūrahā."],[1,8,"وَأَقْطَعُ ٱلسَّاكِنَ مِنْ أَشْدُودَ، وَمَاسِكَ ٱلْقَضِيبِ مِنْ أَشْقَلُونَ، وَأَرُدُّ يَدِي عَلَى عَقْرُونَ، فَتَهْلِكُ بَقِيَّةُ ٱلْفِلِسْطِينِيِّينَ، قَالَ ٱلسَّيِّدُ ٱلرَّبُّ».","wāảq̊ṭaʿu ٱlsãạkina min̊ ạảsẖ̊dūda, wamāsika ٱl̊qaḍībi min̊ ạảsẖ̊qalūna, wāảrudũ yadī ʿalay̱ ʿaq̊rūna, fatah̊liku baqīãẗu ٱl̊filis̊ṭīnīĩyna, qāla ٱlsãyĩdu ٱlrãbũ»."],[1,9,"هَكَذَا قَالَ ٱلرَّبُّ: «مِنْ أَجْلِ ذُنُوبِ صُورَ ٱلثَّلَاثَةِ وَٱلْأَرْبَعَةِ لَا أَرْجِعُ عَنْهُ، لِأَنَّهُمْ سَلَّمُوا سَبْيًا كَامِلًا إِلَى أَدُومَ، وَلَمْ يَذْكُرُوا عَهْدَ ٱلْإِخْوَةِ.","hakadẖā qāla ٱlrãbũ: «min̊ ạảj̊li dẖunūbi ṣūra ٱltẖãlātẖaẗi waٱl̊ạảr̊baʿaẗi lā ạảr̊jiʿu ʿan̊hu, liạảnãhum̊ salãmūạ sab̊yaⁿạ kāmilaⁿạ ại̹lay̱ ạảdūma, walam̊ yadẖ̊kurūạ ʿah̊da ٱl̊ại̹kẖ̊waẗi."],[1,10,"فَأُرْسِلُ نَارًا عَلَى سُورِ صُورَ فَتَأْكُلُ قُصُورَهَا».","fāủr̊silu nāraⁿạ ʿalay̱ sūri ṣūra fatā̊̉kulu quṣūrahā»."],[1,11,"هَكَذَا قَالَ ٱلرَّبُّ: «مِنْ أَجْلِ ذُنُوبِ أَدُومَ ٱلثَّلَاثَةِ وَٱلْأَرْبَعَةِ لَا أَرْجِعُ، لِأَنَّهُ تَبِعَ بِٱلسَّيْفِ أَخَاهُ، وَأَفْسَدَ مَرَاحِمَهُ، وَغضَبُهُ إِلَى ٱلدَّهْرِ يَفْتَرِسُ، وَسَخَطُهُ يَحْفَظُهُ إِلَى ٱلْأَبَدِ.","hakadẖā qāla ٱlrãbũ: «min̊ ạảj̊li dẖunūbi ạảdūma ٱltẖãlātẖaẗi waٱl̊ạảr̊baʿaẗi lā ạảr̊jiʿu, liạảnãhu tabiʿa biٱlsãẙfi ạảkẖāhu, wāảf̊sada marāḥimahu, wagẖḍabuhu ại̹lay̱ ٱldãh̊ri yaf̊tarisu, wasakẖaṭuhu yaḥ̊faẓuhu ại̹lay̱ ٱl̊ạảbadi."],[1,12,"فَأُرْسِلُ نَارًا عَلَى تَيْمَانَ فَتَأْكُلُ قُصُورَ بُصْرَةَ».","fāủr̊silu nāraⁿạ ʿalay̱ taẙmāna fatā̊̉kulu quṣūra buṣ̊raẗa»."],[1,13,"هَكَذَا قَالَ ٱلرَّبُّ: «مِنْ أَجْلِ ذُنُوبِ بَنِي عَمُّونَ ٱلثَّلَاثَةِ وَٱلْأَرْبَعَةِ لَا أَرْجِعُ عَنْهُ، لِأَنَّهُمْ شَقُّوا حَوَامِلَ جِلْعَادَ لِكَيْ يُوَسِّعُوا تُخُومَهُمْ.","hakadẖā qāla ٱlrãbũ: «min̊ ạảj̊li dẖunūbi banī ʿamũwna ٱltẖãlātẖaẗi waٱl̊ạảr̊baʿaẗi lā ạảr̊jiʿu ʿan̊hu, liạảnãhum̊ sẖaqũwạ ḥawāmila jil̊ʿāda likaẙ yūasĩʿūạ tukẖūmahum̊."],[1,14,"فَأُضْرِمُ نَارًا عَلَى سُورِ رَبَّةَ فَتَأْكُلُ قُصُورَهَا. بِجَلَبَةٍ فِي يَوْمِ ٱلْقِتَالِ، بِنَوْءٍ فِي يَوْمِ ٱلزَّوْبَعَةِ.","fāủḍ̊rimu nāraⁿạ ʿalay̱ sūri rabãẗa fatā̊̉kulu quṣūrahā. bijalabaẗiⁿ fī yaẘmi ٱl̊qitāli, binaẘʾiⁿ fī yaẘmi ٱlzãẘbaʿaẗi."],[1,15,"وَيَمْضِي مَلِكُهُمْ إِلَى ٱلسَّبْيِ هُوَ وَرُؤَسَاؤُهُ جَمِيعًا، قَالَ ٱلرَّبُّ».","wayam̊ḍī malikuhum̊ ại̹lay̱ ٱlsãb̊yi hūa warūảsāwủhu jamīʿaⁿạ, qāla ٱlrãbũ»."],[2,1,"هَكَذَا قَالَ ٱلرَّبُّ: «مِنْ أَجْلِ ذُنُوبِ مُوآبَ ٱلثَّلَاثَةِ وَٱلْأَرْبَعَةِ لَا أَرْجِعُ عَنْهُ، لِأَنَّهُمْ أَحْرَقُوا عِظَامَ مَلِكِ أَدُومَ كِلْسًا.","hakadẖā qāla ٱlrãbũ: «min̊ ạảj̊li dẖunūbi mūậba ٱltẖãlātẖaẗi waٱl̊ạảr̊baʿaẗi lā ạảr̊jiʿu ʿan̊hu, liạảnãhum̊ ạảḥ̊raqūạ ʿiẓāma maliki ạảdūma kil̊saⁿạ."],[2,2,"فَأُرْسِلُ نَارًا عَلَى مُوآبَ فَتَأْكُلُ قُصُورَ قَرْيُوتَ، وَيَمُوتُ مُوآبُ بِضَجِيجٍ، بِجَلَبَةٍ، بِصَوْتِ ٱلْبُوقِ.","fāủr̊silu nāraⁿạ ʿalay̱ mūậba fatā̊̉kulu quṣūra qar̊yūta, wayamūtu mūậbu biḍajījiⁿ, bijalabaẗiⁿ, biṣaẘti ٱl̊būqi."],[2,3,"وَأَقْطَعُ ٱلْقَاضِيَ مِنْ وَسَطِهَا، وَأَقْتُلُ جَمِيعَ رُؤَسَائِهَا مَعَهُ، قَالَ ٱلرَّبُّ».","wāảq̊ṭaʿu ٱl̊qāḍīa min̊ wasaṭihā, wāảq̊tulu jamīʿa rūảsāyỉhā maʿahu, qāla ٱlrãbũ»."],[2,4,"هَكَذَا قَالَ ٱلرَّبُّ: «مِنْ أَجْلِ ذُنُوبِ يَهُوذَا ٱلثَّلَاثَةِ وَٱلْأَرْبَعَةِ لَا أَرْجِعُ عَنْهُ، لِأَنَّهُمْ رَفَضُوا نَامُوسَ ٱللهِ وَلَمْ يَحْفَظُوا فَرَائِضَهُ، وَأَضَلَّتْهُمْ أَكَاذِيبُهُمُ ٱلَّتِي سَارَ آبَاؤُهُمْ وَرَاءَهَا.","hakadẖā qāla ٱlrãbũ: «min̊ ạảj̊li dẖunūbi yahūdẖā ٱltẖãlātẖaẗi waٱl̊ạảr̊baʿaẗi lā ạảr̊jiʿu ʿan̊hu, liạảnãhum̊ rafaḍūạ nāmūsa ٱllhi walam̊ yaḥ̊faẓūạ farāyỉḍahu, wāảḍalãt̊hum̊ ạảkādẖībuhumu ٱlãtī sāra ậbāwủhum̊ warāʾahā."],[2,5,"فَأُرْسِلُ نَارًا عَلَى يَهُوذَا فَتَأْكُلُ قُصُورَ أُورُشَلِيمَ».","fāủr̊silu nāraⁿạ ʿalay̱ yahūdẖā fatā̊̉kulu quṣūra ạủwrusẖalīma»."],[2,6,"هَكَذَا قَالَ ٱلرَّبُّ: «مِنْ أَجْلِ ذُنُوبِ إِسْرَائِيلَ ٱلثَّلَاثَةِ وَٱلْأَرْبَعَةِ لَا أَرْجِعُ عَنْهُ، لِأَنَّهُمْ بَاعُوا ٱلْبَارَّ بِٱلْفِضَّةِ، وَٱلْبَائِسَ لِأَجْلِ نَعْلَيْنِ.","hakadẖā qāla ٱlrãbũ: «min̊ ạảj̊li dẖunūbi ại̹s̊rāyỉyla ٱltẖãlātẖaẗi waٱl̊ạảr̊baʿaẗi lā ạảr̊jiʿu ʿan̊hu, liạảnãhum̊ bāʿūạ ٱl̊bārã biٱl̊fiḍãẗi, waٱl̊bāyỉsa liạảj̊li naʿ̊laẙni."],[2,7,"ٱلَّذِينَ يَتَهَمَّمُونَ تُرَابَ ٱلْأَرْضِ عَلَى رُؤُوسِ ٱلْمَسَاكِينِ، وَيَصُدُّونَ سَبِيلَ ٱلْبَائِسِينَ، وَيَذْهَبُ رَجُلٌ وَأَبُوهُ إِلَى صَبِيَّةٍ وَاحِدَةٍ حَتَّى يُدَنِّسُوا ٱسْمَ قُدْسِي.","ٱlãdẖīna yatahamãmūna turāba ٱl̊ạảr̊ḍi ʿalay̱ rūủwsi ٱl̊masākīni, wayaṣudũwna sabīla ٱl̊bāyỉsīna, wayadẖ̊habu rajuluⁿ wāảbūhu ại̹lay̱ ṣabīãẗiⁿ wāḥidaẗiⁿ ḥatãy̱ yudanĩsūạ ٱs̊ma qud̊sī."],[2,8,"وَيَتَمَدَّدُونَ عَلَى ثِيَابٍ مَرْهُونَةٍ بِجَانِبِ كُلِّ مَذْبَحٍ، وَيَشْرَبُونَ خَمْرَ ٱلْمُغَرَّمِينَ فِي بَيْتِ آلِهَتِهِمْ.","wayatamadãdūna ʿalay̱ tẖīābiⁿ mar̊hūnaẗiⁿ bijānibi kulĩ madẖ̊baḥiⁿ, wayasẖ̊rabūna kẖam̊ra ٱl̊mugẖarãmīna fī baẙti ậlihatihim̊."],[2,9,"«وَأَنَا قَدْ أَبَدْتُ مِنْ أَمَامِهِمِ ٱلْأَمُورِيَّ ٱلَّذِي قَامَتُهُ مِثْلُ قَامَةِ ٱلْأَرْزِ، وَهُوَ قَوِيٌّ كَٱلْبَلُّوطِ. أَبَدْتُ ثَمَرَهُ مِنْ فَوْقُ، وَأُصُولَهُ مِنْ تَحْتُ.","«wāảnā qad̊ ạảbad̊tu min̊ ạảmāmihimi ٱl̊ạảmūrīã ٱlãdẖī qāmatuhu mitẖ̊lu qāmaẗi ٱl̊ạảr̊zi, wahūa qawīuⁿ̃ kaٱl̊balũwṭi. ạảbad̊tu tẖamarahu min̊ faẘqu, wāủṣūlahu min̊ taḥ̊tu."],[2,10,"وَأَنَا أَصْعَدْتُكُمْ مِنْ أَرْضِ مِصْرَ وَسِرْتُ بِكُمْ فِي ٱلْبَرِّيَّةِ أَرْبَعِينَ سَنَةً لِتَرِثُوا أَرْضَ ٱلْأَمُورِيِّ.","wāảnā ạảṣ̊ʿad̊tukum̊ min̊ ạảr̊ḍi miṣ̊ra wasir̊tu bikum̊ fī ٱl̊barĩyãẗi ạảr̊baʿīna sanaẗaⁿ litaritẖūạ ạảr̊ḍa ٱl̊ạảmūrīĩ."],[2,11,"وَأَقَمْتُ مِنْ بَنِيكُمْ أَنْبِيَاءَ، وَمِنْ فِتْيَانِكُمْ نَذِيرِينَ. أَلَيْسَ هَكَذَا يَا بَنِي إِسْرَائِيلَ، يَقُولُ ٱلرَّبُّ؟","wāảqam̊tu min̊ banīkum̊ ạản̊bīāʾa, wamin̊ fit̊yānikum̊ nadẖīrīna. ạảlaẙsa hakadẖā yā banī ại̹s̊rāyỉyla, yaqūlu ٱlrãbũ?"],[2,12,"لَكِنَّكُمْ سَقَيْتُمُ ٱلنَّذِيرِينَ خَمْرًا، وَأَوْصَيْتُمُ ٱلْأَنْبِيَاءَ قَائِلِينَ: لَا تَتَنَبَّأُوا.","lakinãkum̊ saqaẙtumu ٱlnãdẖīrīna kẖam̊raⁿạ, wāảẘṣaẙtumu ٱl̊ạản̊bīāʾa qāyỉlīna: lā tatanabãạủwạ."],[2,13,"«هَأَنَذَا أَضْغَطُ مَا تَحْتَكُمْ كَمَا تَضْغَطُ ٱلْعَجَلَةُ ٱلْمَلْآنَةُ حِزَمًا.","«hāảnadẖā ạảḍ̊gẖaṭu mā taḥ̊takum̊ kamā taḍ̊gẖaṭu ٱl̊ʿajalaẗu ٱl̊mal̊ậnaẗu ḥizamaⁿạ."],[2,14,"وَيَبِيدُ ٱلْمَنَاصُ عَنِ ٱلسَّرِيعِ، وَٱلْقَوِيُّ لَا يُشَدِّدُ قُوَّتَهُ، وَٱلْبَطَلُ لَا يُنَجِّي نَفْسَهُ،","wayabīdu ٱl̊manāṣu ʿani ٱlsãrīʿi, waٱl̊qawīũ lā yusẖadĩdu qūãtahu, waٱl̊baṭalu lā yunajĩy naf̊sahu,"],[2,15,"وَمَاسِكُ ٱلْقَوْسِ لَا يَثْبُتُ، وَسَرِيعُ ٱلرِّجْلَيْنِ لَا يَنْجُو، وَرَاكِبُ ٱلْخَيْلِ لَا يُنَجِّي نَفْسَهُ.","wamāsiku ٱl̊qaẘsi lā yatẖ̊butu, wasarīʿu ٱlrĩj̊laẙni lā yan̊jū, warākibu ٱl̊kẖaẙli lā yunajĩy naf̊sahu."],[2,16,"وَٱلْقَوِيُّ ٱلْقَلْبِ بَيْنَ ٱلْأَبْطَالِ يَهْرُبُ عُرْيَانًا فِي ذَلِكَ ٱلْيَوْمِ، يَقُولُ ٱلرَّبُّ».","waٱl̊qawīũ ٱl̊qal̊bi baẙna ٱl̊ạảb̊ṭāli yah̊rubu ʿur̊yānaⁿạ fī dẖalika ٱl̊yaẘmi, yaqūlu ٱlrãbũ»."],[3,1,"اِسْمَعُوا هَذَا ٱلْقَوْلَ ٱلَّذِي تَكَلَّمَ بِهِ ٱلرَّبُّ عَلَيْكُمْ يَا بَنِي إِسْرَائِيلَ، عَلَى كُلِّ ٱلْقَبِيلَةِ ٱلَّتِي أَصْعَدْتُهَا مِنْ أَرْضِ مِصْرَ قَائِلًا:","ạis̊maʿūạ hadẖā ٱl̊qaẘla ٱlãdẖī takalãma bihi ٱlrãbũ ʿalaẙkum̊ yā banī ại̹s̊rāyỉyla, ʿalay̱ kulĩ ٱl̊qabīlaẗi ٱlãtī ạảṣ̊ʿad̊tuhā min̊ ạảr̊ḍi miṣ̊ra qāyỉlaⁿạ:"],[3,2,"«إِيَّاكُمْ فَقَطْ عَرَفْتُ مِنْ جَمِيعِ قَبَائِلِ ٱلْأَرْضِ، لِذَلِكَ أُعَاقِبُكُمْ عَلَى جَمِيعِ ذُنُوبِكُمْ».","«ại̹yãạkum̊ faqaṭ̊ ʿaraf̊tu min̊ jamīʿi qabāyỉli ٱl̊ạảr̊ḍi, lidẖalika ạủʿāqibukum̊ ʿalay̱ jamīʿi dẖunūbikum̊»."],[3,3,"هَلْ يَسِيرُ ٱثْنَانِ مَعًا إِنْ لَمْ يَتَوَاعَدَا؟","hal̊ yasīru ٱtẖ̊nāni maʿaⁿạ ại̹n̊ lam̊ yatawāʿadā?"],[3,4,"هَلْ يُزَمْجِرُ ٱلْأَسَدُ فِي ٱلْوَعْرِ وَلَيْسَ لَهُ فَرِيسَةٌ؟ هَلْ يُعْطِي شِبْلُ ٱلْأَسَدِ زَئِيرَهُ مِنْ خِدْرِهِ إِنْ لَمْ يَخْطَفْ؟","hal̊ yuzam̊jiru ٱl̊ạảsadu fī ٱl̊waʿ̊ri walaẙsa lahu farīsaẗuⁿ? hal̊ yuʿ̊ṭī sẖib̊lu ٱl̊ạảsadi zayỉyrahu min̊ kẖid̊rihi ại̹n̊ lam̊ yakẖ̊ṭaf̊?"],[3,5,"هَلْ يَسْقُطُ عُصْفُورٌ فِي فَخِّ ٱلْأَرْضِ وَلَيْسَ لَهُ شَرَكٌ؟ هَلْ يُرْفَعُ فَخٌّ عَنِ ٱلْأَرْضِ وَهُوَ لَمْ يُمْسِكْ شَيْئًا؟","hal̊ yas̊quṭu ʿuṣ̊fūruⁿ fī fakẖĩ ٱl̊ạảr̊ḍi walaẙsa lahu sẖarakuⁿ? hal̊ yur̊faʿu fakẖuⁿ̃ ʿani ٱl̊ạảr̊ḍi wahūa lam̊ yum̊sik̊ sẖaẙyaⁿ̉ạ?"],[3,6,"أَمْ يُضْرَبُ بِٱلْبُوقِ فِي مَدِينَةٍ وَٱلشَّعْبُ لَا يَرْتَعِدُ؟ هَلْ تَحْدُثُ بَلِيَّةٌ فِي مَدِينَةٍ وَٱلرَّبُّ لَمْ يَصْنَعْهَا؟","ạảm̊ yuḍ̊rabu biٱl̊būqi fī madīnaẗiⁿ waٱlsẖãʿ̊bu lā yar̊taʿidu? hal̊ taḥ̊dutẖu balīãẗuⁿ fī madīnaẗiⁿ waٱlrãbũ lam̊ yaṣ̊naʿ̊hā?"],[3,7,"إِنَّ ٱلسَّيِّدَ ٱلرَّبَّ لَا يَصْنَعُ أَمْرًا إِلَّا وَهُوَ يُعْلِنُ سِرَّهُ لِعَبِيدِهِ ٱلْأَنْبِيَاءِ.","ại̹nã ٱlsãyĩda ٱlrãbã lā yaṣ̊naʿu ạảm̊raⁿạ ại̹lãạ wahūa yuʿ̊linu sirãhu liʿabīdihi ٱl̊ạản̊bīāʾi."],[3,8,"ٱلْأَسَدُ قَدْ زَمْجَرَ، فَمَنْ لَا يَخَافُ؟ ٱلسَّيِّدُ ٱلرَّبُّ قَدْ تَكَلَّمَ، فَمَنْ لَا يَتَنَبَّأُ؟","ٱl̊ạảsadu qad̊ zam̊jara, faman̊ lā yakẖāfu? ٱlsãyĩdu ٱlrãbũ qad̊ takalãma, faman̊ lā yatanabãạủ?"],[3,9,"نَادُوا عَلَى ٱلْقُصُورِ فِي أَشْدُودَ، وَعَلَى ٱلْقُصُورِ فِي أَرْضِ مِصْرَ، وَقُولُوا: «ٱجْتَمِعُوا عَلَى جِبَالِ ٱلسَّامِرَةِ وَٱنْظُرُوا شَغْبًا عَظِيمًا فِي وَسَطِهَا وَمَظَالِمَ فِي دَاخِلِهَا.","nādūạ ʿalay̱ ٱl̊quṣūri fī ạảsẖ̊dūda, waʿalay̱ ٱl̊quṣūri fī ạảr̊ḍi miṣ̊ra, waqūlūạ: «ٱj̊tamiʿūạ ʿalay̱ jibāli ٱlsãạmiraẗi waٱn̊ẓurūạ sẖagẖ̊baⁿạ ʿaẓīmaⁿạ fī wasaṭihā wamaẓālima fī dākẖilihā."],[3,10,"فَإِنَّهُمْ لَا يَعْرِفُونَ أَنْ يَصْنَعُوا ٱلِٱسْتِقَامَةَ، يَقُولُ ٱلرَّبُّ. أُولَئِكَ ٱلَّذِينَ يَخْزِنُونَ ٱلظُّلْمَ وَٱلِٱغْتِصَابَ فِي قُصُورِهِمْ.","fāi̹nãhum̊ lā yaʿ̊rifūna ạản̊ yaṣ̊naʿūạ ٱliٱs̊tiqāmaẗa, yaqūlu ٱlrãbũ. ạủwlayỉka ٱlãdẖīna yakẖ̊zinūna ٱlẓũl̊ma waٱliٱgẖ̊tiṣāba fī quṣūrihim̊."],[3,11,"لِذَلِكَ هَكَذَا قَالَ ٱلسَّيِّدُ ٱلرَّبُّ: ضِيقٌ حَتَّى فِي كُلِّ نَاحِيَةٍ مِنَ ٱلْأَرْضِ، فَيُنْزِلَ عَنْكِ عِزَّكِ وَتُنْهَبُ قُصُورُكِ».","lidẖalika hakadẖā qāla ٱlsãyĩdu ٱlrãbũ: ḍīquⁿ ḥatãy̱ fī kulĩ nāḥīaẗiⁿ mina ٱl̊ạảr̊ḍi, fayun̊zila ʿan̊ki ʿizãki watun̊habu quṣūruki»."],[3,12,"هَكَذَا قَالَ ٱلرَّبُّ: «كَمَا يَنْزِعُ ٱلرَّاعِي مِنْ فَمِ ٱلْأَسَدِ كُرَاعَيْنِ أَوْ قِطْعَةَ أُذُنٍ، هَكَذَا يُنْتَزَعُ بَنُو إِسْرَائِيلَ ٱلْجَالِسُونَ في ٱلسَّامِرَةِ في زَاوِيَةِ ٱلسَّرِيرِ وَعَلَى دِمَقْسِ ٱلْفِرَاشِ!","hakadẖā qāla ٱlrãbũ: «kamā yan̊ziʿu ٱlrãạʿī min̊ fami ٱl̊ạảsadi kurāʿaẙni ạảẘ qiṭ̊ʿaẗa ạủdẖuniⁿ, hakadẖā yun̊tazaʿu banū ại̹s̊rāyỉyla ٱl̊jālisūna fy ٱlsãạmiraẗi fy zāwīaẗi ٱlsãrīri waʿalay̱ dimaq̊si ٱl̊firāsẖi!"],[3,13,"اِسْمَعُوا وَٱشْهَدُوا علَى بَيتِ يَعْقُوبَ، يَقُولُ ٱلسّيِّدُ ٱلرَّبُّ إِلَهُ ٱلْجُنُودِ.","ạis̊maʿūạ waٱsẖ̊hadūạ ʿlay̱ bayti yaʿ̊qūba, yaqūlu ٱls̃yĩdu ٱlrãbũ ại̹lahu ٱl̊junūdi."],[3,14,"إِنِّي يَوْمَ مُعَاقَبَتِي إِسْرَائِيلَ عَلَى ذُنُوبِهِ أُعَاقِبُ مَذَابِحَ بَيْتِ إِيلَ، فَتُقْطَعُ قُرُونُ ٱلْمَذْبَحِ وَتَسْقُطُ إِلَى ٱلْأَرْضِ.","ại̹nĩy yaẘma muʿāqabatī ại̹s̊rāyỉyla ʿalay̱ dẖunūbihi ạủʿāqibu madẖābiḥa baẙti ại̹yla, fatuq̊ṭaʿu qurūnu ٱl̊madẖ̊baḥi watas̊quṭu ại̹lay̱ ٱl̊ạảr̊ḍi."],[3,15,"وَأَضْرِبُ بَيْتَ ٱلشِّتَاءِ مَعَ بَيْتِ ٱلصَّيْفِ، فَتَبِيدُ بُيُوتُ ٱلْعَاجِ، وَتَضْمَحِلُّ ٱلْبُيُوتُ ٱلْعَظِيمَةُ، يَقُولُ ٱلرَّبُّ».","wāảḍ̊ribu baẙta ٱlsẖĩtāʾi maʿa baẙti ٱlṣãẙfi, fatabīdu buyūtu ٱl̊ʿāji, wataḍ̊maḥilũ ٱl̊buyūtu ٱl̊ʿaẓīmaẗu, yaqūlu ٱlrãbũ»."],[4,1,"اِسْمَعِي هَذَا ٱلْقَوْلَ يَا بَقَرَاتِ بَاشَانَ ٱلَّتِي فِي جَبَلِ ٱلسَّامِرَةِ، ٱلظَّالِمَةَ ٱلْمَسَاكِينِ، ٱلسَّاحِقَةَ ٱلْبَائِسِينَ، ٱلْقَائِلَةَ لِسَادَتِهَا: «هَاتِ لِنَشْرَبَ».","ạis̊maʿī hadẖā ٱl̊qaẘla yā baqarāti bāsẖāna ٱlãtī fī jabali ٱlsãạmiraẗi, ٱlẓãạlimaẗa ٱl̊masākīni, ٱlsãạḥiqaẗa ٱl̊bāyỉsīna, ٱl̊qāyỉlaẗa lisādatihā: «hāti linasẖ̊raba»."],[4,2,"قَدْ أَقْسَمَ ٱلسَّيِّدُ ٱلرَّبُّ بِقُدْسِهِ: «هُوَذَا أَيَّامٌ تَأْتِي عَلَيْكُنَّ، يَأْخُذُونَكُنَّ بِخَزَائِمَ، وَذُرِّيَّتَكُنَّ بِشُصُوصِ ٱلسَّمَكِ.","qad̊ ạảq̊sama ٱlsãyĩdu ٱlrãbũ biqud̊sihi: «hūadẖā ạảyãạmuⁿ tā̊̉tī ʿalaẙkunã, yā̊̉kẖudẖūnakunã bikẖazāyỉma, wadẖurĩyãtakunã bisẖuṣūṣi ٱlsãmaki."],[4,3,"وَمِنَ ٱلشُّقُوقِ تَخْرُجْنَ كُلُّ وَاحِدَةٍ عَلَى وَجْهِهَا، وَتَنْدَفِعْنَ إِلَى ٱلْحِصْنِ، يَقُولُ ٱلرَّبُّ.","wamina ٱlsẖũqūqi takẖ̊ruj̊na kulũ wāḥidaẗiⁿ ʿalay̱ waj̊hihā, watan̊dafiʿ̊na ại̹lay̱ ٱl̊ḥiṣ̊ni, yaqūlu ٱlrãbũ."],[4,4,"«هَلُمَّ إِلَى بَيْتِ إِيلَ، وَأَذْنِبُوا إِلَى ٱلْجِلْجَالِ، وَأَكْثِرُوا ٱلذُّنُوبَ، وَأَحْضِرُوا كُلَّ صَبَاحٍ ذَبَائِحَكُمْ، وَكُلَّ ثَلَاثَةِ أَيَّامٍ عُشُورَكُمْ.","«halumã ại̹lay̱ baẙti ại̹yla, wāảdẖ̊nibūạ ại̹lay̱ ٱl̊jil̊jāli, wāảk̊tẖirūạ ٱldẖũnūba, wāảḥ̊ḍirūạ kulã ṣabāḥiⁿ dẖabāyỉḥakum̊, wakulã tẖalātẖaẗi ạảyãạmiⁿ ʿusẖūrakum̊."],[4,5,"وَأَوْقِدُوا مِنَ ٱلْخَمِيرِ تَقْدِمَةَ شُكْرٍ، وَنَادُوا بِنَوَافِلَ وَسَمِّعُوا، لِأَنَّكُمْ هَكَذَا أَحْبَبْتُمْ يَا بَنِي إِسْرَائِيلَ، يَقُولُ ٱلسَّيِّدُ ٱلرَّبُّ.","wāảẘqidūạ mina ٱl̊kẖamīri taq̊dimaẗa sẖuk̊riⁿ, wanādūạ binawāfila wasamĩʿūạ, liạảnãkum̊ hakadẖā ạảḥ̊bab̊tum̊ yā banī ại̹s̊rāyỉyla, yaqūlu ٱlsãyĩdu ٱlrãbũ."],[4,6,"«وَأَنَا أَيْضًا أَعْطَيْتُكُمْ نَظَافَةَ ٱلْأَسْنَانِ فِي جَمِيعِ مُدُنِكُمْ، وَعَوَزَ ٱلْخُبْزِ فِي جَمِيعِ أَمَاكِنِكُمْ، فَلَمْ تَرْجِعُوا إِلَيَّ، يَقُولُ ٱلرَّبُّ.","«wāảnā ạảẙḍaⁿạ ạảʿ̊ṭaẙtukum̊ naẓāfaẗa ٱl̊ạảs̊nāni fī jamīʿi mudunikum̊, waʿawaza ٱl̊kẖub̊zi fī jamīʿi ạảmākinikum̊, falam̊ tar̊jiʿūạ ại̹layã, yaqūlu ٱlrãbũ."],[4,7,"وَأَنَا أَيْضًا مَنَعْتُ عَنْكُمُ ٱلْمَطَرَ إِذْ بَقِيَ ثَلَاثَةُ أَشْهُرٍ لِلْحَصَادِ، وَأَمْطَرْتُ عَلَى مَدِينَةٍ وَاحِدَةٍ، وَعَلَى مَدِينَةٍ أُخْرَى لَمْ أُمْطِرْ. أُمْطِرَ عَلَى ضَيْعَةٍ وَاحِدَةٍ، وَٱلضَّيْعَةُ ٱلَّتِي لَمْ يُمْطَرْ عَلَيْهَا جَفَّتْ.","wāảnā ạảẙḍaⁿạ manaʿ̊tu ʿan̊kumu ٱl̊maṭara ại̹dẖ̊ baqīa tẖalātẖaẗu ạảsẖ̊huriⁿ lil̊ḥaṣādi, wāảm̊ṭar̊tu ʿalay̱ madīnaẗiⁿ wāḥidaẗiⁿ, waʿalay̱ madīnaẗiⁿ ạủkẖ̊ray̱ lam̊ ạủm̊ṭir̊. ạủm̊ṭira ʿalay̱ ḍaẙʿaẗiⁿ wāḥidaẗiⁿ, waٱlḍãẙʿaẗu ٱlãtī lam̊ yum̊ṭar̊ ʿalaẙhā jafãt̊."],[4,8,"فَجَالَتْ مَدِينَتَانِ أَوْ ثَلَاثٌ إِلَى مَدِينَةٍ وَاحِدَةٍ لِتَشْرَبَ مَاءً وَلَمْ تَشْبَعْ، فَلَمْ تَرْجِعُوا إِلَيَّ، يَقُولُ ٱلرَّبُّ.","fajālat̊ madīnatāni ạảẘ tẖalātẖuⁿ ại̹lay̱ madīnaẗiⁿ wāḥidaẗiⁿ litasẖ̊raba māʾaⁿ walam̊ tasẖ̊baʿ̊, falam̊ tar̊jiʿūạ ại̹layã, yaqūlu ٱlrãbũ."],[4,9,"ضَرْبَتُكُمْ بِٱللَّفْحِ وَٱلْيَرَقَانِ. كَثِيرًا مَا أَكَلَ ٱلْقَمَصُ جَنَّاتِكُمْ وَكُرُومَكُمْ وَتِينَكُمْ وَزَيْتُونَكُمْ، فَلَمْ تَرْجِعُوا إِلَيَّ، يَقُولُ ٱلرَّبُّ.","ḍar̊batukum̊ biٱllãf̊ḥi waٱl̊yaraqāni. katẖīraⁿạ mā ạảkala ٱl̊qamaṣu janãạtikum̊ wakurūmakum̊ watīnakum̊ wazaẙtūnakum̊, falam̊ tar̊jiʿūạ ại̹layã, yaqūlu ٱlrãbũ."],[4,10,"أَرْسَلْتُ بَيْنَكُمْ وَبَأً عَلَى طَرِيقَةِ مِصْرَ. قَتَلْتُ بِٱلسَّيْفِ فِتْيَانَكُمْ مَعَ سَبْيِ خَيْلِكُمْ، وَأَصْعَدْتُ نَتْنَ مَحَالِّكُمْ حَتَّى إِلَى أُنُوفِكُمْ، فَلَمْ تَرْجِعُوا إِلَيَّ، يَقُولُ ٱلرَّبُّ.","ạảr̊sal̊tu baẙnakum̊ wabāaⁿ̉ ʿalay̱ ṭarīqaẗi miṣ̊ra. qatal̊tu biٱlsãẙfi fit̊yānakum̊ maʿa sab̊yi kẖaẙlikum̊, wāảṣ̊ʿad̊tu nat̊na maḥālĩkum̊ ḥatãy̱ ại̹lay̱ ạủnūfikum̊, falam̊ tar̊jiʿūạ ại̹layã, yaqūlu ٱlrãbũ."],[4,11,"قَلَبْتُ بَعْضَكُمْ كَمَا قَلَبَ ٱللهُ سَدُومَ وَعَمُورَةَ، فَصِرْتُمْ كَشُعْلَةٍ مُنْتَشَلَةٍ مِنَ ٱلْحَرِيقِ، فَلَمْ تَرْجِعُوا إِلَيَّ، يَقُولُ ٱلرَّبُّ.","qalab̊tu baʿ̊ḍakum̊ kamā qalaba ٱllhu sadūma waʿamūraẗa, faṣir̊tum̊ kasẖuʿ̊laẗiⁿ mun̊tasẖalaẗiⁿ mina ٱl̊ḥarīqi, falam̊ tar̊jiʿūạ ại̹layã, yaqūlu ٱlrãbũ."],[4,12,"«لِذَلِكَ هَكَذَا أَصْنَعُ بِكَ يَا إِسْرَائِيلُ. فَمِنْ أَجْلِ أَنِّي أَصْنَعُ بِكَ هَذَا، فَٱسْتَعِدَّ لِلِقَاءِ إِلَهِكَ يَا إِسْرَائِيلُ».","«lidẖalika hakadẖā ạảṣ̊naʿu bika yā ại̹s̊rāyỉylu. famin̊ ạảj̊li ạảnĩy ạảṣ̊naʿu bika hadẖā, faٱs̊taʿidã liliqāʾi ại̹lahika yā ại̹s̊rāyỉylu»."],[4,13,"فَإِنَّهُ هُوَذَا ٱلَّذِي صَنَعَ ٱلْجِبَالَ وَخَلَقَ ٱلرِّيحَ وَأَخْبَرَ ٱلْإِنْسَانَ مَا هُوَ فِكْرُهُ، ٱلَّذِي يَجْعَلُ ٱلْفَجْرَ ظَلَامًا، وَيَمْشِي عَلَى مَشَارِفِ ٱلْأَرْضِ، يَهْوَهُ إِلَهُ ٱلْجُنُودِ ٱسْمُهُ.","fāi̹nãhu hūadẖā ٱlãdẖī ṣanaʿa ٱl̊jibāla wakẖalaqa ٱlrĩyḥa wāảkẖ̊bara ٱl̊ại̹n̊sāna mā hūa fik̊ruhu, ٱlãdẖī yaj̊ʿalu ٱl̊faj̊ra ẓalāmaⁿạ, wayam̊sẖī ʿalay̱ masẖārifi ٱl̊ạảr̊ḍi, yah̊wahu ại̹lahu ٱl̊junūdi ٱs̊muhu."],[5,1,"اِسْمَعُوا هَذَا ٱلْقَوْلَ ٱلَّذِي أَنَا أُنَادِي بِهِ عَلَيْكُمْ، مَرْثَاةً يَا بَيْتَ إِسْرَائِيلَ:","ạis̊maʿūạ hadẖā ٱl̊qaẘla ٱlãdẖī ạảnā ạủnādī bihi ʿalaẙkum̊, mar̊tẖāẗaⁿ yā baẙta ại̹s̊rāyỉyla:"],[5,2,"«سَقَطَتْ عَذْرَاءُ إِسْرَائِيلَ. لَا تَعُودُ تَقُومُ. ٱنْطَرَحَتْ عَلَى أَرْضِهَا لَيْسَ مَنْ يُقِيمُهَا».","«saqaṭat̊ ʿadẖ̊rāʾu ại̹s̊rāyỉyla. lā taʿūdu taqūmu. ٱn̊ṭaraḥat̊ ʿalay̱ ạảr̊ḍihā laẙsa man̊ yuqīmuhā»."],[5,3,"لِأَنَّهُ هَكَذَا قَالَ ٱلسَّيِّدُ ٱلرَّبُّ: «ٱلْمَدِينَةُ ٱلْخَارِجَةُ بِأَلْفٍ، يَبْقَى لَهَا مِئَةٌ، وَٱلْخَارِجَةُ بِمِئَةٍ يَبْقَى لَهَا عَشَرَةٌ مِنْ بَيْتِ إِسْرَائِيلَ».","liạảnãhu hakadẖā qāla ٱlsãyĩdu ٱlrãbũ: «ٱl̊madīnaẗu ٱl̊kẖārijaẗu biạảl̊fiⁿ, yab̊qay̱ lahā mīảẗuⁿ, waٱl̊kẖārijaẗu bimīảẗiⁿ yab̊qay̱ lahā ʿasẖaraẗuⁿ min̊ baẙti ại̹s̊rāyỉyla»."],[5,4,"لِأَنَّهُ هَكَذَا قَالَ ٱلرَّبُّ لِبَيْتِ إِسْرَائِيلَ: «ٱطْلُبُوا فَتَحْيَوْا.","liạảnãhu hakadẖā qāla ٱlrãbũ libaẙti ại̹s̊rāyỉyla: «ٱṭ̊lubūạ fataḥ̊yaẘạ."],[5,5,"وَلَا تَطْلُبُوا بَيْتَ إِيلَ، وَإِلَى ٱلْجِلْجَالِ لَا تَذْهَبُوا، وَإِلَى بِئْرَ سَبْعٍ لَا تَعْبُرُوا. لِأَنَّ ٱلْجِلْجَالَ تُسْبَى سَبْيًا، وَبَيْتَ إِيلَ تَصِيرُ عَدَمًا».","walā taṭ̊lubūạ baẙta ại̹yla, wāi̹lay̱ ٱl̊jil̊jāli lā tadẖ̊habūạ, wāi̹lay̱ bī̊̉ra sab̊ʿiⁿ lā taʿ̊burūạ. liạảnã ٱl̊jil̊jāla tus̊bay̱ sab̊yaⁿạ, wabaẙta ại̹yla taṣīru ʿadamaⁿạ»."],[5,6,"اُطْلُبُوا ٱلرَّبَّ فَتَحْيَوْا لِئَلَّا يَقْتَحِمَ بَيْتَ يُوسُفَ كَنَارٍ تُحْرِقُ، وَلَا يَكُونُ مَنْ يُطْفِئُهَا مِنْ بَيْتِ إِيلَ.","ạuṭ̊lubūạ ٱlrãbã fataḥ̊yaẘạ līảlãạ yaq̊taḥima baẙta yūsufa kanāriⁿ tuḥ̊riqu, walā yakūnu man̊ yuṭ̊fīủhā min̊ baẙti ại̹yla."],[5,7,"يَا أَيُّهَا ٱلَّذِينَ يُحَوِّلُونَ ٱلْحَقَّ أَفْسَنْتِينًا، وَيُلْقُونَ ٱلْبِرَّ إِلَى ٱلْأَرْضِ.","yā ạảyũhā ٱlãdẖīna yuḥawĩlūna ٱl̊ḥaqã ạảf̊san̊tīnaⁿạ, wayul̊qūna ٱl̊birã ại̹lay̱ ٱl̊ạảr̊ḍi."],[5,8,"اَلَّذِي صَنَعَ ٱلثُّرَيَّا وَٱلْجَبَّارَ، وَيُحَوِّلُ ظِلَّ ٱلْمَوْتِ صُبْحًا، وَيُظْلِمُ ٱلنَّهَارَ كَٱللَّيْلِ. ٱلَّذِي يَدْعُو مِيَاهَ ٱلْبَحْرِ وَيَصُبُّهَا عَلَى وَجْهِ ٱلْأَرْضِ، يَهْوَهُ ٱسْمُهُ.","ạalãdẖī ṣanaʿa ٱltẖũrayãạ waٱl̊jabãạra, wayuḥawĩlu ẓilã ٱl̊maẘti ṣub̊ḥaⁿạ, wayuẓ̊limu ٱlnãhāra kaٱllãẙli. ٱlãdẖī yad̊ʿū mīāha ٱl̊baḥ̊ri wayaṣubũhā ʿalay̱ waj̊hi ٱl̊ạảr̊ḍi, yah̊wahu ٱs̊muhu."],[5,9,"ٱلَّذِي يُفْلِحُ ٱلْخَرِبَ عَلَى ٱلْقَوِيِّ، فَيَأْتِي ٱلْخَرِبُ عَلَى ٱلْحِصْنِ.","ٱlãdẖī yuf̊liḥu ٱl̊kẖariba ʿalay̱ ٱl̊qawīĩ, fayā̊̉tī ٱl̊kẖaribu ʿalay̱ ٱl̊ḥiṣ̊ni."],[5,10,"إِنَّهُمْ فِي ٱلْبَابِ يُبْغِضُونَ ٱلْمُنْذِرَ، وَيَكْرَهُونَ ٱلْمُتَكَلِّمَ بِٱلصِّدْقِ.","ại̹nãhum̊ fī ٱl̊bābi yub̊gẖiḍūna ٱl̊mun̊dẖira, wayak̊rahūna ٱl̊mutakalĩma biٱlṣĩd̊qi."],[5,11,"لِذَلِكَ مِنْ أَجْلِ أَنَّكُمْ تَدُوسُونَ ٱلْمِسْكِينَ، وَتَأْخُذُونَ مِنْهُ هَدِيَّةَ قَمْحٍ، بَنَيْتُمْ بُيُوتًا مِنْ حِجَارَةٍ مَنْحُوتَةٍ وَلَا تَسْكُنُونَ فِيهَا، وَغَرَسْتُمْ كُرُومًا شَهِيَّةً وَلَا تَشْرَبُونَ خَمْرَهَا.","lidẖalika min̊ ạảj̊li ạảnãkum̊ tadūsūna ٱl̊mis̊kīna, watā̊̉kẖudẖūna min̊hu hadīãẗa qam̊ḥiⁿ, banaẙtum̊ buyūtaⁿạ min̊ ḥijāraẗiⁿ man̊ḥūtaẗiⁿ walā tas̊kunūna fīhā, wagẖaras̊tum̊ kurūmaⁿạ sẖahīãẗaⁿ walā tasẖ̊rabūna kẖam̊rahā."],[5,12,"لِأَنِّي عَلِمْتُ أَنَّ ذُنُوبَكُمْ كَثِيرَةٌ وَخَطَايَاكُمْ وَافِرَةٌ أَيُّهَا ٱلْمُضَايِقُونَ ٱلْبَارَّ، ٱلْآخِذُونَ ٱلرَّشْوَةَ، ٱلصَّادُّونَ ٱلْبَائِسِينَ فِي ٱلْبَابِ.","liạảnĩy ʿalim̊tu ạảnã dẖunūbakum̊ katẖīraẗuⁿ wakẖaṭāyākum̊ wāfiraẗuⁿ ạảyũhā ٱl̊muḍāyiqūna ٱl̊bārã, ٱl̊ậkẖidẖūna ٱlrãsẖ̊waẗa, ٱlṣãạdũwna ٱl̊bāyỉsīna fī ٱl̊bābi."],[5,13,"لِذَلِكَ يَصْمُتُ ٱلْعَاقِلُ فِي ذَلِكَ ٱلزَّمَانِ لِأَنَّهُ زَمَانٌ رَدِيءٌ.","lidẖalika yaṣ̊mutu ٱl̊ʿāqilu fī dẖalika ٱlzãmāni liạảnãhu zamānuⁿ radīʾuⁿ."],[5,14,"اُطْلُبُوا ٱلْخَيْرَ لَا ٱلشَّرَّ لِكَىْ تَحْيَوْا، فَعَلَى هَذَا يَكُونُ ٱلرَّبُّ إِلَهُ ٱلْجُنُودِ مَعَكُمْ كَمَا قُلْتُمْ.","ạuṭ̊lubūạ ٱl̊kẖaẙra lā ٱlsẖãrã likaẙ̱ taḥ̊yaẘạ, faʿalay̱ hadẖā yakūnu ٱlrãbũ ại̹lahu ٱl̊junūdi maʿakum̊ kamā qul̊tum̊."],[5,15,"اُبْغُضُوا ٱلشَّرَّ، وَأَحِبُّوا ٱلْخَيْرَ، وَثَبِّتُوا ٱلْحَقَّ فِي ٱلْبَابِ، لَعَلَّ ٱلرَّبَّ إِلَهَ ٱلْجُنُودِ يَتَرَاءَفُ عَلَى بَقِيَّةِ يُوسُفَ.","ạub̊gẖuḍūạ ٱlsẖãrã, wāảḥibũwạ ٱl̊kẖaẙra, watẖabĩtūạ ٱl̊ḥaqã fī ٱl̊bābi, laʿalã ٱlrãbã ại̹laha ٱl̊junūdi yatarāʾafu ʿalay̱ baqīãẗi yūsufa."],[5,16,"لِذَلِكَ هَكَذَا قَالَ ٱلسَّيِّدُ ٱلرَّبُّ إِلَهُ ٱلْجُنُودِ: «فِي جَمِيعِ ٱلْأَسْوَاقِ نَحِيبٌ، وَفِي جَمِيعِ ٱلْأَزِقَّةِ يَقُولُونَ: آهِ! آهِ! وَيَدْعُونَ ٱلْفَلَّاحَ إِلَى ٱلنَّوْحِ، وَجَمِيعَ عَارِفِي ٱلرِّثَاءِ لِلنَّدْبِ.","lidẖalika hakadẖā qāla ٱlsãyĩdu ٱlrãbũ ại̹lahu ٱl̊junūdi: «fī jamīʿi ٱl̊ạảs̊wāqi naḥībuⁿ, wafī jamīʿi ٱl̊ạảziqãẗi yaqūlūna: ậhi! ậhi! wayad̊ʿūna ٱl̊falãạḥa ại̹lay̱ ٱlnãẘḥi, wajamīʿa ʿārifī ٱlrĩtẖāʾi lilnãd̊bi."],[5,17,"وَفِي جَمِيعِ ٱلْكُرُومِ نَدْبٌ، لِأَنِّي أَعْبُرُ فِي وَسَطِكَ، قَالَ ٱلرَّبُّ».","wafī jamīʿi ٱl̊kurūmi nad̊buⁿ, liạảnĩy ạảʿ̊buru fī wasaṭika, qāla ٱlrãbũ»."],[5,18,"وَيْلٌ لِلَّذِينَ يَشْتَهُونَ يَوْمَ ٱلرَّبِّ! لِمَاذَا لَكُمْ يَوْمُ ٱلرَّبِّ؟ هُوَ ظَلَامٌ لَا نُورٌ.","waẙluⁿ lilãdẖīna yasẖ̊tahūna yaẘma ٱlrãbĩ! limādẖā lakum̊ yaẘmu ٱlrãbĩ? hūa ẓalāmuⁿ lā nūruⁿ."],[5,19,"كَمَا إِذَا هَرَبَ إِنْسَانٌ مِنْ أَمَامِ ٱلْأَسَدِ فَصَادَفَهُ ٱلدُّبُّ، أَوْ دَخَلَ ٱلْبَيْتَ وَوَضَعَ يَدَهُ عَلَى ٱلْحَائِطِ فَلَدَغَتْهُ ٱلْحَيَّةُ!","kamā ại̹dẖā haraba ại̹n̊sānuⁿ min̊ ạảmāmi ٱl̊ạảsadi faṣādafahu ٱldũbũ, ạảẘ dakẖala ٱl̊baẙta wawaḍaʿa yadahu ʿalay̱ ٱl̊ḥāyỉṭi faladagẖat̊hu ٱl̊ḥayãẗu!"],[5,20,"أَلَيْسَ يَوْمُ ٱلرَّبِّ ظَلَامًا لَا نُورًا، وَقَتَامًا وَلَا نُورَ لَهُ؟","ạảlaẙsa yaẘmu ٱlrãbĩ ẓalāmaⁿạ lā nūraⁿạ, waqatāmaⁿạ walā nūra lahu?"],[5,21,"«بَغَضْتُ، كَرِهْتُ أَعْيَادَكُمْ، وَلَسْتُ أَلْتَذُّ بِٱعْتِكَافَاتِكُمْ.","«bagẖaḍ̊tu, karih̊tu ạảʿ̊yādakum̊, walas̊tu ạảl̊tadẖũ biٱʿ̊tikāfātikum̊."],[5,22,"إِنِّي إِذَا قَدَّمْتُمْ لِي مُحْرَقَاتِكُمْ وَتَقْدِمَاتِكُمْ لَا أَرْتَضِي، وَذَبَائِحَ ٱلسَّلَامَةِ مِنْ مُسَمَّنَاتِكُمْ لَا أَلْتَفِتُ إِلَيْهَا.","ại̹nĩy ại̹dẖā qadãm̊tum̊ lī muḥ̊raqātikum̊ wataq̊dimātikum̊ lā ạảr̊taḍī, wadẖabāyỉḥa ٱlsãlāmaẗi min̊ musamãnātikum̊ lā ạảl̊tafitu ại̹laẙhā."],[5,23,"أَبْعِدْ عَنِّي ضَجَّةَ أَغَانِيكَ، وَنَغْمَةَ رَبَابِكَ لَا أَسْمَعُ.","ạảb̊ʿid̊ ʿanĩy ḍajãẗa ạảgẖānīka, wanagẖ̊maẗa rabābika lā ạảs̊maʿu."],[5,24,"وَلْيَجْرِ ٱلْحَقُّ كَٱلْمِيَاهِ، وَٱلْبِرُّ كَنَهْرٍ دَائِمٍ.","wal̊yaj̊ri ٱl̊ḥaqũ kaٱl̊mīāhi, waٱl̊birũ kanah̊riⁿ dāyỉmiⁿ."],[5,25,"«هَلْ قَدَّمْتُمْ لِي ذَبَائِحَ وَتَقْدِمَاتٍ فِي ٱلْبَرِّيَّةِ أَرْبَعِينَ سَنَةً يَا بَيْتَ إِسْرَائِيلَ؟","«hal̊ qadãm̊tum̊ lī dẖabāyỉḥa wataq̊dimātiⁿ fī ٱl̊barĩyãẗi ạảr̊baʿīna sanaẗaⁿ yā baẙta ại̹s̊rāyỉyla?"],[5,26,"بَلْ حَمَلْتُمْ خَيْمَةَ مَلْكُومِكُمْ، وَتِمْثَالَ أَصْنَامِكُمْ، نَجْمَ إِلَهِكُمُ ٱلَّذِي صَنَعْتُمْ لِنُفُوسِكُمْ.","bal̊ ḥamal̊tum̊ kẖaẙmaẗa mal̊kūmikum̊, watim̊tẖāla ạảṣ̊nāmikum̊, naj̊ma ại̹lahikumu ٱlãdẖī ṣanaʿ̊tum̊ linufūsikum̊."],[5,27,"فَأَسْبِيكُمْ إِلَى مَا وَرَاءَ دِمَشْقَ، قَالَ ٱلرَّبُّ إِلَهُ ٱلْجُنُودِ ٱسْمُهُ».","fāảs̊bīkum̊ ại̹lay̱ mā warāʾa dimasẖ̊qa, qāla ٱlrãbũ ại̹lahu ٱl̊junūdi ٱs̊muhu»."],[6,1,"وَيْلٌ لِلْمُسْتَرِيحِينَ فِي صِهْيَوْنَ، وَٱلْمُطْمَئِنِّينَ فِي جَبَلِ ٱلسَّامِرَةِ، نُقَبَاءِ أَوَّلِ ٱلْأُمَمِ. يَأْتِي إِلَيْهِمْ بَيْتُ إِسْرَائِيلَ.","waẙluⁿ lil̊mus̊tarīḥīna fī ṣih̊yaẘna, waٱl̊muṭ̊mayỉnĩyna fī jabali ٱlsãạmiraẗi, nuqabāʾi ạảwãli ٱl̊ạủmami. yā̊̉tī ại̹laẙhim̊ baẙtu ại̹s̊rāyỉyla."],[6,2,"اُعْبُرُوا إِلَى كَلْنَةَ وَٱنْظُرُوا، وَٱذْهَبُوا مِنْ هُنَاكَ إِلَى حَمَاةَ ٱلْعَظِيمَةِ، ثُمَّ ٱنْزِلُوا إِلَى جَتِّ ٱلْفِلِسْطِينِيِّينَ. أَهِيَ أَفْضَلُ مِنْ هَذِهِ ٱلْمَمَالِكِ، أَمْ تُخُمُهُمْ أَوْسَعُ مِنْ تُخُمِكُمْ؟","ạuʿ̊burūạ ại̹lay̱ kal̊naẗa waٱn̊ẓurūạ, waٱdẖ̊habūạ min̊ hunāka ại̹lay̱ ḥamāẗa ٱl̊ʿaẓīmaẗi, tẖumã ٱn̊zilūạ ại̹lay̱ jatĩ ٱl̊filis̊ṭīnīĩyna. ạảhīa ạảf̊ḍalu min̊ hadẖihi ٱl̊mamāliki, ạảm̊ tukẖumuhum̊ ạảẘsaʿu min̊ tukẖumikum̊?"],[6,3,"أَنْتُمُ ٱلَّذِينَ تُبْعِدُونَ يَوْمَ ٱلْبَلِيَّةِ وَتُقَرِّبُونَ مَقْعَدَ ٱلظُّلْمِ،","ạản̊tumu ٱlãdẖīna tub̊ʿidūna yaẘma ٱl̊balīãẗi watuqarĩbūna maq̊ʿada ٱlẓũl̊mi,"],[6,4,"ٱلْمُضْطَجِعُونَ عَلَى أَسِرَّةٍ مِنَ ٱلْعَاجِ، وَٱلْمُتَمَدِّدُونَ عَلَى فُرُشِهِمْ، وَٱلْآكِلُونَ خِرَافًا مِنَ ٱلْغَنَمِ، وَعُجُولًا مِنْ وَسَطِ ٱلصِّيَرةِ،","ٱl̊muḍ̊ṭajiʿūna ʿalay̱ ạảsirãẗiⁿ mina ٱl̊ʿāji, waٱl̊mutamadĩdūna ʿalay̱ furusẖihim̊, waٱl̊ậkilūna kẖirāfaⁿạ mina ٱl̊gẖanami, waʿujūlaⁿạ min̊ wasaṭi ٱlṣĩyarẗi,"],[6,5,"ٱلْهَاذِرُونَ مَعَ صَوْتِ ٱلرَّبَابِ، ٱلْمُخْتَرِعُونَ لِأَنْفُسِهِمْ آلَاتِ ٱلْغِنَاءِ كَدَاوُدَ،","ٱl̊hādẖirūna maʿa ṣaẘti ٱlrãbābi, ٱl̊mukẖ̊tariʿūna liạản̊fusihim̊ ậlāti ٱl̊gẖināʾi kadāwuda,"],[6,6,"ٱلشَّارِبُونَ مِنْ كُؤُوسِ ٱلْخَمْرِ، وَٱلَّذِينَ يَدَّهِنُونَ بِأَفْضَلِ ٱلْأَدْهَانِ وَلَا يَغْتَمُّونَ عَلَى ٱنْسِحَاقِ يُوسُفَ.","ٱlsẖãạribūna min̊ kūủwsi ٱl̊kẖam̊ri, waٱlãdẖīna yadãhinūna biạảf̊ḍali ٱl̊ạảd̊hāni walā yagẖ̊tamũwna ʿalay̱ ٱn̊siḥāqi yūsufa."],[6,7,"لِذَلِكَ ٱلْآنَ يُسْبَوْنَ فِي أَوَّلِ ٱلْمَسْبِيِّينَ، وَيَزُولُ صِيَاحُ ٱلْمُتَمَدِّدِينَ.","lidẖalika ٱl̊ậna yus̊baẘna fī ạảwãli ٱl̊mas̊bīĩyna, wayazūlu ṣīāḥu ٱl̊mutamadĩdīna."],[6,8,"قَدْ أَقْسَمَ ٱلسَّيِّدُ ٱلرَّبُّ بِنَفْسِهِ، يَقُولُ ٱلرَّبُّ إِلَهُ ٱلْجُنُودِ: «إِنِّي أَكْرَهُ عَظَمَةَ يَعْقُوبَ وَأُبْغِضُ قُصُورَهُ، فَأُسَلِّمُ ٱلْمَدِينَةَ وَمِلْأَهَا».","qad̊ ạảq̊sama ٱlsãyĩdu ٱlrãbũ binaf̊sihi, yaqūlu ٱlrãbũ ại̹lahu ٱl̊junūdi: «ại̹nĩy ạảk̊rahu ʿaẓamaẗa yaʿ̊qūba wāủb̊gẖiḍu quṣūrahu, fāủsalĩmu ٱl̊madīnaẗa wamil̊ạảhā»."],[6,9,"فَيَكُونُ إِذَا بَقِيَ عَشَرَةُ رِجَالٍ فِي بَيْتٍ وَاحِدٍ أَنَّهُمْ يَمُوتُونَ.","fayakūnu ại̹dẖā baqīa ʿasẖaraẗu rijāliⁿ fī baẙtiⁿ wāḥidiⁿ ạảnãhum̊ yamūtūna."],[6,10,"وَإِذَا حَمَلَ أَحَدًا عَمُّهُ وَمُحْرِقُهُ لِيُخْرِجَ ٱلْعِظَامَ مِنَ ٱلْبَيْتِ، وَقَالَ لِمَنْ هُوَ فِي جَوَانِبِ ٱلْبَيْتِ: «أَعِنْدَكَ بَعْدُ؟» يَقُولُ: «لَيْسَ بَعْدُ». فَيَقُولُ: «ٱسْكُتْ، فَإِنَّهُ لَا يُذْكَرُ ٱسْمُ ٱلرَّبِّ».","wāi̹dẖā ḥamala ạảḥadaⁿạ ʿamũhu wamuḥ̊riquhu līukẖ̊rija ٱl̊ʿiẓāma mina ٱl̊baẙti, waqāla liman̊ hūa fī jawānibi ٱl̊baẙti: «ạảʿin̊daka baʿ̊du?» yaqūlu: «laẙsa baʿ̊du». fayaqūlu: «ٱs̊kut̊, fāi̹nãhu lā yudẖ̊karu ٱs̊mu ٱlrãbĩ»."],[6,11,"لِأَنَّهُ هُوَذَا ٱلرَّبُّ يَأْمُرُ فَيَضْرِبُ ٱلْبَيْتَ ٱلْكَبِيرَ رَدْمًا، وَٱلْبَيْتَ ٱلصَّغِيرَ شُقُوقًا.","liạảnãhu hūadẖā ٱlrãbũ yā̊̉muru fayaḍ̊ribu ٱl̊baẙta ٱl̊kabīra rad̊maⁿạ, waٱl̊baẙta ٱlṣãgẖīra sẖuqūqaⁿạ."],[6,12,"هَلْ تَرْكُضُ ٱلْخَيْلُ عَلَى ٱلصَّخْرِ؟ أَوْ يُحْرَثُ عَلَيْهِ بِٱلْبَقَرِ؟ حَتَّى حَوَّلْتُمُ ٱلْحَقَّ سَمًّا، وَثَمَرَ ٱلْبِرِّ أَفْسَنْتِينًا.","hal̊ tar̊kuḍu ٱl̊kẖaẙlu ʿalay̱ ٱlṣãkẖ̊ri? ạảẘ yuḥ̊ratẖu ʿalaẙhi biٱl̊baqari? ḥatãy̱ ḥawãl̊tumu ٱl̊ḥaqã samaⁿ̃ạ, watẖamara ٱl̊birĩ ạảf̊san̊tīnaⁿạ."],[6,13,"أَنْتُمُ ٱلْفَرِحُونَ بِٱلْبُطْلِ، ٱلْقَائِلُونَ: «أَلَيْسَ بِقُوَّتِنَا ٱتَّخَذْنَا لِأَنْفُسِنَا قُرُونًا؟»","ạản̊tumu ٱl̊fariḥūna biٱl̊buṭ̊li, ٱl̊qāyỉlūna: «ạảlaẙsa biqūãtinā ٱtãkẖadẖ̊nā liạản̊fusinā qurūnaⁿạ?»"],[6,14,"«لِأَنِّي هَأَنَذَا أُقِيمُ عَلَيْكُمْ يَا بَيْتَ إِسْرَائِيلَ، يَقُولُ ٱلرَّبُّ إِلَهُ ٱلْجُنُودِ، أُمَّةً فَيُضَايِقُونَكُمْ مِنْ مَدْخَلِ حَمَاةَ إِلَى وَادِي ٱلْعَرَبَةِ».","«liạảnĩy hāảnadẖā ạủqīmu ʿalaẙkum̊ yā baẙta ại̹s̊rāyỉyla, yaqūlu ٱlrãbũ ại̹lahu ٱl̊junūdi, ạủmãẗaⁿ fayuḍāyiqūnakum̊ min̊ mad̊kẖali ḥamāẗa ại̹lay̱ wādī ٱl̊ʿarabaẗi»."],[7,1,"هَكَذَا أَرَانِي ٱلسَّيِّدُ ٱلرَّبُّ وَإِذَا هُوَ يَصْنَعُ جَرَادًا فِي أَوَّلِ طُلُوعِ خِلْفِ ٱلْعُشْبِ. وَإِذَا خِلْفُ عُشْبٍ بَعْدَ جِزَازِ ٱلْمَلِكِ.","hakadẖā ạảrānī ٱlsãyĩdu ٱlrãbũ wāi̹dẖā hūa yaṣ̊naʿu jarādaⁿạ fī ạảwãli ṭulūʿi kẖil̊fi ٱl̊ʿusẖ̊bi. wāi̹dẖā kẖil̊fu ʿusẖ̊biⁿ baʿ̊da jizāzi ٱl̊maliki."],[7,2,"وَحَدَثَ لَمَّا فَرَغَ مِنْ أَكْلِ عُشْبِ ٱلْأَرْضِ أَنِّي قُلْتُ: «أَيُّهَا ٱلسَّيِّدُ ٱلرَّبُّ، ٱصْفَحْ! كَيْفَ يَقُومُ يَعْقُوبُ؟ فَإِنَّهُ صَغِيرٌ!».","waḥadatẖa lamãạ faragẖa min̊ ạảk̊li ʿusẖ̊bi ٱl̊ạảr̊ḍi ạảnĩy qul̊tu: «ạảyũhā ٱlsãyĩdu ٱlrãbũ, ٱṣ̊faḥ̊! kaẙfa yaqūmu yaʿ̊qūbu? fāi̹nãhu ṣagẖīruⁿ!»."],[7,3,"فَنَدِمَ ٱلرَّبُّ عَلَى هَذَا. «لَا يَكُونُ» قَالَ ٱلرَّبُّ.","fanadima ٱlrãbũ ʿalay̱ hadẖā. «lā yakūnu» qāla ٱlrãbũ."],[7,4,"هَكَذَا أَرَانِي ٱلسَّيِّدُ ٱلرَّبُّ، وَإِذَا ٱلسَّيِّدُ ٱلرَّبُّ قَدْ دَعَا لِلْمُحَاكَمَةِ بِٱلنَّارِ، فَأَكَلَتِ ٱلْغَمْرَ ٱلْعَظِيمَ وَأَكَلَتِ ٱلْحَقْلَ.","hakadẖā ạảrānī ٱlsãyĩdu ٱlrãbũ, wāi̹dẖā ٱlsãyĩdu ٱlrãbũ qad̊ daʿā lil̊muḥākamaẗi biٱlnãạri, fāảkalati ٱl̊gẖam̊ra ٱl̊ʿaẓīma wāảkalati ٱl̊ḥaq̊la."],[7,5,"فَقُلْتُ: «أَيُّهَا ٱلسَّيِّدُ ٱلرَّبُّ، كُفَّ! كَيْفَ يَقُومُ يَعْقُوبُ؟ فَإِنَّهُ صَغِيرٌ!».","faqul̊tu: «ạảyũhā ٱlsãyĩdu ٱlrãbũ, kufã! kaẙfa yaqūmu yaʿ̊qūbu? fāi̹nãhu ṣagẖīruⁿ!»."],[7,6,"فَنَدِمَ ٱلرَّبُّ عَلَى هَذَا.«فَهُوَ أَيْضًا لَا يَكُونُ» قَالَ ٱلسَّيِّدُ ٱلرَّبُّ.","fanadima ٱlrãbũ ʿalay̱ hadẖā.«fahūa ạảẙḍaⁿạ lā yakūnu» qāla ٱlsãyĩdu ٱlrãbũ."],[7,7,"هَكَذَا أَرَانِي وَإِذَا ٱلرَّبُّ وَاقِفٌ عَلَى حَائِطٍ قَائِمٍ وَفِي يَدِهِ زِيجٌ.","hakadẖā ạảrānī wāi̹dẖā ٱlrãbũ wāqifuⁿ ʿalay̱ ḥāyỉṭiⁿ qāyỉmiⁿ wafī yadihi zījuⁿ."],[7,8,"فَقَالَ لِي ٱلرَّبُّ: «مَا أَنْتَ رَاءٍ يَا عَامُوسُ؟» فَقُلْتُ: «زِيجًا». فَقَالَ ٱلسَّيِّدُ: «هَأَنَذَا وَاضِعٌ زِيجًا فِي وَسَطِ شَعْبِي إِسْرَائِيلَ. لَا أَعُودُ أَصْفَحُ لَهُ بَعْدُ.","faqāla lī ٱlrãbũ: «mā ạản̊ta rāʾiⁿ yā ʿāmūsu?» faqul̊tu: «zījaⁿạ». faqāla ٱlsãyĩdu: «hāảnadẖā wāḍiʿuⁿ zījaⁿạ fī wasaṭi sẖaʿ̊bī ại̹s̊rāyỉyla. lā ạảʿūdu ạảṣ̊faḥu lahu baʿ̊du."],[7,9,"فَتُقْفِرُ مُرْتَفَعَاتُ إِسْحَاقَ وَتَخْرَبُ مَقَادِسُ إِسْرَائِيلَ، وَأَقُومُ عَلَى بَيْتِ يَرُبْعَامَ بِٱلسَّيْفِ».","fatuq̊firu mur̊tafaʿātu ại̹s̊ḥāqa watakẖ̊rabu maqādisu ại̹s̊rāyỉyla, wāảqūmu ʿalay̱ baẙti yarub̊ʿāma biٱlsãẙfi»."],[7,10,"فَأَرْسَلَ أَمَصْيَا كَاهِنُ بَيْتِ إِيلَ إِلَى يَرُبْعَامَ مَلِكِ إِسْرَائِيلَ قَائِلًا: «قَدْ فَتَنَ عَلَيْكَ عَامُوسُ فِي وَسَطِ بَيْتِ إِسْرَائِيلَ. لَا تَقْدِرُ ٱلْأَرْضُ أَنْ تُطِيقَ كُلَّ أَقْوَالِهِ.","fāảr̊sala ạảmaṣ̊yā kāhinu baẙti ại̹yla ại̹lay̱ yarub̊ʿāma maliki ại̹s̊rāyỉyla qāyỉlaⁿạ: «qad̊ fatana ʿalaẙka ʿāmūsu fī wasaṭi baẙti ại̹s̊rāyỉyla. lā taq̊diru ٱl̊ạảr̊ḍu ạản̊ tuṭīqa kulã ạảq̊wālihi."],[7,11,"لِأَنَّهُ هَكَذَا قَالَ عَامُوسُ: يَمُوتُ يَرُبْعَامُ بِٱلسَّيْفِ، وَيُسْبَى إِسْرَائِيلُ عَنْ أَرْضِهِ».","liạảnãhu hakadẖā qāla ʿāmūsu: yamūtu yarub̊ʿāmu biٱlsãẙfi, wayus̊bay̱ ại̹s̊rāyỉylu ʿan̊ ạảr̊ḍihi»."],[7,12,"فَقَالَ أَمَصْيَا لِعَامُوسَ: «أَيُّهَا ٱلرَّائِي، ٱذْهَبِ ٱهْرُبْ إِلَى أَرْضِ يَهُوذَا وَكُلْ هُنَاكَ خُبْزًا وَهُنَاكَ تَنَبَّأْ.","faqāla ạảmaṣ̊yā liʿāmūsa: «ạảyũhā ٱlrãạyỉy, ٱdẖ̊habi ٱh̊rub̊ ại̹lay̱ ạảr̊ḍi yahūdẖā wakul̊ hunāka kẖub̊zaⁿạ wahunāka tanabãạ̊̉."],[7,13,"وَأَمَّا بَيْتُ إِيلَ فَلَا تَعُدْ تَتَنَبَّأُ فِيهَا بَعْدُ، لِأَنَّهَا مَقْدِسُ ٱلْمَلِكِ وَبَيْتُ ٱلْمُلْكِ».","wāảmãạ baẙtu ại̹yla falā taʿud̊ tatanabãạủ fīhā baʿ̊du, liạảnãhā maq̊disu ٱl̊maliki wabaẙtu ٱl̊mul̊ki»."],[7,14,"فَأَجَابَ عَامُوسُ وَقَالَ لِأَمَصْيَا: «لَسْتُ أَنَا نَبِيًّا وَلَا أَنَا ٱبْنُ نَبِيٍّ، بَلْ أَنَا رَاعٍ وَجَانِي جُمَّيْزٍ.","fāảjāba ʿāmūsu waqāla liạảmaṣ̊yā: «las̊tu ạảnā nabīaⁿ̃ạ walā ạảnā ٱb̊nu nabīiⁿ̃, bal̊ ạảnā rāʿiⁿ wajānī jumãẙziⁿ."],[7,15,"فَأَخَذَنِي ٱلرَّبُّ مِنْ وَرَاءِ ٱلضَّأْنِ وَقَالَ لِي ٱلرَّبُّ: ٱذْهَبْ تَنَبَّأْ لِشَعْبِي إِسْرَائِيلَ.","fāảkẖadẖanī ٱlrãbũ min̊ warāʾi ٱlḍãạ̊̉ni waqāla lī ٱlrãbũ: ٱdẖ̊hab̊ tanabãạ̊̉ lisẖaʿ̊bī ại̹s̊rāyỉyla."],[7,16,"«فَٱلْآنَ ٱسْمَعْ قَوْلَ ٱلرَّبِّ: أَنْتَ تَقُولُ: لَا تَتَنَبَّأْ عَلَى إِسْرَائِيلَ وَلَا تَتَكَلَّمْ عَلَى بَيْتِ إِسْحَاقَ.","«faٱl̊ậna ٱs̊maʿ̊ qaẘla ٱlrãbĩ: ạản̊ta taqūlu: lā tatanabãạ̊̉ ʿalay̱ ại̹s̊rāyỉyla walā tatakalãm̊ ʿalay̱ baẙti ại̹s̊ḥāqa."],[7,17,"لِذَلِكَ هَكَذَا قَالَ ٱلرَّبُّ: ٱمْرَأَتُكَ تَزْنِي فِي ٱلْمَدِينَةِ، وَبَنُوكَ وَبَنَاتُكَ يَسْقُطُونَ بِٱلسَّيْفِ، وَأَرْضُكَ تُقْسَمُ بِٱلْحَبْلِ، وَأَنْتَ تَمُوتُ فِي أَرْضٍ نَجِسَةٍ، وَإِسْرَائِيلُ يُسْبَى سَبْيًا عَنْ أَرْضِهِ».","lidẖalika hakadẖā qāla ٱlrãbũ: ٱm̊rāảtuka taz̊nī fī ٱl̊madīnaẗi, wabanūka wabanātuka yas̊quṭūna biٱlsãẙfi, wāảr̊ḍuka tuq̊samu biٱl̊ḥab̊li, wāản̊ta tamūtu fī ạảr̊ḍiⁿ najisaẗiⁿ, wāi̹s̊rāyỉylu yus̊bay̱ sab̊yaⁿạ ʿan̊ ạảr̊ḍihi»."],[8,1,"هَكَذَا أَرَانِي ٱلسَّيِّدُ ٱلرَّبُّ وَإِذَا سَلَّةٌ لِلْقِطَافِ.","hakadẖā ạảrānī ٱlsãyĩdu ٱlrãbũ wāi̹dẖā salãẗuⁿ lil̊qiṭāfi."],[8,2,"فَقَالَ: «مَاذَا أَنْتَ رَاءٍ يَا عَامُوسُ؟» فَقُلْتُ: «سَلَّةً لِلْقِطَافِ». فَقَالَ لِي ٱلرَّبُّ: «قَدْ أَتَتِ ٱلنِّهَايَةُ عَلَى شَعْبِي إِسْرَائِيلَ. لَا أَعُودُ أَصْفَحُ لَهُ بَعْدُ.","faqāla: «mādẖā ạản̊ta rāʾiⁿ yā ʿāmūsu?» faqul̊tu: «salãẗaⁿ lil̊qiṭāfi». faqāla lī ٱlrãbũ: «qad̊ ạảtati ٱlnĩhāyaẗu ʿalay̱ sẖaʿ̊bī ại̹s̊rāyỉyla. lā ạảʿūdu ạảṣ̊faḥu lahu baʿ̊du."],[8,3,"فَتَصِيرُ أَغَانِي ٱلْقَصْرِ وَلَاوِلَ فِي ذَلِكَ ٱلْيَوْمِ، يَقُولُ ٱلسَّيِّدُ ٱلرَّبُّ، ٱلْجُثَثُ كَثِيرَةٌ يَطْرَحُونَهَا فِي كُلِّ مَوْضِعٍ بِٱلسُّكُوتِ».","fataṣīru ạảgẖānī ٱl̊qaṣ̊ri walāwila fī dẖalika ٱl̊yaẘmi, yaqūlu ٱlsãyĩdu ٱlrãbũ, ٱl̊jutẖatẖu katẖīraẗuⁿ yaṭ̊raḥūnahā fī kulĩ maẘḍiʿiⁿ biٱlsũkūti»."],[8,4,"اِسْمَعُوا هَذَا أَيُّهَا ٱلْمُتَهَمِّمُونَ ٱلْمَسَاكِينَ لِكَيْ تُبِيدُوا بَائِسِي ٱلْأَرْضِ،","ạis̊maʿūạ hadẖā ạảyũhā ٱl̊mutahamĩmūna ٱl̊masākīna likaẙ tubīdūạ bāyỉsī ٱl̊ạảr̊ḍi,"],[8,5,"قَائِلِينَ: «مَتَى يَمْضِي رَأْسُ ٱلشَّهْرِ لِنَبِيعَ قَمْحًا، وَٱلسَّبْتُ لِنَعْرِضَ حِنْطَةً؟ لِنُصَغِّرَ ٱلْإِيفَةَ، وَنُكَبِّرَ ٱلشَّاقِلَ، وَنُعَوِّجَ مَوَازِينَ ٱلْغِشِّ.","qāyỉlīna: «matay̱ yam̊ḍī rā̊̉su ٱlsẖãh̊ri linabīʿa qam̊ḥaⁿạ, waٱlsãb̊tu linaʿ̊riḍa ḥin̊ṭaẗaⁿ? linuṣagẖĩra ٱl̊ại̹yfaẗa, wanukabĩra ٱlsẖãạqila, wanuʿawĩja mawāzīna ٱl̊gẖisẖĩ."],[8,6,"لِنَشْتَرِيَ ٱلضُّعَفَاءَ بِفِضَّةٍ، وَٱلْبَائِسَ بِنَعْلَيْنِ، وَنَبِيعَ نُفَايَةَ ٱلْقَمْحِ».","linasẖ̊tarīa ٱlḍũʿafāʾa bifiḍãẗiⁿ, waٱl̊bāyỉsa binaʿ̊laẙni, wanabīʿa nufāyaẗa ٱl̊qam̊ḥi»."],[8,7,"قَدْ أَقْسَمَ ٱلرَّبُّ بِفَخْرِ يَعْقُوبَ: «إِنِّي لَنْ أَنْسَى إِلَى ٱلْأَبَدِ جَمِيعَ أَعْمَالِهِمْ.","qad̊ ạảq̊sama ٱlrãbũ bifakẖ̊ri yaʿ̊qūba: «ại̹nĩy lan̊ ạản̊say̱ ại̹lay̱ ٱl̊ạảbadi jamīʿa ạảʿ̊mālihim̊."],[8,8,"أَلَيْسَ مِنْ أَجْلِ هَذَا تَرْتَعِدُ ٱلْأَرْضُ، وَيَنُوحُ كُلُّ سَاكِنٍ فِيهَا، وَتَطْمُو كُلُّهَا كَنَهْرٍ، وَتَفِيضُ وَتَنْضُبُ كَنِيلِ مِصْرَ؟","ạảlaẙsa min̊ ạảj̊li hadẖā tar̊taʿidu ٱl̊ạảr̊ḍu, wayanūḥu kulũ sākiniⁿ fīhā, wataṭ̊mū kulũhā kanah̊riⁿ, watafīḍu watan̊ḍubu kanīli miṣ̊ra?"],[8,9,"وَيَكُونُ فِي ذَلِكَ ٱلْيَوْمِ، يَقُولُ ٱلسَّيِّدُ ٱلرَّبُّ، أَنِّي أُغَيِّبُ ٱلشَّمْسَ فِي ٱلظُّهْرِ، وَأُقْتِمُ ٱلْأَرْضَ فِي يَوْمِ نُورٍ،","wayakūnu fī dẖalika ٱl̊yaẘmi, yaqūlu ٱlsãyĩdu ٱlrãbũ, ạảnĩy ạủgẖayĩbu ٱlsẖãm̊sa fī ٱlẓũh̊ri, wāủq̊timu ٱl̊ạảr̊ḍa fī yaẘmi nūriⁿ,"],[8,10,"وَأُحَوِّلُ أَعْيَادَكُمْ نَوْحًا، وَجَمِيعَ أَغَانِيكُمْ مَرَاثِيَ، وَأُصْعِدُ عَلَى كُلِّ ٱلْأَحْقَاءِ مِسْحًا، وَعَلَى كُلِّ رَأْسٍ قَرَعَةً، وَأَجْعَلُهَا كَمَنَاحَةِ ٱلْوَحِيدِ وَآخِرَهَا يَوْمًا مُرًّا!","wāủḥawĩlu ạảʿ̊yādakum̊ naẘḥaⁿạ, wajamīʿa ạảgẖānīkum̊ marātẖīa, wāủṣ̊ʿidu ʿalay̱ kulĩ ٱl̊ạảḥ̊qāʾi mis̊ḥaⁿạ, waʿalay̱ kulĩ rā̊̉siⁿ qaraʿaẗaⁿ, wāảj̊ʿaluhā kamanāḥaẗi ٱl̊waḥīdi wā̂kẖirahā yaẘmaⁿạ muraⁿ̃ạ!"],[8,11,"«هُوَذَا أَيَّامٌ تَأْتِي، يَقُولُ ٱلسَّيِّدُ ٱلرَّبُّ، أُرْسِلُ جُوعًا فِي ٱلْأَرْضِ، لَا جُوعًا لِلْخُبْزِ، وَلَا عَطَشًا لِلْمَاءِ، بَلْ لِٱسْتِمَاعِ كَلِمَاتِ ٱلرَّبِّ.","«hūadẖā ạảyãạmuⁿ tā̊̉tī, yaqūlu ٱlsãyĩdu ٱlrãbũ, ạủr̊silu jūʿaⁿạ fī ٱl̊ạảr̊ḍi, lā jūʿaⁿạ lil̊kẖub̊zi, walā ʿaṭasẖaⁿạ lil̊māʾi, bal̊ liٱs̊timāʿi kalimāti ٱlrãbĩ."],[8,12,"فَيَجُولُونَ مِنْ بَحْرٍ إِلَى بَحْرٍ، وَمِنَ ٱلشِّمَالِ إِلَى ٱلْمَشْرِقِ، يَتَطَوَّحُونَ لِيَطْلُبُوا كَلِمَةَ ٱلرَّبِّ فَلَا يَجِدُونَهَا.","fayajūlūna min̊ baḥ̊riⁿ ại̹lay̱ baḥ̊riⁿ, wamina ٱlsẖĩmāli ại̹lay̱ ٱl̊masẖ̊riqi, yataṭawãḥūna līaṭ̊lubūạ kalimaẗa ٱlrãbĩ falā yajidūnahā."],[8,13,"فِي ذَلِكَ ٱلْيَوْمِ تَذْبُلُ بِٱلْعَطَشِ ٱلْعَذَارَى ٱلْجَمِيلَاتُ وَٱلْفِتْيَانُ،","fī dẖalika ٱl̊yaẘmi tadẖ̊bulu biٱl̊ʿaṭasẖi ٱl̊ʿadẖāray̱ ٱl̊jamīlātu waٱl̊fit̊yānu,"],[8,14,"ٱلَّذِينَ يَحْلِفُونَ بِذَنْبِ ٱلسَّامِرَةِ، وَيَقُولُونَ: حَيٌّ إِلَهُكَ يَا دَانُ، وَحَيَّةٌ طَرِيقَةُ بِئْرِ سَبْعٍ. فَيَسْقُطُونَ وَلَا يَقُومُونَ بَعْدُ».","ٱlãdẖīna yaḥ̊lifūna bidẖan̊bi ٱlsãạmiraẗi, wayaqūlūna: ḥayuⁿ̃ ại̹lahuka yā dānu, waḥayãẗuⁿ ṭarīqaẗu bī̊̉ri sab̊ʿiⁿ. fayas̊quṭūna walā yaqūmūna baʿ̊du»."],[9,1,"رَأَيْتُ ٱلسَّيِّدَ قَائِمًا عَلَى ٱلْمَذْبَحِ، فَقَالَ: «اِضْرِبْ تَاجَ ٱلْعَمُودِ حَتَّى تَرْجُفَ ٱلْأَعْتَابُ، وَكَسِّرْهَا عَلَى رُؤُوسِ جَمِيعِهِمْ، فَأَقْتُلَ آخِرَهُمْ بِٱلسَّيْفِ. لَا يَهْرُبُ مِنْهُمْ هَارِبٌ وَلَا يُفْلِتُ مِنْهُمْ نَاجٍ.","rāảẙtu ٱlsãyĩda qāyỉmaⁿạ ʿalay̱ ٱl̊madẖ̊baḥi, faqāla: «ạiḍ̊rib̊ tāja ٱl̊ʿamūdi ḥatãy̱ tar̊jufa ٱl̊ạảʿ̊tābu, wakasĩr̊hā ʿalay̱ rūủwsi jamīʿihim̊, fāảq̊tula ậkẖirahum̊ biٱlsãẙfi. lā yah̊rubu min̊hum̊ hāribuⁿ walā yuf̊litu min̊hum̊ nājiⁿ."],[9,2,"إِنْ نَقَبُوا إِلَى ٱلْهَاوِيَةِ فَمِنْ هُنَاكَ تَأْخُذُهُمْ يَدِي، وَإِنْ صَعِدُوا إِلَى ٱلسَّمَاءِ فَمِنْ هُنَاكَ أُنْزِلُهُمْ.","ại̹n̊ naqabūạ ại̹lay̱ ٱl̊hāwīaẗi famin̊ hunāka tā̊̉kẖudẖuhum̊ yadī, wāi̹n̊ ṣaʿidūạ ại̹lay̱ ٱlsãmāʾi famin̊ hunāka ạủn̊ziluhum̊."],[9,3,"وَإِنِ ٱخْتَبَأُوا فِي رَأْسِ ٱلْكَرْمَلِ فَمِنْ هُنَاكَ أُفَتِّشُ وَآخُذُهُمْ، وَإِنِ ٱخْتَفَوْا مِنْ أَمَامِ عَيْنَيَّ فِي قَعْرِ ٱلْبَحْرِ فَمِنْ هُنَاكَ آمُرُ ٱلْحَيَّةَ فَتَلْدَغُهُمْ.","wāi̹ni ٱkẖ̊tabāủwạ fī rā̊̉si ٱl̊kar̊mali famin̊ hunāka ạủfatĩsẖu wā̂kẖudẖuhum̊, wāi̹ni ٱkẖ̊tafaẘạ min̊ ạảmāmi ʿaẙnayã fī qaʿ̊ri ٱl̊baḥ̊ri famin̊ hunāka ậmuru ٱl̊ḥayãẗa fatal̊dagẖuhum̊."],[9,4,"وَإِنْ مَضَوْا فِي ٱلسَّبْيِ أَمَامَ أَعْدَائِهِمْ فَمِنْ هُنَاكَ آمُرُ ٱلسَّيْفَ فَيَقْتُلُهُمْ، وَأَجْعَلُ عَيْنَيَّ عَلَيْهِمْ لِلشَّرِّ لَا لِلْخَيْرِ».","wāi̹n̊ maḍaẘạ fī ٱlsãb̊yi ạảmāma ạảʿ̊dāyỉhim̊ famin̊ hunāka ậmuru ٱlsãẙfa fayaq̊tuluhum̊, wāảj̊ʿalu ʿaẙnayã ʿalaẙhim̊ lilsẖãrĩ lā lil̊kẖaẙri»."],[9,5,"وَٱلسَّيِّدُ رَبُّ ٱلْجُنُودِ ٱلَّذِي يَمَسُّ ٱلْأَرْضَ فَتَذُوبُ، وَيَنُوحُ ٱلسَّاكِنُونَ فِيهَا، وَتَطْمُو كُلُّهَا كَنَهْرٍ وَتَنْضُبُ كَنِيلِ مِصْرَ.","waٱlsãyĩdu rabũ ٱl̊junūdi ٱlãdẖī yamasũ ٱl̊ạảr̊ḍa fatadẖūbu, wayanūḥu ٱlsãạkinūna fīhā, wataṭ̊mū kulũhā kanah̊riⁿ watan̊ḍubu kanīli miṣ̊ra."],[9,6,"ٱلَّذِي بَنَى فِي ٱلسَّمَاءِ عَلَالِيَهُ وَأَسَّسَ عَلَى ٱلْأَرْضِ قُبَّتَهُ، ٱلَّذِي يَدْعُو مِيَاهَ ٱلْبَحْرِ وَيَصُبُّهَا عَلَى وَجْهِ ٱلْأَرْضِ، يَهْوَهُ ٱسْمُهُ.","ٱlãdẖī banay̱ fī ٱlsãmāʾi ʿalālīahu wāảsãsa ʿalay̱ ٱl̊ạảr̊ḍi qubãtahu, ٱlãdẖī yad̊ʿū mīāha ٱl̊baḥ̊ri wayaṣubũhā ʿalay̱ waj̊hi ٱl̊ạảr̊ḍi, yah̊wahu ٱs̊muhu."],[9,7,"«أَلَسْتُمْ لِي كَبَنِي ٱلْكُوشِيِّينَ يَا بَنِي إِسْرَائِيلَ، يَقُولُ ٱلرَّبُّ؟ أَلَمْ أُصْعِدْ إِسْرَائِيلَ مِنْ أَرْضِ مِصْرَ، وَٱلْفِلِسْطِينِيِّينَ مِنْ كَفْتُورَ، وَٱلْأَرَامِيِّينَ مِنْ قِيرٍ؟","«ạảlas̊tum̊ lī kabanī ٱl̊kūsẖīĩyna yā banī ại̹s̊rāyỉyla, yaqūlu ٱlrãbũ? ạảlam̊ ạủṣ̊ʿid̊ ại̹s̊rāyỉyla min̊ ạảr̊ḍi miṣ̊ra, waٱl̊filis̊ṭīnīĩyna min̊ kaf̊tūra, waٱl̊ạảrāmīĩyna min̊ qīriⁿ?"],[9,8,"هُوَذَا عَيْنَا ٱلسَّيِّدِ ٱلرَّبِّ عَلَى ٱلْمَمْلَكَةِ ٱلْخَاطِئَةِ، وَأُبِيدُهَا عَنْ وَجْهِ ٱلْأَرْضِ. غَيْرَ أَنِّي لَا أُبِيدُ بَيْتَ يَعْقُوبَ تَمَامًا، يَقُولُ ٱلرَّبُّ.","hūadẖā ʿaẙnā ٱlsãyĩdi ٱlrãbĩ ʿalay̱ ٱl̊mam̊lakaẗi ٱl̊kẖāṭīảẗi, wāủbīduhā ʿan̊ waj̊hi ٱl̊ạảr̊ḍi. gẖaẙra ạảnĩy lā ạủbīdu baẙta yaʿ̊qūba tamāmaⁿạ, yaqūlu ٱlrãbũ."],[9,9,"لِأَنَّهُ هَأَنَذَا آمُرُ فَأُغَرْبِلُ بَيْتَ إِسْرَائِيلَ بَيْنَ جَمِيعِ ٱلْأُمَمِ كَمَا يُغَرْبَلُ فِي ٱلْغُرْبَالِ، وَحَبَّةٌ لَا تَقَعُ إِلَى ٱلْأَرْضِ.","liạảnãhu hāảnadẖā ậmuru fāủgẖar̊bilu baẙta ại̹s̊rāyỉyla baẙna jamīʿi ٱl̊ạủmami kamā yugẖar̊balu fī ٱl̊gẖur̊bāli, waḥabãẗuⁿ lā taqaʿu ại̹lay̱ ٱl̊ạảr̊ḍi."],[9,10,"بِٱلسَّيْفِ يَمُوتُ كُلُّ خَاطِئِي شَعْبِي ٱلْقَائِلِينَ: لَا يَقْتَرِبُ ٱلشَّرُّ، وَلَا يَأْتِي بَيْنَنَا.","biٱlsãẙfi yamūtu kulũ kẖāṭīỉy sẖaʿ̊bī ٱl̊qāyỉlīna: lā yaq̊taribu ٱlsẖãrũ, walā yā̊̉tī baẙnanā."],[9,11,"«فِي ذَلِكَ ٱلْيَوْمِ أُقِيمُ مِظَلَّةَ دَاوُدَ ٱلسَّاقِطَةَ، وَأُحَصِّنُ شُقُوقَهَا، وَأُقِيمُ رَدْمَهَا، وَأَبْنِيهَا كَأَيَّامِ ٱلدَّهْرِ.","«fī dẖalika ٱl̊yaẘmi ạủqīmu miẓalãẗa dāwuda ٱlsãạqiṭaẗa, wāủḥaṣĩnu sẖuqūqahā, wāủqīmu rad̊mahā, wāảb̊nīhā kāảyãạmi ٱldãh̊ri."],[9,12,"لِكَيْ يَرِثُوا بَقِيَّةَ أَدُومَ وَجَمِيعَ ٱلْأُمَمِ ٱلَّذِينَ دُعِيَ ٱسْمِي عَلَيْهِمْ، يَقُولُ ٱلرَّبُّ، ٱلصَّانِعُ هَذَا.","likaẙ yaritẖūạ baqīãẗa ạảdūma wajamīʿa ٱl̊ạủmami ٱlãdẖīna duʿīa ٱs̊mī ʿalaẙhim̊, yaqūlu ٱlrãbũ, ٱlṣãạniʿu hadẖā."],[9,13,"هَا أَيَّامٌ تَأْتِي، يَقُولُ ٱلرَّبُّ، يُدْرِكُ ٱلْحَارِثُ ٱلْحَاصِدَ، وَدَائِسُ ٱلْعِنَبِ بَاذِرَ ٱلزَّرْعِ، وَتَقْطُرُ ٱلْجِبَالُ عَصِيرًا، وَتَسِيلُ جَمِيعُ ٱلتِّلَالِ.","hā ạảyãạmuⁿ tā̊̉tī, yaqūlu ٱlrãbũ, yud̊riku ٱl̊ḥāritẖu ٱl̊ḥāṣida, wadāyỉsu ٱl̊ʿinabi bādẖira ٱlzãr̊ʿi, wataq̊ṭuru ٱl̊jibālu ʿaṣīraⁿạ, watasīlu jamīʿu ٱltĩlāli."],[9,14,"وَأَرُدُّ سَبْيَ شَعْبِي إِسْرَائِيلَ فَيَبْنُونَ مُدُنًا خَرِبَةً وَيَسْكُنُونَ، وَيَغْرِسُونَ كُرُومًا وَيَشْرَبُونَ خَمْرَهَا، وَيَصْنَعُونَ جَنَّاتٍ وَيَأْكُلُونَ أَثْمَارَهَا.","wāảrudũ sab̊ya sẖaʿ̊bī ại̹s̊rāyỉyla fayab̊nūna mudunaⁿạ kẖaribaẗaⁿ wayas̊kunūna, wayagẖ̊risūna kurūmaⁿạ wayasẖ̊rabūna kẖam̊rahā, wayaṣ̊naʿūna janãạtiⁿ wayā̊̉kulūna ạảtẖ̊mārahā."],[9,15,"وَأَغْرِسُهُمْ فِي أَرْضِهِمْ، وَلَنْ يُقْلَعُوا بَعْدُ مِنْ أَرْضِهِمِ ٱلَّتِي أَعْطَيْتُهُمْ، قَالَ ٱلرَّبُّ إِلَهُكَ».","wāảgẖ̊risuhum̊ fī ạảr̊ḍihim̊, walan̊ yuq̊laʿūạ baʿ̊du min̊ ạảr̊ḍihimi ٱlãtī ạảʿ̊ṭaẙtuhum̊, qāla ٱlrãbũ ại̹lahuka»."]],"bis-obbr":[[1,1,"Profet Amos, hem i man blong lukaot long sipsip, mo ples blong hem long taon ya Tekoa long Juda.* Long taem we King Usia i king long Juda, mo King Jeroboam, we papa blong hem King Jehoas, i king long Isrel,* profet ya i luk wan vison.* Long vison ya, God i givim ol tok long hem blong hem i go talemaot long ol laen* blong Isrel long not. Hem i luk vison ya fastaem, bigfala etkwek ya we i kasem olgeta long taem blong King Usia, hem i kam biaen, we tu yia i pas finis. Ol tok we i stap long buk ya, hemia nao ol tok we God i talem long hem.","Profet Amos, hem i man blong lukaot long sipsip, mo ples blong hem long taon ya Tekoa long Juda.* Long taem we King Usia i king long Juda, mo King Jeroboam, we papa blong hem King Jehoas, i king long Isrel,* profet ya i luk wan vison.* Long vison ya, God i givim ol tok long hem blong hem i go talemaot long ol laen* blong Isrel long not. Hem i luk vison ya fastaem, bigfala etkwek ya we i kasem olgeta long taem blong King Usia, hem i kam biaen, we tu yia i pas finis. Ol tok we i stap long buk ya, hemia nao ol tok we God i talem long hem."],[1,2,"Nao Profet Amos i talem se, “Hae God i stap long hil ya Saeon,* long Jerusalem.* Hem i singaot i kam, we voes blong hem i faerap bigwan olsem tanda. Ol gudgudfala gras we ol sipsip oli stap kakae, mo olgeta gras long hil ya Kamel oli drae evriwan.” Bambae hem i panisim ol man Siria","Nao Profet Amos i talem se, “Hae God i stap long hil ya Saeon,* long Jerusalem.* Hem i singaot i kam, we voes blong hem i faerap bigwan olsem tanda. Ol gudgudfala gras we ol sipsip oli stap kakae, mo olgeta gras long hil ya Kamel oli drae evriwan.” Bambae hem i panisim ol man Siria"],[1,3,"Nao Profet Amos i talemaot we Hae God i talem se, “Ol man Damaskes ya, oli stap mekem sin plante taem, we oli no save lego fasin ya. Oli mekem i strong tumas long ol man Gilead, oli spolemgud olgeta we oli no gat sore. Tru, mi talem long yufala, mi bambae mi panisim olgeta from ol rabis fasin ya blong olgeta.","Nao Profet Amos i talemaot we Hae God i talem se, “Ol man Damaskes ya, oli stap mekem sin plante taem, we oli no save lego fasin ya. Oli mekem i strong tumas long ol man Gilead, oli spolemgud olgeta we oli no gat sore. Tru, mi talem long yufala, mi bambae mi panisim olgeta from ol rabis fasin ya blong olgeta."],[1,4,"Bambae mi bonem haos ya blong king, we King Hasael i bin wokem bifo, mo bambae mi bonem ol strong ples blong haed blong King Benadad tu.","Bambae mi bonem haos ya blong king, we King Hasael i bin wokem bifo, mo bambae mi bonem ol strong ples blong haed blong King Benadad tu."],[1,5,"Bambae mi brekemdaon ol doa* blong bigfala stonwol blong taon ya Damaskes, mo bambae mi tekemaot haeman blong taon ya Beteden, wetem ol man blong bigfala levelples ya Aven we i stap daon, long medel blong ol hil. Bambae mi tekemaot olgeta man Siria oli go wok slef* longwe long ples ya Kiri. Mi mi Hae God, mo hemia tok blong mi.” Hae God bambae i panisim kantri ya Filistia","Bambae mi brekemdaon ol doa* blong bigfala stonwol blong taon ya Damaskes, mo bambae mi tekemaot haeman blong taon ya Beteden, wetem ol man blong bigfala levelples ya Aven we i stap daon, long medel blong ol hil. Bambae mi tekemaot olgeta man Siria oli go wok slef* longwe long ples ya Kiri. Mi mi Hae God, mo hemia tok blong mi.” Hae God bambae i panisim kantri ya Filistia"],[1,6,"Bakegen, Profet Amos i talemaot we Hae God i talem se, “Ol man Gasa ya, oli stap mekem sin plante taem, we oli no save lego fasin ya. Taem oli go mekem faet, nao oli winim wan ples, oli stap karemaot olgeta man blong hem evriwan, oli go salem olgeta long ol man Edom blong oli go wok slef,* be fasin ya i no stret nating. Tru, mi talem long yufala, mi bambae mi panisim olgeta from ol rabis fasin ya blong olgeta.","Bakegen, Profet Amos i talemaot we Hae God i talem se, “Ol man Gasa ya, oli stap mekem sin plante taem, we oli no save lego fasin ya. Taem oli go mekem faet, nao oli winim wan ples, oli stap karemaot olgeta man blong hem evriwan, oli go salem olgeta long ol man Edom blong oli go wok slef,* be fasin ya i no stret nating. Tru, mi talem long yufala, mi bambae mi panisim olgeta from ol rabis fasin ya blong olgeta."],[1,7,"Bambae mi bonem olgeta samting blong taon ya Gasa, mo bambae mi bonem ol strong ples blong haed blong olgeta tu.","Bambae mi bonem olgeta samting blong taon ya Gasa, mo bambae mi bonem ol strong ples blong haed blong olgeta tu."],[1,8,"Bambae mi tekemaot king blong taon ya Asdod wetem king blong taon ya Askelon. Bambae mi panisim ol man blong taon ya Ekron, mo ol man Filistia we oli stap yet, bambae mi kilim olgeta oli ded. Mi mi Hae God, mo hemia tok blong mi.” Hae God bambae i panisim ol man Taea","Bambae mi tekemaot king blong taon ya Asdod wetem king blong taon ya Askelon. Bambae mi panisim ol man blong taon ya Ekron, mo ol man Filistia we oli stap yet, bambae mi kilim olgeta oli ded. Mi mi Hae God, mo hemia tok blong mi.” Hae God bambae i panisim ol man Taea"],[1,9,"Bakegen, Profet Amos i talemaot we Hae God i talem se, “Ol man Taea ya, oli stap mekem sin plante taem, we oli no save lego fasin ya. Olgeta oli mekem promes blong fren gud wetem ol brata blong yufala, be biaen, oli no holem promes ya, oli girap, oli go mekem faet long olgeta ya bakegen, oli winim olgeta, nao oli karemaot olgeta evriwan oli go wok slef* long Edom. Tru, mi talem long yufala, mi bambae mi panisim olgeta from ol rabis fasin ya blong olgeta.","Bakegen, Profet Amos i talemaot we Hae God i talem se, “Ol man Taea ya, oli stap mekem sin plante taem, we oli no save lego fasin ya. Olgeta oli mekem promes blong fren gud wetem ol brata blong yufala, be biaen, oli no holem promes ya, oli girap, oli go mekem faet long olgeta ya bakegen, oli winim olgeta, nao oli karemaot olgeta evriwan oli go wok slef* long Edom. Tru, mi talem long yufala, mi bambae mi panisim olgeta from ol rabis fasin ya blong olgeta."],[1,10,"Bambae mi bonem olgeta samting blong taon ya blong olgeta, mo bambae mi bonem ol strong ples blong haed blong olgeta tu.” Hae God bambae i panisim ol man Edom","Bambae mi bonem olgeta samting blong taon ya blong olgeta, mo bambae mi bonem ol strong ples blong haed blong olgeta tu.” Hae God bambae i panisim ol man Edom"],[1,11,"Bakegen, Profet Amos i talemaot we Hae God i talem se, “Ol man Edom ya, oli stap mekem sin plante taem, we oli no save lego fasin ya. Olgeta oli brata blong yufala nomo, be oli girap, oli stap ronem yufala long not, oli stap kilim yufala, we oli no gat sore nating. Olgeta oli kros tumas, we oli no save lego kros blong olgeta nating. Tru, mi talem long yufala, mi bambae mi panisim olgeta from ol rabis fasin ya blong olgeta.","Bakegen, Profet Amos i talemaot we Hae God i talem se, “Ol man Edom ya, oli stap mekem sin plante taem, we oli no save lego fasin ya. Olgeta oli brata blong yufala nomo, be oli girap, oli stap ronem yufala long not, oli stap kilim yufala, we oli no gat sore nating. Olgeta oli kros tumas, we oli no save lego kros blong olgeta nating. Tru, mi talem long yufala, mi bambae mi panisim olgeta from ol rabis fasin ya blong olgeta."],[1,12,"Bambae mi bonem taon ya Teman, mo mi bonem ol strong ples blong haed blong olgeta long taon ya Bojeraha.” Hae God bambae i panisim ol man Amon","Bambae mi bonem taon ya Teman, mo mi bonem ol strong ples blong haed blong olgeta long taon ya Bojeraha.” Hae God bambae i panisim ol man Amon"],[1,13,"Bakegen, Profet Amos i talemaot we Hae God i talem se, “Ol man Amon ya, oli stap mekem sin plante taem, we oli no save lego fasin ya. Bifo, taem oli go mekem faet long ol man Gilead blong winim graon blong olgeta, oli holem ol woman we oli gat bel, nao oli katem bel blong olgeta i open, blong kilim olgeta i ded. Tru, mi talem long yufala, mi bambae mi panisim olgeta from ol rabis fasin ya blong olgeta.","Bakegen, Profet Amos i talemaot we Hae God i talem se, “Ol man Amon ya, oli stap mekem sin plante taem, we oli no save lego fasin ya. Bifo, taem oli go mekem faet long ol man Gilead blong winim graon blong olgeta, oli holem ol woman we oli gat bel, nao oli katem bel blong olgeta i open, blong kilim olgeta i ded. Tru, mi talem long yufala, mi bambae mi panisim olgeta from ol rabis fasin ya blong olgeta."],[1,14,"Bambae mi bonem olgeta samting blong taon ya Raba we i kaptel blong olgeta, mo bambae mi bonem ol strong ples blong haed blong olgeta tu. Long taem blong faet, bambae ol enemi blong olgeta oli stap singaot bigwan, mo bambae oli stap kilim olgeta, olsem we hariken i kilimdaon evri samting.","Bambae mi bonem olgeta samting blong taon ya Raba we i kaptel blong olgeta, mo bambae mi bonem ol strong ples blong haed blong olgeta tu. Long taem blong faet, bambae ol enemi blong olgeta oli stap singaot bigwan, mo bambae oli stap kilim olgeta, olsem we hariken i kilimdaon evri samting."],[1,15,"Bambae ol enemi ya oli tekemaot king blong olgeta wetem ol haeman blong olgeta, oli tekem olgeta i go wok slef* long narafala ples. Mi mi Hae God, mo hemia tok blong mi.”","Bambae ol enemi ya oli tekemaot king blong olgeta wetem ol haeman blong olgeta, oli tekem olgeta i go wok slef* long narafala ples. Mi mi Hae God, mo hemia tok blong mi.”"],[2,1,"Bakegen, Profet Amos i talemaot we Hae God i talem se, “Ol man Moab ya, oli stap mekem sin plante taem, we oli no save lego fasin ya. Olgeta oli no save tinghevi long ol bun blong king blong Edom. Oli girap, oli bonem ol bun ya blong wokem laem long hem. Tru, mi talem long yufala, mi bambae mi panisim olgeta from ol rabis fasin ya blong olgeta.","Bakegen, Profet Amos i talemaot we Hae God i talem se, “Ol man Moab ya, oli stap mekem sin plante taem, we oli no save lego fasin ya. Olgeta oli no save tinghevi long ol bun blong king blong Edom. Oli girap, oli bonem ol bun ya blong wokem laem long hem. Tru, mi talem long yufala, mi bambae mi panisim olgeta from ol rabis fasin ya blong olgeta."],[2,2,"Bambae mi bonem olgeta ples blong olgeta. Ol strong ples blong haed blong ol man blong taon ya Keriot, bambae mi bonem olgeta evriwan. Bambae i gat bigfala faet, we ol enemi blong ol man Moab ya bambae oli stap singsingaot bigwan, mo oli stap blu long ol bigfala pupu blong olgeta, nao long faet ya, ol man Moab ya bambae oli ded.","Bambae mi bonem olgeta ples blong olgeta. Ol strong ples blong haed blong ol man blong taon ya Keriot, bambae mi bonem olgeta evriwan. Bambae i gat bigfala faet, we ol enemi blong ol man Moab ya bambae oli stap singsingaot bigwan, mo oli stap blu long ol bigfala pupu blong olgeta, nao long faet ya, ol man Moab ya bambae oli ded."],[2,3,"Mi bambae mi kilim king blong olgeta, wetem ol lida blong olgeta oli ded. Mi mi Hae God, mo hemia tok blong mi.” Hae God bambae i panisim ol man Juda","Mi bambae mi kilim king blong olgeta, wetem ol lida blong olgeta oli ded. Mi mi Hae God, mo hemia tok blong mi.” Hae God bambae i panisim ol man Juda"],[2,4,"Bakegen, Profet Amos i talemaot we Hae God i talem se, “Ol man Juda* ya, oli stap mekem sin plante taem, we oli no save lego fasin ya. Olgeta oli tanem baksaed long ol tok blong mi, mo oli no obei nating long ol tok we mi mi putum. Fasin blong ol narafala god ya we ol bubu blong olgeta bifo oli stap mekem wosip long olgeta, hem i pulum olgeta oli gowe long mi finis. Tru, mi talem long yufala, mi bambae mi panisim olgeta from ol rabis fasin ya blong olgeta.","Bakegen, Profet Amos i talemaot we Hae God i talem se, “Ol man Juda* ya, oli stap mekem sin plante taem, we oli no save lego fasin ya. Olgeta oli tanem baksaed long ol tok blong mi, mo oli no obei nating long ol tok we mi mi putum. Fasin blong ol narafala god ya we ol bubu blong olgeta bifo oli stap mekem wosip long olgeta, hem i pulum olgeta oli gowe long mi finis. Tru, mi talem long yufala, mi bambae mi panisim olgeta from ol rabis fasin ya blong olgeta."],[2,5,"Bambae mi bonem olgeta ples blong olgeta. Ol strong ples blong haed blong olgeta long Jerusalem,* bambae mi bonem olgeta evriwan.”","Bambae mi bonem olgeta ples blong olgeta. Ol strong ples blong haed blong olgeta long Jerusalem,* bambae mi bonem olgeta evriwan.”"],[2,6,"Mo bakegen, Profet Amos i talemaot we Hae God i talem se, “Ol man Isrel.* !Yufala i stap mekem sin plante taem, we yufala i no save lego fasin ya! !Tru, mi talem long yufala, mi bambae mi panisim yufala from ol rabis fasin ya blong yufala! Ol stret man we oli no save pem ol kaon blong olgeta long yufala, be yufala i stap salem olgeta oli kam slef* blong ol narafala man. Sam long olgeta oli pua tumas, we oli stap kaon blong pem sandel nomo, be yufala i salemaot olgeta.","Mo bakegen, Profet Amos i talemaot we Hae God i talem se, “Ol man Isrel.* !Yufala i stap mekem sin plante taem, we yufala i no save lego fasin ya! !Tru, mi talem long yufala, mi bambae mi panisim yufala from ol rabis fasin ya blong yufala! Ol stret man we oli no save pem ol kaon blong olgeta long yufala, be yufala i stap salem olgeta oli kam slef* blong ol narafala man. Sam long olgeta oli pua tumas, we oli stap kaon blong pem sandel nomo, be yufala i salemaot olgeta."],[2,7,"Olgeta we oli no strong, mo oli no gat paoa, yufala i stap purumbut long olgeta, mo ol puaman, yufala i stap blokem olgeta blong oli no save kasem ol samting we oli gat raet blong kasem. Fasin blong yufala, man i tekem woman slef blong hem, blong i slip wetem hem, nao pikinini blong hem i girap, i go slip wetem sem woman ya bakegen. Fasin ya i mekem nem blong mi i kam nogud olgeta.","Olgeta we oli no strong, mo oli no gat paoa, yufala i stap purumbut long olgeta, mo ol puaman, yufala i stap blokem olgeta blong oli no save kasem ol samting we oli gat raet blong kasem. Fasin blong yufala, man i tekem woman slef blong hem, blong i slip wetem hem, nao pikinini blong hem i girap, i go slip wetem sem woman ya bakegen. Fasin ya i mekem nem blong mi i kam nogud olgeta."],[2,8,"Kaliko blong ol puaman we yufala i holem fastaem, blong letem olgeta oli kaon long yufala, be long naet, yufala i no givimbak long olgeta. Yufala i yusum blong mekem bed blong yufala long ol ples blong mekem wosip. Waen ya we ol man oli stap givim long yufala blong pemaot ol faen we yufala i putum long olgeta, yufala i stap yusum blong dring long haos* blong mi.","Kaliko blong ol puaman we yufala i holem fastaem, blong letem olgeta oli kaon long yufala, be long naet, yufala i no givimbak long olgeta. Yufala i yusum blong mekem bed blong yufala long ol ples blong mekem wosip. Waen ya we ol man oli stap givim long yufala blong pemaot ol faen we yufala i putum long olgeta, yufala i stap yusum blong dring long haos* blong mi."],[2,9,"“Be mi nao mi kilim ol laen* blong Amoro* evriwan oli ded blong tekem yufala i kam stap long ples ya. Nating we olgeta ya oli longlongfala man, olsem ol tri ya sida,* mo oli strong tumas olsem oktri,* be mi mi flatemgud olgeta evriwan.","“Be mi nao mi kilim ol laen* blong Amoro* evriwan oli ded blong tekem yufala i kam stap long ples ya. Nating we olgeta ya oli longlongfala man, olsem ol tri ya sida,* mo oli strong tumas olsem oktri,* be mi mi flatemgud olgeta evriwan."],[2,10,"Bifo, taem yufala i stap long Ijip, mi nao mi tekemaot yufala, mo long foti yia ya we yufala i stap wokbaot long draeples, mi mi stap lidim yufala. Mo biaen, graon ya we fastaem i blong ol laen blong Amoro, mi mi givim i go long yufala.","Bifo, taem yufala i stap long Ijip, mi nao mi tekemaot yufala, mo long foti yia ya we yufala i stap wokbaot long draeples, mi mi stap lidim yufala. Mo biaen, graon ya we fastaem i blong ol laen blong Amoro, mi mi givim i go long yufala."],[2,11,"Mo mi jusumaot sam long ol pikinini blong yufala blong oli kam profet, mo sam blong oli kam spesel man blong mi, we nem blong olgeta Nasiraet ?Tok ya i tru, no nogat?","Mo mi jusumaot sam long ol pikinini blong yufala blong oli kam profet, mo sam blong oli kam spesel man blong mi, we nem blong olgeta Nasiraet ?Tok ya i tru, no nogat?"],[2,12,"Ol Nasiraet* ya, i tabu blong oli dring, be yufala i girap, yufala i mekem olgeta oli dring waen, mo yufala i blokem ol profet ya blong mi, blong oli no talemaot tok blong mi long ol man.","Ol Nasiraet* ya, i tabu blong oli dring, be yufala i girap, yufala i mekem olgeta oli dring waen, mo yufala i blokem ol profet ya blong mi, blong oli no talemaot tok blong mi long ol man."],[2,13,"Naoia, bambae mi panisim yufala, we bambae yufala i stap krae from, olsem we wil blong kat i stap krae, taem we kat i fulap tumas.","Naoia, bambae mi panisim yufala, we bambae yufala i stap krae from, olsem we wil blong kat i stap krae, taem we kat i fulap tumas."],[2,14,"Long taem ya, ol strong man blong resis bambae oli no save ronwe. Ol strong man bambae oli no moa strong, mo ol lariken man blong faet bambae oli no moa save sevem laef blong olgeta.","Long taem ya, ol strong man blong resis bambae oli no save ronwe. Ol strong man bambae oli no moa strong, mo ol lariken man blong faet bambae oli no moa save sevem laef blong olgeta."],[2,15,"Ol man blong sut long bonara bambae oli fraet, oli ronwe, mo ol strong man blong resis, bambae oli traem ronwe, be bambae oli kanduit. Mo ol man blong ron long hos bambae oli traem ronwe, be bambae oli no save sevem laef blong olgeta.","Ol man blong sut long bonara bambae oli fraet, oli ronwe, mo ol strong man blong resis, bambae oli traem ronwe, be bambae oli kanduit. Mo ol man blong ron long hos bambae oli traem ronwe, be bambae oli no save sevem laef blong olgeta."],[2,16,"Ol nambawan man blong faet, be long taem ya, bambae oli sakem ol samting blong faet blong olgeta, oli resis, oli ronwe. Mi mi Hae God, mo hemia tok blong mi.”","Ol nambawan man blong faet, be long taem ya, bambae oli sakem ol samting blong faet blong olgeta, oli resis, oli ronwe. Mi mi Hae God, mo hemia tok blong mi.”"],[3,1,"Nao profet i talem se, “!Ol laen blong Isrel! Yufala i lesin gud long tok we Hae God i talem. Bifo hem i tekemaot ol olfala bubu blong yumi long Ijip, mo tok ya blong hem i jajem yumi evriwan we i kamaot biaen long ol olfala ya. Hem i talem se,","Nao profet i talem se, “!Ol laen blong Isrel! Yufala i lesin gud long tok we Hae God i talem. Bifo hem i tekemaot ol olfala bubu blong yumi long Ijip, mo tok ya blong hem i jajem yumi evriwan we i kamaot biaen long ol olfala ya. Hem i talem se,"],[3,2,"‘Long olgeta man long wol, be yufala ya nomo we mi mi jusumaot yufala blong yufala i man blong mi. Be oltaem yufala i stap mekem sin agens long mi, nao from samting ya, bambae mi mi panisim yufala.’ ”","‘Long olgeta man long wol, be yufala ya nomo we mi mi jusumaot yufala blong yufala i man blong mi. Be oltaem yufala i stap mekem sin agens long mi, nao from samting ya, bambae mi mi panisim yufala.’ ”"],[3,3,"Nao Profet Amos i talem se, “!Yufala i traem tingbaot! ?Sipos tu man i no mekem plan blong kam wanples fastaem, yufala i ting se tufala i save wokbaot wanples?","Nao Profet Amos i talem se, “!Yufala i traem tingbaot! ?Sipos tu man i no mekem plan blong kam wanples fastaem, yufala i ting se tufala i save wokbaot wanples?"],[3,4,"“?Sipos laeon i no luk wan samting we i save kakae, yufala i ting se hem i save singaot bigwan? “?Taem smol laeon i stap kakae, sipos brata blong hem i no kam klosap long hem, yufala i ting se hem i save mekenoes?","“?Sipos laeon i no luk wan samting we i save kakae, yufala i ting se hem i save singaot bigwan? “?Taem smol laeon i stap kakae, sipos brata blong hem i no kam klosap long hem, yufala i ting se hem i save mekenoes?"],[3,5,"“?Sipos man we i putum trap i no putum kakae long hem, yufala i ting se trap ya i save kasem faol? “?Sipos wan samting i no go insaed long trap ya, yufala i ting se trap ya i save jam?","“?Sipos man we i putum trap i no putum kakae long hem, yufala i ting se trap ya i save kasem faol? “?Sipos wan samting i no go insaed long trap ya, yufala i ting se trap ya i save jam?"],[3,6,"“?Sipos ol lida oli blu long pupu blong singaot ol man blong faet, yufala i ting se ol man blong ples ya oli no save fraet? “Taem trabol i kam kasem ol man long wan ples, be hemia Hae God nomo we i sanem i kam.","“?Sipos ol lida oli blu long pupu blong singaot ol man blong faet, yufala i ting se ol man blong ples ya oli no save fraet? “Taem trabol i kam kasem ol man long wan ples, be hemia Hae God nomo we i sanem i kam."],[3,7,"“Hae God i Masta* blong yumi, mo ol profet oli man blong wok blong hem, mo oltaem, sipos hem i wantem mekem wan samting, hem i stap soemaot ol plan blong hem fastaem long olgeta.","“Hae God i Masta* blong yumi, mo ol profet oli man blong wok blong hem, mo oltaem, sipos hem i wantem mekem wan samting, hem i stap soemaot ol plan blong hem fastaem long olgeta."],[3,8,"“?Sipos wan laeon i stap singaot bigwan, yufala i ting se ol man oli no save fraet long hem? “Hae God i Masta blong yumi, mo sipos hem i tok, ol profet blong hem oli mas go talemaot ol tok blong hem.”","“?Sipos wan laeon i stap singaot bigwan, yufala i ting se ol man oli no save fraet long hem? “Hae God i Masta blong yumi, mo sipos hem i tok, ol profet blong hem oli mas go talemaot ol tok blong hem.”"],[3,9,"Nao Profet Amos i talem se, “Naoia, yufala i go talemaot tok blong mi long ol haeman we oli stap long haos blong king blong Filistia long Asdod, mo long ol haos blong king blong Ijip. Yufala i go talem long olgeta se, ‘I gud yufala evriwan i kam long Sameria,* yufala i kam stap long ol hil raonabaot long taon ya. Nao bambae yufala i save luk we ol samting long ples ya i olbaot tumas, mo we plante man oli stap mekem i strong tumas long ol narafala man.’ ”","Nao Profet Amos i talem se, “Naoia, yufala i go talemaot tok blong mi long ol haeman we oli stap long haos blong king blong Filistia long Asdod, mo long ol haos blong king blong Ijip. Yufala i go talem long olgeta se, ‘I gud yufala evriwan i kam long Sameria,* yufala i kam stap long ol hil raonabaot long taon ya. Nao bambae yufala i save luk we ol samting long ples ya i olbaot tumas, mo we plante man oli stap mekem i strong tumas long ol narafala man.’ ”"],[3,10,"Mo hem i talemaot we Hae God i talem se, “Stret fasin i no stap nating long laef blong ol man Sameria. Oltaem oli stap stil, mo oli stap kilim man, nao ol haos blong olgeta i fulap gud long olting blong ol narafala man we oli stap kasem long fasin ya.","Mo hem i talemaot we Hae God i talem se, “Stret fasin i no stap nating long laef blong ol man Sameria. Oltaem oli stap stil, mo oli stap kilim man, nao ol haos blong olgeta i fulap gud long olting blong ol narafala man we oli stap kasem long fasin ya."],[3,11,"Be ol enemi bambae oli kam hivap raon long ples blong olgeta blong mekem faet long olgeta, nao bambae oli brekemdaon ol strong ples blong haed blong olgeta, mo bambae oli go insaed long ol haos ya blong olgeta, oli tekemaot olting ya blong olgeta, oli karem i go.","Be ol enemi bambae oli kam hivap raon long ples blong olgeta blong mekem faet long olgeta, nao bambae oli brekemdaon ol strong ples blong haed blong olgeta, mo bambae oli go insaed long ol haos ya blong olgeta, oli tekemaot olting ya blong olgeta, oli karem i go."],[3,12,"“Naoia, ol man Sameria oli stap slip gud long ol gudfala bed blong olgeta, be taem ol enemi ya oli aot long olgeta bakegen, bambae oli livim olgeta i stap, olsem sipsip we laeon i kakae, we taem man blong lukaot long sipsip i go faenem, i luk we tu leg blong hem nomo, no haf blong wan sora nomo blong hem i stap.","“Naoia, ol man Sameria oli stap slip gud long ol gudfala bed blong olgeta, be taem ol enemi ya oli aot long olgeta bakegen, bambae oli livim olgeta i stap, olsem sipsip we laeon i kakae, we taem man blong lukaot long sipsip i go faenem, i luk we tu leg blong hem nomo, no haf blong wan sora nomo blong hem i stap."],[3,13,"“Mi mi Hae God, mi Masta* blong olgeta man, mo mi gat olgeta paoa. Mo mi mi talem long yufala, se yufala i mas lesin gud long tok ya blong mi. Mo yufala i mas tok strong long ol laen* ya blong Jekob,* blong wekemap olgeta.","“Mi mi Hae God, mi Masta* blong olgeta man, mo mi gat olgeta paoa. Mo mi mi talem long yufala, se yufala i mas lesin gud long tok ya blong mi. Mo yufala i mas tok strong long ol laen* ya blong Jekob,* blong wekemap olgeta."],[3,14,"Long dei ya we mi bambae mi panisim olgeta, bambae mi spolem ol olta ya long Betel tu. Mo long evri olta, ol fo hon* ya we oli stap long ol fo kona blong olgeta, bambae mi katemaot olgeta oli foldaon i go long graon.","Long dei ya we mi bambae mi panisim olgeta, bambae mi spolem ol olta ya long Betel tu. Mo long evri olta, ol fo hon* ya we oli stap long ol fo kona blong olgeta, bambae mi katemaot olgeta oli foldaon i go long graon."],[3,15,"Ol haos ya blong olgeta we oli stap yusum long koltaem, wetem olgeta we oli stap yusum long hot taem, bambae mi spolem olgeta. Ol bigbigfala haos ya blong olgeta we oli flasem olgeta long tut blong elefen, be bambae mi spolem olgeta evriwan.”","Ol haos ya blong olgeta we oli stap yusum long koltaem, wetem olgeta we oli stap yusum long hot taem, bambae mi spolem olgeta. Ol bigbigfala haos ya blong olgeta we oli flasem olgeta long tut blong elefen, be bambae mi spolem olgeta evriwan.”"],[4,1,"Mo profet i talem se, “Ol rij woman blong Sameria. Yufala i mas lesin gud long tok blong mi. Oltaem yufala i stap spolem olgeta we oli no strong, mo yufala i stap mekem i strong tumas long ol puaman, mo oltaem, yufala i stap talem long ol man blong yufala blong oli stap givim waen long yufala. Nao from samting ya, yufala i kam fatfat gud olsem ol buluk blong ples ya Basan.","Mo profet i talem se, “Ol rij woman blong Sameria. Yufala i mas lesin gud long tok blong mi. Oltaem yufala i stap spolem olgeta we oli no strong, mo yufala i stap mekem i strong tumas long ol puaman, mo oltaem, yufala i stap talem long ol man blong yufala blong oli stap givim waen long yufala. Nao from samting ya, yufala i kam fatfat gud olsem ol buluk blong ples ya Basan."],[4,2,"Hae God i Masta blong yumi, mo hem i tabu, fasin blong hem i stret olgeta. Mo hem i promes finis se, ‘I gat dei blong yufala i stap kam we bambae ol enemi blong yufala oli kam hukum yufala long ol huk, oli pulum yufala i goaot long ples ya, yufala i go longwe. Bambae yufala evriwan i hang long ol huk ya olsem fis.","Hae God i Masta blong yumi, mo hem i tabu, fasin blong hem i stret olgeta. Mo hem i promes finis se, ‘I gat dei blong yufala i stap kam we bambae ol enemi blong yufala oli kam hukum yufala long ol huk, oli pulum yufala i goaot long ples ya, yufala i go longwe. Bambae yufala evriwan i hang long ol huk ya olsem fis."],[4,3,"Nao bambae oli pulum yufala i go long ol hol blong bigfala stonwol blong taon ya we oli stap klosap nomo, oli pulum yufala i gotru, yufala i go afsaed, long saed blong go long hil ya Hemon. Mi mi Hae God, mo hemia tok blong mi.’ ”","Nao bambae oli pulum yufala i go long ol hol blong bigfala stonwol blong taon ya we oli stap klosap nomo, oli pulum yufala i gotru, yufala i go afsaed, long saed blong go long hil ya Hemon. Mi mi Hae God, mo hemia tok blong mi.’ ”"],[4,4,"Mo Profet Amos i talemaot we Hae God i talem se, “Ol man Isrel.* Oltaem yufala i laekem tumas blong kam long tabu ples ya Betel blong mekem wosip, be ol wosip blong yufala, sin nomo. Yufala i laekem moa blong kam long tabu ples ya Gilgal blong mekem wosip long ples ya, be blong dabolem ol sin blong yufala nomo. Evri moning, yufala i stap tekem ol anamol blong yufala i kam blong mekem sakrefaes, be long fasin we i nogud olgeta. Mo evri tri dei, yufala i stap tekem ol taet* blong yufala i kam blong givim long mi, be long fasin we i no stret nating.","Mo Profet Amos i talemaot we Hae God i talem se, “Ol man Isrel.* Oltaem yufala i laekem tumas blong kam long tabu ples ya Betel blong mekem wosip, be ol wosip blong yufala, sin nomo. Yufala i laekem moa blong kam long tabu ples ya Gilgal blong mekem wosip long ples ya, be blong dabolem ol sin blong yufala nomo. Evri moning, yufala i stap tekem ol anamol blong yufala i kam blong mekem sakrefaes, be long fasin we i nogud olgeta. Mo evri tri dei, yufala i stap tekem ol taet* blong yufala i kam blong givim long mi, be long fasin we i no stret nating."],[4,5,"Taem yufala i givim bred i kam long mi blong talem tangkiu long mi, yufala i stap mekem sin nomo. Mo taem yufala i givim presen long mi we i ova long mak we Loa i putum, be yufala i girap, yufala i stap tok flas from. !Hemia nao fasin blong yufala stret! Mi mi Hae God, mi Masta* blong yufala, mo hemia tok blong mi.","Taem yufala i givim bred i kam long mi blong talem tangkiu long mi, yufala i stap mekem sin nomo. Mo taem yufala i givim presen long mi we i ova long mak we Loa i putum, be yufala i girap, yufala i stap tok flas from. !Hemia nao fasin blong yufala stret! Mi mi Hae God, mi Masta* blong yufala, mo hemia tok blong mi."],[4,6,"“Plante taem, long ol taon blong yufala, mi mi mekem we yufala i gat hadtaem blong kasem kakae, be yufala i no tanem tingting blong yufala nating, from ol rabis fasin ya blong yufala, blong kam long mi bakegen.","“Plante taem, long ol taon blong yufala, mi mi mekem we yufala i gat hadtaem blong kasem kakae, be yufala i no tanem tingting blong yufala nating, from ol rabis fasin ya blong yufala, blong kam long mi bakegen."],[4,7,"Mo long taem ya we yufala i wantem tumas blong ren i kam wasem ol garen blong yufala, be mi stap blokem ren blong i no kam. Oltaem, mi stap mekem we long sam taon i gat ren, be long samfala taon i no gat, mo long sam ples, ren i stap wasem ol garen, be long samfala ples, ol garen oli kam drae olgeta.","Mo long taem ya we yufala i wantem tumas blong ren i kam wasem ol garen blong yufala, be mi stap blokem ren blong i no kam. Oltaem, mi stap mekem we long sam taon i gat ren, be long samfala taon i no gat, mo long sam ples, ren i stap wasem ol garen, be long samfala ples, ol garen oli kam drae olgeta."],[4,8,"From ol samting ya, ol man blong samfala taon we oli hafded long tosta, oli stap traehad blong go long narafala taon blong lukaot wota, be taem oli faenem, wota ya i no naf blong mekem olgeta oli harem gud. !Be yufala i no tanem tingting blong yufala nating blong kambak long mi!","From ol samting ya, ol man blong samfala taon we oli hafded long tosta, oli stap traehad blong go long narafala taon blong lukaot wota, be taem oli faenem, wota ya i no naf blong mekem olgeta oli harem gud. !Be yufala i no tanem tingting blong yufala nating blong kambak long mi!"],[4,9,"“Bifo mi mekem win we i hot we i hot i kam bonem ol garen blong yufala, nao i mekem olgeta i drae. Taem yufala i putumgud ol kakae blong garen i stap, be mi mekem we olgeta oli kam nogud kwiktaem. Ol plantesen blong grep* wetem ol figtri,* mo ol tri ya olif* blong yufala, mi letem ol lokis* oli kam kakae olgeta. !Be yufala i no tanem tingting blong yufala nating blong kambak long mi bakegen!","“Bifo mi mekem win we i hot we i hot i kam bonem ol garen blong yufala, nao i mekem olgeta i drae. Taem yufala i putumgud ol kakae blong garen i stap, be mi mekem we olgeta oli kam nogud kwiktaem. Ol plantesen blong grep* wetem ol figtri,* mo ol tri ya olif* blong yufala, mi letem ol lokis* oli kam kakae olgeta. !Be yufala i no tanem tingting blong yufala nating blong kambak long mi bakegen!"],[4,10,"“Long taem ya, mi sanem wan rabis sik i kam long yufala we i sem mak long hemia we i kasem ol man Ijip bifo. Mo mi kilim olgeta yang man blong yufala evriwan i ded long taem blong faet, mo mi tekemaot ol hos blong yufala tu i gowe long yufala. Mi mekem we ples blong yufala i sting we i sting from ol dedman ya. !Be yufala i no tanem tingting blong yufala nating blong kambak long mi bakegen!","“Long taem ya, mi sanem wan rabis sik i kam long yufala we i sem mak long hemia we i kasem ol man Ijip bifo. Mo mi kilim olgeta yang man blong yufala evriwan i ded long taem blong faet, mo mi tekemaot ol hos blong yufala tu i gowe long yufala. Mi mekem we ples blong yufala i sting we i sting from ol dedman ya. !Be yufala i no tanem tingting blong yufala nating blong kambak long mi bakegen!"],[4,11,"“Sam long yufala, mi kilim olgeta i ded, stret olsem we bifo, mi kilim ol man blong tufala taon ya Sodom mo Gomora oli ded. Mo yufala we i stap laef yet, yufala i olsem wud we i go long faea, mo i laet, be biaen, man i pulumaot bakegen. !Be yufala i no tanem tingting blong yufala nating blong kambak long mi bakegen! Mi mi Hae God, mo hemia tok blong mi.","“Sam long yufala, mi kilim olgeta i ded, stret olsem we bifo, mi kilim ol man blong tufala taon ya Sodom mo Gomora oli ded. Mo yufala we i stap laef yet, yufala i olsem wud we i go long faea, mo i laet, be biaen, man i pulumaot bakegen. !Be yufala i no tanem tingting blong yufala nating blong kambak long mi bakegen! Mi mi Hae God, mo hemia tok blong mi."],[4,12,"“!Ol man Isrel! From ol samting ya, bambae mi mi panisimgud yufala. Mo from we mi bambae mi mekem olsem, yufala evriwan i mas mekemrere blong kam stanap long fes blong mi.”","“!Ol man Isrel! From ol samting ya, bambae mi mi panisimgud yufala. Mo from we mi bambae mi mekem olsem, yufala evriwan i mas mekemrere blong kam stanap long fes blong mi.”"],[4,13,"Nao profet i talem se, “God ya, hem nao i mekem ol hil, mo hem nomo i mekem win i blu. Hem i letem long ol man blong oli save tingting blong hem, mo hem i gat paoa blong mekem delaet i kam tudak. Hem i hae we i hae, mo hem i stap rul long olgeta ples long wol ya. Nem blong hem, ‘Hae God we i Gat Olgeta Paoa’, mo hem i God blong yumi.”","Nao profet i talem se, “God ya, hem nao i mekem ol hil, mo hem nomo i mekem win i blu. Hem i letem long ol man blong oli save tingting blong hem, mo hem i gat paoa blong mekem delaet i kam tudak. Hem i hae we i hae, mo hem i stap rul long olgeta ples long wol ya. Nem blong hem, ‘Hae God we i Gat Olgeta Paoa’, mo hem i God blong yumi.”"],[5,1,"Nao Profet Amos i talem se, “Ol man Isrel.* Bambae mi singim wan sing blong krae long dedman. Sing ya i blong krae long yufala. Yufala i mas lesin gud long hem.","Nao Profet Amos i talem se, “Ol man Isrel.* Bambae mi singim wan sing blong krae long dedman. Sing ya i blong krae long yufala. Yufala i mas lesin gud long hem."],[5,2,"!Isrel ooo! Yu yu wan kantri we yu gudfala tumas. Yu yu olsem wan gudfala gel we i no mekem wan samting nogud. Be ol enemi blong yu oli kilim yu yu ded. Yu yu ded olgeta, yu no save laef bakegen samtaem. Yu yu ded long graon ya blong yu nomo, mo i no gat man nating i save givhan long yu. !Isrel ooo!”","!Isrel ooo! Yu yu wan kantri we yu gudfala tumas. Yu yu olsem wan gudfala gel we i no mekem wan samting nogud. Be ol enemi blong yu oli kilim yu yu ded. Yu yu ded olgeta, yu no save laef bakegen samtaem. Yu yu ded long graon ya blong yu nomo, mo i no gat man nating i save givhan long yu. !Isrel ooo!”"],[5,3,"Mo profet i gohed i talem se, “Hae God i Masta* blong yumi, mo hem i talem se, ‘Wan taon long Isrel i sanemaot wan taosen soldia blong hem oli go faet, be i gat wan handred nomo oli kambak we oli no ded. Mo narafala taon i sanemaot wan handred soldia blong hem oli go, be i gat ten nomo oli kambak we oli no ded.","Mo profet i gohed i talem se, “Hae God i Masta* blong yumi, mo hem i talem se, ‘Wan taon long Isrel i sanemaot wan taosen soldia blong hem oli go faet, be i gat wan handred nomo oli kambak we oli no ded. Mo narafala taon i sanemaot wan handred soldia blong hem oli go, be i gat ten nomo oli kambak we oli no ded."],[5,4,"“ ‘Ol man Isrel. !Yufala i mas kambak long mi! Sipos yufala i kambak long mi, bambae yufala i save stap gud.","“ ‘Ol man Isrel. !Yufala i mas kambak long mi! Sipos yufala i kambak long mi, bambae yufala i save stap gud."],[5,5,"Be i nogud yufala i go long ples ya Bereseba blong mekem wosip long mi. Mo i nogud yufala i go joen wetem olgeta long ples ya Gilgal, from we olgeta ya bambae oli go wok slef* long narafala kantri. Mo i nogud yufala i stap lukaot mi long ples ya Betel, from we ples ya bambae i lus olgeta.","Be i nogud yufala i go long ples ya Bereseba blong mekem wosip long mi. Mo i nogud yufala i go joen wetem olgeta long ples ya Gilgal, from we olgeta ya bambae oli go wok slef* long narafala kantri. Mo i nogud yufala i stap lukaot mi long ples ya Betel, from we ples ya bambae i lus olgeta."],[5,6,"Sipos yufala i kambak long mi, bambae yufala i save stap gud. !Yufala i mas kambak long mi! Mi mi Hae God, mo hemia tok blong mi.’ ” Nao profet i talem se, “Be sipos yufala i no kambak long Hae God, bambae hem i kamdaon wantaem long yufala olsem faea, i kakae yufala. Faea ya bambae i finisim olgeta man Betel evriwan, mo bambae i no gat man we i save kilim.","Sipos yufala i kambak long mi, bambae yufala i save stap gud. !Yufala i mas kambak long mi! Mi mi Hae God, mo hemia tok blong mi.’ ” Nao profet i talem se, “Be sipos yufala i no kambak long Hae God, bambae hem i kamdaon wantaem long yufala olsem faea, i kakae yufala. Faea ya bambae i finisim olgeta man Betel evriwan, mo bambae i no gat man we i save kilim."],[5,7,"Fasin blong yufala i no stret nating. Oltaem yufala i stap tekem ol gudfala fasin, yufala i tanem i kam rabis fasin. Mo stret fasin blong jajem man long kot, i no gat nating long ples blong yufala. Mo from samting ya, Hae God bambae i jajem yufala.","Fasin blong yufala i no stret nating. Oltaem yufala i stap tekem ol gudfala fasin, yufala i tanem i kam rabis fasin. Mo stret fasin blong jajem man long kot, i no gat nating long ples blong yufala. Mo from samting ya, Hae God bambae i jajem yufala."],[5,8,"“Hae God ya, hem nomo i mekem olgeta sta long skae. Hem i mekem ol seven sta ya we nem blong olgeta Pleades,* mo i mekem narafala grup ya tu we nem blong hem Oraeon.* Hem i gat paoa blong mekem tudak i kam delaet, mo blong mekem dei i kam naet. Hem i gat paoa blong singaot solwota i go antap, i kam klaod, mo blong mekem i kam ren, i foldaon bakegen long wol ya. Hem i gat paoa blong spolemgud ol strong man blong wol ya, mo blong brekemdaon ol strong ples blong haed blong olgeta. Nem blong hem, Hae God.","“Hae God ya, hem nomo i mekem olgeta sta long skae. Hem i mekem ol seven sta ya we nem blong olgeta Pleades,* mo i mekem narafala grup ya tu we nem blong hem Oraeon.* Hem i gat paoa blong mekem tudak i kam delaet, mo blong mekem dei i kam naet. Hem i gat paoa blong singaot solwota i go antap, i kam klaod, mo blong mekem i kam ren, i foldaon bakegen long wol ya. Hem i gat paoa blong spolemgud ol strong man blong wol ya, mo blong brekemdaon ol strong ples blong haed blong olgeta. Nem blong hem, Hae God.",9],[5,10,"“Fasin blong yufala long kot, sipos wan man i girap, i tok strong long ol man we oli wantem pulum kot i go krangke, oltaem yufala i no laekem hem, yufala i agens long hem. Mo man we ol tok blong hem i tru, yufala i no laekem hem nating.","“Fasin blong yufala long kot, sipos wan man i girap, i tok strong long ol man we oli wantem pulum kot i go krangke, oltaem yufala i no laekem hem, yufala i agens long hem. Mo man we ol tok blong hem i tru, yufala i no laekem hem nating."],[5,11,"Oltaem, yufala i stap mekem i strong tumas long ol puaman. Yufala i stap ravem olgeta, mo yufala i stap stilim ol kakae blong olgeta. Nao from samting ya, ol gudgudfala haos we yufala i wokem long ston, neva bambae yufala i go stap long olgeta. Mo ol grep* blong yufala, neva bambae yufala i dring waen blong hem.","Oltaem, yufala i stap mekem i strong tumas long ol puaman. Yufala i stap ravem olgeta, mo yufala i stap stilim ol kakae blong olgeta. Nao from samting ya, ol gudgudfala haos we yufala i wokem long ston, neva bambae yufala i go stap long olgeta. Mo ol grep* blong yufala, neva bambae yufala i dring waen blong hem."],[5,12,"Mi mi savegud yufala. Plante taem yufala i stap brekem loa, mo ol sin blong yufala oli nogud we i nogud. Yufala i stap agens long ol stret man, yufala i stap ronem olgeta, be yufala i stap kasem mane long ol man nogud blong haedem ol rong blong olgeta. Yufala i stap blokem wok blong kot, blong man blong kot i no save jajem bisnes blong ol puaman long stret fasin.","Mi mi savegud yufala. Plante taem yufala i stap brekem loa, mo ol sin blong yufala oli nogud we i nogud. Yufala i stap agens long ol stret man, yufala i stap ronem olgeta, be yufala i stap kasem mane long ol man nogud blong haedem ol rong blong olgeta. Yufala i stap blokem wok blong kot, blong man blong kot i no save jajem bisnes blong ol puaman long stret fasin."],[5,13,"Man we yufala i agens long hem, sipos hem i gat hed, bambae hem i stap kwaet, i no tok, from we naoia, laef i strong, yufala ol man nogud i holem paoa.","Man we yufala i agens long hem, sipos hem i gat hed, bambae hem i stap kwaet, i no tok, from we naoia, laef i strong, yufala ol man nogud i holem paoa."],[5,14,"“Be yufala i mas lego ol rabis fasin, mo yufala i mas traehad blong folem stret fasin. Sipos yufala i mekem olsem, bambae yufala i gat longfala laef. Naoia yufala i stap talem se Hae God i God blong yufala, mo hem i gat olgeta paoa, mo hem i stap oltaem wetem yufala, be sipos yufala i stap mekem olsem we mi mi talem, oltaem bambae hem i stap wetem yufala tru.","“Be yufala i mas lego ol rabis fasin, mo yufala i mas traehad blong folem stret fasin. Sipos yufala i mekem olsem, bambae yufala i gat longfala laef. Naoia yufala i stap talem se Hae God i God blong yufala, mo hem i gat olgeta paoa, mo hem i stap oltaem wetem yufala, be sipos yufala i stap mekem olsem we mi mi talem, oltaem bambae hem i stap wetem yufala tru."],[5,15,"Fasin we i no stret, yufala i mas tanem baksaed long hem, be fasin we i stret, yufala i mas glad long hem, mo oltaem yufala i mas folem. Mo taem yufala i mekem kot, yufala i mas lukaot gud, blong kot i wok long stret fasin. Sipos yufala i mekem olsem, maet Hae God bambae i gat sore long haf blong yufala we bambae oli stap laef yet.","Fasin we i no stret, yufala i mas tanem baksaed long hem, be fasin we i stret, yufala i mas glad long hem, mo oltaem yufala i mas folem. Mo taem yufala i mekem kot, yufala i mas lukaot gud, blong kot i wok long stret fasin. Sipos yufala i mekem olsem, maet Hae God bambae i gat sore long haf blong yufala we bambae oli stap laef yet."],[5,16,"“Hae God i God blong yumi, mo hem i gat olgeta paoa, mo hem i talem se, ‘Mi bambae mi pas long medel blong yufala blong jajem yufala. Nao from samting ya, olbaot long ples blong yufala, bambae i gat fulap man oli stap krae bigwan from yufala. Olbaot long ol big rod, ol man bambae oli stap krae tumas se, “!O, sore tumas long yufala!” Ol man ya we wok blong olgeta i blong krae long ol dedman, bambae oli harem se oli no naf, nao bambae oli singaot i go long ol man blong wokem garen blong oli kam givhan long olgeta blong krae. Olbaot long ol plantesen blong grep, ol man blong plantesen tu bambae oli krae from yufala. Ol samting ya bambae i kamtru olsem, from we mi bambae mi jajem yufala. Mi mi Hae God, mo hemia tok blong mi.’ ”","“Hae God i God blong yumi, mo hem i gat olgeta paoa, mo hem i talem se, ‘Mi bambae mi pas long medel blong yufala blong jajem yufala. Nao from samting ya, olbaot long ples blong yufala, bambae i gat fulap man oli stap krae bigwan from yufala. Olbaot long ol big rod, ol man bambae oli stap krae tumas se, “!O, sore tumas long yufala!” Ol man ya we wok blong olgeta i blong krae long ol dedman, bambae oli harem se oli no naf, nao bambae oli singaot i go long ol man blong wokem garen blong oli kam givhan long olgeta blong krae. Olbaot long ol plantesen blong grep, ol man blong plantesen tu bambae oli krae from yufala. Ol samting ya bambae i kamtru olsem, from we mi bambae mi jajem yufala. Mi mi Hae God, mo hemia tok blong mi.’ ”",17],[5,18,"Nao profet i talem se, “!Be yufala ya we i wantem tumas blong luk Dei ya blong Hae God, sore tumas long yufala! ?Blong wanem yufala i ting se long dei ya bambae yufala i win? Dei ya bambae i taem blong tudak nomo long yufala, we bambae i no gat delaet nating long hem.","Nao profet i talem se, “!Be yufala ya we i wantem tumas blong luk Dei ya blong Hae God, sore tumas long yufala! ?Blong wanem yufala i ting se long dei ya bambae yufala i win? Dei ya bambae i taem blong tudak nomo long yufala, we bambae i no gat delaet nating long hem."],[5,19,"Long dei ya, bambae i olsem we man i ronwe long wan laeon, nao taem i stap resis i go, be i sek long wan bea we i stap stret long fes blong hem. No i olsem man we i kambak long haos blong hem, nao i lei long wol blong haos blong i spel smol, be wantaem nomo, wan posen snek i kakae han blong hem.","Long dei ya, bambae i olsem we man i ronwe long wan laeon, nao taem i stap resis i go, be i sek long wan bea we i stap stret long fes blong hem. No i olsem man we i kambak long haos blong hem, nao i lei long wol blong haos blong i spel smol, be wantaem nomo, wan posen snek i kakae han blong hem."],[5,20,"Long bigfala Dei ya blong Hae God, bambae i gat tudak nomo, bambae i no gat delaet nating i kamtru. Long dei ya, bambae ol man oli stap harem nogud nomo, bambae i no gat wan samting nating blong mekem man i harem gud.”","Long bigfala Dei ya blong Hae God, bambae i gat tudak nomo, bambae i no gat delaet nating i kamtru. Long dei ya, bambae ol man oli stap harem nogud nomo, bambae i no gat wan samting nating blong mekem man i harem gud.”"],[5,21,"Mo hem i talemaot we Hae God i talem se, “Mi mi no laekem nating ol lafet ya blong yufala blong mekem wosip long mi, mi no wantem luk olgeta nating.","Mo hem i talemaot we Hae God i talem se, “Mi mi no laekem nating ol lafet ya blong yufala blong mekem wosip long mi, mi no wantem luk olgeta nating."],[5,22,"Ol sakrefaes ya blong yufala we yufala i bonem anamol i bon evriwan blong mekem wosip long mi, mo ol presen long kakae blong garen we yufala i givim i kam long mi, bambae mi no save tekem olgeta. Nating we yufala i tekem ol anamol ya we yufala i stap fidim olgeta i fatfat gud, nao yufala i kilim olgeta blong mekem sakrefaes long mi, be bambae mi no save glad long olgeta.","Ol sakrefaes ya blong yufala we yufala i bonem anamol i bon evriwan blong mekem wosip long mi, mo ol presen long kakae blong garen we yufala i givim i kam long mi, bambae mi no save tekem olgeta. Nating we yufala i tekem ol anamol ya we yufala i stap fidim olgeta i fatfat gud, nao yufala i kilim olgeta blong mekem sakrefaes long mi, be bambae mi no save glad long olgeta."],[5,23,"Yufala i stap sing bigwan blong presem mi, mo yufala i stap plei gita blong mekem wosip long mi, be mi mi no wantem ol samting ya.","Yufala i stap sing bigwan blong presem mi, mo yufala i stap plei gita blong mekem wosip long mi, be mi mi no wantem ol samting ya."],[5,24,"Mi mi wantem we stret fasin blong jajem man bambae i stap oltaem long medel blong yufala, olsem wan springwota. Mo mi wantem we fasin ya we man i mekem i stret long narafala man, bambae i stap oltaem long laef blong yufala, olsem wan bigfala reva we i ron oltaem, i no save drae.”","Mi mi wantem we stret fasin blong jajem man bambae i stap oltaem long medel blong yufala, olsem wan springwota. Mo mi wantem we fasin ya we man i mekem i stret long narafala man, bambae i stap oltaem long laef blong yufala, olsem wan bigfala reva we i ron oltaem, i no save drae.”"],[5,25,"“Ol man Isrel. Long foti yia ya we mi mi stap lidim ol bubu blong yufala bifo long draeples, be mi no talem long olgeta blong oli kilim anamol, oli bonem blong mekem wosip long mi, mo mi no talem long olgeta blong oli kam givim presen long mi, nogat.","“Ol man Isrel. Long foti yia ya we mi mi stap lidim ol bubu blong yufala bifo long draeples, be mi no talem long olgeta blong oli kilim anamol, oli bonem blong mekem wosip long mi, mo mi no talem long olgeta blong oli kam givim presen long mi, nogat."],[5,26,"Be yufala i girap, yufala i go mekem wosip long god ya Sakut we i kam olsem king blong yufala, mo yufala i mekem wosip tu long god ya Kaewan we i sta nomo.","Be yufala i girap, yufala i go mekem wosip long god ya Sakut we i kam olsem king blong yufala, mo yufala i mekem wosip tu long god ya Kaewan we i sta nomo."],[5,27,"Nao from samting ya, long taem ya we bambae mi tekemaot yufala i go wok slef long kantri ya long narasaed Damaskes i go, be bambae mi mekem yufala i karem pija blong tufala god ya i go wetem yufala. Nem blong mi, Hae God we i Gat Olgeta Paoa. Mi mi God blong yufala, mo hemia tok blong mi.”","Nao from samting ya, long taem ya we bambae mi tekemaot yufala i go wok slef long kantri ya long narasaed Damaskes i go, be bambae mi mekem yufala i karem pija blong tufala god ya i go wetem yufala. Nem blong mi, Hae God we i Gat Olgeta Paoa. Mi mi God blong yufala, mo hemia tok blong mi.”"],[6,1,"Nao Profet Amos i talem se, “Ol laen* blong Isrel.* !Yufala we i stap long tabu hil ya Saeon,* we yufala i gat gudfala laef, mo yufala i ting se evri samting i oraet nomo, sore tumas long yufala! !Mo yufala ol man Sameria,* we yufala i harem se yufala i stap gud, sore tumas long yufala! !Yufala i hae moa, i winim ol narafala man long kantri ya Isrel, we hem i wan strong kantri, mo ol man blong yufala oli stap kam long yufala blong yufala i givhan long olgeta, be sore tumas long yufala!","Nao Profet Amos i talem se, “Ol laen* blong Isrel.* !Yufala we i stap long tabu hil ya Saeon,* we yufala i gat gudfala laef, mo yufala i ting se evri samting i oraet nomo, sore tumas long yufala! !Mo yufala ol man Sameria,* we yufala i harem se yufala i stap gud, sore tumas long yufala! !Yufala i hae moa, i winim ol narafala man long kantri ya Isrel, we hem i wan strong kantri, mo ol man blong yufala oli stap kam long yufala blong yufala i givhan long olgeta, be sore tumas long yufala!"],[6,2,"Yufala i stap leftemap tingting blong ol man blong yufala long tok ya se, ‘I gud yufala i traem go luk taon ya Kalnei, mo yufala i go luk bigfala taon ya Hamat, mo biaen, yufala i go luk bigfala taon ya Gat long Filistia. Bambae yufala i luksave wantaem nomo. Ol man blong ol ples ya oli no strong olsem yumi ya long Isrel, mo long Juda.* Ol graon blong olgeta ya oli no bigwan, olsem ol graon ya blong yumi.’","Yufala i stap leftemap tingting blong ol man blong yufala long tok ya se, ‘I gud yufala i traem go luk taon ya Kalnei, mo yufala i go luk bigfala taon ya Hamat, mo biaen, yufala i go luk bigfala taon ya Gat long Filistia. Bambae yufala i luksave wantaem nomo. Ol man blong ol ples ya oli no strong olsem yumi ya long Isrel, mo long Juda.* Ol graon blong olgeta ya oli no bigwan, olsem ol graon ya blong yumi.’"],[6,3,"Be yufala i no wantem talemaot se i gat dei i stap kam we ol man blong faet bambae oli kam flatemgud yumi. Ol fasin ya blong yufala i stap pulum dei ya i kam klosap moa.","Be yufala i no wantem talemaot se i gat dei i stap kam we ol man blong faet bambae oli kam flatemgud yumi. Ol fasin ya blong yufala i stap pulum dei ya i kam klosap moa."],[6,4,"“!Yufala ya we yufala i stap lafet olwe nomo, sore tumas long yufala! Yufala i stap ledaon long ol bed ya blong yufala we oli flasemgud long tut blong elefen, mo yufala i stap kakae mit blong ol yang buluk mo sipsip, we praes blong ol samting ya i antap tumas, be sore tumas long yufala.","“!Yufala ya we yufala i stap lafet olwe nomo, sore tumas long yufala! Yufala i stap ledaon long ol bed ya blong yufala we oli flasemgud long tut blong elefen, mo yufala i stap kakae mit blong ol yang buluk mo sipsip, we praes blong ol samting ya i antap tumas, be sore tumas long yufala."],[6,5,"Yufala i wantem tumas blong kam man blong wokem singsing, olsem King Deved ya bifo, mo oltaem yufala i stap plei long ol gita blong sing long ol singsing ya.","Yufala i wantem tumas blong kam man blong wokem singsing, olsem King Deved ya bifo, mo oltaem yufala i stap plei long ol gita blong sing long ol singsing ya."],[6,6,"Yufala i stap yusum ol bigbigfala panikin blong dring waen, mo yufala i stap yusum ol gudgudfala oel blong ravem long bodi blong yufala. Be yufala i no stap harem nogud nating from kantri ya Isrel we bambae i kasem panis, i kam nogud olgeta.","Yufala i stap yusum ol bigbigfala panikin blong dring waen, mo yufala i stap yusum ol gudgudfala oel blong ravem long bodi blong yufala. Be yufala i no stap harem nogud nating from kantri ya Isrel we bambae i kasem panis, i kam nogud olgeta."],[6,7,"Nao from samting ya, yufala ya nao bambae i faswan blong go wok slef* long narafala kantri. Mo ol lafet blong yufala we yufala i stap harem gud long hem, bambae i finis olgeta.","Nao from samting ya, yufala ya nao bambae i faswan blong go wok slef* long narafala kantri. Mo ol lafet blong yufala we yufala i stap harem gud long hem, bambae i finis olgeta."],[6,8,"“Hae God, Masta* blong yumi, hem i gat olgeta paoa, mo hem i mekem wan strong promes* finis blong panisim yufala. Hem i talem se, ‘Ol man Isrel. Fasin ya blong yufala we yufala i stap flas tumas, mi mi no laekem nating, mi agens long hem. Ol gudgudfala haos ya blong yufala, mi mi no glad nating long olgeta. Bigfala taon ya we i kaptel blong yufala wetem olgeta samting we i stap long hem, mi bambae mi putum olgeta evriwan i go long han blong ol enemi blong yufala.’ ”","“Hae God, Masta* blong yumi, hem i gat olgeta paoa, mo hem i mekem wan strong promes* finis blong panisim yufala. Hem i talem se, ‘Ol man Isrel. Fasin ya blong yufala we yufala i stap flas tumas, mi mi no laekem nating, mi agens long hem. Ol gudgudfala haos ya blong yufala, mi mi no glad nating long olgeta. Bigfala taon ya we i kaptel blong yufala wetem olgeta samting we i stap long hem, mi bambae mi putum olgeta evriwan i go long han blong ol enemi blong yufala.’ ”"],[6,9,"Nao profet i talem se, “Sipos i gat ten man oli go haed long wan haos, be olgeta ya bambae oli ded evriwan.","Nao profet i talem se, “Sipos i gat ten man oli go haed long wan haos, be olgeta ya bambae oli ded evriwan."],[6,10,"Nao sipos wan man olsem i ded, mo wan famle blong hem i kam wetem man blong berem dedman, blong tufala i berem hem, maet famle ya blong dedman i save singaot se, ‘!E! ?Olsem wanem? ?I gat man i stap yet wetem yu, no i no gat?’ Nao sipos man ya i talem se, ‘!No, i no gat!’, be famle blong dedman ya bambae i talem se, ‘Ssss. Yu stap kwaet. Yumi no mas talem nem blong Hae God. I nogud hem i harem yumi.’","Nao sipos wan man olsem i ded, mo wan famle blong hem i kam wetem man blong berem dedman, blong tufala i berem hem, maet famle ya blong dedman i save singaot se, ‘!E! ?Olsem wanem? ?I gat man i stap yet wetem yu, no i no gat?’ Nao sipos man ya i talem se, ‘!No, i no gat!’, be famle blong dedman ya bambae i talem se, ‘Ssss. Yu stap kwaet. Yumi no mas talem nem blong Hae God. I nogud hem i harem yumi.’"],[6,11,"“Yufala i mas save. Sipos Hae God i tok strong, bambae ol bigbigfala haos oli folfoldaon oli smas, mo ol smosmol haos bambae oli brobrok olbaot.","“Yufala i mas save. Sipos Hae God i tok strong, bambae ol bigbigfala haos oli folfoldaon oli smas, mo ol smosmol haos bambae oli brobrok olbaot."],[6,12,"Yufala i traem tingbaot. ?Samtaem, yufala i luk we hos i stap resis long ol sap ston? ?Samtaem yufala i luk we man i go digim solwota blong planem garen blong hem long hem? Neva man i save mekem samting ya. Be hemia nao ol samting we yufala i stap mekem. Ol stret fasin, yufala i tanem i kam olsem posen, mo ol stret fasin blong mekem wok blong kot, yufala i tanem i kam krangke olgeta.","Yufala i traem tingbaot. ?Samtaem, yufala i luk we hos i stap resis long ol sap ston? ?Samtaem yufala i luk we man i go digim solwota blong planem garen blong hem long hem? Neva man i save mekem samting ya. Be hemia nao ol samting we yufala i stap mekem. Ol stret fasin, yufala i tanem i kam olsem posen, mo ol stret fasin blong mekem wok blong kot, yufala i tanem i kam krangke olgeta."],[6,13,"“Oltaem yufala i stap bigmaot, yufala i stap talem se yufala i holem taon ya Lodebara finis. Oltaem yufala i stap tok flas se, ‘Mifala i strong, mifala i winim ol man blong taon ya Kanaem Hfinis.’","“Oltaem yufala i stap bigmaot, yufala i stap talem se yufala i holem taon ya Lodebara finis. Oltaem yufala i stap tok flas se, ‘Mifala i strong, mifala i winim ol man blong taon ya Kanaem Hfinis.’"],[6,14,"“Be Hae God i gat olgeta paoa, mo hem i talem se, ‘Ol man Isrel. !Yufala i lesin! Mi bambae mi tekem ol soldia blong narafala kantri oli kam winim yufala, nao bambae oli holem evri haf blong kantri ya blong yufala, i stat long ples ya we rod i gotru long ol hil, long Hamat long not, i go olwe kasem reva ya Araba, long saot.’ ”","“Be Hae God i gat olgeta paoa, mo hem i talem se, ‘Ol man Isrel. !Yufala i lesin! Mi bambae mi tekem ol soldia blong narafala kantri oli kam winim yufala, nao bambae oli holem evri haf blong kantri ya blong yufala, i stat long ples ya we rod i gotru long ol hil, long Hamat long not, i go olwe kasem reva ya Araba, long saot.’ ”"],[7,1,"Nao Profet Amos i talem se, “Hae God we i Masta* blong yumi, hem i soemaot wan vison* long mi. Long taem ya, ol man blong king oli katem gras finis, blong ol anamol blong king oli save kakae long koltaem, mo gras i stat gru bakegen. Long vison ya, mi mi luk we Hae God i mekem ol lokis* i kamaot, oli kakae ol niufala gras ya,","Nao Profet Amos i talem se, “Hae God we i Masta* blong yumi, hem i soemaot wan vison* long mi. Long taem ya, ol man blong king oli katem gras finis, blong ol anamol blong king oli save kakae long koltaem, mo gras i stat gru bakegen. Long vison ya, mi mi luk we Hae God i mekem ol lokis* i kamaot, oli kakae ol niufala gras ya,"],[7,2,"gogo oli finisimgud olgeta samting we i stap gru long ples ya. Nao mi mi talem se, ‘Hae God. Yu yu Masta blong mifala. Plis yu fogivim ol man Isrel* ya. Olgeta oli man blong yu, oli laen* blong Jekob,* we i stamba blong mifala evriwan. ?Bambae oli save stap gud olsem wanem? Olgeta oli no plante ya.’","gogo oli finisimgud olgeta samting we i stap gru long ples ya. Nao mi mi talem se, ‘Hae God. Yu yu Masta blong mifala. Plis yu fogivim ol man Isrel* ya. Olgeta oli man blong yu, oli laen* blong Jekob,* we i stamba blong mifala evriwan. ?Bambae oli save stap gud olsem wanem? Olgeta oli no plante ya.’"],[7,3,"Nao Hae God i jenisim tingting blong hem, i talem se, ‘Oraet. Samting ya we yu yu luk, bambae i no save kamtru olsem.’","Nao Hae God i jenisim tingting blong hem, i talem se, ‘Oraet. Samting ya we yu yu luk, bambae i no save kamtru olsem.’"],[7,4,"“Mo biaen, hem i soemaot wan narafala vison long mi bakegen. Long vison ya, mi luk wan bigfala faea we Hae God i mekemrere, blong i bonem ol man blong hem blong panisim olgeta. Dip solwota ya we i godaon olgeta, be bigfala faea ya i bonem evriwan finis, mo mi luk we i jes stat bakegen blong kakae ol graon.","“Mo biaen, hem i soemaot wan narafala vison long mi bakegen. Long vison ya, mi luk wan bigfala faea we Hae God i mekemrere, blong i bonem ol man blong hem blong panisim olgeta. Dip solwota ya we i godaon olgeta, be bigfala faea ya i bonem evriwan finis, mo mi luk we i jes stat bakegen blong kakae ol graon."],[7,5,"Nao mi mi talem se, ‘Hae God. Yu yu Masta blong mifala. Plis yu kilim faea ya. Olgeta ya oli man blong yu. ?Bambae oli save stap gud olsem wanem? Olgeta oli no plante ya.’","Nao mi mi talem se, ‘Hae God. Yu yu Masta blong mifala. Plis yu kilim faea ya. Olgeta ya oli man blong yu. ?Bambae oli save stap gud olsem wanem? Olgeta oli no plante ya.’"],[7,6,"Nao hem i jenisim tingting blong hem bakegen, i talem se, ‘Oraet. Samting ya tu bambae i no save kamtru olsem.’","Nao hem i jenisim tingting blong hem bakegen, i talem se, ‘Oraet. Samting ya tu bambae i no save kamtru olsem.’"],[7,7,"“Bakegen mi luk wan narafala vison, we Hae God i soemaot long mi. Long vison ya, mi luk we hem i stap stanap klosap long wan stonwol, we taem oli wokem stonwol ya fastaem, oli yusum ledlaen blong makem se i stret. Mo mi luk we hem i stap holem wan ledlaen,","“Bakegen mi luk wan narafala vison, we Hae God i soemaot long mi. Long vison ya, mi luk we hem i stap stanap klosap long wan stonwol, we taem oli wokem stonwol ya fastaem, oli yusum ledlaen blong makem se i stret. Mo mi luk we hem i stap holem wan ledlaen,"],[7,8,"nao hem i askem long mi se, ‘Amos. ?Yu save samting ya we mi stap holem?’ Nao mi talem se, ‘Yes, wan ledlaen ya.’ Nao hem i talem long mi se, ‘Samting ya, mi stap yusum blong soemaot long ol man blong mi, we oli olsem stonwol ya we i no stanap stret. Mi mi no save jenisim tingting blong mi bakegen. Bambae mi mas panisim olgeta.","nao hem i askem long mi se, ‘Amos. ?Yu save samting ya we mi stap holem?’ Nao mi talem se, ‘Yes, wan ledlaen ya.’ Nao hem i talem long mi se, ‘Samting ya, mi stap yusum blong soemaot long ol man blong mi, we oli olsem stonwol ya we i no stanap stret. Mi mi no save jenisim tingting blong mi bakegen. Bambae mi mas panisim olgeta."],[7,9,"Ol man Isrel ya oli laen blong Aesak, be ol tabu ples ya olbaot antap long ol hil we oli stap go blong mekem wosip long hem, mi bambae mi flatemdaon evriwan. Mo olgeta we bambae oli kamaot biaen long King Jeroboam, bambae mi kilim olgeta evriwan i ded.’ ”","Ol man Isrel ya oli laen blong Aesak, be ol tabu ples ya olbaot antap long ol hil we oli stap go blong mekem wosip long hem, mi bambae mi flatemdaon evriwan. Mo olgeta we bambae oli kamaot biaen long King Jeroboam, bambae mi kilim olgeta evriwan i ded.’ ”"],[7,10,"Nao pris* ya Amajia we i pris long ples ya blong mekem wosip long Betel, hem i sanem tok i go long King Jeroboam we i king blong ol man Isrel* blong ripotem Profet Amos. Hem i talem se, “Naoia, Profet Amos i stap pulum ol man ples, blong oli mekem plan blong spolem yu. Mo ol tok we hem i stap talem, bambae i spolemgud kantri ya blong yumi.","Nao pris* ya Amajia we i pris long ples ya blong mekem wosip long Betel, hem i sanem tok i go long King Jeroboam we i king blong ol man Isrel* blong ripotem Profet Amos. Hem i talem se, “Naoia, Profet Amos i stap pulum ol man ples, blong oli mekem plan blong spolem yu. Mo ol tok we hem i stap talem, bambae i spolemgud kantri ya blong yumi."],[7,11,"Hem i stap talem se, ‘King Jeroboam bambae i ded long taem blong faet, mo yufala ya tu, ol enemi blong yufala bambae oli kam tekemaot yufala i go wok slef* long narafala kantri.’ ”","Hem i stap talem se, ‘King Jeroboam bambae i ded long taem blong faet, mo yufala ya tu, ol enemi blong yufala bambae oli kam tekemaot yufala i go wok slef* long narafala kantri.’ ”"],[7,12,"Nao pris ya i kam luk profet ya, i talem long hem se, “Profet. I gud yu hareap, yu gobak long Juda,* yu go talemaot tok blong yu long ol man ples blong yu, nao olgeta bambae oli save pem yu from.","Nao pris ya i kam luk profet ya, i talem long hem se, “Profet. I gud yu hareap, yu gobak long Juda,* yu go talemaot tok blong yu long ol man ples blong yu, nao olgeta bambae oli save pem yu from."],[7,13,"I nogud yu stap long ples ya, from we Betel i ples blong mekem wosip blong king.”","I nogud yu stap long ples ya, from we Betel i ples blong mekem wosip blong king.”"],[7,14,"Be profet i talem se, “Mi mi no wan long ol profet ya, we taem oli talemaot tok blong olgeta, be ol man oli mas pem olgeta from. Mi mi wan man blong lukaot long ol buluk mo sipsip, mo mi gat plantesen blong figtri* blong mi, we mi stap lukaot bifo.","Be profet i talem se, “Mi mi no wan long ol profet ya, we taem oli talemaot tok blong olgeta, be ol man oli mas pem olgeta from. Mi mi wan man blong lukaot long ol buluk mo sipsip, mo mi gat plantesen blong figtri* blong mi, we mi stap lukaot bifo."],[7,15,"Be Hae God i tekemaot mi long wok ya, mo hem i talem strong long mi blong mi kam talemaot tok blong hem long yufala long Isrel, from we yufala i man blong hem.","Be Hae God i tekemaot mi long wok ya, mo hem i talem strong long mi blong mi kam talemaot tok blong hem long yufala long Isrel, from we yufala i man blong hem."],[7,16,"Amajia. !Yu lesin gud! Bambae mi talemaot long yu tok ya we Hae God i talem long mi. Yu yu wantem blokem mi blong mi no moa talemaot tok blong hem, mo blong mi no moa prij agens long yufala long Isrel.","Amajia. !Yu lesin gud! Bambae mi talemaot long yu tok ya we Hae God i talem long mi. Yu yu wantem blokem mi blong mi no moa talemaot tok blong hem, mo blong mi no moa prij agens long yufala long Isrel."],[7,17,"Be Hae God i talem se, ‘Woman blong yu bambae i kam woman blong rod, mo ol pikinini blong yutufala bambae oli ded evriwan long taem blong faet. Ol graon blong yu, bambae ol narafala man oli seraot i go long olgeta, mo yu bambae yu ded long kantri blong narafala man. Mo ol man Isrel evriwan, bambae ol enemi blong yufala oli kam tekemaot olgeta oli go wok slef long ples blong olgeta.’ ”","Be Hae God i talem se, ‘Woman blong yu bambae i kam woman blong rod, mo ol pikinini blong yutufala bambae oli ded evriwan long taem blong faet. Ol graon blong yu, bambae ol narafala man oli seraot i go long olgeta, mo yu bambae yu ded long kantri blong narafala man. Mo ol man Isrel evriwan, bambae ol enemi blong yufala oli kam tekemaot olgeta oli go wok slef long ples blong olgeta.’ ”"],[8,1,"Nao Profet Amos i talem se, “Mi mi luk wan narafala vison* bakegen we Hae God we i Masta* blong yumi i soemaot long mi. Long vison ya, mi luk wan bigfala basket we i fulap long frut,","Nao Profet Amos i talem se, “Mi mi luk wan narafala vison* bakegen we Hae God we i Masta* blong yumi i soemaot long mi. Long vison ya, mi luk wan bigfala basket we i fulap long frut,"],[8,2,"mo Hae God i askem long mi se, ‘Amos. ?Yu save samting ya?’ Mo mi talem se, ‘Yes, wan basket frut ya.’ Nao hem i talem long mi se, ‘Yes. Mo hemia i min se nating we ol man Isrel* ya oli man blong mi, be naoia i taem blong olgeta blong oli lus. Bambae mi mi no save jenisim tingting blong mi bakegen, mi mas panisim olgeta, olsem we mi talem finis.","mo Hae God i askem long mi se, ‘Amos. ?Yu save samting ya?’ Mo mi talem se, ‘Yes, wan basket frut ya.’ Nao hem i talem long mi se, ‘Yes. Mo hemia i min se nating we ol man Isrel* ya oli man blong mi, be naoia i taem blong olgeta blong oli lus. Bambae mi mi no save jenisim tingting blong mi bakegen, mi mas panisim olgeta, olsem we mi talem finis."],[8,3,"Long taem ya, ol woman ya we oltaem oli stap singsing blong mekem king i glad, oli no moa save singsing, bambae oli stap krae nomo. Nao ples ya blong yufala bambae i kam fulap long ol dedbodi blong yufala, mo bambae yufala i jes sakem olgeta oli go afsaed long taon nomo, we bambae yufala i no save mekenoes nating.’ ”","Long taem ya, ol woman ya we oltaem oli stap singsing blong mekem king i glad, oli no moa save singsing, bambae oli stap krae nomo. Nao ples ya blong yufala bambae i kam fulap long ol dedbodi blong yufala, mo bambae yufala i jes sakem olgeta oli go afsaed long taon nomo, we bambae yufala i no save mekenoes nating.’ ”"],[8,4,"Nao Profet Amos i talem se, “Ol bisnesman. !Yufala i lesin gud long tok blong mi! Fasin blong yufala, oltaem yufala i stap mekem i strong tumas long ol puaman, mo yufala i stap traem blong spolem olgeta we oli no gat paoa.","Nao Profet Amos i talem se, “Ol bisnesman. !Yufala i lesin gud long tok blong mi! Fasin blong yufala, oltaem yufala i stap mekem i strong tumas long ol puaman, mo yufala i stap traem blong spolem olgeta we oli no gat paoa."],[8,5,"Oltaem yufala i stap taltalem long yufala se, ‘?Ol tabu dei ya bambae i finis wetaem, blong yumi save go salem ol wit* blong yumi? !Sabat dei* ya i longfala tumas! !I gud i finis kwik, blong yumi save go salem olting blong yumi bakegen! !Ol giaman lita mo ol giaman skel ya blong yumi i stap finis! !Bambae yumi giaman gud long olgeta! !Yumi save leftemap praes blong ol samting i go antap moa, nao bambae yumi save stil gud long olgeta!","Oltaem yufala i stap taltalem long yufala se, ‘?Ol tabu dei ya bambae i finis wetaem, blong yumi save go salem ol wit* blong yumi? !Sabat dei* ya i longfala tumas! !I gud i finis kwik, blong yumi save go salem olting blong yumi bakegen! !Ol giaman lita mo ol giaman skel ya blong yumi i stap finis! !Bambae yumi giaman gud long olgeta! !Yumi save leftemap praes blong ol samting i go antap moa, nao bambae yumi save stil gud long olgeta!"],[8,6,"!Ol wit ya blong yumi we i nogud finis be bambae yumi leftemap praes blong olgeta! Ol puaman ya oli trabol gud. Olgeta oli no save pem ol kaon blong olgeta, mo oli no gat mane nating blong pem sandel blong olgeta, be bambae yumi givim sandel long olgeta, mo yumi pem ol kaon blong olgeta, blong fosem olgeta blong oli kam slef* blong yumi.’","!Ol wit ya blong yumi we i nogud finis be bambae yumi leftemap praes blong olgeta! Ol puaman ya oli trabol gud. Olgeta oli no save pem ol kaon blong olgeta, mo oli no gat mane nating blong pem sandel blong olgeta, be bambae yumi givim sandel long olgeta, mo yumi pem ol kaon blong olgeta, blong fosem olgeta blong oli kam slef* blong yumi.’"],[8,7,"“Ol man Isrel.* Hae God i God blong yumi, mo hem i mekem wan strong promes finis long yufala se, ‘Ol rabis fasin ya blong yufala, mi bambae mi no save fogetem olgeta samtaem.","“Ol man Isrel.* Hae God i God blong yumi, mo hem i mekem wan strong promes finis long yufala se, ‘Ol rabis fasin ya blong yufala, mi bambae mi no save fogetem olgeta samtaem."],[8,8,"Olbaot long kantri ya, bambae i gat etkwek, nao bambae yufala evriwan i kasem plante trabol from samting ya. Long evri ples, graon bambae i kam antap, i godaon, i kam antap, i godaon, olsem we long taem blong taedelwef, solwota i stap kam antap, i godaon.","Olbaot long kantri ya, bambae i gat etkwek, nao bambae yufala evriwan i kasem plante trabol from samting ya. Long evri ples, graon bambae i kam antap, i godaon, i kam antap, i godaon, olsem we long taem blong taedelwef, solwota i stap kam antap, i godaon."],[8,9,"Mi mi Hae God, mi Masta* blong yufala, mo mi talem stret long yufala, se i gat taem i stap kam we bambae mi mi mekem san i godaon nomo long medel dei, nao olgeta ples long wol ya bambae i kam tudak.","Mi mi Hae God, mi Masta* blong yufala, mo mi talem stret long yufala, se i gat taem i stap kam we bambae mi mi mekem san i godaon nomo long medel dei, nao olgeta ples long wol ya bambae i kam tudak."],[8,10,"Ol dei blong lafet blong yufala, bambae mi mekem i kam dei blong berem dedman. Mo ol sing ya blong mekem yufala i glad, bambae mi jenisim olgeta oli kam sing blong krae long dedman. Bambae mi mekem we yufala i pulum resa long hed blong yufala, mo yufala i stap werem ol rabis klos nomo, blong soemaot we yufala i stap harem nogud. Bambae mi mekem we yufala i kam olsem man wetem woman blong hem, we tufala i stap harem nogud tumas from we pikinini blong tufala i ded, we hem i wan pikinini nomo we tufala i gat. !Dei ya bambae i nogud we i nogud! Mi mi Hae God, mo hemia tok blong mi.","Ol dei blong lafet blong yufala, bambae mi mekem i kam dei blong berem dedman. Mo ol sing ya blong mekem yufala i glad, bambae mi jenisim olgeta oli kam sing blong krae long dedman. Bambae mi mekem we yufala i pulum resa long hed blong yufala, mo yufala i stap werem ol rabis klos nomo, blong soemaot we yufala i stap harem nogud. Bambae mi mekem we yufala i kam olsem man wetem woman blong hem, we tufala i stap harem nogud tumas from we pikinini blong tufala i ded, we hem i wan pikinini nomo we tufala i gat. !Dei ya bambae i nogud we i nogud! Mi mi Hae God, mo hemia tok blong mi."],[8,11,"“ ‘I gat taem i stap kam we bambae mi mekem we yufala i gat hadtaem blong kasem kakae. Bambae yufala i hanggri tumas, mo yufala i tosta tumas, be i no from wota. Long taem ya, bambae yufala i wantem tumas blong harem tok blong mi, olsem we man we i hanggri tumas i wantem kakae, mo man we i tosta tumas i wantem dring.","“ ‘I gat taem i stap kam we bambae mi mekem we yufala i gat hadtaem blong kasem kakae. Bambae yufala i hanggri tumas, mo yufala i tosta tumas, be i no from wota. Long taem ya, bambae yufala i wantem tumas blong harem tok blong mi, olsem we man we i hanggri tumas i wantem kakae, mo man we i tosta tumas i wantem dring."],[8,12,"Long taem ya, bambae yufala i stap go olbaot blong harem tok blong mi. Olgeta long not bambae oli wokbaot i go kasem ol ples long saot, mo olgeta long is bambae oli wokbaot i go kasem ol ples long wes, be neva bambae oli save harem.","Long taem ya, bambae yufala i stap go olbaot blong harem tok blong mi. Olgeta long not bambae oli wokbaot i go kasem ol ples long saot, mo olgeta long is bambae oli wokbaot i go kasem ol ples long wes, be neva bambae oli save harem."],[8,13,"Long taem ya, ol boe mo gel we oli strong gud, be bambae oli ded nomo long tosta.","Long taem ya, ol boe mo gel we oli strong gud, be bambae oli ded nomo long tosta."],[8,14,"Yufala we i stap talem nem blong rabis aedol ya blong ol man Sameria,* mo yufala we i stap talem nem blong god blong ol man Dan, mo yufala we i stap talem nem blong god blong ol man Bereseba, blong mekem tok blong yufala i strong, long taem ya, bambae yufala evriwan i ded we nem blong yufala bambae i lus olgeta. Mi mi Hae God, mo hemia tok blong mi.’ ”","Yufala we i stap talem nem blong rabis aedol ya blong ol man Sameria,* mo yufala we i stap talem nem blong god blong ol man Dan, mo yufala we i stap talem nem blong god blong ol man Bereseba, blong mekem tok blong yufala i strong, long taem ya, bambae yufala evriwan i ded we nem blong yufala bambae i lus olgeta. Mi mi Hae God, mo hemia tok blong mi.’ ”"],[9,1,"Nao bakegen, Profet Amos i talem se, “Mi mi luk wan vison* bakegen, we Masta* blong yumi i soemaot long mi, mo long vison ya, mi luk we hem i stap stanap klosap long olta ya long haos* blong hem. Nao mi harem we hem i talem se, ‘Yufala i go kilimstrong top blong tu bigfala pos ya long vranda blong haos ya, blong mekem fandesen blong hem i seksek evriwan. Bambae yufala i go kilimaot tufala pos ya, blong tufala i folfoldaon long hed blong ol man we i stap long ples ya. Ol narafala man we oli no ded long taem ya, mi bambae mi kilim olgeta long taem blong faet. Bambae i no gat wan long olgeta i save ronwe blong go haed. Bambae i no gat wan long olgeta nating i stap.","Nao bakegen, Profet Amos i talem se, “Mi mi luk wan vison* bakegen, we Masta* blong yumi i soemaot long mi, mo long vison ya, mi luk we hem i stap stanap klosap long olta ya long haos* blong hem. Nao mi harem we hem i talem se, ‘Yufala i go kilimstrong top blong tu bigfala pos ya long vranda blong haos ya, blong mekem fandesen blong hem i seksek evriwan. Bambae yufala i go kilimaot tufala pos ya, blong tufala i folfoldaon long hed blong ol man we i stap long ples ya. Ol narafala man we oli no ded long taem ya, mi bambae mi kilim olgeta long taem blong faet. Bambae i no gat wan long olgeta i save ronwe blong go haed. Bambae i no gat wan long olgeta nating i stap."],[9,2,"Nating we sam long olgeta oli digim hol i godaon blong go haed long Hom* blong ol Dedman, be bambae mi tekemaot olgeta i kam antap bakegen. Mo nating we sam long olgeta oli ronwe i go antap i kasem long skae, be bambae mi tekemaot olgeta i kamdaon bakegen.","Nating we sam long olgeta oli digim hol i godaon blong go haed long Hom* blong ol Dedman, be bambae mi tekemaot olgeta i kam antap bakegen. Mo nating we sam long olgeta oli ronwe i go antap i kasem long skae, be bambae mi tekemaot olgeta i kamdaon bakegen."],[9,3,"Nating we sam long olgeta oli go haed olbaot long hil ya Kamel, be bambae mi go lukaot olgeta, mi holem olgeta, mi tekem olgeta i kambak bakegen. Mo nating we sam long olgeta oli go haed long solwota, oli godaon olgeta long botom blong hem, be bambae mi givim tok long bigfala samting ya Leviatan,* blong i kakae olgeta.","Nating we sam long olgeta oli go haed olbaot long hil ya Kamel, be bambae mi go lukaot olgeta, mi holem olgeta, mi tekem olgeta i kambak bakegen. Mo nating we sam long olgeta oli go haed long solwota, oli godaon olgeta long botom blong hem, be bambae mi givim tok long bigfala samting ya Leviatan,* blong i kakae olgeta."],[9,4,"Nating we ol enemi blong olgeta oli kam tekemaot olgeta i go wok slef,* be bambae mi givim tok long ol enemi ya blong oli kilim olgeta oli ded. Tingting blong mi i stap strong yet, se bambae mi no save givhan long ol man ya, mi mas kilim olgeta oli ded.’ ”","Nating we ol enemi blong olgeta oli kam tekemaot olgeta i go wok slef,* be bambae mi givim tok long ol enemi ya blong oli kilim olgeta oli ded. Tingting blong mi i stap strong yet, se bambae mi no save givhan long ol man ya, mi mas kilim olgeta oli ded.’ ”"],[9,5,"Nao profet i talem se, “Hae God i Masta blong yumi, mo hem i gat olgeta paoa. Taem hem i tajem wol ya, wantaem nomo graon ya i seksek, nao olgeta man we oli stap long hem oli stap krae bigwan. Long evri ples, bambae graon i kam antap, i godaon, i kam antap, i godaon, olsem we long taem blong taedelwef, solwota i stap kam antap, i godaon.","Nao profet i talem se, “Hae God i Masta blong yumi, mo hem i gat olgeta paoa. Taem hem i tajem wol ya, wantaem nomo graon ya i seksek, nao olgeta man we oli stap long hem oli stap krae bigwan. Long evri ples, bambae graon i kam antap, i godaon, i kam antap, i godaon, olsem we long taem blong taedelwef, solwota i stap kam antap, i godaon."],[9,6,"Hae God ya, hem i wokem ples blong hem antap long skae ya, mo i mekem wan samting olsem ruf, i putum antap long wol ya. Hem i gat paoa blong singaot solwota i go antap, i kam klaod, mo blong mekem i kam ren, i foldaon bakegen long wol ya. !Nem blong hem, Hae God!”","Hae God ya, hem i wokem ples blong hem antap long skae ya, mo i mekem wan samting olsem ruf, i putum antap long wol ya. Hem i gat paoa blong singaot solwota i go antap, i kam klaod, mo blong mekem i kam ren, i foldaon bakegen long wol ya. !Nem blong hem, Hae God!”"],[9,7,"Mo profet i talemaot we Hae God i talem se, “Ol man Isrel.* ?Yufala i ting se mi mi stap tinghevi long yufala nomo? !Nogat! Ol man Itiopia, mi mi stap tinghevi long olgeta tu, olsem we mi stap tinghevi long yufala. I tru, bifo, taem we yufala i stap long kantri ya Ijip, mi mi tekem yufala i kam long ples ya. !Be yufala i luk! Ol man Filistia ya, fastaem oli stap long ples ya Krit, be mi nao mi tekem olgeta i kam stap long ples blong olgeta, we oli stap long hem naoia. Mo ol man Siria ya, fastaem oli stap long ples ya Kiri, be mi nao mi tekem olgeta i kam stap long ples blong olgeta, we oli stap long hem naoia.","Mo profet i talemaot we Hae God i talem se, “Ol man Isrel.* ?Yufala i ting se mi mi stap tinghevi long yufala nomo? !Nogat! Ol man Itiopia, mi mi stap tinghevi long olgeta tu, olsem we mi stap tinghevi long yufala. I tru, bifo, taem we yufala i stap long kantri ya Ijip, mi mi tekem yufala i kam long ples ya. !Be yufala i luk! Ol man Filistia ya, fastaem oli stap long ples ya Krit, be mi nao mi tekem olgeta i kam stap long ples blong olgeta, we oli stap long hem naoia. Mo ol man Siria ya, fastaem oli stap long ples ya Kiri, be mi nao mi tekem olgeta i kam stap long ples blong olgeta, we oli stap long hem naoia."],[9,8,"Ol man Isrel. Mi mi Hae God, mi Masta blong yufala, mo oltaem mi stap lukluk ol rabis fasin blong yufala. Bambae mi flatemgud yufala evriwan, we bambae i no moa gat wan long yufala i stap long wol ya. Be bambae mi no save kilim yufala evriwan we i laen* blong Jekob.*","Ol man Isrel. Mi mi Hae God, mi Masta blong yufala, mo oltaem mi stap lukluk ol rabis fasin blong yufala. Bambae mi flatemgud yufala evriwan, we bambae i no moa gat wan long yufala i stap long wol ya. Be bambae mi no save kilim yufala evriwan we i laen* blong Jekob.*"],[9,9,"“Mi bambae mi talem wan tok, nao yufala we i stap long ol narafala kantri, bambae mi mekem long yufala, olsem we man i sevem sanbij long netwaea blong tekemaot ol ston long hem. Olsem we i no gat ston i save pastru long netwaea ya, long sem fasin, bambae i no gat wan long yufala we mi save mestem.","“Mi bambae mi talem wan tok, nao yufala we i stap long ol narafala kantri, bambae mi mekem long yufala, olsem we man i sevem sanbij long netwaea blong tekemaot ol ston long hem. Olsem we i no gat ston i save pastru long netwaea ya, long sem fasin, bambae i no gat wan long yufala we mi save mestem."],[9,10,"Sam long yufala ol man blong mi, yufala i man nogud, mo yufala i stap talem se, ‘God bambae i no save letem wan samting nogud i kam spolem yumi ya.’ Be mi bambae mi kilim yufala evriwan i ded long taem blong faet.”","Sam long yufala ol man blong mi, yufala i man nogud, mo yufala i stap talem se, ‘God bambae i no save letem wan samting nogud i kam spolem yumi ya.’ Be mi bambae mi kilim yufala evriwan i ded long taem blong faet.”"],[9,11,"Nao Profet Amos i talemaot we Hae God i talem se, “I gat taem i stap kam we mi bambae mi mekem kantri ya blong yufala, we King Deved i stap rul long hem bifo, we i foldaon finis olsem haos we i kam nogud olgeta, hem i kam gud bakegen. Bambae mi mekem olsem we mi wokem ol wol blong haos ya oli kam niuwan bakegen olsem fastaem.","Nao Profet Amos i talemaot we Hae God i talem se, “I gat taem i stap kam we mi bambae mi mekem kantri ya blong yufala, we King Deved i stap rul long hem bifo, we i foldaon finis olsem haos we i kam nogud olgeta, hem i kam gud bakegen. Bambae mi mekem olsem we mi wokem ol wol blong haos ya oli kam niuwan bakegen olsem fastaem."],[9,12,"Nao long taem ya, olgeta we bambae oli kamaot biaen long yufala, bambae oli winim kantri ya Edom, oli holem ol graon blong hem i blong olgeta, mo bambae oli winimbak ol narafala kantri ya tu, we fastaem yufala i holem olgeta long nem blong mi. Olgeta samting ya, mi bambae mi mekem i kamtru. Mi mi Hae God, mo hemia tok blong mi.”","Nao long taem ya, olgeta we bambae oli kamaot biaen long yufala, bambae oli winim kantri ya Edom, oli holem ol graon blong hem i blong olgeta, mo bambae oli winimbak ol narafala kantri ya tu, we fastaem yufala i holem olgeta long nem blong mi. Olgeta samting ya, mi bambae mi mekem i kamtru. Mi mi Hae God, mo hemia tok blong mi.”"],[9,13,"Nao profet i finisim tok blong hem, i talemaot we Hae God i talem se, “I gat taem i stap kam we bambae ol garen oli stap gru kwiktaem nomo, we ol kakae blong hem bambae oli plante we plante, ol man bambae oli no naf // blong karem i kam. Long taem ya, ol rop ya grep* bambae oli stap gru kwiktaem, we ol frut blong hem bambae oli plante we plante. Bambae ol man oli no naf blong wokem waen long hem. Olbaot long ol hil, long ol ples ya we oli planem ol rop ya long hem, wota blong ol grep ya bambae i fulap we i fulap, i mekem graon i sofsof, nao i ron i kamdaon // olsem bigfala reva.","Nao profet i finisim tok blong hem, i talemaot we Hae God i talem se, “I gat taem i stap kam we bambae ol garen oli stap gru kwiktaem nomo, we ol kakae blong hem bambae oli plante we plante, ol man bambae oli no naf // blong karem i kam. Long taem ya, ol rop ya grep* bambae oli stap gru kwiktaem, we ol frut blong hem bambae oli plante we plante. Bambae ol man oli no naf blong wokem waen long hem. Olbaot long ol hil, long ol ples ya we oli planem ol rop ya long hem, wota blong ol grep ya bambae i fulap we i fulap, i mekem graon i sofsof, nao i ron i kamdaon // olsem bigfala reva."],[9,14,"Long taem ya, olgeta we bambae oli kamaot biaen long yufala, we oli stap olbaot long ol narafala kantri, mi bambae mi tekem olgeta i kambak long ples ya, we i stret ples blong yufala. Nao bambae oli wokemgud ol taon ya blong yufala we oli folfoldaon, mo bambae oli planem ol grep bakegen, nao bambae oli stap dring waen we oli wokem long ol frut blong hem. Bambae oli wokem ol garen bakegen, nao bambae oli stap kakae ol kakae blong ol garen ya blong olgeta.","Long taem ya, olgeta we bambae oli kamaot biaen long yufala, we oli stap olbaot long ol narafala kantri, mi bambae mi tekem olgeta i kambak long ples ya, we i stret ples blong yufala. Nao bambae oli wokemgud ol taon ya blong yufala we oli folfoldaon, mo bambae oli planem ol grep bakegen, nao bambae oli stap dring waen we oli wokem long ol frut blong hem. Bambae oli wokem ol garen bakegen, nao bambae oli stap kakae ol kakae blong ol garen ya blong olgeta."],[9,15,"Mi bambae mi putum olgeta long kantri ya we mi mi givim long yufala, mo neva bambae mi letem ol man oli tekemaot olgeta long kantri ya bakegen. Mi mi Hae God, mi God blong yufala, mo hemia tok blong mi.”","Mi bambae mi putum olgeta long kantri ya we mi mi givim long yufala, mo neva bambae mi letem ol man oli tekemaot olgeta long kantri ya bakegen. Mi mi Hae God, mi God blong yufala, mo hemia tok blong mi.”"]]}};